/* 自动生成，请勿手工修改。来源：DSH chemistry/chem-substance；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"chem-substance-1","title":"空气的组成与保护：成分测定·氧气含量实验·污染防治","subtitle":"人教版九年级 · 第二单元 我们周围的空气 · 9a","grade":"9a","tags":["人教版九年级 · 第二单元 我们周围的空气"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第二单元 我们周围的空气 · 9a"},{"type":"note","title":"问题切入","text":"空气看不见、摸不着，它到底由哪些物质组成、各占多少？把红磷点燃后放进密闭的集气瓶里，为什么打开弹簧夹水正好倒吸约五分之一？工厂的烟囱和汽车尾气又是怎样把空气弄脏的？"},{"type":"note","title":"一句话抓住关键","text":"空气是混合物，按体积分数计大约是氮气 78%、氧气 21%、稀有气体 0.94%、二氧化碳 0.03%、其他气体和杂质 0.03%。红磷燃烧只消耗瓶内的氧气，生成的 P₂O₅ 是固体，瓶内气体减少、压强变小，水就被压进来约五分之一体积——这是「用压强差把气体的体积显出来」的典型方法，也是误差分析的出发点。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"空气像一锅看不见的汤：主要成分是氮气，第二多是氧气，还撒了少量稀有气体、二氧化碳和水蒸气。它无色无味，所以你平时感觉不到，但每一次呼吸都在用它。","walk":["按体积分数记：氮气约 78%，氧气约 21%，稀有气体约 0.94%，二氧化碳约 0.03%，其余是杂质。注意是体积分数，不是质量分数。","测定氧气含量的经典实验用红磷：红磷燃烧消耗瓶内氧气，生成固体五氧化二磷，瓶内压强变小，打开弹簧夹后水倒吸约五分之一。","实验误差要会分析：红磷不足、装置漏气、没等冷却就打开弹簧夹，都会让水位小于五分之一；点燃后伸入太慢，也会让结果偏小。"],"try":"在安全、有成人陪同的前提下，把一支燃着的蜡烛放进盛水的盘中，再用玻璃杯倒扣罩住，观察杯内水位慢慢上升，体会「气体被消耗、压强变小」。","use":["实验题答误差，先想「氧气有没有被耗尽、装置漏没漏气、温度恢复没有」。","空气污染题按「污染源—污染物—防治措施」三条线作答。"]},{"type":"h","text":"【宏观】宏观：空气由哪几种物质组成，各占多少"},{"type":"p","text":"把空气的成分按体积分数排一排：氮气 78%、氧气 21%、稀有气体 0.94%、二氧化碳 0.03%、其他气体和杂质 0.03%。请注意三个容易记错的地方：一是这些数字都是体积分数而不是质量分数；二是含量最多的是氮气而不是氧气；三是稀有气体是氦、氖、氩、氪、氙等的总称，它们的化学性质很不活泼，过去叫惰性气体。"},{"type":"figure","figure":{"id":"fig-chem-substance-1-1","title":"空气的成分（按体积分数）","caption":"横条长度代表体积分数，含量太小的几条为便于观察做了放大","view":"wide","alt":"条形图列出空气的成分：氮气 78%、氧气 21%、稀有气体 0.94%、二氧化碳 0.03%、其他气体和杂质 0.03%","prims":[{"t":"text","x":22,"y":12,"text":"N₂","anchor":"end","size":3.8},{"t":"rect","x":24,"y":9,"w":46.8,"h":6,"fill":true,"tone":"main"},{"t":"text","x":72,"y":12,"text":"78%","anchor":"start","size":3.8},{"t":"text","x":22,"y":22,"text":"O₂","anchor":"end","size":3.8},{"t":"rect","x":24,"y":19,"w":12.6,"h":6,"fill":true,"tone":"accent"},{"t":"text","x":38,"y":22,"text":"21%","anchor":"start","size":3.8},{"t":"text","x":22,"y":34,"text":"稀有气体","anchor":"end","size":3.4},{"t":"rect","x":24,"y":31,"w":6,"h":6,"fill":true,"tone":"ok"},{"t":"text","x":32,"y":34,"text":"0.94%","anchor":"start","size":3.4},{"t":"text","x":22,"y":44,"text":"CO₂","anchor":"end","size":3.4},{"t":"rect","x":24,"y":41,"w":6,"h":6,"fill":true,"tone":"danger"},{"t":"text","x":32,"y":44,"text":"0.03%","anchor":"start","size":3.4},{"t":"text","x":22,"y":54,"text":"其他气体和杂质","anchor":"end","size":3.4},{"t":"rect","x":24,"y":51,"w":6,"h":6,"fill":true,"tone":"muted"},{"t":"text","x":32,"y":54,"text":"0.03%","anchor":"start","size":3.4},{"t":"text","x":62,"y":59,"text":"（含量小的几条按放大比例示意）","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"答题时「78%」「21%」后面一定要跟上「体积分数」四个字。写作「氮气约占空气质量的 78%」是常见错误：氮气比空气略轻，按质量算它的比例不到 78%。"},{"type":"h","text":"【宏观】宏观实验：用红磷把氧气的体积「量」出来"},{"type":"p","text":"在集气瓶里放少量水，把足量红磷放在燃烧匙里点燃后迅速伸入瓶中并塞紧塞子，红磷燃烧产生大量白烟，放出热量。等火焰熄灭、瓶子冷却到室温再打开弹簧夹，烧杯里的水就沿着导管倒吸进集气瓶，体积约占瓶内空气体积的五分之一。水为什么会被吸进去？因为红磷只跟氧气反应，生成的五氧化二磷是固体，瓶内气体少了、压强变小了，外界大气压就把水压了进来——吸入的水的体积就等于被消耗掉的氧气的体积。"},{"type":"figure","figure":{"id":"fig-chem-substance-1-2","title":"测定空气中氧气的含量","caption":"红磷足量、装置不漏气、冷却到室温后打开弹簧夹，水倒吸约 1/5 体积","view":"wide","alt":"集气瓶内盛少量水、瓶内燃烧匙上放着足量红磷，双孔橡皮塞上插着导管，导管用弹簧夹夹住后伸入盛水的烧杯中","prims":[{"t":"gasJar","x":34,"y":32,"w":22,"h":28,"liquid":0.15,"color":"colorless"},{"t":"rect","x":24,"y":15.5,"w":20,"h":2.5,"fill":true},{"t":"line","x1":34,"y1":18,"x2":34,"y2":23.5,"width":0.7},{"t":"circle","cx":34,"cy":26,"r":3.2,"fill":true},{"t":"text","x":44,"y":26,"text":"燃烧匙（足量红磷）","anchor":"start","size":3.4},{"t":"text","x":22,"y":48,"text":"集气瓶（内盛少量水）","anchor":"start","size":3.4,"tone":"muted"},{"t":"curve","points":[[42,17],[58,12],[76,13],[76,50]]},{"t":"line","x1":56,"y1":10,"x2":60,"y2":14.6,"width":1.4},{"t":"text","x":52,"y":7,"text":"弹簧夹","size":3.4},{"t":"beaker","x":66,"y":36,"w":22,"h":20,"fill":0.5},{"t":"text","x":77,"y":60,"text":"烧杯（水）","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"现象与结论要分开写：现象是「红磷燃烧产生大量白烟，冷却后打开弹簧夹，水倒吸进集气瓶约五分之一体积」；结论是「空气中氧气的体积分数约为 1/5」。只说结论没有现象，实验题拿不到分。"},{"type":"h","text":"【微观】微观：为什么是「气体分子变少」，而不是「空气消失了」"},{"type":"p","text":"从粒子角度看，集气瓶里本来混着氮分子、氧分子等不同种分子，这正是空气属于混合物的原因。点燃红磷后，磷原子与氧分子发生反应：氧分子被拆开、与磷原子重新组合成五氧化二磷，而五氧化二磷在常温下是固体，不再以气体分子的形式占体积。于是瓶内气体分子的总数减少了（剩下的主要是氮分子），在体积和温度不变的情况下，瓶内压强就变小，外界大气压把水压进瓶里。注意：氮分子自始至终没有参加反应，它们只是「被挤得少了位置」。"},{"type":"figure","figure":{"id":"fig-chem-substance-1-3","title":"红磷燃烧前后瓶内粒子的变化","caption":"氧分子被消耗、生成物是固体，气体分子数减少 → 压强变小","view":"wide","alt":"左侧是瓶内原有的氮分子与氧分子，中间箭头标出点燃红磷，右侧只剩下氮分子和五氧化二磷固体微粒","prims":[{"t":"molecule","x":12,"y":12,"atoms":[{"dx":-3,"dy":0,"symbol":"N"},{"dx":3,"dy":0,"symbol":"N"}],"bonds":[[0,1]],"label":"N₂"},{"t":"molecule","x":12,"y":30,"atoms":[{"dx":-3,"dy":0,"symbol":"O","color":"red"},{"dx":3,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"text","x":12,"y":48,"text":"瓶内原有气体分子","size":3.4,"tone":"muted"},{"t":"arrow","x1":24,"y1":24,"x2":38,"y2":24,"label":"点燃红磷","labelDy":-4},{"t":"molecule","x":54,"y":12,"atoms":[{"dx":-3,"dy":0,"symbol":"N"},{"dx":3,"dy":0,"symbol":"N"}],"bonds":[[0,1]],"label":"N₂（剩余）"},{"t":"hatch","x":45,"y":30,"w":18,"h":8,"gap":2.2},{"t":"text","x":54,"y":44,"text":"P₂O₅ 固体微粒","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":57,"text":"气体分子数减少 → 压强变小 → 水倒吸约 1/5","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"微观解释里必须出现「分子」和「原子」两个词：化学变化中分子被拆成原子，原子再重新组合成新的分子（或直接构成固体），反应前后原子的种类和个数都没有变。"},{"type":"h","text":"【符号】符号：把这件事写成化学方程式"},{"type":"p","text":"红磷燃烧的反应写成 4P + 5O₂ —点燃→ 2P₂O₅：左边 4 个磷原子、10 个氧原子，右边 2 个 P₂O₅ 里同样是 4 个磷原子和 10 个氧原子，配平是正确的。写方程式要守住三条：化学式下标不能改（P₂O₅ 不能写成 PO₅），条件必须写在箭头上（点燃），气体、沉淀符号只用在溶液中的反应上——本题生成物是固体，既不写 ↑ 也不写 ↓。空气里其他成分也各对应一个化学式：N₂、O₂、CO₂、SO₂、NO₂、He、Ne、Ar。"},{"type":"figure","figure":{"id":"fig-chem-substance-1-4","title":"粒子模型与方程式对照","caption":"4 个磷原子 + 5 个氧分子 → 2 个五氧化二磷「单元」","view":"wide","alt":"左边四个磷原子和五个氧分子，箭头标注点燃，右边是两个五氧化二磷的粒子单元，与方程式 4P + 5O₂ 点燃 2P₂O₅ 逐一对应","prims":[{"t":"atom","x":10,"y":16,"symbol":"P","color":"brown"},{"t":"atom","x":20,"y":16,"symbol":"P","color":"brown"},{"t":"atom","x":10,"y":30,"symbol":"P","color":"brown"},{"t":"atom","x":20,"y":30,"symbol":"P","color":"brown"},{"t":"text","x":15,"y":42,"text":"4 个 P","size":3.4,"tone":"muted"},{"t":"molecule","x":38,"y":16,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]]},{"t":"molecule","x":38,"y":30,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]]},{"t":"text","x":38,"y":42,"text":"5 个 O₂（示意）","size":3.4,"tone":"muted"},{"t":"arrow","x1":50,"y1":24,"x2":62,"y2":24,"label":"点燃","labelDy":-4},{"t":"molecule","x":74,"y":16,"atoms":[{"dx":0,"dy":0,"r":4,"symbol":"P","color":"brown"},{"dx":7,"dy":-3.4,"symbol":"O","color":"red"},{"dx":7,"dy":3.4,"symbol":"O","color":"red"},{"dx":-7,"dy":-3.4,"symbol":"O","color":"red"},{"dx":-7,"dy":3.4,"symbol":"O","color":"red"}]},{"t":"text","x":74,"y":42,"text":"2 个 P₂O₅（固体）","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"配平不是「凑数字」：先把最复杂的化学式（P₂O₅）的系数定为 2，再让两边的 P 和 O 原子个数相等，最后检查一遍并把它约成最简整数比。"},{"type":"h","text":"【应用】应用：空气的污染与防治"},{"type":"p","text":"空气污染物主要是两类：有害气体（二氧化硫 SO₂、二氧化氮 NO₂、一氧化碳 CO 等）和烟尘（可吸入颗粒物 PM10、PM2.5）。注意二氧化碳不是空气污染物，它含量升高主要带来温室效应，两者不能混为一谈。污染物从哪里来？煤和石油的燃烧、工厂废气、汽车尾气、扬尘。防治也就从这里下手：使用清洁能源、废气处理达标后排放、汽车尾气净化、植树造林、工地洒水降尘。空气质量指数 AQI 越大，说明污染越重。"},{"type":"note","title":"","text":"简答题答「防治措施」时要与污染源对应：说燃煤污染就写「使用清洁能源、脱硫」，说汽车尾气就写「尾气净化、推广新能源汽车」，泛泛写「保护环境」拿不到分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["空气中某成分的体积分数","某成分的体积分数 = 该成分的体积 ÷ 空气的总体积 × 100%","用来表示气体混合物中各成分的含量。空气中氮气 78%、氧气 21% 都是体积分数，不是质量分数。若按质量分数计算，氧气的比例会比 21% 大一些（氧气比氮气略重），所以答题时「体积分数」四个字不能省。"],["压强差法测气体含量","被消耗气体的体积分数 = 进入容器的液体体积 ÷ 容器内原有气体的总体积 × 100%","只适用于「被消耗的气体不再生成新气体，或生成物是固体、液体」的测定实验，例如红磷燃烧测空气中氧气的含量。若改用木炭、硫代替红磷，产物是气体，瓶内压强变化不明显，这个关系就不成立（但把生成的气体用碱液吸收后仍可用，属于拓展）。"],["方程式计算中的质量比","4P + 5O₂ —点燃→ 2P₂O₅，m(P)∶m(O₂)∶m(P₂O₅) = 124∶160∶284","质量比由化学方程式里各物质的相对分子质量乘系数得到：4×31 = 124，5×32 = 160，2×142 = 284。已知其中任一物质的质量，就能按这个比例求出另外两种物质的质量，这是化学方程式计算的依据；只有纯物质的质量才能代入。"]]},{"type":"h","text":"应用 · 用实验数据算空气中氧气的体积分数"},{"type":"note","title":"情境","text":"某同学用容积 250 mL 的集气瓶做红磷燃烧实验：红磷足量，装置不漏气，冷却到室温后打开弹簧夹，水倒吸进集气瓶 45 mL。求测得的氧气体积分数，并分析结果偏小的原因。"},{"type":"list","title":"解答步骤","items":["抓出两个量：进入瓶内水的体积 V水 = 45 mL，瓶内空气的总体积 V空气 = 250 mL。","写出关系式：氧气的体积分数 = V水 ÷ V空气 × 100%。","代入数据：45 mL ÷ 250 mL × 100% = 18%。","与理论值 21% 比较，说明偏小，并给出原因：红磷量不足（氧气没消耗完）、装置漏气、未冷却到室温就打开弹簧夹。"]},{"type":"note","title":"结论","text":"测得氧气的体积分数为 18%，小于 21%。评分点在「进入的水的体积就是被消耗氧气的体积」这一句话上，误差原因还要说清是「使瓶内气体偏多」还是「使消耗的氧气偏少」。"},{"type":"h","text":"应用 · 从空气质量日报读出污染信息"},{"type":"note","title":"情境","text":"某市某日空气质量日报：空气质量指数 AQI 为 158，首要污染物为可吸入颗粒物 PM10，空气级别为轻度污染，建议儿童、老人减少户外活动。"},{"type":"list","title":"解答步骤","items":["看 AQI 的大小：数值越大污染越重，158 属于轻度污染。","看首要污染物，联系污染源：PM10 说明颗粒物是主要问题，要从扬尘、燃煤、尾气几方面找原因。","对应写出防治措施：工地洒水降尘、燃煤脱硫除尘、汽车尾气净化、绿化造林。"]},{"type":"note","title":"结论","text":"AQI 越大污染越重；空气污染物是 SO₂、NO₂、CO、O₃ 和可吸入颗粒物等，不包括 CO₂；防治措施要与污染源一一对应才得分。"},{"type":"h","text":"实验 1 · 测定空气中氧气的含量（红磷燃烧法）"},{"type":"note","title":"实验目的","text":"用只与氧气反应、且生成物为固体的红磷，把集气瓶内氧气消耗掉，通过倒吸进瓶内水的体积测出空气中氧气的体积分数。"},{"type":"list","title":"实验器材","items":["集气瓶（容积已知，内盛少量水，用来吸收生成的 P₂O₅ 并帮助降温）","燃烧匙、足量红磷","双孔橡皮塞、导管、弹簧夹","烧杯（盛足量水）、酒精灯、火柴"]},{"type":"figure","figure":{"id":"fig-chem-substance-1-exp1","title":"测定空气中氧气含量的装置","caption":"红磷足量、塞紧塞子，冷却到室温后再打开弹簧夹","view":"wide","alt":"集气瓶内盛少量水，燃烧匙中放足量红磷，双孔橡皮塞上插着被弹簧夹夹住的导管，导管另一端伸入盛水的烧杯中","prims":[{"t":"gasJar","x":32,"y":32,"w":22,"h":28,"liquid":0.15,"color":"colorless"},{"t":"rect","x":22,"y":15.5,"w":20,"h":2.5,"fill":true},{"t":"line","x1":32,"y1":18,"x2":32,"y2":23.5,"width":0.7},{"t":"circle","cx":32,"cy":26,"r":3.2,"fill":true},{"t":"text","x":42,"y":24,"text":"足量红磷","anchor":"start","size":3.4},{"t":"curve","points":[[40,17],[56,12],[74,13],[74,50]]},{"t":"line","x1":54,"y1":10,"x2":58,"y2":14.6,"width":1.4},{"t":"text","x":50,"y":7,"text":"弹簧夹（先夹紧）","size":3.4},{"t":"beaker","x":64,"y":36,"w":22,"h":20,"fill":0.5},{"t":"text","x":75,"y":60,"text":"烧杯与水","size":3.4,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["在集气瓶内加入少量水，把水面以上的容积分成 5 等份（也可事先用记号笔标出）。","检查装置的气密性：塞紧橡皮塞、夹紧弹簧夹，把手贴在集气瓶外壁，导管口在烧杯水中出现气泡或水柱变化，说明不漏气。","取足量红磷放在燃烧匙中，在酒精灯上点燃后迅速伸入集气瓶，立即塞紧橡皮塞。","观察红磷燃烧的现象，待火焰熄灭、集气瓶冷却到室温后，打开弹簧夹，观察并记录倒吸进瓶内水的体积。"]},{"type":"note","title":"实验现象","text":"红磷燃烧产生大量白烟，放出热量；冷却后打开弹簧夹，烧杯中的水沿导管倒吸进集气瓶，进入瓶内的水的体积约占瓶内空气体积的 1/5。"},{"type":"note","title":"实验结论","text":"空气中氧气的体积分数约为 1/5（约 21%）。反应的化学方程式为 4P + 5O₂ —点燃→ 2P₂O₅，生成物是固体，瓶内气体减少、压强变小，所以水被压入瓶中。"},{"type":"list","title":"注意事项","items":["红磷必须足量：量不足时瓶内氧气消耗不完，倒吸的水会少于 1/5。","装置必须气密性良好：漏气时外界空气进入瓶内，倒吸的水也会偏少。","必须等集气瓶冷却到室温后再打开弹簧夹：不冷却就打开，瓶内气体受热膨胀，进入的水偏少。","不能用木炭、硫代替红磷：它们燃烧的产物是气体（CO₂、SO₂），瓶内压强变化不明显，水几乎不倒吸。","点燃红磷后要迅速伸入瓶中并塞紧塞子，防止瓶内空气受热后逸出，使结果偏大。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["4P + 5O₂ —点燃→ 2P₂O₅","点燃","红磷燃烧产生大量白烟，放出热量；冷却到室温后打开弹簧夹，水倒吸进集气瓶约 1/5 体积","配平：左边 4 个 P、10 个 O，右边 2 个 P₂O₅ 也是 4 个 P、10 个 O。P₂O₅ 的下标不能改，也不能写成 PO₅。生成的 P₂O₅ 是白色固体，所以说「白烟」；「白雾」指的是液体小液滴，用在这里是错的。"],["C + O₂ —点燃→ CO₂","点燃","木炭在氧气中剧烈燃烧，发出白光，放出热量，生成能使澄清石灰水变浑浊的气体","这是氧气充足时的完全燃烧；氧气不足时会生成一氧化碳（2C + O₂ —点燃→ 2CO）。写这类方程式前先看清题目给的是「足量氧气」还是「氧气不足」，反应物不同、方程式就不同。"],["S + O₂ —点燃→ SO₂","点燃","硫在氧气中燃烧发出明亮的蓝紫色火焰，放出热量，生成有刺激性气味的气体","SO₂ 是空气污染物之一，也是形成酸雨的主要气体。现象里必须写「明亮的蓝紫色火焰」（在空气中是淡蓝色火焰），「黄色火焰」「白烟」都是错的。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["空气中含量最多的成分是氧气，因为它最有用。","按体积分数计，氮气约占 78%，是含量最多的成分；氧气约占 21%。","把「用途多」当成了「含量多」。空气中的氮气是化工原料（合成氨、制氮肥）和食品保护气的重要来源，用途同样广泛，只是不常被提起。"],["红磷燃烧产生大量白雾，冷却后水倒吸约 1/5 体积。","红磷燃烧产生大量白烟，冷却到室温后打开弹簧夹，水倒吸约 1/5 体积。","烟是固体小颗粒，雾是液体小液滴。红磷燃烧生成的 P₂O₅ 是白色固体，所以只能写「白烟」。这一字之差在中考现象描述题里就是零分。"],["二氧化碳是空气污染物，空气质量指数越高说明二氧化碳越多。","二氧化碳不是空气污染物；空气污染物主要是二氧化硫、二氧化氮、一氧化碳和可吸入颗粒物等。","二氧化碳参与自然界的碳循环，是植物光合作用的原料，它含量升高带来的问题是温室效应，属于环境问题但不属于「空气污染指数」统计的污染物。"]]},{"type":"table","title":"氮气与氧气：性质与用途对照（化学性质活泼程度与主要用途）","head":["比较项","氮气 N₂","氧气 O₂"],"rows":[["在空气中的体积分数","约 78%，含量最多","约 21%，含量第二"],["化学性质","很不活泼，常温下几乎不与别的物质反应","比较活泼，能与许多物质反应并放出热量"],["主要用途","食品充氮防腐、化工原料（合成氨、制氮肥）、液氮作制冷剂","供给呼吸（医疗、潜水）、支持燃烧（气焊、炼钢）"],["检验方法","没有简便的检验方法（一般靠排除法）","把带火星的木条伸入瓶中，木条复燃"]]},{"type":"table","title":"混合物与纯净物（组成物质的种类与判断依据）","head":["比较项","混合物（如空气）","纯净物（如氧气）"],"rows":[["组成","由两种或两种以上物质组成，如 N₂、O₂、CO₂ 等混在一起","只由一种物质组成，如 O₂、N₂、CO₂ 各自都是纯净物"],["组成是否固定","不固定，不同地点、不同时间的空气成分略有差别","固定，有确定的化学式"],["分离方法","可用过滤、蒸馏、分离液态空气等物理方法把各成分分开","不能用物理方法再分成别的物质"],["判断口诀","「多种物质混在一起」——看有没有化学式","「只有一种物质」——有化学式且只表示一种物质"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["空气组成的判断与记忆","常以选择题或填空题出现，考「含量最多的气体是氮气」「78% 与 21% 是体积分数」「稀有气体、二氧化碳的含量数值」这几个点，偶尔用「空气属于混合物还是纯净物」做干扰项。"],["测定空气中氧气含量的实验探究","非选择题的高频考点：装置图判读（红磷足量、弹簧夹的位置、导管伸入的深度）、现象描述（白烟而不是白雾）、误差分析（偏小与偏大的原因）以及「为什么不能用木炭、硫代替红磷」。"],["空气污染与防治的情境题","以空气质量日报、雾霾、酸雨为情境，考污染物的判断（CO₂ 不是污染物）、污染源与防治措施的对应关系，答案要具体到「谁在排放、怎么减少」。"],["化学用语与实验数据的结合","在实验情境中直接要求写出红磷燃烧的化学方程式并配平，或根据倒吸水的体积计算氧气的体积分数，把化学用语与数据处理放在同一道题里考。"]]},{"type":"quote","text":"【材料一】空气的成分（按体积分数计）：氮气 78%、氧气 21%、稀有气体 0.94%、二氧化碳 0.03%、其他气体和杂质 0.03%。【材料二】某市某日空气质量日报：空气质量指数 AQI 为 158，首要污染物为可吸入颗粒物 PM10，空气级别为轻度污染，建议儿童、老年人减少户外活动。【材料三】某同学用容积 250 mL 的集气瓶做「测定空气中氧气含量」的实验（红磷足量、装置气密性良好、冷却到室温后打开弹簧夹），有 45 mL 水倒吸进集气瓶。（以上数据为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）材料一中含量最多的气体是什么？它在空气中的含量用体积分数表示是多少？空气属于纯净物还是混合物？请说明判断依据。","【设问】（4 分）根据材料三，计算该同学测得的空气中氧气的体积分数（结果保留一位小数），并说明结果与理论值有偏差的一条可能原因。","【设问】（3 分）材料二中的首要污染物属于哪一类空气污染物？再写出一种有害气体类的空气污染物，并针对这种污染物提出一条防治措施。"]}],"questions":[{"id":"chem-substance-1-q1","type":"choice","stem":"如图是测定空气中氧气含量的实验装置。下列关于该实验的说法正确的是（　）","answer":"A","explain":"A 正确：红磷足量才能把瓶内氧气消耗完全，否则倒吸的水会少于 1/5。B 错在现象描述：红磷燃烧生成的是白色固体 P₂O₅，应说「产生大量白烟」，白雾指的是液体小液滴。C 错在选错药品：木炭燃烧的产物 CO₂ 是气体，瓶内气体减少不多、压强变化不明显，水几乎不倒吸。D 错在操作顺序：必须等集气瓶冷却到室温再打开弹簧夹，否则瓶内气体受热膨胀，进入的水偏少，结果偏小。","options":["红磷必须足量，才能把瓶内的氧气尽可能消耗完","红磷燃烧产生大量白雾，冷却后水倒吸约 1/5 体积","可以用木炭代替红磷，因为木炭燃烧也能消耗氧气","红磷一熄灭就应立即打开弹簧夹读取水的体积"],"difficulty":2,"tags":["空气","测定氧气含量","实验操作"],"figure":{"id":"fig-chem-substance-1-q1","title":"测定空气中氧气含量的实验装置","caption":"判断哪一个说法正确","view":"wide","alt":"集气瓶内有少量水和放在燃烧匙上的红磷，橡皮塞上插着被弹簧夹夹住的导管，导管另一端伸入盛水的烧杯中","prims":[{"t":"gasJar","x":32,"y":32,"w":22,"h":28,"liquid":0.15,"color":"colorless"},{"t":"rect","x":22,"y":15.5,"w":20,"h":2.5,"fill":true},{"t":"line","x1":32,"y1":18,"x2":32,"y2":23.5,"width":0.7},{"t":"circle","cx":32,"cy":26,"r":3.2,"fill":true},{"t":"text","x":42,"y":26,"text":"红磷","anchor":"start","size":3.4},{"t":"curve","points":[[40,17],[56,12],[74,13],[74,50]]},{"t":"line","x1":54,"y1":10,"x2":58,"y2":14.6,"width":1.4},{"t":"text","x":50,"y":7,"text":"弹簧夹","size":3.4},{"t":"beaker","x":64,"y":36,"w":22,"h":20,"fill":0.5},{"t":"text","x":75,"y":60,"text":"烧杯与水","size":3.4,"tone":"muted"}]}},{"id":"chem-substance-1-q2","type":"choice","stem":"下列关于空气成分的说法正确的是（　）","answer":"B","explain":"B 正确，这是空气组成的标准表述。A 把氮气和氧气的顺序记反了：含量最多的是氮气。C 把两个数字弄混了：约 0.94% 的是稀有气体，二氧化碳只占约 0.03%。D 错在物质分类：空气由氮气、氧气、稀有气体、二氧化碳等多种物质混合而成，属于混合物，没有固定的化学式，更不是化合物。","options":["空气中含量最多的成分是氧气，其次是氮气","按体积分数计，空气中氮气约占 78%，氧气约占 21%","二氧化碳约占空气体积的 0.94%，是含量第三多的成分","空气是一种化合物，由氮元素和氧元素组成"],"difficulty":1,"tags":["空气","空气的成分"]},{"id":"chem-substance-1-q3","type":"choice","stem":"下列关于空气污染的说法正确的是（　）","answer":"C","explain":"C 正确，这正是空气质量日报统计的几类污染物。A 错在概念混淆：CO₂ 会造成温室效应，但不属于空气污染物；形成酸雨的主要气体是 SO₂ 和 NO₂。B 把关系说反了：AQI 越大表示污染越严重。D 错在绝对化：氧气含量过高会加快金属锈蚀、使可燃物更容易燃烧，也会影响人体（长时间吸入高浓度氧气会伤害肺部），并非越多越好。","options":["二氧化碳是空气污染物，也是形成酸雨的主要气体","空气质量指数越大，说明空气质量越好","二氧化硫、二氧化氮、一氧化碳和可吸入颗粒物都属于空气污染物","空气中的氧气越多越好，氧气含量升高不会带来任何问题"],"difficulty":1,"tags":["空气","空气污染与防治"]},{"id":"chem-substance-1-q4","type":"choice","stem":"下列物质中属于混合物的是（　）","answer":"D","explain":"D 正确：洁净的空气虽然「干净」，但仍由氮气、氧气、稀有气体、二氧化碳等多种物质组成，属于混合物。A 液氧是液态的氧气，只是状态变了，仍只含氧分子这一种物质，属于纯净物。B 氮气是纯净物，化学式为 N₂。C 二氧化碳是纯净物，化学式为 CO₂。判断这类题的窍门：只有一种物质（一种分子）的是纯净物，有化学式且只表示一种物质。","options":["液氧","氮气","二氧化碳","洁净的空气"],"difficulty":1,"tags":["空气","混合物与纯净物"]},{"id":"chem-substance-1-q5","type":"choice","stem":"下列关于空气各成分用途的说法正确的是（　）","answer":"B","explain":"B 正确：氖气通电发红光、氩气通电发蓝紫光，霓虹灯、霓虹广告牌就用它。A 因果颠倒：氮气化学性质很不活泼，才适合做食品保护气（隔绝氧气防氧化）。C 混淆了「助燃」与「可燃」：氧气本身不能燃烧，它支持燃烧，是助燃剂，不能作燃料。D 把原料说成了产物：CO₂ 是光合作用的原料，温室里适当补充 CO₂ 可以促进植物生长，所以能作气体肥料。","options":["氮气的化学性质很活泼，所以可用作食品的保护气","稀有气体通电时能发出不同颜色的光，可用于制作电光源","氧气具有可燃性，可以用作燃料","二氧化碳是植物光合作用的产物，不能用作气体肥料"],"difficulty":2,"tags":["空气","空气各成分的用途"]},{"id":"chem-substance-1-q6","type":"fill","stem":"按体积分数计算，空气中氮气约占 ______%（填整数）。","answer":"78","explain":"空气的成分按体积分数计：氮气 78%、氧气 21%、稀有气体 0.94%、二氧化碳 0.03%、其他气体和杂质 0.03%。这里必须写 78 而不是 21，因为含量最多的是氮气。填 21 是把氧气当成了含量最多的成分，是最常见的错误。","difficulty":1,"tags":["空气","空气的成分"]},{"id":"chem-substance-1-q7","type":"fill","stem":"某同学用容积 200 mL 的集气瓶做测定空气中氧气含量的实验，待冷却到室温后打开弹簧夹，有 41 mL 水倒吸进集气瓶。他测得空气中氧气的体积分数是 ______%（结果保留一位小数）。","answer":"20.5","explain":"进入瓶内水的体积等于被消耗的氧气的体积，所以氧气的体积分数 = 41 mL ÷ 200 mL × 100% = 20.5%。若算成 41 ÷ 200 = 0.205 后忘记写成百分数，或把 41 mL 当成氧气的质量，都会失分。结果略小于 21% 是正常的：红磷不足、装置轻微漏气或温度未完全降到室温，都会使进入的水偏少。","difficulty":2,"tags":["空气","测定氧气含量","体积分数计算"]},{"id":"chem-substance-1-q8","type":"short","stem":"某集气瓶内共有氧气 1.6 g，把足量红磷放在瓶内完全燃烧，恰好把瓶内的氧气全部消耗完。求参加反应的红磷质量和生成的五氧化二磷质量。（相对原子质量：P 31、O 16）","answer":"设参加反应的红磷质量为 x，生成的五氧化二磷质量为 y。由 4P + 5O₂ —点燃→ 2P₂O₅ 可知 m(P)∶m(O₂)∶m(P₂O₅) = 124∶160∶284。由 124∶160 = x∶1.6 g 得 x = 1.24 g；由 160∶284 = 1.6 g∶y 得 y = 2.84 g。答：参加反应的红磷质量为 1.24 g，生成的五氧化二磷质量为 2.84 g。","explain":"这类题的算理是质量守恒：化学方程式里各物质前面的系数乘以相对分子质量，得到的就是它们之间固定的质量比。最容易错的地方有三处：一是方程式没配平（写成 P + O₂ → P₂O₅），相对质量就算错；二是把 O₂ 的相对质量算成 16 而不是 32；三是把「1.6 g 氧气」错当成「1.6 g 空气」代入，只有参加反应的纯物质质量才能代入计算。","difficulty":2,"tags":["空气","化学方程式计算","质量比"],"rubric":["正确写出并配平化学方程式 4P + 5O₂ —点燃→ 2P₂O₅（不配平或不写条件不得分）","算出相关物质的相对质量总和 124、160、284","比例式列对，两个未知量分别求出","结果带单位 g，并写出完整答句"],"steps":["设未知量：设参加反应的红磷质量为 x，生成的五氧化二磷质量为 y。","写出并配平化学方程式：4P + 5O₂ —点燃→ 2P₂O₅。","算出相关物质的相对质量：4×31 = 124，5×(16×2) = 160，2×(31×2 + 16×5) = 284。","列比例式：124∶160 = x∶1.6 g，解得 x = 1.24 g；160∶284 = 1.6 g∶y，解得 y = 2.84 g。","简明作答：参加反应的红磷质量为 1.24 g，生成的五氧化二磷质量为 2.84 g。"]},{"id":"chem-substance-1-q9","type":"short","stem":"某同学做测定空气中氧气含量的实验时，发现水倒吸进集气瓶的体积明显小于集气瓶内空气体积的 1/5。请写出两种可能的原因，并说明各自为什么会使结果偏小。","answer":"原因一：红磷的量不足。瓶内的氧气没有被完全消耗，剩下的氧气仍占体积，瓶内气体减少得不够多，压强下降幅度小，水倒吸得就少。原因二：装置漏气。外界空气会在压强变小时进入集气瓶，使瓶内气体不能继续减少，进入的水偏少。原因三（任答两种即可）：没有冷却到室温就打开弹簧夹，瓶内气体受热膨胀，占的体积偏大，进入的水也偏少。","explain":"实验误差分析要抓住一个核心：水倒吸的多少由瓶内压强下降的多少决定，而压强下降的多少由「瓶内气体减少了多少」决定。凡是让气体减少得不够多（红磷不足、氧气没反应完）或让气体重新变多（漏气、没冷却、伸入红磷时空气逸出后又进入）的因素，都会使结果偏小。反过来，若点燃红磷前没有夹紧弹簧夹、红磷伸入太慢使空气受热逸出，结果就会偏大。答这类题必须「一条原因配一句解释」，只写原因不作解释一般不给满分。","difficulty":2,"tags":["空气","实验探究","误差分析"],"rubric":["写出两条合理原因（红磷不足、装置漏气、未冷却就打开弹簧夹，任写两条）","每条原因都说明「为什么会使瓶内气体偏多或消耗的氧气偏少」","表述规范：现象与原因分开写，结论落在「水倒吸偏少」上"]},{"id":"chem-substance-1-q10","type":"short","stem":"如图是测定空气中氧气含量的装置（弹簧夹处于夹紧状态、红磷尚未点燃）。请你在图中画出实验结束、冷却到室温后打开弹簧夹，水倒吸进集气瓶后水面的大致位置，并标注「约 1/5 体积」。","answer":"水面应画在集气瓶下部、约占瓶内空气体积的 1/5 处（原来瓶内已有少量水，倒吸后水面在原有水面的上方约 1/5 处），并标注「水（约 1/5 体积）」。其余部分仍为气体（主要是氮气）。","explain":"作图的关键是「水进入的体积等于被消耗氧气的体积」。氧气约占空气体积的 1/5，所以水面停在瓶内空气体积的 1/5 处；原来瓶底已有的少量水只是用来吸收 P₂O₅ 和帮助降温，不参与这 1/5 的计算。常见的错误是把水面画到瓶的一半甚至画满，那等于说氧气占 50% 或 100%，与事实不符。","difficulty":2,"tags":["空气","作图题","测定氧气含量"],"rubric":["水面画在集气瓶下部，约占瓶内空气体积的 1/5","水面画成水平线（不能画成斜线）","标注出「约 1/5」，并能看出倒吸后水面高于原来的少量水","装置其余部分保持不变，没有把水画到瓶口以外"],"figure":{"id":"fig-chem-substance-1-q10","title":"待标注水面位置的装置图","caption":"请在图上画出水倒吸后水面的大致位置","view":"wide","alt":"测定空气中氧气含量的装置，集气瓶内只有少量水，等待画出一段时间后水倒吸进瓶内的水面位置","prims":[{"t":"gasJar","x":32,"y":32,"w":22,"h":28,"liquid":0.15,"color":"colorless"},{"t":"rect","x":22,"y":15.5,"w":20,"h":2.5,"fill":true},{"t":"line","x1":32,"y1":18,"x2":32,"y2":23.5,"width":0.7},{"t":"circle","cx":32,"cy":26,"r":3.2,"fill":true},{"t":"text","x":43,"y":26,"text":"红磷（已燃尽）","anchor":"start","size":3.4},{"t":"curve","points":[[40,17],[56,12],[74,13],[74,50]]},{"t":"text","x":50,"y":7,"text":"弹簧夹（已打开）","size":3.4},{"t":"beaker","x":64,"y":36,"w":22,"h":20,"fill":0.5},{"t":"text","x":75,"y":60,"text":"烧杯与水","size":3.4,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-1-q10-a","title":"参考答案：水倒吸后的水面位置","caption":"水面停在瓶内空气体积约 1/5 的高度，上面是剩余的氮气","view":"wide","alt":"集气瓶下部约五分之一高度的水，水平线标注为约五分之一体积，水面以上是剩余的氮气","prims":[{"t":"gasJar","x":32,"y":32,"w":22,"h":28,"liquid":0.2,"color":"colorless"},{"t":"rect","x":22,"y":15.5,"w":20,"h":2.5,"fill":true},{"t":"line","x1":21,"y1":40.4,"x2":43,"y2":40.4,"tone":"accent","width":0.7},{"t":"text","x":46,"y":40.4,"text":"水面（约 1/5 体积）","anchor":"start","size":3.4,"tone":"accent"},{"t":"text","x":32,"y":26,"text":"剩余的氮气","size":3.4,"tone":"muted"},{"t":"curve","points":[[40,17],[56,12],[74,13],[74,50]]},{"t":"beaker","x":64,"y":36,"w":22,"h":20,"fill":0.35},{"t":"text","x":75,"y":60,"text":"烧杯中的水减少","size":3.4,"tone":"muted"}]}},{"id":"chem-substance-1-m1-q1","type":"short","stem":"（3 分）材料一中含量最多的气体是什么？它在空气中的含量用体积分数表示是多少？空气属于纯净物还是混合物？请说明判断依据。","answer":"含量最多的气体是氮气；它约占空气体积的 78%；空气属于混合物。判断依据：空气由氮气、氧气、稀有气体、二氧化碳等多种物质组成，没有固定的化学式。","explain":"","rubric":["答出「氮气」","含量写成「约占空气体积的 78%」，写出体积分数而不是质量分数","答出「混合物」并说出依据「由多种物质组成」"]},{"id":"chem-substance-1-m1-q2","type":"short","stem":"（4 分）根据材料三，计算该同学测得的空气中氧气的体积分数（结果保留一位小数），并说明结果与理论值有偏差的一条可能原因。","answer":"进入瓶内水的体积就等于被消耗的氧气的体积，所以氧气的体积分数 = 45 mL ÷ 250 mL × 100% = 18.0%，小于理论值 21%。可能原因：红磷的量不足，瓶内氧气没有被完全消耗（或装置漏气，外界空气进入瓶内；或没有冷却到室温就打开弹簧夹，瓶内气体受热膨胀占体积）。","explain":"","rubric":["写出计算式「45 mL ÷ 250 mL × 100%」（或等效表述）","算出 18.0%（写成 18% 同样给分）","给出一条合理原因","说明这条原因为什么会使结果偏小（如「氧气没被完全消耗」）"]},{"id":"chem-substance-1-m1-q3","type":"short","stem":"（3 分）材料二中的首要污染物属于哪一类空气污染物？再写出一种有害气体类的空气污染物，并针对这种污染物提出一条防治措施。","answer":"可吸入颗粒物（PM10）属于烟尘类污染物；有害气体如二氧化硫 SO₂（或二氧化氮 NO₂、一氧化碳 CO）；针对二氧化硫可采取的防治措施：燃煤时进行脱硫处理、使用清洁能源代替直接燃煤、废气处理达标后排放。","explain":"","rubric":["答出「可吸入颗粒物（PM10）」属于烟尘（颗粒物）类污染物","写出一种有害气体并写出正确的化学式（SO₂、NO₂、CO 等）","防治措施与所写污染物对应，且具体可操作"]}]},{"id":"chem-substance-2","title":"氧气的性质：物理性质·与碳硫磷铁镁的反应·氧化反应与化合反应","subtitle":"人教版九年级 · 第二单元 我们周围的空气 · 9a","grade":"9a","tags":["人教版九年级 · 第二单元 我们周围的空气"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第二单元 我们周围的空气 · 9a"},{"type":"note","title":"问题切入","text":"一瓶无色气体，把带火星的木条伸进去木条复燃，它就是氧气——凭的是什么？木炭、硫、磷、铁丝、镁条在氧气里燃烧的样子各不相同，「白光」「明亮的蓝紫色火焰」「火星四射」这些现象该怎么描述才不失分？它们又分别属于哪一类反应？"},{"type":"note","title":"一句话抓住关键","text":"氧气是一种化学性质比较活泼的气体，能跟许多物质反应并放出热量；同样的物质在氧气中燃烧比在空气中剧烈得多，说明氧气的浓度越大，燃烧越剧烈。物质与氧发生的反应叫氧化反应，其中由两种或两种以上物质生成另一种物质的反应叫化合反应——两者是交叉关系，不是一回事。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"把带火星的木条伸进一瓶气体，木条「啪」地复燃了，这瓶气体多半就是氧气。氧气本身不能燃烧，但它能大力支持燃烧，就像给火添了一把风。","walk":["氧气的物理性质：无色无味气体，不易溶于水，密度比空气略大，液态和固态时呈淡蓝色。","氧气的化学性质是助燃性和氧化性：木炭在氧气中发出白光，硫在氧气中发出明亮的蓝紫色火焰，红磷产生大量白烟，铁丝火星四射生成黑色固体，镁条发出耀眼白光。","这些反应都是氧化反应；其中由两种物质生成一种物质的，又属于化合反应。描述现象只写「看到什么、感到什么」，不要直接把产物名称当现象。"],"try":"观察一根燃着的木条在空气中与在纯氧中的区别（由老师演示）：空气中的火焰小、发黄，纯氧中的火焰更亮更旺，说明氧气浓度越高燃烧越剧烈。","use":["现象描述按「光/焰/烟、放热、生成物颜色状态」三块写，别漏「放出热量」。","写方程式时条件、配平、箭头都要齐全，现象和方程式是两回事。"]},{"type":"h","text":"【宏观】宏观：氧气的物理性质与检验方法"},{"type":"p","text":"通常状况下氧气是无色、无味的气体，不易溶于水，密度比空气略大（所以能用向上排空气法收集，也能用排水法收集）。在加压降温的条件下，氧气会变成淡蓝色的液体，继续降温得到淡蓝色雪花状的固体。检验氧气的方法是把带火星的木条伸入集气瓶中，木条复燃，说明瓶内是氧气——利用的正是「氧气能支持燃烧」这一性质。"},{"type":"figure","figure":{"id":"fig-chem-substance-2-1","title":"氧气的三态变化与检验方法","caption":"气态无色，液态和固态都是淡蓝色；带火星的木条复燃可检验氧气","view":"wide","alt":"左边集气瓶中是无色氧气，箭头标注降温加压后，中间的集气瓶中出现淡蓝色的液态氧，右边说明用带火星的木条检验氧气时木条复燃","prims":[{"t":"gasJar","x":16,"y":26,"w":20,"h":26,"color":"colorless"},{"t":"text","x":16,"y":56,"text":"氧气（无色）","size":3.4},{"t":"arrow","x1":28,"y1":24,"x2":42,"y2":24,"label":"降温加压","labelDy":-4},{"t":"gasJar","x":54,"y":26,"w":20,"h":26,"liquid":0.6,"color":"blue"},{"t":"text","x":54,"y":56,"text":"液态氧（淡蓝色）","size":3.4},{"t":"line","x1":72,"y1":20,"x2":82,"y2":32,"width":0.8},{"t":"poly","points":[[82,20],[88,20],[88,26],[82,26]],"fill":true,"tone":"danger"},{"t":"text","x":84,"y":42,"text":"带火星的木条","size":3.2,"tone":"muted"},{"t":"text","x":84,"y":49,"text":"复燃 → 是氧气","size":3.2,"tone":"accent"}]}},{"type":"note","title":"","text":"「不易溶于水」是氧气能用排水法收集的原因；「密度比空气略大」是它能用向上排空气法收集的原因。不要把「不易溶于水」写成「不溶于水」——水中溶有少量氧气，鱼儿才能呼吸。"},{"type":"h","text":"【宏观】宏观实验：几种物质在氧气中燃烧的现象"},{"type":"p","text":"把点燃的木炭伸进氧气里，木炭剧烈燃烧、发出白光；把燃着的硫伸进去，发出明亮的蓝紫色火焰，生成有刺激性气味的气体；红磷燃烧产生大量白烟；细铁丝在氧气中剧烈燃烧、火星四射，生成黑色固体；镁条燃烧发出耀眼的白光，生成白色固体。把这些现象排在一起看就会发现一条规律：同样的物质在氧气中比在空气中燃烧得更剧烈、更明亮，因为氧气浓度更大了。"},{"type":"figure","figure":{"id":"fig-chem-substance-2-2","title":"硫在氧气中燃烧的装置","caption":"瓶底预先放少量水，用来吸收生成的二氧化硫","view":"wide","alt":"集气瓶内充满氧气，燃烧匙中的硫燃烧发出明亮的蓝紫色火焰，瓶底放有少量水用来吸收生成的二氧化硫","prims":[{"t":"gasJar","x":46,"y":30,"w":26,"h":28,"liquid":0.2,"color":"colorless"},{"t":"rect","x":36,"y":13.5,"w":20,"h":2.5,"fill":true},{"t":"line","x1":46,"y1":16,"x2":46,"y2":21.5,"width":0.7},{"t":"circle","cx":46,"cy":24,"r":3.2,"fill":true,"tone":"accent"},{"t":"text","x":63,"y":22,"text":"燃烧匙中的硫","anchor":"start","size":3.4},{"t":"text","x":46,"y":8,"text":"瓶内充满氧气","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":56,"text":"瓶底放少量水：吸收 SO₂，防止污染空气","size":3.4,"tone":"muted"},{"t":"text","x":18,"y":24,"text":"明亮的","size":3.4,"tone":"accent"},{"t":"text","x":18,"y":31,"text":"蓝紫色火焰","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"现象描述的红线：硫在氧气中是「明亮的蓝紫色火焰」，在空气中是「淡蓝色火焰」；铁丝是「火星四射，生成黑色固体」，不能写「生成黑色气体」；木炭是「发出白光」，不是「产生白色火焰」。"},{"type":"h","text":"【微观】微观：燃烧时分子被拆开，原子重新组合"},{"type":"p","text":"把木炭在氧气中燃烧的过程放大到粒子层面：木炭的主要成分是碳，碳由碳原子构成；氧气由氧分子构成。点燃后，氧分子被拆成氧原子，氧原子与碳原子重新组合成二氧化碳分子——1 个碳原子结合 1 个氧分子，生成 1 个二氧化碳分子。硫燃烧也是一样：1 个硫原子结合 1 个氧分子，生成 1 个二氧化硫分子。整个过程里，原子的种类没有变、个数也没有变，变的只是「谁和谁在一起」，所以反应前后物质的总质量相等。"},{"type":"figure","figure":{"id":"fig-chem-substance-2-3","title":"碳、硫在氧气中燃烧的粒子变化","caption":"分子被拆成原子，原子重新组合成新分子，原子的种类和个数不变","view":"wide","alt":"碳原子与氧分子在点燃条件下重新组合成二氧化碳分子，硫原子与氧分子重新组合成二氧化硫分子，反应前后原子的种类和个数都没有改变","prims":[{"t":"atom","x":10,"y":16,"symbol":"C","color":"black","label":"碳原子"},{"t":"molecule","x":10,"y":38,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"氧分子"},{"t":"arrow","x1":22,"y1":26,"x2":36,"y2":26,"label":"点燃","labelDy":-4},{"t":"molecule","x":50,"y":16,"atoms":[{"dx":-4.4,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":0,"r":3.8,"symbol":"C","color":"black"},{"dx":4.4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"molecule","x":50,"y":40,"atoms":[{"dx":0,"dy":0,"symbol":"S","color":"yellow"},{"dx":5,"dy":-3,"symbol":"O","color":"red"},{"dx":5,"dy":3,"symbol":"O","color":"red"}],"bonds":[[0,1],[0,2]],"label":"SO₂"},{"t":"text","x":78,"y":26,"text":"原子种类、个数不变","size":3.4,"tone":"muted"},{"t":"text","x":78,"y":33,"text":"总质量不变","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"初中对氧化反应的现象描述不要求从电子得失解释，但微观上必须说清「分子分成原子、原子重新组合」这两步，第 3 步「原子的种类和个数不变」正是质量守恒定律的微观解释。"},{"type":"h","text":"【符号】符号：方程式怎么配平，反应类型怎么判断"},{"type":"p","text":"这一组反应的方程式要逐条写对、配平：C + O₂ —点燃→ CO₂；S + O₂ —点燃→ SO₂；4P + 5O₂ —点燃→ 2P₂O₅；3Fe + 2O₂ —点燃→ Fe₃O₄；2Mg + O₂ —点燃→ 2MgO。配平的检验方法只有一个：数一数两边每种元素的原子个数是否相等，例如 3Fe + 2O₂ 的左边有 3 个铁原子、4 个氧原子，Fe₃O₄ 里恰好是 3 个铁原子和 4 个氧原子。判断反应类型：这些反应都是「多变一」，属于化合反应；同时它们都有氧参加，又都是氧化反应。"},{"type":"figure","figure":{"id":"fig-chem-substance-2-4","title":"氧化反应与化合反应是交叉关系","caption":"有些氧化反应不是化合反应，有些化合反应也不是氧化反应","view":"square","alt":"两个相交的圆分别表示氧化反应和化合反应，重叠部分是以铁燃烧为代表的既氧化又化合的反应，左边单独一块是石蜡燃烧，右边单独一块是氧化钙与水反应","prims":[{"t":"circle","cx":36,"cy":42,"r":22,"tone":"accent"},{"t":"circle","cx":64,"cy":42,"r":22,"tone":"ok"},{"t":"text","x":28,"y":14,"text":"氧化反应","size":4,"tone":"accent"},{"t":"text","x":72,"y":14,"text":"化合反应","size":4,"tone":"ok"},{"t":"text","x":22,"y":42,"text":"石蜡燃烧","size":3.2},{"t":"text","x":50,"y":42,"text":"铁燃烧","size":3.2},{"t":"text","x":78,"y":42,"text":"CaO 与水","size":3.2},{"t":"text","x":22,"y":33,"text":"有氧参加","size":3,"tone":"muted"},{"t":"text","x":78,"y":33,"text":"多变一","size":3,"tone":"muted"},{"t":"text","x":50,"y":74,"text":"两圆重叠处：既属于氧化反应，又属于化合反应","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":82,"text":"3Fe + 2O₂ —点燃→ Fe₃O₄","size":3.4}]}},{"type":"note","title":"","text":"常见的三种「氧化反应但不是化合反应」：石蜡燃烧、甲烷燃烧、酒精燃烧——它们的生成物都有两种。常见的「化合反应但不是氧化反应」：CaO + H₂O = Ca(OH)₂、CO₂ + H₂O = H₂CO₃。"},{"type":"h","text":"【应用】应用：氧气能做什么"},{"type":"p","text":"氧气的用途都由「能供给呼吸」和「能支持燃烧」两条性质决定：医疗上给病人输氧、潜水员和登山运动员背氧气瓶、航空供氧靠的是供给呼吸；气焊与气割（氧炔焰）、炼钢时吹氧、火箭助燃剂靠的是支持燃烧。反过来，这些性质也带来风险：氧气瓶附近严禁明火和油脂，油污遇到高压氧气会剧烈燃烧甚至爆炸；仓库、地窖里氧气含量过高会加速金属锈蚀和有机物腐败。"},{"type":"note","title":"","text":"答题时要把「性质」和「用途」对应起来写：氧气能支持燃烧 → 用于气焊、炼钢；氧气能供给呼吸 → 用于医疗急救、潜水。只写用途不写性质，说理题会丢分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["化学方程式的质量比","各物质的质量比 = 化学计量数 × 相对分子质量之比，如 3Fe + 2O₂ —点燃→ Fe₃O₄ 中 m(Fe)∶m(O₂)∶m(Fe₃O₄) = 168∶64∶232","化学方程式计算的依据，适用于所有已配平的化学方程式。算出比例后，只有参加反应的纯物质质量才能代入：混合物、溶液都要先换算成纯物质的质量。"],["相对分子质量","O₂ 的相对分子质量 = 16×2 = 32；Fe₃O₄ 的相对分子质量 = 56×3 + 16×4 = 232","用于化学方程式计算里求质量比，也用于判断气体密度大小（同温同压下，相对分子质量越大密度越大，所以氧气比空气略重）。计算时各元素的相对原子质量取整数：O 16、Fe 56、Mg 24。"],["元素的质量分数","某元素的质量分数 = 该元素的相对原子质量 × 原子个数 ÷ 相对分子质量 × 100%","用于计算纯净物中某元素所占的比例，如 MgO 中镁元素的质量分数 = 24 ÷ 40 × 100% = 60%。只能用于纯净物；混合物要先按纯度折算，且不能直接用化学式计算混合物中元素的质量分数。"]]},{"type":"h","text":"应用 · 带火星的木条为什么能检验氧气"},{"type":"note","title":"情境","text":"实验室里有一瓶无色气体，把带火星的木条伸入瓶中，木条重新燃烧起来。这瓶气体是什么？为什么木条会复燃？"},{"type":"list","title":"解答步骤","items":["先看现象：带火星的木条伸入后复燃，说明该气体能支持燃烧。","再对应性质：氧气能支持燃烧，是常见的助燃剂，所以瓶内气体是氧气。","补充理由：空气中氧气只占约 21%，带火星的木条在空气中只能慢慢熄灭；瓶内氧气浓度大，木条才能复燃。","答：这瓶气体是氧气；木条复燃是因为氧气能支持燃烧，瓶内氧气的浓度比空气中大。"]},{"type":"note","title":"结论","text":"结论是氧气。答题时要同时写出现象（复燃）和对应的性质（支持燃烧），只说「因为它是氧气」属于循环论证，不得分。"},{"type":"h","text":"应用 · 镁条燃烧的质量关系"},{"type":"note","title":"情境","text":"把 4.8 g 镁条放在空气中完全燃烧，镁全部变成了白色固体氧化镁。求参加反应的氧气质量和生成的氧化镁质量。（相对原子质量：Mg 24、O 16）"},{"type":"list","title":"解答步骤","items":["写出并配平化学方程式：2Mg + O₂ —点燃→ 2MgO。","算出相对质量：2Mg = 48，O₂ = 32，2MgO = 80。","设参加反应的氧气质量为 x：48∶32 = 4.8 g∶x，解得 x = 3.2 g。","设生成的氧化镁质量为 y：48∶80 = 4.8 g∶y，解得 y = 8 g。","验算：4.8 g + 3.2 g = 8 g，与质量守恒定律相符。"]},{"type":"note","title":"结论","text":"参加反应的氧气质量为 3.2 g，生成的氧化镁质量为 8 g。验算「反应物质量之和 = 生成物质量」是这类题最好的自检方法。"},{"type":"h","text":"实验 1 · 铁丝在氧气中燃烧"},{"type":"note","title":"实验目的","text":"观察铁丝在氧气中燃烧的现象，认识「氧气的浓度越大，燃烧越剧烈」，并掌握该实验的操作与安全要点。"},{"type":"list","title":"实验器材","items":["集气瓶（内盛少量水或铺一层细沙）","细铁丝（绕成螺旋状）","火柴","酒精灯","氧气（预先收集好的集气瓶）"]},{"type":"figure","figure":{"id":"fig-chem-substance-2-exp1","title":"铁丝在氧气中燃烧","caption":"铁丝绕成螺旋状、下端系一根火柴，瓶底预先放少量水或铺一层细沙","view":"wide","alt":"集气瓶内充满氧气、瓶底有少量水，一根绕成螺旋状的铁丝下端系着火柴伸入瓶中，铁丝正在剧烈燃烧、火星四射","prims":[{"t":"gasJar","x":40,"y":32,"w":26,"h":30,"liquid":0.22,"color":"colorless"},{"t":"rect","x":30,"y":15,"w":20,"h":2.5,"fill":true},{"t":"line","x1":40,"y1":17.5,"x2":40,"y2":38,"width":0.7},{"t":"circle","cx":40,"cy":23,"r":3.6},{"t":"circle","cx":40,"cy":27.5,"r":3.6},{"t":"circle","cx":40,"cy":32,"r":3.6},{"t":"line","x1":37.6,"y1":38,"x2":42.4,"y2":38,"width":1.8},{"t":"text","x":58,"y":24,"text":"铁丝绕成螺旋状","anchor":"start","size":3.4},{"t":"text","x":58,"y":31,"text":"（增大受热面积）","anchor":"start","size":3.2,"tone":"muted"},{"t":"text","x":58,"y":38,"text":"下端系一根火柴","anchor":"start","size":3.4},{"t":"text","x":40,"y":52,"text":"瓶底预先放少量水或铺一层细沙","size":3.4,"tone":"accent"},{"t":"text","x":16,"y":24,"text":"集气瓶内","size":3.2,"tone":"muted"},{"t":"text","x":16,"y":30,"text":"充满氧气","size":3.2,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["把细铁丝绕成螺旋状，下端系一根火柴，另一端固定在橡皮塞的弯钩上。","在集气瓶底部预先放少量水或铺一层细沙，瓶内收集满氧气并用玻璃片盖住。","点燃火柴，待火柴快燃尽时，把铁丝连同橡皮塞一起伸入集气瓶中（不要立即塞紧，以免瓶内气体受热膨胀冲出）。","观察铁丝燃烧的现象，反应结束后取出铁丝，观察瓶中生成物的颜色和状态。"]},{"type":"note","title":"实验现象","text":"铁丝在氧气中剧烈燃烧，火星四射，放出大量热，生成黑色固体，瓶底的水（或细沙）上落有黑色熔化物。"},{"type":"note","title":"实验结论","text":"铁在氧气中燃烧生成四氧化三铁，化学方程式为 3Fe + 2O₂ —点燃→ Fe₃O₄。同样的铁丝在空气中只能烧至红热、不能燃烧，说明氧气浓度越大燃烧越剧烈。"},{"type":"list","title":"注意事项","items":["瓶底必须预先放少量水或铺一层细沙：防止高温熔化物溅落，炸裂瓶底。","铁丝必须绕成螺旋状：增大铁丝与氧气的接触面积、使热量集中，便于铁丝持续燃烧。","铁丝下端必须系一根火柴：火柴燃烧放出的热量使铁丝温度升高到着火点，起到引燃作用。","必须待火柴快燃尽时再把铁丝伸入瓶中：伸入过早，火柴燃烧会消耗瓶内氧气，导致铁丝不能燃烧或燃烧不剧烈。","实验结束后不要用手直接触摸集气瓶底部与黑色固体，防止烫伤；未完全冷却前不能加水。"]},{"type":"h","text":"实验 2 · 硫在氧气中燃烧（与在空气中燃烧对比）"},{"type":"note","title":"实验目的","text":"观察硫在空气中和在氧气中燃烧的不同现象，认识氧气浓度对燃烧剧烈程度的影响，学会用对比实验控制变量。"},{"type":"list","title":"实验器材","items":["集气瓶（内盛少量水）","燃烧匙","硫粉","酒精灯","氧气（预先收集）"]},{"type":"figure","figure":{"id":"fig-chem-substance-2-exp2","title":"硫在氧气中燃烧","caption":"瓶内充满氧气，瓶底放少量水吸收生成的 SO₂","view":"wide","alt":"集气瓶内充满氧气、瓶底有少量水，燃烧匙中的硫燃烧发出明亮的蓝紫色火焰，生成有刺激性气味的气体","prims":[{"t":"gasJar","x":40,"y":32,"w":26,"h":30,"liquid":0.2,"color":"colorless"},{"t":"rect","x":30,"y":15,"w":20,"h":2.5,"fill":true},{"t":"line","x1":40,"y1":17.5,"x2":40,"y2":23,"width":0.7},{"t":"circle","cx":40,"cy":25.5,"r":3.4,"fill":true,"tone":"accent"},{"t":"text","x":58,"y":22,"text":"明亮的蓝紫色火焰","anchor":"start","size":3.4,"tone":"accent"},{"t":"text","x":58,"y":29,"text":"燃烧匙中的硫","anchor":"start","size":3.2,"tone":"muted"},{"t":"text","x":40,"y":52,"text":"瓶底放少量水：吸收 SO₂，防止污染空气","size":3.4,"tone":"muted"},{"t":"text","x":16,"y":26,"text":"空气中","size":3.2,"tone":"muted"},{"t":"text","x":16,"y":32,"text":"淡蓝色火焰","size":3.2,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["在集气瓶底部放少量水，收集满氧气后用玻璃片盖住备用。","取少量硫粉放在燃烧匙中，在酒精灯上加热至燃烧，观察硫在空气中燃烧的火焰颜色。","迅速把燃烧匙伸入盛有氧气的集气瓶中，观察火焰颜色、放出热量与气味。","反应结束后把燃烧匙取出，观察瓶中水面上方气体的颜色与气味（在通风处进行）。"]},{"type":"note","title":"实验现象","text":"硫在空气中燃烧发出微弱的淡蓝色火焰；在氧气中燃烧发出明亮的蓝紫色火焰，放出热量，生成有刺激性气味的气体。"},{"type":"note","title":"实验结论","text":"硫在氧气中燃烧生成二氧化硫，化学方程式为 S + O₂ —点燃→ SO₂。同一物质在氧气中燃烧比在空气中剧烈，说明氧气的浓度越大，燃烧越剧烈。"},{"type":"list","title":"注意事项","items":["瓶底预先放少量水：SO₂ 有毒且能溶于水，放水可以吸收大部分 SO₂，防止污染空气。","整个实验要在通风处进行，闻气体气味时用手轻轻扇动，让少量气体飘进鼻孔，不能把鼻子凑到瓶口直接闻。","不能用嘴吹灭酒精灯：要用灯帽盖灭；实验中如果需要熄灭酒精灯，也必须用灯帽。","燃烧匙伸入集气瓶时要迅速，防止瓶内氧气受热逸出过多；伸入后不要立即塞紧瓶塞。","取用硫粉要少量，实验后剩余的硫不能随意丢弃，要按要求处理。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["C + O₂ —点燃→ CO₂","点燃","木炭在氧气中剧烈燃烧，发出白光，放出热量，生成能使澄清石灰水变浑浊的气体","配平：1 个碳原子与 1 个氧分子恰好生成 1 个二氧化碳分子，系数都是 1，不需要额外配平。注意「发出白光」指的是灼热的固体发光，不是火焰；木炭在空气中燃烧只是红热，不发白光——差别就在氧气的浓度。"],["S + O₂ —点燃→ SO₂","点燃","硫在氧气中燃烧发出明亮的蓝紫色火焰，放出热量，生成有刺激性气味的气体","现象必须写成「明亮的蓝紫色火焰」（在空气中是淡蓝色火焰）。瓶底预先放少量水用来吸收 SO₂，防止污染空气。SO₂ 中的硫为 +4 价，化学式是 SO₂ 不是 SO₃，下标写错整条方程式都错。"],["4P + 5O₂ —点燃→ 2P₂O₅","点燃","红磷燃烧产生大量白烟，放出热量（可用于测定空气中氧气的含量）","配平：先定 P₂O₅ 的系数为 2，则 P 的系数为 4、O₂ 的系数为 5，两边 P 都是 4 个、O 都是 10 个。现象是「白烟」（固体小颗粒），绝不能写成「白雾」。"],["3Fe + 2O₂ —点燃→ Fe₃O₄","点燃","铁丝在氧气中剧烈燃烧，火星四射，放出大量热，生成黑色固体","配平：左边 3 个 Fe、4 个 O，与 Fe₃O₄ 中的 3 个 Fe、4 个 O 相等。产物是四氧化三铁 Fe₃O₄，不能写成 Fe₂O₃（铁生锈的产物）或 FeO。注意只有「铁丝在氧气中点燃」才写这个方程式，铁在空气中生锈是缓慢氧化。"],["2Mg + O₂ —点燃→ 2MgO","点燃","镁条在空气（或氧气）中剧烈燃烧，发出耀眼的白光，放出大量热，生成白色固体","配平：把 MgO 的系数定为 2，则 Mg 为 2、O₂ 为 1，两边 Mg 各 2 个、O 各 2 个。注意 MgO 中镁为 +2 价，化学式是 MgO 不是 MgO₂；镁燃烧发出的是「耀眼的白光」，是照明弹与烟花发光的原理。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["铁丝在氧气中燃烧，生成黑色的气体。","铁丝在氧气中剧烈燃烧，火星四射，放出大量热，生成黑色固体四氧化三铁。","把「固体」写成了「气体」。四氧化三铁 Fe₃O₄ 是黑色固体，落到瓶底还能看到黑色熔化物，这一点也是瓶底要放水或细沙的原因。"],["硫在氧气中燃烧发出淡蓝色火焰。","硫在空气中燃烧发出微弱的淡蓝色火焰，在氧气中燃烧发出明亮的蓝紫色火焰。","把两种情境下的现象记混了。氧气的浓度越大，燃烧越剧烈，火焰的颜色也越明亮，所以「蓝紫色」对应氧气、「淡蓝色」对应空气，两个词不能互换。"],["木炭在氧气中燃烧发出白光，说明木炭燃烧产生了火焰。","木炭在氧气中燃烧发出白光，放出热量，没有火焰；白光是灼热的固体发出的。","火焰是气体（或蒸气）燃烧的现象。木炭是固体，燃烧时是固体直接发光发热，所以只能说「发出白光」。「发出白色火焰」是常见错误说法。"],["氧化反应一定是化合反应。","氧化反应与化合反应是交叉关系：铁燃烧既是氧化反应又是化合反应，而石蜡燃烧是氧化反应但不是化合反应。","两个概念从不同角度分类：氧化反应看「有没有氧参加」，化合反应看「是不是多变一」。石蜡燃烧生成二氧化碳和水两种产物，属于「多变多」，故不是化合反应。"]]},{"type":"table","title":"几种物质在空气与氧气中燃烧的现象对照（同一物质在空气、氧气中燃烧的剧烈程度与现象差异）","head":["比较项","在空气中","在氧气中"],"rows":[["木炭","持续红热，无火焰，不发白光","剧烈燃烧，发出白光，放出热量"],["硫","发出微弱的淡蓝色火焰","发出明亮的蓝紫色火焰"],["红磷","燃烧产生大量白烟","燃烧更剧烈，产生大量白烟，放热更明显"],["铁丝","只能烧至红热，不能燃烧","剧烈燃烧，火星四射，生成黑色固体"],["共同结论","氧气浓度较小，燃烧较缓和","氧气浓度较大，燃烧更剧烈、更明亮"]]},{"type":"table","title":"氧化反应与化合反应的区别（两个概念的判断依据与相互关系）","head":["比较项","氧化反应","化合反应"],"rows":[["判断依据","物质与氧发生的反应","两种或两种以上物质生成另一种物质的反应"],["例子","石蜡燃烧：石蜡 + O₂ → CO₂ + H₂O","CaO + H₂O = Ca(OH)₂"],["交集","铁燃烧：3Fe + 2O₂ —点燃→ Fe₃O₄","铁燃烧：3Fe + 2O₂ —点燃→ Fe₃O₄"],["数量关系","不一定是化合反应","不一定是氧化反应"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["实验现象的描述与判断","高频选择与填空题：给出几个现象描述让学生挑出正确的，或让学生把现象补写完整。判分点全在「颜色的准确词」「固体还是气体」「烟还是雾」上，硫的蓝紫色火焰、铁丝的火星四射与黑色固体是必考现象。"],["实验操作与安全意识","以铁丝燃烧的装置图为情境，考「瓶底为什么要放水或细沙」「铁丝为什么要绕成螺旋状」「为什么待火柴快燃尽时才伸入」。这类题必须写清操作背后的目的，不能只答「防止发生危险」。"],["化学用语与反应类型判断","要求书写并配平碳、硫、磷、铁、镁燃烧的化学方程式，判断属于化合反应还是分解反应，并说明该反应是否属于氧化反应。Fe₃O₄ 的化学式与配平系数是常见失分点。"],["方程式计算与质量守恒","用燃烧反应考相对质量比计算（已知某物质质量求另一物质质量），并常与质量守恒定律结合，要求用「反应物质量之和等于生成物质量之和」来验算或解释。"]]},{"type":"quote","text":"【材料一】某同学把一根细铁丝绕成螺旋状，下端系一根火柴，点燃火柴，待火柴快燃尽时把铁丝伸入盛有氧气的集气瓶中（瓶底预先放有少量水）。观察到铁丝剧烈燃烧、火星四射，生成黑色固体。【材料二】另一位同学把 3.2 g 硫粉放在燃烧匙中加热至燃烧，先观察它在空气中的火焰，再迅速伸入盛有氧气的集气瓶中（瓶底预先放有少量水），观察到明亮的蓝紫色火焰，生成有刺激性气味的气体。【材料三】经检验，铁的燃烧产物是 Fe₃O₄，硫的燃烧产物是 SO₂。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）写出材料一中铁丝在氧气中燃烧的现象，并写出该反应的化学方程式。","【设问】（4 分）根据材料二计算：3.2 g 硫完全燃烧需要消耗多少克氧气？生成多少克二氧化硫？（相对原子质量：S 32、O 16）","【设问】（3 分）材料一与材料二中，集气瓶底部都预先放了少量水。这两处水的作用是否相同？请分别说明。"]}],"questions":[{"id":"chem-substance-2-q1","type":"choice","stem":"如图是铁丝在氧气中燃烧的实验装置。下列关于该实验的说法正确的是（　）","answer":"C","explain":"C 正确：火柴燃烧放出的热量使铁丝温度升高到着火点，起引燃作用。A 把目的说错了：瓶底放水（或细沙）是为了防止高温熔化物溅落炸裂瓶底，黑色固体 Fe₃O₄ 落在水里只是现象，不是放水的目的。B 错：绕成螺旋状能增大铁丝与氧气的接触面积、使热量集中，便于持续燃烧。D 错：必须待火柴快燃尽时再伸入，伸入过早火柴燃烧会消耗瓶内氧气，导致铁丝燃烧不剧烈甚至不燃烧。","options":["瓶底预先放少量水，是为了吸收生成的黑色固体","铁丝绕成螺旋状只是为了好看，与实验效果无关","铁丝下端系一根火柴，是为了引燃铁丝","火柴点燃后应立即把铁丝伸入瓶中，以免火柴烧完"],"difficulty":2,"tags":["氧气","铁丝燃烧","实验操作"],"figure":{"id":"fig-chem-substance-2-q1","title":"铁丝在氧气中燃烧的装置","caption":"判断哪一个说法正确","view":"wide","alt":"集气瓶内充满氧气、瓶底有少量水，一根绕成螺旋状、下端系着火柴的铁丝伸入瓶中燃烧，火星四射","prims":[{"t":"gasJar","x":40,"y":32,"w":26,"h":30,"liquid":0.22,"color":"colorless"},{"t":"rect","x":30,"y":15,"w":20,"h":2.5,"fill":true},{"t":"line","x1":40,"y1":17.5,"x2":40,"y2":38,"width":0.7},{"t":"circle","cx":40,"cy":23,"r":3.6},{"t":"circle","cx":40,"cy":27.5,"r":3.6},{"t":"circle","cx":40,"cy":32,"r":3.6},{"t":"line","x1":37.6,"y1":38,"x2":42.4,"y2":38,"width":1.8},{"t":"text","x":58,"y":24,"text":"铁丝（螺旋状）","anchor":"start","size":3.4},{"t":"text","x":58,"y":31,"text":"下端系火柴","anchor":"start","size":3.4},{"t":"text","x":40,"y":52,"text":"瓶底有少量水","size":3.4,"tone":"muted"}]}},{"id":"chem-substance-2-q2","type":"choice","stem":"下列有关实验现象的描述正确的是（　）","answer":"D","explain":"D 正确：镁燃烧发出耀眼的白光、生成白色固体 MgO，这也是照明弹和烟花发光的原理。A 把颜色记错了：硫在氧气中是「明亮的蓝紫色火焰」，淡蓝色火焰是它在空气中燃烧的现象。B 把状态写错了：四氧化三铁是黑色固体，不是气体。C 把「烟」写成了「雾」：红磷燃烧生成的是白色固体小颗粒 P₂O₅，应写「大量白烟」。","options":["硫在氧气中燃烧发出淡蓝色火焰","铁丝在氧气中燃烧生成黑色的气体","红磷在氧气中燃烧产生大量白雾","镁条在空气中燃烧发出耀眼的白光，生成白色固体"],"difficulty":1,"tags":["氧气","燃烧现象"]},{"id":"chem-substance-2-q3","type":"choice","stem":"关于氧化反应和化合反应，下列说法正确的是（　）","answer":"A","explain":"A 正确：石蜡燃烧有氧参加，属于氧化反应；但生成物有 CO₂ 和 H₂O 两种，不符合「多变一」，不是化合反应。B 错：氧化反应与化合反应是交叉关系，铁燃烧既氧化又化合，石蜡燃烧只氧化不化合。C 前后矛盾：CaO + H₂O = Ca(OH)₂ 是化合反应，但没有氧气参加，不是氧化反应，用它来证明「化合反应一定是氧化反应」恰好举错了例子。D 错：物质与氧气的反应生成两种或两种以上产物时就不是化合反应，例如石蜡、甲烷的燃烧。","options":["石蜡燃烧生成二氧化碳和水，它是氧化反应但不是化合反应","氧化反应一定是化合反应","化合反应一定是氧化反应，例如氧化钙与水反应","物质与氧气发生的反应都属于化合反应"],"difficulty":2,"tags":["氧气","氧化反应","化合反应"]},{"id":"chem-substance-2-q4","type":"choice","stem":"下列关于氧气性质的说法正确的是（　）","answer":"B","explain":"B 正确：气体不易溶于水就可以用排水法收集，氧气正符合这一条件，而且排水法收集到的气体更纯净。A 混淆了「助燃性」和「可燃性」：氧气本身不能燃烧，它是助燃剂。C 颜色说错了：液态氧和固态氧都是淡蓝色，不是白色。D 绝对化：氧气化学性质比较活泼，但不是跟所有物质反应，金、铂等贵金属在常温下就几乎不与氧气反应。","options":["氧气能支持燃烧，因此氧气具有可燃性","氧气不易溶于水，因此可以用排水法收集氧气","液态氧是白色的，可用于医疗急救","氧气能跟所有物质发生反应"],"difficulty":1,"tags":["氧气","氧气的性质与收集"]},{"id":"chem-substance-2-q5","type":"choice","stem":"下列反应中属于化合反应的是（　）","answer":"C","explain":"C 正确：铁与氧气两种物质生成四氧化三铁一种物质，符合「多变一」，属于化合反应（同时也是氧化反应）。A 是「一变多」，属于分解反应。B 是单质与化合物反应生成另一种单质与另一种化合物，不属于化合反应。D 是两种化合物互相交换成分生成两种新化合物，也不属于化合反应。判断类型只看反应物与生成物的种类数目，不看反应条件。","options":["2H₂O —通电→ 2H₂↑ + O₂↑","C + 2CuO —高温→ 2Cu + CO₂↑","3Fe + 2O₂ —点燃→ Fe₃O₄","CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑"],"difficulty":2,"tags":["氧气","化合反应","反应类型"]},{"id":"chem-substance-2-q6","type":"fill","stem":"铁丝在氧气中燃烧生成的黑色固体的化学式是 ______。","answer":"Fe₃O₄|Fe3O4","explain":"铁在氧气中燃烧生成四氧化三铁，化学式是 Fe₃O₄。写成 Fe₂O₃ 是铁生锈（缓慢氧化）的产物，写成 FeO 也不对——四氧化三铁里的铁既有 +2 价又有 +3 价，初中只要求记住化学式 Fe₃O₄。下标必须写在元素符号的右下角。","difficulty":2,"tags":["氧气","化学式","铁燃烧"]},{"id":"chem-substance-2-q7","type":"fill","stem":"把 4.8 g 镁条放在氧气中完全燃烧，生成氧化镁 ______ g。（相对原子质量：Mg 24、O 16）","answer":"8","explain":"由 2Mg + O₂ —点燃→ 2MgO 可知，镁与氧化镁的质量比为 (2×24)∶(2×40) = 48∶80 = 3∶5，所以 4.8 g 镁完全燃烧生成氧化镁 4.8 g × 5/3 = 8 g。另一种算法是先求消耗的氧气：由 48∶32 = 4.8 g∶x 得 x = 3.2 g，再由质量守恒得 4.8 g + 3.2 g = 8 g。若把 MgO 的相对分子质量算成 24 + 32 = 56（把氧的相对原子质量当成 32），就会得到错误的答案。","difficulty":2,"tags":["氧气","化学方程式计算"]},{"id":"chem-substance-2-q8","type":"short","stem":"把 16.8 g 细铁丝放在足量氧气中完全燃烧，铁丝全部变成黑色固体四氧化三铁。求参加反应的氧气质量和生成的四氧化三铁质量。（相对原子质量：Fe 56、O 16）","answer":"设参加反应的氧气质量为 x，生成四氧化三铁的质量为 y。由 3Fe + 2O₂ —点燃→ Fe₃O₄ 可知 m(Fe)∶m(O₂)∶m(Fe₃O₄) = 168∶64∶232。由 168∶64 = 16.8 g∶x 得 x = 6.4 g；由 168∶232 = 16.8 g∶y 得 y = 23.2 g。验算：16.8 g + 6.4 g = 23.2 g，符合质量守恒定律。答：参加反应的氧气质量为 6.4 g，生成的四氧化三铁质量为 23.2 g。","explain":"这类题的两处陷阱：一是方程式没配平（写成 Fe + O₂ → Fe₃O₄），相对质量就全错了；二是把 O₂ 的相对分子质量当成 16（那是氧原子的相对原子质量）。检查办法很简单：算完以后看看「反应物质量之和是否等于生成物质量之和」，不相等就说明中途算错了。","difficulty":2,"tags":["氧气","化学方程式计算","铁燃烧"],"rubric":["化学方程式书写正确并配平，条件写「点燃」","相对质量 168、64、232 算对（特别是 O₂ 要按 32 算）","两个比例式分别列对并求出结果","结果带单位，且用质量守恒定律验算或说明依据"],"steps":["设未知量：设参加反应的氧气质量为 x，生成的四氧化三铁质量为 y。","写出并配平化学方程式：3Fe + 2O₂ —点燃→ Fe₃O₄。","算出相关物质的相对质量总和：3×56 = 168，2×(16×2) = 64，56×3 + 16×4 = 232。","列比例式：168∶64 = 16.8 g∶x 得 x = 6.4 g；168∶232 = 16.8 g∶y 得 y = 23.2 g。","用质量守恒验算（16.8 + 6.4 = 23.2），写出带单位的答句。"]},{"id":"chem-substance-2-q9","type":"short","stem":"请设计一个实验，比较硫在空气中和在氧气中燃烧现象的差异。写出实验操作、观察到的现象和由此得出的结论。","answer":"操作：在集气瓶底部放少量水，收集满氧气后用玻璃片盖住；取少量硫粉放在燃烧匙中，在酒精灯上加热至燃烧，先观察它在空气中燃烧的现象；再迅速把燃烧匙伸入盛有氧气的集气瓶中，观察现象。现象：硫在空气中燃烧发出微弱的淡蓝色火焰；在氧气中燃烧发出明亮的蓝紫色火焰，放热更明显，生成有刺激性气味的气体。结论：硫在氧气中燃烧生成二氧化硫（S + O₂ —点燃→ SO₂）；同一物质在氧气中燃烧比在空气中剧烈，说明氧气的浓度越大，燃烧越剧烈。","explain":"对比实验的灵魂是「控制变量」：两次实验里可燃物（硫）相同、引燃方式相同，唯一改变的是氧气的浓度，这样现象差异才能归因到氧气浓度上。答题时现象与结论必须分开写；只写「氧气中燃烧更旺」而不写具体现象（颜色、气味），等于没有证据。瓶底放水的目的（吸收 SO₂）也要在操作中体现出来。","difficulty":2,"tags":["氧气","实验探究","对比实验"],"rubric":["操作中写清「两次实验都用相同的硫」，体现控制变量（可燃物相同、只改变氧气浓度）","分别写清空气中与氧气中的现象，颜色词准确（淡蓝色／明亮的蓝紫色）","写出生成物的气味与化学方程式 S + O₂ —点燃→ SO₂","由现象归纳出结论：氧气浓度越大，燃烧越剧烈"]},{"id":"chem-substance-2-q10","type":"short","stem":"如图只画出了集气瓶和一根笔直的铁丝。请你在图上把铁丝在氧气中燃烧的实验装置补充完整：画出铁丝的绕法、它下端所系的火柴、瓶底所放的水（或细沙），并用文字标注这三处。","answer":"铁丝应画成螺旋状（绕在细铁丝上呈螺旋形，以增大受热面积、使热量集中）；下端画一小段火柴（用于引燃）；集气瓶底部画一条水平线表示预先放入的少量水（或铺一层细沙），并标注「防止高温熔化物溅落炸裂瓶底」。","explain":"这道作图题考的是「装置的每一处细节都有它的目的」：螺旋状是为了聚热、火柴是为了引燃、瓶底的水或细沙是为了保护瓶底。作图时长度的比例也要合理，火柴应画在铁丝的最下端而不是中间，水面画成水平线并在瓶底薄薄一层，画成半瓶水就与实际操作不符。","difficulty":2,"tags":["氧气","作图题","铁燃烧装置"],"rubric":["铁丝画成螺旋状，而不是笔直的或随意弯曲的","铁丝下端画出火柴，并标注「引燃铁丝」","瓶底画出水面（或细沙层），标注「防止炸裂瓶底」","装置整体符合实际：铁丝伸入瓶中、瓶内充满氧气，标注文字与图形一一对应"],"figure":{"id":"fig-chem-substance-2-q10","title":"待补充完整的装置图","caption":"请在图上画出螺旋状的铁丝、下端的火柴和瓶底的水或细沙","view":"wide","alt":"集气瓶内没有水，一根笔直的铁丝竖直伸入瓶中，等待画出螺旋状的绕法、下端的火柴和瓶底的水或细沙","prims":[{"t":"gasJar","x":40,"y":32,"w":26,"h":30,"color":"colorless"},{"t":"rect","x":30,"y":15,"w":20,"h":2.5,"fill":true},{"t":"line","x1":40,"y1":17.5,"x2":40,"y2":40,"width":0.8},{"t":"text","x":58,"y":28,"text":"一瓶氧气","anchor":"start","size":3.4,"tone":"muted"},{"t":"text","x":58,"y":36,"text":"（待补充装置）","anchor":"start","size":3.4,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-2-q10-a","title":"参考答案：完整的铁丝燃烧装置","caption":"螺旋状铁丝 + 下端火柴 + 瓶底少量水（或细沙）","view":"wide","alt":"集气瓶内充满氧气、瓶底有少量水，铁丝绕成螺旋状，下端系一根火柴，三处都标注了它们的作用","prims":[{"t":"gasJar","x":40,"y":32,"w":26,"h":30,"liquid":0.22,"color":"colorless"},{"t":"rect","x":30,"y":15,"w":20,"h":2.5,"fill":true},{"t":"line","x1":40,"y1":17.5,"x2":40,"y2":38,"width":0.7},{"t":"circle","cx":40,"cy":23,"r":3.6},{"t":"circle","cx":40,"cy":27.5,"r":3.6},{"t":"circle","cx":40,"cy":32,"r":3.6},{"t":"line","x1":37.6,"y1":38,"x2":42.4,"y2":38,"width":1.8},{"t":"text","x":56,"y":23,"text":"① 绕成螺旋状：聚热","anchor":"start","size":3.2,"tone":"accent"},{"t":"text","x":56,"y":31,"text":"② 下端系火柴：引燃","anchor":"start","size":3.2,"tone":"accent"},{"t":"text","x":40,"y":52,"text":"③ 瓶底放少量水或细沙：防止炸裂瓶底","size":3.4,"tone":"accent"}]}},{"id":"chem-substance-2-m1-q1","type":"short","stem":"（3 分）写出材料一中铁丝在氧气中燃烧的现象，并写出该反应的化学方程式。","answer":"现象：铁丝剧烈燃烧，火星四射，放出大量热，生成黑色固体。化学方程式：3Fe + 2O₂ —点燃→ Fe₃O₄。","explain":"","rubric":["现象写全「剧烈燃烧」「火星四射」「放出大量热」「生成黑色固体」","化学式与化学方程式书写正确，产物写 Fe₃O₄ 而不是 Fe₂O₃","方程式配平正确，条件写「点燃」"]},{"id":"chem-substance-2-m1-q2","type":"short","stem":"（4 分）根据材料二计算：3.2 g 硫完全燃烧需要消耗多少克氧气？生成多少克二氧化硫？（相对原子质量：S 32、O 16）","answer":"设消耗氧气的质量为 x，生成二氧化硫的质量为 y。由 S + O₂ —点燃→ SO₂ 可知 m(S)∶m(O₂)∶m(SO₂) = 32∶32∶64。由 32∶32 = 3.2 g∶x 得 x = 3.2 g；由 32∶64 = 3.2 g∶y 得 y = 6.4 g。答：需要消耗 3.2 g 氧气，生成 6.4 g 二氧化硫。","explain":"","rubric":["写出并配平化学方程式 S + O₂ —点燃→ SO₂","算出相对质量 32、32、64（或说明质量比为 1∶1∶2）","求出氧气的质量为 3.2 g","求出二氧化硫的质量为 6.4 g，并带单位写出答句"]},{"id":"chem-substance-2-m1-q3","type":"short","stem":"（3 分）材料一与材料二中，集气瓶底部都预先放了少量水。这两处水的作用是否相同？请分别说明。","answer":"不相同。铁丝燃烧时瓶底放水（或铺一层细沙）是为了防止生成的高温熔化物溅落下来炸裂瓶底，起的是保护瓶底的作用；硫燃烧时瓶底放水是为了吸收生成的有毒气体 SO₂，防止污染空气，起的是吸收尾气的作用。","explain":"","rubric":["答出「不相同」","说明铁丝燃烧处的水（细沙）用于防止高温熔化物溅落炸裂瓶底","说明硫燃烧处的水用于吸收 SO₂、防止污染空气"]}]},{"id":"chem-substance-3","title":"氧气的制取：实验室制法·装置选择与操作顺序·催化剂与工业制氧","subtitle":"人教版九年级 · 第二单元 我们周围的空气 · 9a","grade":"9a","tags":["人教版九年级 · 第二单元 我们周围的空气"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第二单元 我们周围的空气 · 9a"},{"type":"note","title":"问题切入","text":"实验室里做氧气性质的实验，氧气从哪里来？加热高锰酸钾、加热氯酸钾、常温分解过氧化氢都能得到氧气，为什么装置完全不同？试管口为什么要略向下倾斜？实验结束时为什么必须先撤导管后熄灭酒精灯？"},{"type":"note","title":"一句话抓住关键","text":"实验室制氧有三条常用路线：加热高锰酸钾、加热氯酸钾（二氧化锰作催化剂）、常温下分解过氧化氢（二氧化锰作催化剂）。发生装置由反应物的状态和反应条件决定——固体加热用固体加热型，固体与液体常温反应用固液常温型；收集装置由气体的密度和溶解性决定。操作顺序记「查、装、定、点、收、离、熄」七个字。工业制氧是分离液态空气，属于物理变化。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"同一个目标——制氧气，却有三条路：加热高锰酸钾、加热氯酸钾、常温分解过氧化氢。就像去同一个地方，可以坐高铁、开车、骑车，选哪种取决于你手里的条件。","walk":["高锰酸钾受热生成锰酸钾、二氧化锰和氧气；氯酸钾在二氧化锰催化下受热生成氯化钾和氧气；过氧化氢在二氧化锰催化下常温分解成水和氧气。","反应物是固体且需要加热，用「固固加热型」装置，试管口略向下倾斜，防止冷凝水倒流炸裂试管；反应物是固体和液体且常温，用「固液常温型」装置，可以用分液漏斗控制速率。","操作顺序要记牢：查（气密性）、装（药品）、定（固定）、点（点燃酒精灯）、收（收集）、离（撤离导管）、熄（熄灭酒精灯）。先撤导管后熄灯，是为了防止水倒吸。"],"try":"在成人陪同下，把少量过氧化氢溶液倒进装有二氧化锰的瓶中，用带火星的木条靠近瓶口，观察木条复燃，感受「常温也能制氧」。","use":["装置选择题先看「反应物状态 + 是否加热」，再选发生装置；收集看「密度和溶解性」。","催化剂只改变化学反应速率，本身的质量和化学性质在反应前后都不变，不能把「加快」说成「只能加快」。"]},{"type":"h","text":"【宏观】宏观：三种制法与装置的选择依据"},{"type":"p","text":"看三条路线的反应物状态和条件：加热高锰酸钾是固体加热，加热氯酸钾（加二氧化锰）也是固体加热，它们都用固体加热型装置——试管、酒精灯、铁架台、单孔橡皮塞和导管；用过氧化氢溶液加二氧化锰是「固体 + 液体、常温」，用固液常温型装置——锥形瓶（或广口瓶）、长颈漏斗（或分液漏斗）、双孔橡皮塞。所以选装置先问两句话：反应物是固体还是固体加液体？要不要加热？"},{"type":"figure","figure":{"id":"fig-chem-substance-3-1","title":"两种发生装置的选择依据","caption":"左：固体加热型；右：固液常温型（长颈漏斗下端要伸入液面以下）","view":"wide","alt":"左边是试管口略向下倾斜、用酒精灯加热的固体加热型发生装置，右边是锥形瓶配长颈漏斗的固液常温型发生装置，长颈漏斗下端伸入液面以下","prims":[{"t":"stand","x":10,"y":46,"h":34,"w":16,"clamps":[0.7]},{"t":"testTube","x":22,"y":22,"h":28,"w":9,"tilt":100},{"t":"alcoholLamp","x":14,"y":40,"lit":true},{"t":"text","x":22,"y":56,"text":"固体加热型","size":3.4,"tone":"accent"},{"t":"text","x":22,"y":61,"text":"（高锰酸钾、氯酸钾）","size":3,"tone":"muted"},{"t":"flask","x":64,"y":36,"kind":"conical","h":24,"w":26,"liquid":0.5,"color":"colorless"},{"t":"funnel","x":64,"y":26,"kind":"long","h":18,"label":"长颈漏斗"},{"t":"curve","points":[[70,30],[82,28],[88,40]],"tone":"main"},{"t":"text","x":64,"y":56,"text":"固液常温型","size":3.4,"tone":"accent"},{"t":"text","x":64,"y":61,"text":"（过氧化氢溶液 + 二氧化锰）","size":3,"tone":"muted"}]}},{"type":"note","title":"","text":"长颈漏斗的下端管口必须伸入液面以下，形成「液封」，否则生成的气体会从长颈漏斗中逸出，收集不到气体。这是装置图判读题最常考的一处。"},{"type":"h","text":"【宏观】宏观：收集方法与操作顺序"},{"type":"p","text":"氧气不易溶于水，可以用排水法收集，收集到的气体比较纯净；氧气的密度比空气略大，也可以用向上排空气法收集，收集到的气体比较干燥。排水法要注意：等导管口有连续均匀的气泡冒出时再开始收集，因为刚冒出的气泡里混有装置内原有的空气。整套操作顺序记成七个字「查、装、定、点、收、离、熄」：查气密性、装药品、固定装置、点燃酒精灯、收集气体、把导管移出水面、熄灭酒精灯。最后两步的顺序绝不能颠倒。"},{"type":"figure","figure":{"id":"fig-chem-substance-3-2","title":"排水法收集氧气","caption":"集气瓶倒置、瓶口向下，瓶内充满水，气体从瓶口进入把水排出","view":"wide","alt":"水槽中放着一个倒置的集气瓶，瓶口向下、瓶内充满水，导管从集气瓶口伸入瓶内，气体进入后把水排出","prims":[{"t":"beaker","x":54,"y":34,"w":40,"h":22,"fill":0.55},{"t":"line","x1":68,"y1":26,"x2":68,"y2":44,"width":0.6},{"t":"line","x1":84,"y1":26,"x2":84,"y2":44,"width":0.6},{"t":"line","x1":68,"y1":26,"x2":84,"y2":26,"width":0.6},{"t":"rect","x":68.6,"y":30,"w":14.8,"h":13,"fill":true,"tone":"main"},{"t":"curve","points":[[16,20],[34,16],[46,18],[50,40],[50,48],[76,48],[78,42]]},{"t":"circle","cx":74,"cy":46,"r":0.9,"tone":"accent","fill":true},{"t":"circle","cx":71,"cy":43.5,"r":0.8,"tone":"accent","fill":true},{"t":"text","x":76,"y":22,"text":"倒置集气瓶（瓶口向下）","size":3.2,"tone":"accent"},{"t":"text","x":74,"y":60,"text":"水槽中的水被排入水槽，瓶内氧气逐渐增多","size":3.2,"tone":"muted"},{"t":"text","x":34,"y":26,"text":"来自发生装置的导管","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"不要把「倒置集气瓶」画成瓶口朝上。排水法里集气瓶必须倒置、瓶口向下伸入水中，导管只伸到瓶口内一点；向上排空气法里集气瓶正放，导管要伸到接近瓶底。两种画法正好相反，这是实验题判分的分水岭。"},{"type":"h","text":"【微观】微观：催化剂在反应中到底做什么"},{"type":"p","text":"以过氧化氢分解为例：过氧化氢分子由氢、氧两种原子构成，在常温下也能慢慢分解，但速度太慢。加入二氧化锰后，反应速率明显加快——二氧化锰提供了另一条「更容易走的路」，它参与了反应的过程，却在反应前后质量不变、化学性质也不变，所以叫催化剂。催化剂的定义里有三个关键点：能改变（包括加快和减慢）其他物质的化学反应速率、本身的质量在反应前后不变、本身的化学性质在反应前后不变。它不会让你得到更多的氧气，只是让同样的过氧化氢更快地分解完。"},{"type":"figure","figure":{"id":"fig-chem-substance-3-3","title":"催化剂改变反应速率，自身不变","caption":"两个过氧化氢分子分解成两个水分子和一个氧分子，二氧化锰写在箭头上方","view":"wide","alt":"两个过氧化氢分子在二氧化锰催化下分解成两个水分子和一个氧分子，二氧化锰的质量和化学性质在反应前后都没有改变","prims":[{"t":"molecule","x":12,"y":18,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":4.6,"dy":0,"symbol":"O","color":"red"},{"dx":-2.4,"dy":-3.6,"symbol":"H"},{"dx":7,"dy":-3.6,"symbol":"H"}],"bonds":[[0,1],[0,2],[1,3]],"label":"H₂O₂"},{"t":"molecule","x":12,"y":38,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":4.6,"dy":0,"symbol":"O","color":"red"},{"dx":-2.4,"dy":-3.6,"symbol":"H"},{"dx":7,"dy":-3.6,"symbol":"H"}],"bonds":[[0,1],[0,2],[1,3]],"label":"H₂O₂"},{"t":"arrow","x1":26,"y1":28,"x2":44,"y2":28,"label":"MnO₂","labelDy":-6},{"t":"molecule","x":58,"y":16,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4,"dy":-3,"symbol":"H"},{"dx":4,"dy":-3,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":58,"y":38,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4,"dy":-3,"symbol":"H"},{"dx":4,"dy":-3,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":82,"y":27,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"text","x":50,"y":52,"text":"催化剂改变反应速率","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"反应前后质量和化学性质都不变","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"「二氧化锰是催化剂」这句话必须带上范围：在过氧化氢分解、氯酸钾分解这几个反应里二氧化锰是催化剂，但不能说「催化剂就是二氧化锰」——不同反应有不同的催化剂，有的反应还可以用氧化铁、硫酸铜溶液作催化剂。"},{"type":"h","text":"【符号】符号：三条路线写成方程式，并判断反应类型"},{"type":"p","text":"加热高锰酸钾：2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑，注意产物是锰酸钾 K₂MnO₄ 而不是 KMnO₄，两个化学式只差一个钾，下标写错整题皆错。加热氯酸钾：2KClO₃ —MnO₂ 作催化剂并加热→ 2KCl + 3O₂↑，检查氧原子：左边 2×3 = 6 个，右边 3×2 = 6 个。分解过氧化氢：2H₂O₂ —MnO₂→ 2H₂O + O₂↑，检查氧原子：左边 2×2 = 4 个，右边 2×1 + 2 = 4 个。这三个反应都是「一变多」，属于分解反应。"},{"type":"note","title":"","text":"写这三个方程式时有三个必写项：气体符号 ↑（因为生成的气体从溶液中或固体中放出）、反应条件、以及催化剂要写在箭头上方。氯酸钾制氧的条件是「加热」且需要催化剂，两个都要写出来。"},{"type":"h","text":"【应用】应用：工业制氧与实验安全"},{"type":"p","text":"工业上要得到大量的氧气，用的是分离液态空气的方法：先把空气加压、降温变成液态，再逐渐升温，利用液态氮的沸点（−196 ℃）比液态氧的沸点（−183 ℃）低，氮气先汽化跑出来，剩下的主要是液态氧。整个过程中没有生成新物质，属于物理变化——这与实验室里用化学变化制氧有本质区别。实验室制氧的安全要点则是两条：试管口略向下倾斜，防止冷凝水倒流炸裂试管；实验结束先撤导管后熄灭酒精灯，防止水槽中的水倒吸进试管。"},{"type":"note","title":"","text":"「工业制氧是物理变化」是必考判断点：只要抓住「有没有新物质生成」就不会错。分离液态空气得到的是氧气（还含少量稀有气体），属于混合物；实验室制得的氧气中常混有水蒸气。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["相对分子质量（含原子团）","KMnO₄ 的相对分子质量 = 39 + 55 + 16×4 = 158；K₂MnO₄ 的相对分子质量 = 39×2 + 55 + 16×4 = 197","用于化学方程式计算里求质量比。注意 KMnO₄ 与 K₂MnO₄ 只差一个钾原子，相对分子质量分别是 158 和 197，写错产物整个计算都会错。括号要按倍数乘：Ca(OH)₂ 的相对分子质量 = 40 + (16 + 1)×2 = 74。"],["化学方程式计算的一般步骤","设未知数 → 写方程式 → 算相对质量 → 列比例式 → 求解并作答","适用于所有根据化学方程式的计算。三个必须守住的条件：方程式必须配平；只有参加反应的纯物质质量才能代入；代入的质量单位要统一（一般用 g）。生成气体的体积若要求算，还要用密度换算成质量后再代入。"],["催化剂的三条判断标准","① 改变（加快或减慢）其他物质的化学反应速率；② 本身的质量在反应前后不变；③ 本身的化学性质在反应前后不变","三条同时满足才叫催化剂。只满足「反应前后质量不变」的物质不一定是催化剂（它可能根本没参加反应）；「加入二氧化锰后反应变快」也不能直接断定二氧化锰是催化剂，还要检验它在反应前后的质量和化学性质是否改变。"]]},{"type":"h","text":"应用 · 检查装置的气密性"},{"type":"note","title":"情境","text":"组装好加热高锰酸钾制氧气的装置后，怎样判断装置是否漏气？"},{"type":"list","title":"解答步骤","items":["把导管的另一端浸入水中，双手紧握试管外壁（也可用微热的毛巾包住试管）。","观察导管口：有气泡不断冒出，说明装置不漏气。","松开手后，导管内会上升一段水柱并保持住，进一步证明装置不漏气。","若导管口没有气泡冒出、也没有水柱上升，说明装置漏气，应检查橡皮塞是否塞紧、导管与橡皮塞的连接处是否严密。"]},{"type":"note","title":"结论","text":"「手握试管外壁，导管口有气泡冒出，松手后导管内形成一段水柱」是标准答案。只说「检查一下」或「看是否漏气」没有操作和现象，不得分。"},{"type":"h","text":"应用 · 加热高锰酸钾能得到多少氧气"},{"type":"note","title":"情境","text":"实验室要制取 3.2 g 氧气，需要加热分解多少克高锰酸钾？反应后试管内剩余的固体共多少克？（相对原子质量：K 39、Mn 55、O 16）"},{"type":"list","title":"解答步骤","items":["算出 KMnO₄ 的相对分子质量：39 + 55 + 16×4 = 158。","写出质量比：2KMnO₄∶O₂ = 316∶32。","设需要高锰酸钾的质量为 x：316∶32 = x∶3.2 g，解得 x = 31.6 g。","求剩余固体：用质量守恒定律，31.6 g − 3.2 g = 28.4 g（即 K₂MnO₄ 与 MnO₂ 的质量之和）。"]},{"type":"note","title":"结论","text":"需要高锰酸钾 31.6 g，反应后剩余固体 28.4 g。用质量守恒定律求剩余固体质量比逐个算出两种产物更快，也是这类题的常见解法。"},{"type":"h","text":"实验 1 · 加热高锰酸钾制取氧气"},{"type":"note","title":"实验目的","text":"学习用固体加热型装置和排水法制取并收集氧气，掌握装置的组装、操作顺序与安全要点。"},{"type":"list","title":"实验器材","items":["铁架台（带铁夹）","大试管、单孔橡皮塞、导管","高锰酸钾、一团棉花","酒精灯、火柴","水槽、集气瓶、玻璃片"]},{"type":"figure","figure":{"id":"fig-chem-substance-3-exp1","title":"加热高锰酸钾制取氧气","caption":"试管口略向下倾斜，试管口塞一团棉花，导管只伸到集气瓶口，用排水法收集","view":"wide","alt":"铁架台夹住试管，试管口略向下倾斜并在管口塞有棉花，酒精灯在试管下方加热，导管从橡皮塞伸出后进入水槽，通到倒置的集气瓶口","prims":[{"t":"stand","x":16,"y":48,"h":38,"w":20,"clamps":[0.72]},{"t":"testTube","x":34,"y":22,"h":30,"w":9,"tilt":100},{"t":"circle","cx":45,"cy":24,"r":2.4,"tone":"muted"},{"t":"text","x":26,"y":9,"text":"KMnO₄（紫黑色固体）","size":3.2},{"t":"text","x":45,"y":17,"text":"棉花","size":3,"tone":"accent"},{"t":"alcoholLamp","x":26,"y":40,"lit":true,"label":"酒精灯"},{"t":"line","x1":48,"y1":29,"x2":49.6,"y2":20.2,"width":1.2},{"t":"curve","points":[[50,25],[58,21],[66,22],[68,44],[68,49],[78,49],[79,42]]},{"t":"beaker","x":62,"y":34,"w":34,"h":22,"fill":0.55},{"t":"line","x1":72,"y1":28,"x2":72,"y2":44,"width":0.6},{"t":"line","x1":86,"y1":28,"x2":86,"y2":44,"width":0.6},{"t":"line","x1":72,"y1":28,"x2":86,"y2":28,"width":0.6},{"t":"rect","x":72.6,"y":32,"w":12.8,"h":11,"fill":true,"tone":"main"},{"t":"text","x":79,"y":60,"text":"倒置集气瓶（瓶口向下）","size":3.2,"tone":"accent"},{"t":"text","x":20,"y":58,"text":"铁架台","size":3.2,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["组装装置并检查气密性：把导管口插入水中，用手紧握试管外壁，导管口有气泡冒出、松手后导管内形成一段水柱，说明装置不漏气。","把高锰酸钾装入试管（约占试管容积的 1/4）。","在试管口塞一团棉花，用带导管的单孔橡皮塞塞紧试管口，把试管固定在铁架台上，使试管口略向下倾斜。","把集气瓶装满水，倒扣在水槽中（瓶口向下），把导管口伸到集气瓶口附近。","点燃酒精灯，先来回移动使试管均匀受热，再对准药品部位加热；待导管口有连续均匀的气泡冒出时开始收集。","收集满后，先把导管移出水面，再熄灭酒精灯，取出集气瓶正放在桌面上（用玻璃片盖住瓶口）。"]},{"type":"note","title":"实验现象","text":"紫黑色的高锰酸钾受热后逐渐减少，导管口有气泡连续均匀地冒出；集气瓶内的水逐渐被排入水槽，收集满后取出，把带火星的木条伸入瓶中，木条复燃。"},{"type":"note","title":"实验结论","text":"高锰酸钾受热分解生成锰酸钾、二氧化锰和氧气，化学方程式为 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。收集到的气体是氧气，可用带火星的木条检验。"},{"type":"list","title":"注意事项","items":["试管口必须略向下倾斜：防止加热时产生的冷凝水倒流到试管底部，使试管炸裂。","试管口必须塞一团棉花：防止高锰酸钾粉末随气流进入导管，堵塞导管或使水槽中的水变红。","实验结束必须先撤导管、后熄灭酒精灯：如果先熄灯，试管内温度降低、压强减小，水槽中的水会倒吸进试管，使试管炸裂。","要等导管口冒出连续均匀的气泡时再收集：刚开始冒出的气泡里含有装置内的空气，立即收集会使收集到的氧气不纯。","用酒精灯外焰加热，先预热再固定加热药品部位；加热时不能用手直接接触试管，也不能把试管口对着自己或他人。","药品要平铺在试管底部，不要堆积在一处，也不要超过试管容积的 1/3，防止加热时药品随气流冲出。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑","加热","紫黑色的高锰酸钾固体受热分解，导管口有气泡连续均匀地冒出，收集到的气体能使带火星的木条复燃","配平：左边 2 个 K、2 个 Mn、8 个 O；右边 K₂MnO₄ 有 2 个 K、1 个 Mn、4 个 O，MnO₂ 有 1 个 Mn、2 个 O，O₂ 有 2 个 O，合计 2 个 K、2 个 Mn、8 个 O。产物是锰酸钾 K₂MnO₄，与高锰酸钾 KMnO₄ 只差一个钾原子，最易写错；气体符号 ↑ 不能漏。"],["2KClO₃ —MnO₂作催化剂并加热→ 2KCl + 3O₂↑","加热，二氧化锰作催化剂","白色的氯酸钾固体受热熔化，产生大量气泡，收集到的气体能使带火星的木条复燃","配平：氧原子左边 2×3 = 6 个，右边 3×2 = 6 个；钾、氯各 2 个。二氧化锰是催化剂，写在箭头上方，不能写成反应物也不能写成生成物；不写「MnO₂」这个条件只写「加热」会被扣分。"],["2H₂O₂ —MnO₂→ 2H₂O + O₂↑","常温，二氧化锰作催化剂","过氧化氢溶液中产生大量气泡，带火星的木条伸入后复燃，反应放热、试管外壁微微发热","配平：氧原子左边 2×2 = 4 个，右边 2 个（水中）+ 2 个（氧气中）= 4 个；氢原子左右各 4 个。催化剂只改变反应速率，不加二氧化锰反应也能进行，只是很慢，所以条件写「MnO₂」而不是「点燃」。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["催化剂就是二氧化锰。","二氧化锰只是在过氧化氢分解、氯酸钾分解等反应中常用的一种催化剂；催化剂是「能改变反应速率而自身质量和化学性质不变」的物质。","把具体物质与一类物质的概念混为一谈。不同反应可以用不同的催化剂，例如过氧化氢分解还可以用氧化铁、硫酸铜溶液作催化剂；反过来，二氧化锰在某些反应里也不是催化剂。"],["用过氧化氢制氧气时，加入二氧化锰可以生成更多的氧气。","二氧化锰只改变反应速率，不改变生成氧气的质量；生成氧气的多少由过氧化氢的质量决定。","催化剂不参与「生成多少产物」的账。它让反应更快结束，但反应物用完为止，总产物量只与反应物的量有关——这也是催化剂的定义里只提「改变速率」而不提「改变产量」的原因。"],["加热高锰酸钾制氧气，实验结束时应先熄灭酒精灯，再撤导管。","必须先撤导管、后熄灭酒精灯。","若先熄灭酒精灯，试管内气体温度降低、压强减小，水槽中的水会被倒吸进热的试管，试管骤冷容易炸裂。凡是「加热固体并用排水法收集」的实验，都要守住这个顺序。"],["工业上制取氧气，是用化学方法分解空气得到氧气。","工业制氧是分离液态空气：利用液态氮和液态氧沸点不同，把空气液化后分馏，氮气先汽化出来，剩下的主要是液态氧。","整个过程没有生成新物质，属于物理变化。判断的关键永远是「有没有新物质生成」，而不是「操作复杂不复杂」。"]]},{"type":"table","title":"三种实验室制氧方法的比较（反应物状态、反应条件、装置类型与特点）","head":["比较项","加热高锰酸钾","过氧化氢溶液加二氧化锰"],"rows":[["反应物状态","固体（紫黑色）","液体 + 固体粉末（常温）"],["反应条件","加热","常温，二氧化锰作催化剂"],["发生装置","固体加热型（试管、酒精灯、铁架台）","固液常温型（锥形瓶、长颈漏斗）"],["化学方程式","2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑","2H₂O₂ —MnO₂→ 2H₂O + O₂↑"],["优点与注意","装置简单、速率平稳；管口要放棉花，结束要先撤导管","不需加热、操作简便、可控制反应速率；长颈漏斗下端要伸入液面以下"]]},{"type":"table","title":"排水法与向上排空气法（收集方法的依据、装置画法与气体纯度）","head":["比较项","排水法","向上排空气法"],"rows":[["适用依据","气体不易溶于水（氧气、氢气）","气体密度比空气大（氧气、二氧化碳）"],["集气瓶画法","集气瓶倒置、瓶口向下伸入水槽","集气瓶正放，瓶口用玻璃片盖住"],["导管位置","导管只伸到集气瓶口附近","导管伸到接近集气瓶底部"],["气体特点","收集到的气体较纯净，但含有水蒸气","收集到的气体较干燥，但可能混有空气"],["何时收集","气泡连续均匀冒出时开始收集","导管伸到瓶底，收集较长时间后验满"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["发生装置与收集装置的选择","以「给药品和条件，选装置」或「给装置图，判断能不能用」的形式出现。判分点：反应物状态与是否加热决定发生装置；气体的密度和溶解性决定收集装置，氧气两条路都能走。"],["操作顺序与装置细节的正误判断","高频考点集中在一句话上：先撤导管后熄灭酒精灯、试管口略向下倾斜、试管口塞棉花、长颈漏斗下端伸入液面以下、排水法导管只伸到瓶口、排空气法导管伸到瓶底。选择题常把这些细节反过来设成错误选项。"],["催化剂与分解反应的判断","考催化剂「一变两不变」的表述，或用对照实验的数据（加入催化剂后反应时间缩短、催化剂质量不变）判断某物质是不是催化剂；也常与分解反应的类型判断合并考查。"],["方程式书写与制氧计算","要求书写并配平三个制氧方程式（注意 K₂MnO₄ 与 KMnO₄ 的区别、气体符号与条件），并根据方程式计算药品用量或产氧量，剩余固体的质量常用质量守恒定律求出。"]]},{"type":"quote","text":"【材料一】某小组用加热高锰酸钾的方法制取氧气，装置如图：试管口略向下倾斜，管口塞有一团棉花，导管伸入水槽中倒置的集气瓶里。【材料二】为探究二氧化锰的作用，甲同学取两份质量相同、浓度相同的过氧化氢溶液，只在其中一份中加入 0.5 g 二氧化锰粉末，记录产生 100 mL 氧气所需的时间：加二氧化锰的一份用 8 s，不加的一份用 210 s。【材料三】实验记录：加热分解 15.8 g 高锰酸钾（KMnO₄ 的相对分子质量为 158），完全反应后得到氧气和固体残留物。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）材料一中试管口为什么要略向下倾斜？管口塞一团棉花的作用是什么？","【设问】（4 分）根据材料二，你能得出什么结论？该实验为什么要用「质量相同、浓度相同」的两份过氧化氢溶液？","【设问】（4 分）根据材料三计算：15.8 g 高锰酸钾完全分解能生成多少克氧气？反应后固体残留物的质量是多少克？（相对原子质量：K 39、Mn 55、O 16）"]}],"questions":[{"id":"chem-substance-3-q1","type":"choice","stem":"如图是用向上排空气法收集氧气的装置。下列说法正确的是（　）","answer":"D","explain":"D 正确：向上排空气法靠氧气把瓶内空气「挤」出去，导管伸到接近瓶底才能使空气从瓶口排出，收集到的氧气更纯。A 把两种收集方法的导管位置弄混了：导管只伸到瓶口是排水法的要求，排空气法必须伸到瓶底。B 把正放倒放记反了：氧气密度比空气大，集气瓶应正放；倒放（瓶口向下）是向下排空气法，用于密度比空气小的气体如氢气。C 错：收集时要用玻璃片盖住瓶口（或用手按住），否则氧气会逸出、空气也会进入。","options":["导管口只需伸到集气瓶口，不需要伸入瓶内","集气瓶应该倒置，因为氧气的密度比空气大","集气瓶口不必盖玻璃片，氧气不会逸出","导管应伸到接近集气瓶底部，以便把瓶内的空气排尽"],"difficulty":2,"tags":["氧气的制取","收集装置","向上排空气法"],"figure":{"id":"fig-chem-substance-3-q1","title":"向上排空气法收集氧气","caption":"集气瓶正放，导管伸到接近瓶底，瓶口盖玻璃片","view":"wide","alt":"集气瓶正放在桌面上，一根导管从橡皮塞伸出后弯下伸到接近瓶底，瓶口盖有玻璃片","prims":[{"t":"gasJar","x":46,"y":34,"w":24,"h":30,"color":"colorless","cover":true},{"t":"rect","x":36,"y":17,"w":20,"h":2.5,"fill":true},{"t":"curve","points":[[18,22],[34,20],[46,20],[46,46]]},{"t":"text","x":66,"y":24,"text":"玻璃片","anchor":"start","size":3.4},{"t":"text","x":66,"y":40,"text":"导管伸到","anchor":"start","size":3.4},{"t":"text","x":66,"y":47,"text":"接近瓶底","anchor":"start","size":3.4},{"t":"text","x":22,"y":14,"text":"来自发生装置","size":3.2,"tone":"muted"}]}},{"id":"chem-substance-3-q2","type":"choice","stem":"实验室用加热高锰酸钾的方法制取并用排水法收集氧气，下列操作顺序正确的是（　）","answer":"A","explain":"A 正确，符合「查、装、定、点、收、离、熄」的顺序，最后两步是先撤导管后熄灯。B 错在检查气密性放在加热之后：装置漏气时要先发现、先处理，加热后再检查既危险又浪费药品。C 把最后两步颠倒了：先熄灯会使试管内压强减小，水槽中的水倒吸进试管，导致试管炸裂。D 把固定装置放到点燃酒精灯之后，还先撤了导管再收集气体，顺序完全错乱。","options":["检查装置气密性→装入药品→固定装置→点燃酒精灯加热→收集气体→把导管移出水面→熄灭酒精灯","装入药品→点燃酒精灯加热→检查装置气密性→收集气体→把导管移出水面→熄灭酒精灯","检查装置气密性→装入药品→固定装置→点燃酒精灯加热→收集气体→熄灭酒精灯→把导管移出水面","检查装置气密性→装入药品→点燃酒精灯加热→固定装置→把导管移出水面→熄灭酒精灯→收集气体"],"difficulty":2,"tags":["氧气的制取","操作顺序","实验安全"]},{"id":"chem-substance-3-q3","type":"choice","stem":"下列关于催化剂的叙述正确的是（　）","answer":"B","explain":"B 正确，这是催化剂定义的核心内容。A 有两处错：催化剂能改变反应速率，既可能加快也可能减慢（如某些反应的阻化剂）；「一定是二氧化锰」更错，二氧化锰只是常用的一种催化剂。C 混淆了速率与产量：催化剂不改变生成物的质量，氧气产量由过氧化氢的量决定。D 与 B 直接矛盾：催化剂在反应前后质量不变，不需要补充。","options":["催化剂一定能加快化学反应速率，而且一定是二氧化锰","催化剂在反应前后本身的质量和化学性质都不改变","在过氧化氢溶液中加入二氧化锰，可以生成更多的氧气","催化剂在反应过程中不断被消耗，需要及时补充"],"difficulty":1,"tags":["氧气的制取","催化剂","分解反应"]},{"id":"chem-substance-3-q4","type":"choice","stem":"下列制取氧气的方法中，反应在常温下就能进行、不需要加热的是（　）","answer":"C","explain":"C 正确：过氧化氢在常温下就能分解，加入二氧化锰只是加快反应速率，所以不需要加热，装置也用固液常温型。A、B、D 都需要加热：加热高锰酸钾和加热氯酸钾都用固体加热型装置；加热氧化汞同样需要加热（2HgO —加热→ 2Hg + O₂↑），它在初中只作为化学史的例子出现。区分「要不要加热」是选择发生装置的第一步。","options":["加热高锰酸钾","加热氯酸钾和二氧化锰的混合物","用过氧化氢溶液和二氧化锰","加热氧化汞"],"difficulty":1,"tags":["氧气的制取","发生装置"]},{"id":"chem-substance-3-q5","type":"choice","stem":"下列关于氧气收集方法与依据的说法正确的是（　）","answer":"D","explain":"D 正确：这是氧气能用两种方法收集的原因。A 把溶解性说反了：氧气不易溶于水，所以能用排水法收集（水中溶有少量氧气，鱼儿才能呼吸，但溶解度很小）。B 把密度关系说反了：氧气密度比空气略大，应该用向上排空气法；向下排空气法用于氢气这类密度比空气小的气体。C 错在收集时机：刚开始冒出的气泡里混有装置内的空气，要等气泡连续均匀地冒出时再收集，否则收集到的氧气不纯。","options":["氧气易溶于水，所以不能用排水法收集","氧气的密度比空气小，可以用向下排空气法收集","用排水法收集时，导管口一有气泡冒出就应立即开始收集","氧气不易溶于水，可以用排水法收集；密度比空气略大，也可以用向上排空气法收集"],"difficulty":2,"tags":["氧气的制取","收集方法","氧气的性质"]},{"id":"chem-substance-3-q6","type":"fill","stem":"用过氧化氢溶液制取氧气时，加入的二氧化锰起 ______ 作用（填两字）。","answer":"催化","explain":"二氧化锰能改变过氧化氢分解的速率，而自身的质量和化学性质在反应前后都不变，所以起催化作用，是这一反应的催化剂。填「氧化」就错了：二氧化锰并没有被消耗、也没有提供氧，它只是让反应走得更快。判断的关键是「一变两不变」。","difficulty":1,"tags":["氧气的制取","催化剂"]},{"id":"chem-substance-3-q7","type":"fill","stem":"实验室加热分解 15.8 g 高锰酸钾（KMnO₄ 的相对分子质量为 158），理论上可得到氧气 ______ g。（O 16）","answer":"1.6","explain":"由 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑ 可知 m(KMnO₄)∶m(O₂) = (2×158)∶(16×2) = 316∶32，所以 15.8 g 高锰酸钾可得到氧气 15.8 g × 32/316 = 1.6 g。若忘记配平、把比例写成 158∶32，或把 O₂ 的相对分子质量算成 16，都会得到错误结果。","difficulty":2,"tags":["氧气的制取","化学方程式计算"]},{"id":"chem-substance-3-q8","type":"short","stem":"实验室要制取 4.8 g 氧气，用加热高锰酸钾的方法，至少需要称取多少克高锰酸钾？反应后试管内剩余固体的总质量是多少克？（相对原子质量：K 39、Mn 55、O 16）","answer":"设需要高锰酸钾的质量为 x。由 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑ 可知 m(KMnO₄)∶m(O₂) = 316∶32。由 316∶32 = x∶4.8 g 得 x = 47.4 g。反应后剩余固体为锰酸钾和二氧化锰，质量为 47.4 g − 4.8 g = 42.6 g。答：至少需要高锰酸钾 47.4 g，剩余固体总质量为 42.6 g。","explain":"剩余固体是 K₂MnO₄ 与 MnO₂ 的混合物，逐个算再加起来当然可以，但用质量守恒定律「剩余固体质量 = 参加反应的高锰酸钾质量 − 生成的氧气质量」一步就能得出，既快又不容易错。常见错误是把氧气按 32 g 还是 32 的比例弄混，或者忘了配平导致比例变成 158∶32，算出的高锰酸钾质量会少一半。","difficulty":2,"tags":["氧气的制取","化学方程式计算","质量守恒"],"rubric":["化学方程式书写正确并配平，条件写「加热」，气体符号不遗漏","KMnO₄ 相对分子质量算成 158，质量比 316∶32 正确","求出高锰酸钾质量为 47.4 g","剩余固体质量用质量守恒定律求出 42.6 g，并写出答句"],"steps":["设未知量：设需要高锰酸钾的质量为 x。","写出并配平化学方程式：2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。","算出相对质量总和：2×158 = 316，O₂ 为 32，质量比 m(KMnO₄)∶m(O₂) = 316∶32。","列比例式：316∶32 = x∶4.8 g，解得 x = 47.4 g。","用质量守恒定律求剩余固体：47.4 g − 4.8 g = 42.6 g，写出带单位的答句。"]},{"id":"chem-substance-3-q9","type":"short","stem":"某小组想证明「二氧化锰是过氧化氢分解的催化剂」。请你帮他们设计实验方案（写出实验步骤、需要观察记录的现象和数据，以及判断的依据）。","answer":"步骤一：取两支试管，各加入 5 mL 相同浓度的过氧化氢溶液，其中一支加入少量二氧化锰粉末，另一支不加，观察并记录两支试管中产生气泡的快慢（或收集相同体积氧气所需的时间）。现象：加入二氧化锰的试管中迅速产生大量气泡，不加入的试管中气泡很少、很慢。步骤二：待加入二氧化锰的试管中反应停止后，把二氧化锰过滤、洗涤、干燥后称量，比较它与反应前加入的质量是否相同。步骤三：把回收的二氧化锰再加入新的过氧化氢溶液中，观察它能否再次加快反应速率，以证明它的化学性质没有改变。判断依据：反应速率明显加快（一变），且反应前后二氧化锰的质量和化学性质都不变（两不变），才能说明它是这个反应的催化剂。","explain":"证明某物质是催化剂，必须把定义里的三个要点逐一验证：「速率改变」用对照实验看气泡快慢（或计时收集等体积气体）；「质量不变」用过滤、洗涤、干燥、称量的方法；「化学性质不变」则要把它再放进新的反应物中试一次。只做第一步就下结论是这类题最典型的失分点。另外，对照实验中两份过氧化氢溶液的浓度和体积必须相同，否则无法排除「反应物多所以气泡多」的可能。","difficulty":3,"tags":["氧气的制取","实验探究","催化剂"],"rubric":["设计对照实验：两份浓度、体积相同的过氧化氢溶液，一份加二氧化锰、一份不加（控制变量）","现象与数据写清楚：产生气泡的快慢或收集相同体积氧气所用的时间","检验「质量不变」：过滤、洗涤、干燥后称量并与反应前比较","检验「化学性质不变」：把回收的二氧化锰再加入过氧化氢溶液中，重复实验看是否仍能加快反应","结论表述为「一变两不变」，只写「加快反应」不算完整证明"]},{"id":"chem-substance-3-q10","type":"short","stem":"如图已画好排水法收集氧气的水槽、倒置的集气瓶和导管。请你在图上补全发生装置：画出装高锰酸钾的试管（注意试管的倾斜方向）、管口的棉花、单孔橡皮塞与酒精灯的位置，并用文字标注试管口的倾斜方向。","answer":"试管口应略向下倾斜（管口低于管底），试管口塞一团棉花，用带导管的单孔橡皮塞塞紧，试管用铁架台的铁夹固定，酒精灯放在试管下方、对准药品部位用外焰加热，导管从橡皮塞伸出后弯下伸入水槽、通向倒置的集气瓶口。","explain":"这道作图题考两处最常画错的地方：一是试管口的倾斜方向，必须是口略向下倾斜（防止冷凝水倒流炸裂试管），画成口向上或水平都属于装置错误；二是导管的连接，导管在试管内只略伸出橡皮塞，伸得太长会阻碍气体排出，而伸入集气瓶的那一端在排水法中只到瓶口附近。酒精灯要画在试管下方、用外焰加热药品部位，不能画成对着试管口。","difficulty":2,"tags":["氧气的制取","作图题","装置连接"],"rubric":["试管口明显低于试管底部（略向下倾斜），而不是向上倾斜或完全水平","试管口画出棉花，并标注「防止粉末进入导管」","橡皮塞与导管连接正确，导管在试管内只略伸出橡皮塞","酒精灯位置在试管下方并对准药品部位，标注「用外焰加热」"],"figure":{"id":"fig-chem-substance-3-q10","title":"待补全发生装置的装置图","caption":"水槽、倒置集气瓶与导管已画好，请补画发生装置","view":"wide","alt":"已画好水槽、倒置的集气瓶和伸入瓶口的导管，左侧留出空位等待画装高锰酸钾的试管、棉花、橡皮塞和酒精灯","prims":[{"t":"beaker","x":54,"y":34,"w":40,"h":22,"fill":0.55},{"t":"line","x1":68,"y1":26,"x2":68,"y2":44,"width":0.6},{"t":"line","x1":84,"y1":26,"x2":84,"y2":44,"width":0.6},{"t":"line","x1":68,"y1":26,"x2":84,"y2":26,"width":0.6},{"t":"rect","x":68.6,"y":30,"w":14.8,"h":13,"fill":true,"tone":"main"},{"t":"curve","points":[[10,20],[34,16],[46,18],[50,40],[50,48],[76,48],[78,42]]},{"t":"text","x":26,"y":40,"text":"发生装置","size":3.6,"tone":"accent"},{"t":"text","x":26,"y":47,"text":"（待补画）","size":3.4,"tone":"muted"},{"t":"text","x":76,"y":60,"text":"排水法收集（已画好）","size":3.2,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-3-q10-a","title":"参考答案：补全后的完整装置","caption":"试管口略向下倾斜、管口塞棉花，酒精灯用外焰加热药品部位","view":"wide","alt":"铁架台固定着试管，试管口略向下倾斜并塞有棉花，酒精灯在试管下方加热，导管从橡皮塞伸出后通入水槽中倒置的集气瓶","prims":[{"t":"stand","x":16,"y":48,"h":38,"w":20,"clamps":[0.72]},{"t":"testTube","x":34,"y":22,"h":30,"w":9,"tilt":100},{"t":"circle","cx":45,"cy":24,"r":2.4,"tone":"muted"},{"t":"text","x":45,"y":17,"text":"棉花","size":3,"tone":"accent"},{"t":"alcoholLamp","x":26,"y":40,"lit":true},{"t":"text","x":20,"y":58,"text":"试管口略向下倾斜","size":3,"tone":"accent"},{"t":"line","x1":48,"y1":29,"x2":49.6,"y2":20.2,"width":1.2},{"t":"curve","points":[[50,25],[58,21],[66,22],[68,44],[68,49],[78,49],[79,42]]},{"t":"beaker","x":62,"y":34,"w":34,"h":22,"fill":0.55},{"t":"line","x1":72,"y1":28,"x2":72,"y2":44,"width":0.6},{"t":"line","x1":86,"y1":28,"x2":86,"y2":44,"width":0.6},{"t":"line","x1":72,"y1":28,"x2":86,"y2":28,"width":0.6},{"t":"rect","x":72.6,"y":32,"w":12.8,"h":11,"fill":true,"tone":"main"},{"t":"text","x":79,"y":60,"text":"倒置集气瓶","size":3.2,"tone":"muted"}]}},{"id":"chem-substance-3-m1-q1","type":"short","stem":"（3 分）材料一中试管口为什么要略向下倾斜？管口塞一团棉花的作用是什么？","answer":"试管口略向下倾斜是为了防止加热时药品中的湿存水或反应生成的冷凝水倒流到试管底部，使试管骤冷炸裂；管口塞一团棉花是为了防止高锰酸钾粉末随气流进入导管，堵塞导管或使水槽中的水变红。","explain":"","rubric":["答出「防止冷凝水倒流」并说明后果（试管炸裂）","答出「防止高锰酸钾粉末进入导管」","说明粉末进入导管的后果（堵塞导管或使水变红）"]},{"id":"chem-substance-3-m1-q2","type":"short","stem":"（4 分）根据材料二，你能得出什么结论？该实验为什么要用「质量相同、浓度相同」的两份过氧化氢溶液？","answer":"结论：二氧化锰能加快过氧化氢分解的速率，在这个反应中起催化作用。用两份质量相同、浓度相同的过氧化氢溶液是为了控制变量：保证反应物的量相同，这样产生 100 mL 氧气所用时间的差异就只能由是否加入二氧化锰造成，否则无法判断是反应物多少还是催化剂造成的差别。","explain":"","rubric":["答出「二氧化锰能加快过氧化氢的分解速率」","答出「控制变量」并说明控制的是什么变量（反应物的质量和浓度相同）","说明控制变量的目的：排除反应物多少对反应时间的影响","表述中把「速率」与「产量」区分开（若答「二氧化锰能生成更多氧气」不得分）"]},{"id":"chem-substance-3-m1-q3","type":"short","stem":"（4 分）根据材料三计算：15.8 g 高锰酸钾完全分解能生成多少克氧气？反应后固体残留物的质量是多少克？（相对原子质量：K 39、Mn 55、O 16）","answer":"设生成氧气的质量为 x。由 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑ 可知 m(KMnO₄)∶m(O₂) = 316∶32。由 316∶32 = 15.8 g∶x 得 x = 1.6 g。由质量守恒定律，固体残留物的质量 = 15.8 g − 1.6 g = 14.2 g。答：生成氧气 1.6 g，反应后固体残留物的质量为 14.2 g。","explain":"","rubric":["写出并配平化学方程式 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑","算出 KMnO₄ 的相对分子质量为 158，质量比为 316∶32","求出氧气质量为 1.6 g","用质量守恒求出固体残留物为 14.2 g，并写出带单位的答句"]}]},{"id":"chem-substance-4","title":"水的组成与净化：电解水实验·氢气性质与验纯·硬水软水与净水方法","subtitle":"人教版九年级 · 第四单元 自然界的水 · 9a","grade":"9a","tags":["人教版九年级 · 第四单元 自然界的水"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第四单元 自然界的水 · 9a"},{"type":"note","title":"问题切入","text":"水是由什么组成的？把水通电，两极上竟然冒出了两种不同的气体——这凭什么能证明水由氢、氧两种元素组成？氢气为什么点燃前必须验纯？自来水厂的净水流程每一步在做什么，硬水又该怎么软化？"},{"type":"note","title":"一句话抓住关键","text":"电解水时正极产生氧气、负极产生氢气，体积比约为 1∶2（口诀「正氧负氢，氢二氧一」），由此得出结论：水是由氢元素和氧元素组成的。从微观上看，水分子在通电条件下分成氢原子和氧原子，原子再重新组合成氢分子和氧分子——化学变化中分子可分、原子不可分，原子的种类和个数都不变。硬水含较多可溶性钙、镁化合物，用肥皂水鉴别，用煮沸或蒸馏的方法软化。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"把水通上直流电，两个电极上竟然冒出了两种不同的气体：一边能燃烧，一边能让带火星的木条复燃。水明明是「一种东西」，怎么能拆出两种气体？这正是电解水实验最有意思的地方。","walk":["电解水时，正极产生氧气，负极产生氢气，体积比约为 1∶2。口诀「正氧负氢，氢二氧一」。","氢气本身可以燃烧，但点燃前必须验纯：收集一小试管氢气，靠近火焰，听到尖锐爆鸣声说明不纯，声音很小说明较纯。混入空气点燃可能爆炸。","水的净化流程通常包括沉淀、过滤、吸附、消毒；活性炭起吸附作用，煮沸可以降低水的硬度。硬水是含较多可溶性钙镁化合物的水，软水则较少。"],"try":"观察家里烧水壶内壁的水垢：水垢多的地区水质偏硬。用煮沸后的水与自来水对比，体会「煮沸能降低硬度」。","use":["电解水结论表述要严谨：水由氢元素和氧元素组成，不能写成「水由氢气和氧气组成」。","净水题按「除不溶性杂质—除色素异味—杀菌消毒—软化」的顺序答，每一步对应一种方法。"]},{"type":"h","text":"【宏观】宏观：电解水的现象与结论"},{"type":"p","text":"在电解器里装满水（预先加入少量硫酸钠溶液增强导电性），接通直流电源，可以看到两个电极上都有气泡产生。一段时间后比较两支试管中气体的体积：与电源负极相连的一极收集到的气体体积大约是与正极相连那一极的 2 倍。检验一下：把带火星的木条伸入正极的气体中，木条复燃，那是氧气；负极的气体可以燃烧，产生淡蓝色火焰，那是氢气。于是得到结论——水在通电条件下分解生成氢气和氧气，说明水是由氢元素和氧元素组成的。"},{"type":"figure","figure":{"id":"fig-chem-substance-4-1","title":"电解水实验","caption":"正氧负氢、氢二氧一：正极氧气、负极氢气，体积比约 1∶2","view":"wide","alt":"水槽中插着两支试管，与电源负极相连的一极收集到的气体体积约为正极的两倍，正极上产生的是氧气、负极上产生的是氢气","prims":[{"t":"beaker","x":24,"y":40,"w":52,"h":16,"fill":0.6},{"t":"testTube","x":36,"y":26,"h":32,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":64,"y":26,"h":32,"w":12,"liquid":0.78,"color":"colorless"},{"t":"line","x1":36,"y1":14,"x2":36,"y2":50,"width":0.6,"tone":"muted"},{"t":"line","x1":64,"y1":14,"x2":64,"y2":50,"width":0.6,"tone":"muted"},{"t":"text","x":36,"y":7,"text":"H₂（负极）","size":3.4,"tone":"accent"},{"t":"text","x":64,"y":7,"text":"O₂（正极）","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"正氧负氢，氢二氧一（体积比约 2∶1）","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"结论的表述必须严密：「水是由氢元素和氧元素组成的」，不能写成「水是由氢气和氧气组成的」。元素是宏观概念，氢气、氧气是两种具体的单质，水通电才分解出它们。"},{"type":"h","text":"【宏观】微观：水分子分成原子，原子重新组合"},{"type":"p","text":"把通电的过程放大到粒子层面就很清楚了：2 个水分子在通电条件下各自分成 2 个氢原子和 1 个氧原子，共 4 个氢原子和 2 个氧原子；这些原子重新组合，每 2 个氢原子结合成 1 个氢分子（共 2 个氢分子），每 2 个氧原子结合成 1 个氧分子（共 1 个氧分子）。整个过程里原子的种类没变、个数也没变，所以反应前后的总质量相等，也就解释了为什么水中只有氢、氧两种元素。"},{"type":"figure","figure":{"id":"fig-chem-substance-4-2","title":"电解水的微观过程","caption":"两个水分子分成原子，原子重新组合成两个氢分子和一个氧分子","view":"tall","alt":"两个水分子在通电条件下分成四个氢原子和两个氧原子，这些原子重新组合成两个氢分子和一个氧分子，反应前后原子的种类和个数都没有改变","prims":[{"t":"molecule","x":16,"y":26,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-5,"dy":-4,"r":2.6,"symbol":"H"},{"dx":5,"dy":-4,"r":2.6,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":16,"y":58,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-5,"dy":-4,"r":2.6,"symbol":"H"},{"dx":5,"dy":-4,"r":2.6,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"arrow","x1":28,"y1":42,"x2":42,"y2":42,"label":"通电","labelDy":-4},{"t":"atom","x":54,"y":16,"r":4,"symbol":"O","color":"red"},{"t":"atom","x":54,"y":30,"r":4,"symbol":"O","color":"red"},{"t":"atom","x":54,"y":48,"r":4,"symbol":"H"},{"t":"atom","x":54,"y":62,"r":4,"symbol":"H"},{"t":"atom","x":54,"y":76,"r":4,"symbol":"H"},{"t":"atom","x":54,"y":90,"r":4,"symbol":"H"},{"t":"text","x":54,"y":108,"text":"原子（种类、个数不变）","size":3.4,"tone":"muted"},{"t":"arrow","x1":68,"y1":60,"x2":80,"y2":60,"label":"重新组合","labelDy":-4},{"t":"molecule","x":88,"y":22,"atoms":[{"dx":-3,"dy":0,"symbol":"H"},{"dx":3,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":88,"y":60,"atoms":[{"dx":-3,"dy":0,"symbol":"H"},{"dx":3,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":88,"y":98,"atoms":[{"dx":-3.4,"dy":0,"symbol":"O","color":"red"},{"dx":3.4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"text","x":50,"y":128,"text":"化学变化中分子可分，原子不可分","size":3.6,"tone":"muted"}]}},{"type":"note","title":"","text":"「分子可分、原子不可分」是理解一切化学变化的钥匙：电解水里变的是水分子，氢分子和氧分子是「新造出来」的；原子只是换了搭档。答题时把「分成原子」和「重新组合」两步都写出来才算完整。"},{"type":"h","text":"【微观】符号：把电解水和氢气燃烧写成方程式"},{"type":"p","text":"电解水的方程式是 2H₂O —通电→ 2H₂↑ + O₂↑：左边 4 个氢原子、2 个氧原子，右边 2 个 H₂ 有 4 个氢原子、1 个 O₂ 有 2 个氧原子，两边相等。氢气燃烧的方程式是 2H₂ + O₂ —点燃→ 2H₂O，它正好是电解水的逆过程。把两个方程式放在一起看，就明白「水 ⇄ 氢气 + 氧气」这一对反应在元素组成上是守恒的。还要记住水的化学式 H₂O：氢为 +1 价、氧为 −2 价，化合物中各元素化合价的代数和为零。"},{"type":"note","title":"","text":"电解水的条件必须写「通电」，不能写成「电解」以外的字样，也不能不写；氢气燃烧的条件写「点燃」。气体符号 ↑ 只用在溶液或液体中放出气体的反应上，所以电解水要写 ↑，而氢气燃烧生成液态水不写 ↑。"},{"type":"h","text":"【符号】宏观：氢气的性质与验纯"},{"type":"p","text":"氢气是无色、无味的气体，密度比空气小得多（是所有气体中最小的），难溶于水，所以既能用向下排空气法收集，也能用排水法收集。氢气具有可燃性，纯净的氢气在空气中能安静地燃烧，产生淡蓝色火焰，放出大量热，在火焰上方罩一个干冷的烧杯，烧杯内壁会出现水雾——说明氢气燃烧的产物是水。但如果氢气中混有空气，点燃时可能发生爆炸，所以点燃氢气前必须验纯：用排水法收集一小试管氢气，用拇指堵住管口，管口向下移到酒精灯火焰旁，松开拇指，听到尖锐的爆鸣声说明氢气不纯，声音很小说明氢气较纯。"},{"type":"figure","figure":{"id":"fig-chem-substance-4-3","title":"氢气的验纯方法","caption":"试管口向下靠近火焰：尖锐爆鸣声说明不纯，声音很小说明较纯","view":"wide","alt":"一支管口向下的试管中收集了氢气，管口靠近点燃的酒精灯火焰，说明用声音判断氢气是否纯净的方法","prims":[{"t":"testTube","x":34,"y":20,"h":26,"w":10,"tilt":180},{"t":"alcoholLamp","x":34,"y":44,"lit":true},{"t":"text","x":52,"y":14,"text":"收集一小试管氢气","anchor":"start","size":3.4},{"t":"text","x":52,"y":21,"text":"（管口向下，氢气比空气轻）","anchor":"start","size":3.2,"tone":"muted"},{"t":"text","x":52,"y":30,"text":"管口移到酒精灯火焰旁，松开拇指","anchor":"start","size":3.2},{"t":"text","x":50,"y":58,"text":"尖锐的爆鸣声 → 氢气不纯；声音很小 → 氢气较纯","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"验纯的三种表述都要会写：操作（收集一试管氢气、管口靠近火焰、松开拇指）、现象（声音大小）、结论（纯或不纯）。凡可燃性气体（氢气、一氧化碳、甲烷）点燃前都要验纯，这是安全常识，也是必考操作点。"},{"type":"h","text":"【应用】应用：水的净化与硬水软化"},{"type":"p","text":"自来水厂的净水流程是：取水→加絮凝剂使悬浮杂质凝聚沉降→过滤→用活性炭吸附色素和异味→投药消毒→配水。其中沉淀、过滤、吸附都是物理方法，消毒是化学方法。实验室里净化程度最高的方法是蒸馏，能得到几乎纯净的水。判断水的硬度用肥皂水：加等量肥皂水搅拌，泡沫少、浮渣多的是硬水，泡沫多、浮渣少的是软水。硬水洗衣服费肥皂、烧水容易结水垢，生活中用煮沸的方法软化（可溶性钙镁化合物受热分解、沉淀下来），实验室里用蒸馏的方法软化。"},{"type":"figure","figure":{"id":"fig-chem-substance-4-4","title":"过滤操作的要点","caption":"一贴、二低、三靠：滤纸紧贴漏斗内壁，液面低于滤纸边缘，漏斗下端管口紧靠烧杯内壁","view":"wide","alt":"漏斗中放有滤纸、滤纸紧贴漏斗内壁，玻璃棒斜靠在三层滤纸处引流，液体沿玻璃棒流下，漏斗下端管口紧靠烧杯内壁，烧杯中收集到澄清的滤液","prims":[{"t":"funnel","x":46,"y":30,"kind":"funnel","h":18},{"t":"poly","points":[[39.5,21.5],[47,31],[54.5,21.5]],"tone":"muted"},{"t":"line","x1":41,"y1":13,"x2":47,"y2":29,"width":0.9},{"t":"beaker","x":34,"y":38,"w":26,"h":16,"fill":0.35},{"t":"text","x":25,"y":12,"text":"玻璃棒（引流）","anchor":"start","size":3.2},{"t":"text","x":72,"y":24,"text":"滤纸紧贴漏斗内壁","anchor":"start","size":3},{"t":"text","x":72,"y":32,"text":"液面低于滤纸边缘","anchor":"start","size":3},{"t":"text","x":50,"y":59,"text":"漏斗下端管口紧靠烧杯内壁","size":3.2,"tone":"muted"},{"t":"text","x":16,"y":46,"text":"烧杯","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"硬水软化与消毒是两件事：煮沸能降低水的硬度，却不能杀菌（杀菌靠投药或加热到沸腾一段时间）；过滤只能除去不溶性杂质，不能除去可溶性钙镁化合物，所以过滤后的水仍是混合物。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["元素的质量分数（以水为例）","水中氢元素的质量分数 = (1×2) ÷ (1×2 + 16) × 100% ≈ 11.1%","用于计算纯净物中某元素所占的质量比例。水中氢元素与氧元素的质量比是 2∶16 = 1∶8，所以电解水得到的氢气与氧气的质量比也是 1∶8（不是体积比 2∶1）。计算时相对原子质量取整数：H 1、O 16。"],["化学方程式中的质量比与体积比","2H₂O —通电→ 2H₂↑ + O₂↑：m(H₂O)∶m(H₂)∶m(O₂) = 36∶4∶32 = 9∶1∶8；V(H₂)∶V(O₂) ≈ 2∶1","化学方程式计算只能用质量比；体积比只能由化学计量数（分子个数比）推出，且要求同温同压。电解水题里最常见的错误就是把体积比 2∶1 直接当成质量比来算。"],["化合价规则","化合物中各元素化合价的代数和为零；水中氢为 +1 价、氧为 −2 价","用于书写或检验化学式：已知化合价可以写出化学式（如 H 为 +1、O 为 −2，得到 H₂O），反过来也能由化学式求某元素的化合价。单质中元素的化合价规定为零。"]]},{"type":"h","text":"应用 · 电解水的计算"},{"type":"note","title":"情境","text":"在电解水实验中，某同学电解了 18 g 水，水全部分解完。求生成氢气和氧气的质量各是多少克，并写出它们的体积比（理论上）。（相对原子质量：H 1、O 16）"},{"type":"list","title":"解答步骤","items":["算出相对质量：2H₂O = 36，2H₂ = 4，O₂ = 32。","设生成氢气的质量为 x：36∶4 = 18 g∶x，解得 x = 2 g。","设生成氧气的质量为 y：36∶32 = 18 g∶y，解得 y = 16 g。","验算：2 g + 16 g = 18 g，符合质量守恒定律，答案正确。","由方程式中的化学计量数可知，氢气与氧气的分子个数比为 2∶1，同温同压下的体积比约为 2∶1。"]},{"type":"note","title":"结论","text":"生成氢气 2 g、氧气 16 g，体积比约为 2∶1。这里要分清两个比：质量比是 4∶32 = 1∶8，体积比是 2∶1，二者不同，别混用。"},{"type":"h","text":"应用 · 鉴别硬水与软水"},{"type":"note","title":"情境","text":"有两瓶无色透明的液体，一瓶是硬水（含有较多可溶性钙、镁化合物），另一瓶是软水，怎样把它们区分开？如果要把硬水软化，可以怎么做？"},{"type":"list","title":"解答步骤","items":["各取等量的两种水样分别加入两支试管中。","向两支试管中分别滴加等量的肥皂水，振荡（搅拌）。","观察现象：泡沫多、浮渣少的是软水；泡沫少、浮渣多的是硬水。","软化方法：生活中煮沸；实验室中蒸馏（也可用离子交换法，属于拓展）。"]},{"type":"note","title":"结论","text":"用等量肥皂水比较泡沫与浮渣的多少。注意两个「等量」不能漏：水样要等量、肥皂水也要等量，否则比较没有意义，这是这类鉴别题最容易被扣分的地方。"},{"type":"h","text":"实验 1 · 电解水实验"},{"type":"note","title":"实验目的","text":"通过电解水得到的氢气和氧气，推断水的元素组成，并用粒子模型解释化学变化中分子与原子的行为。"},{"type":"list","title":"实验器材","items":["水电解器（或两支试管、水槽、直流电源、电极）","水（预先加入少量硫酸钠或氢氧化钠溶液）","带火星的木条、火柴","酒精灯"]},{"type":"figure","figure":{"id":"fig-chem-substance-4-exp1","title":"电解水实验装置","caption":"接通直流电源后，负极产生的气体体积约为正极的 2 倍","view":"wide","alt":"水槽中倒插着两支试管，电极分别接直流电源的正负极，负极一极收集到的气体较多、正极一极较少，通电后两极都有气泡产生","prims":[{"t":"beaker","x":20,"y":40,"w":60,"h":16,"fill":0.6},{"t":"testTube","x":34,"y":26,"h":32,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":66,"y":26,"h":32,"w":12,"liquid":0.78,"color":"colorless"},{"t":"line","x1":34,"y1":14,"x2":34,"y2":50,"width":0.6,"tone":"muted"},{"t":"line","x1":66,"y1":14,"x2":66,"y2":50,"width":0.6,"tone":"muted"},{"t":"text","x":34,"y":7,"text":"负极（H₂）","size":3.4,"tone":"accent"},{"t":"text","x":66,"y":7,"text":"正极（O₂）","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"加入少量硫酸钠溶液：增强水的导电性","size":3.4,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["在水电解器中注满水，预先向水中加入少量硫酸钠溶液（或氢氧化钠溶液）。","接通直流电源，观察两个电极上出现的现象。","通电一段时间后，比较两支试管中收集到的气体体积。","用带火星的木条检验正极产生的气体；用燃着的木条（或点燃）检验负极产生的气体。","记录现象并写出反应的化学方程式，归纳结论。"]},{"type":"note","title":"实验现象","text":"通电后两个电极上都有气泡产生；一段时间后负极收集到的气体体积约为正极的 2 倍。正极的气体使带火星的木条复燃，证明是氧气；负极的气体能燃烧并产生淡蓝色火焰，证明是氢气。"},{"type":"note","title":"实验结论","text":"水在通电条件下分解生成氢气和氧气，化学方程式为 2H₂O —通电→ 2H₂↑ + O₂↑。根据化学变化前后元素的种类不变，可以推断水是由氢元素和氧元素组成的。"},{"type":"list","title":"注意事项","items":["水中要预先加入少量硫酸钠或氢氧化钠溶液：增强水的导电性，使反应能较快进行；它不是催化剂，也不改变生成气体的质量和体积比。","必须使用直流电源，不能用交流电源，否则两极产生的气体无法分开检验。","电解水时氢气与氧气的体积比理论上是 2∶1，实际实验中氧气体积往往略小于理论值（氧气在水中溶解得比氢气多、电极上也会消耗少量氧气），这是正常现象。","检验氢气并点燃前必须验纯，防止氢气中混有空气发生爆炸；点燃时要用燃着的木条靠近管口，不要对着人。","实验需要通电一段时间后才能收集到足够多的气体；观察现象要等气泡稳定、气体体积有明显差别时再比较，不能刚通电就下结论。"]},{"type":"h","text":"实验 2 · 过滤——除去水中不溶性杂质"},{"type":"note","title":"实验目的","text":"学会用过滤的方法分离液体与不溶性固体，掌握「一贴、二低、三靠」的操作要领。"},{"type":"list","title":"实验器材","items":["漏斗、滤纸、玻璃棒","烧杯（两只）、铁架台（带铁圈）","浑浊的河水（或泥水）"]},{"type":"figure","figure":{"id":"fig-chem-substance-4-exp2","title":"过滤操作","caption":"滤纸紧贴漏斗内壁，液面低于滤纸边缘，玻璃棒引流，漏斗下端管口紧靠烧杯内壁","view":"wide","alt":"漏斗内放有滤纸并紧贴内壁，玻璃棒斜靠在三层滤纸一侧引流，浑浊液体沿玻璃棒缓缓流入漏斗，漏斗下端管口紧靠烧杯内壁，烧杯中收集到澄清的滤液","prims":[{"t":"funnel","x":46,"y":30,"kind":"funnel","h":18},{"t":"poly","points":[[39.5,21.5],[47,31],[54.5,21.5]],"tone":"muted"},{"t":"line","x1":41,"y1":13,"x2":47,"y2":29,"width":0.9},{"t":"beaker","x":34,"y":38,"w":26,"h":16,"fill":0.35},{"t":"text","x":24,"y":12,"text":"玻璃棒（引流）","anchor":"start","size":3.2},{"t":"text","x":72,"y":24,"text":"滤纸紧贴漏斗内壁","anchor":"start","size":3},{"t":"text","x":72,"y":32,"text":"漏斗下端管口紧靠","anchor":"start","size":3},{"t":"text","x":72,"y":39,"text":"烧杯内壁","anchor":"start","size":3},{"t":"text","x":50,"y":59,"text":"液面要低于滤纸边缘","size":3.2,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["把滤纸对折两次，展开成圆锥形，放入漏斗中，使滤纸紧贴漏斗内壁，用少量水润湿并赶走气泡。","把漏斗放在铁架台的铁圈上，调整高度，使漏斗下端管口紧靠烧杯内壁。","把浑浊的水沿玻璃棒缓缓倒入漏斗（玻璃棒下端要斜靠在三层滤纸处），液面始终低于滤纸边缘。","待液体全部滤过后，观察滤液是否澄清，比较滤纸上的固体与滤液的差别。"]},{"type":"note","title":"实验现象","text":"浑浊的河水经过滤后变得澄清透明，滤纸上留下泥沙等不溶性固体；如果滤液仍然浑浊，说明操作存在问题。"},{"type":"note","title":"实验结论","text":"过滤可以把不溶于水的固体与液体分开，得到澄清的液体，但它只能除去不溶性杂质，不能除去可溶性杂质，所以过滤后的水仍然是混合物。"},{"type":"list","title":"注意事项","items":["一贴：滤纸要紧贴漏斗内壁，中间不能有气泡，否则液体从缝隙流下、过滤太慢且滤液浑浊。","二低：滤纸边缘要低于漏斗边缘，液面要低于滤纸边缘；液面高于滤纸边缘时，液体会从滤纸与漏斗之间流下，滤液仍然浑浊。","三靠：玻璃棒下端要斜靠三层滤纸处（不能戳破滤纸）、倾倒液体的烧杯口要紧靠玻璃棒、漏斗下端管口要紧靠烧杯内壁。","不能用玻璃棒在漏斗内搅拌来加快过滤，这样会把滤纸戳破，使滤液浑浊。","若滤液仍然浑浊，应查清原因（滤纸破损、液面高于滤纸边缘、仪器不干净）后重新过滤，不能直接当作滤液使用。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2H₂O —通电→ 2H₂↑ + O₂↑","通电","通电后两极上都有气泡产生，负极产生的气体体积约为正极的 2 倍；正极的气体使带火星的木条复燃，负极的气体点燃时产生淡蓝色火焰","配平：左边 2×2 = 4 个氢原子、2 个氧原子，右边 2 个 H₂ 有 4 个氢原子、1 个 O₂ 有 2 个氧原子，两边相等。条件必须写「通电」，不能漏；生成的气体从液体中放出，两个气体符号 ↑ 都不能少。"],["2H₂ + O₂ —点燃→ 2H₂O","点燃","纯净的氢气在空气中安静地燃烧，产生淡蓝色火焰，放出大量热，在火焰上方罩一个干冷的烧杯，烧杯内壁出现水雾","配平：左边 4 个氢原子、2 个氧原子，右边 2H₂O 也是 4 个氢原子、2 个氧原子。生成的水在常温下是液体，不写 ↑；点燃前必须验纯，氢气不纯时点燃会发生爆炸。现象写「淡蓝色火焰」，不要写成「蓝紫色」（那是硫在氧气中燃烧的现象）。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["电解水时加入硫酸钠，是为了加快水的分解，它就是催化剂。","加入少量硫酸钠（或氢氧化钠）是为了增强水的导电性，使电解能较快进行；它不参与反应，也不改变生成的氢气和氧气的质量与体积比。","纯水的导电性很弱，实验会进行得非常慢。硫酸钠只是溶于水后提供自由移动的离子，并不是「改变反应速率而自身质量和化学性质不变」意义上的催化剂，答题时说「增强导电性」才准确。"],["电解水得到氢气和氧气，说明水是由氢气和氧气组成的。","水是由氢元素和氧元素组成的；氢气、氧气是水分解后生成的两种单质。","混淆了「元素」和「物质」两个层次。组成物质的是元素，水这种物质里并没有氢气或氧气，只有氢、氧两种元素；说「水由氢气和氧气组成」等于说水里溶有氢气和氧气，与事实不符。"],["河水经过沉淀、过滤、吸附、消毒变成自来水后，就是纯净物了。","自来水中仍含有可溶性钙、镁化合物等杂质，属于混合物；实验室里用蒸馏才能得到几乎纯净的水。","过滤只能除去不溶性杂质，吸附只能除去色素和异味，两者都除不掉溶于水的钙镁化合物。判断纯净物的标准仍然是「只由一种物质组成」。"],["氢气燃烧产生蓝紫色火焰，与硫在氧气中燃烧的现象相同。","氢气燃烧产生淡蓝色火焰；「明亮的蓝紫色火焰」是硫在氧气中燃烧的现象。","两种气体的火焰颜色很接近、容易混，「淡蓝」与「蓝紫」要按要求区分。氢气燃烧还能看到烧杯内壁出现水雾，这是判断产物是水的重要证据。"]]},{"type":"table","title":"硬水与软水（成分差别、鉴别方法与软化方法）","head":["比较项","硬水","软水"],"rows":[["成分","含较多可溶性钙、镁化合物","含较少或不含可溶性钙、镁化合物"],["加肥皂水","泡沫少、浮渣多","泡沫多、浮渣少"],["生活影响","洗衣服费肥皂、烧水结水垢、管道易堵塞","洗涤效果好、不易结水垢"],["软化方法","生活中煮沸，实验室中蒸馏","无需软化（本身就是软水）"]]},{"type":"table","title":"三种净水方法的比较（能除去哪类杂质、净化程度与原理）","head":["比较项","过滤","吸附与蒸馏"],"rows":[["过滤","除去不溶性固体杂质，净化程度较低","—（过滤是物理方法，只能分离不溶物）"],["吸附","—","活性炭吸附色素和异味，不能除去可溶性钙镁化合物"],["蒸馏","—","根据沸点不同把水变成蒸气再冷凝，能除去可溶与不溶杂质，净化程度最高"],["共同点","都是物理变化，都没有生成新物质","消毒属于化学方法，会杀死细菌（生成新物质）"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["电解水实验的现象、结论与微观解释","高频考点：正氧负氢与体积比 2∶1 的判断、气体的检验方法、由实验推出「水由氢氧两种元素组成」的结论，以及用粒子模型描述「分子分成原子、原子重新组合」的过程。"],["水的净化流程与过滤操作","以自来水厂净水流程或实验室过滤为情境，考每一步的作用、过滤的「一贴二低三靠」、滤液仍然浑浊的原因分析，以及「净水方法都是物理变化、消毒是化学变化」的判断。"],["硬水与软水的鉴别和软化","常以生活情境（烧水结水垢、洗衣服费肥皂）设题，考肥皂水鉴别法（两个「等量」）、煮沸与蒸馏的区别，以及与蒸馏、过滤等净化方法的组合判断。"],["氢气性质与安全操作","考氢气的物理性质（密度最小、难溶于水）、可燃性与验纯的操作步骤，以及「点燃可燃性气体前必须验纯」这一安全规范在实验题中的表述。"]]},{"type":"quote","text":"【材料一】某小组用如图装置电解水，接通直流电源一段时间后观察：与电源负极相连的电极上收集到 20 mL 气体，与正极相连的电极上收集到 10 mL 气体。把带火星的木条伸入正极的气体中，木条复燃。【材料二】自来水厂的净水流程：取水→加絮凝剂使悬浮物凝聚沉降→过滤→用活性炭吸附→投药消毒→配水。【材料三】某地区自来水中可溶性钙、镁化合物含量较高，属于硬水。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）根据材料一，写出负极和正极上分别得到什么气体，并写出电解水的化学方程式。由此可以得出关于水的组成的什么结论？","【设问】（4 分）在电解水实验中，若有 18 g 水完全分解，计算生成氢气和氧气的质量各是多少克？生成氢气和氧气的质量比与体积比是否相同？（相对原子质量：H 1、O 16）","【设问】（3 分）根据材料二与材料三，说明自来水厂的哪些净水步骤属于物理变化？怎样用简单的方法证明该地区的自来水是硬水？生活中可以怎样把它软化？"]}],"questions":[{"id":"chem-substance-4-q1","type":"choice","stem":"如图是电解水的实验装置，a 试管与电源负极相连、b 试管与电源正极相连。下列说法正确的是（　）","answer":"B","explain":"B 正确，正是「正氧负氢、氢二氧一」中的体积关系。A 把两极的气体弄反了：a 与负极相连，收集到的是氢气，氢气能燃烧但不支持燃烧，带火星的木条不会复燃；使木条复燃的是正极的氧气。C 把导电性和产量混为一谈：硫酸钠只是增强水的导电性，不改变生成气体的质量。D 错在结论的表述：应为「水是由氢元素和氧元素组成的」，氢气与氧气是电解生成的产物，不是水的组成成分。","options":["a 试管中收集到的气体能使带火星的木条复燃","正极产生的气体与负极产生的气体的体积比约为 1∶2","电解水时加入少量硫酸钠溶液，是为了增加生成氧气的质量","该实验说明水是由氢气和氧气组成的"],"difficulty":2,"tags":["水的组成","电解水","实验结论"],"figure":{"id":"fig-chem-substance-4-q1","title":"电解水实验装置","caption":"a 接负极、b 接正极","view":"wide","alt":"水槽中倒插着两支试管，a 试管与电源负极相连、收集到的气体较多，b 试管与电源正极相连、收集到的气体较少","prims":[{"t":"beaker","x":20,"y":40,"w":60,"h":16,"fill":0.6},{"t":"testTube","x":36,"y":26,"h":32,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":64,"y":26,"h":32,"w":12,"liquid":0.78,"color":"colorless"},{"t":"text","x":36,"y":8,"text":"a","size":4},{"t":"text","x":64,"y":8,"text":"b","size":4},{"t":"text","x":36,"y":60,"text":"接电源负极","size":3.2,"tone":"muted"},{"t":"text","x":64,"y":60,"text":"接电源正极","size":3.2,"tone":"muted"}]}},{"id":"chem-substance-4-q2","type":"choice","stem":"下列关于氢气的说法正确的是（　）","answer":"C","explain":"C 正确：氢气是可燃性气体，混有空气时点燃会发生爆炸，验纯是必做的安全操作。A 有两处错：氢气难溶于水，可以用排水法收集；「只能用向下排空气法」也就不成立。B 把颜色记错了：氢气燃烧是淡蓝色火焰，明亮的蓝紫色火焰是硫在氧气中燃烧的现象。D 把密度关系说反了：氢气是密度最小的气体，比空气小得多，用向下排空气法收集时集气瓶应倒放（瓶口向下）。","options":["氢气易溶于水，所以只能用向下排空气法收集","氢气燃烧产生明亮的蓝紫色火焰","点燃氢气前必须检验它的纯度，否则可能发生爆炸","氢气的密度比空气大，收集时集气瓶应该正放"],"difficulty":1,"tags":["水的组成","氢气的性质","验纯"]},{"id":"chem-substance-4-q3","type":"choice","stem":"下列关于水的净化的说法正确的是（　）","answer":"D","explain":"D 正确：蒸馏利用水与杂质的沸点不同，把水变成蒸气再冷凝，除去了可溶与不溶的杂质，净化程度最高。A 错：过滤只能除去不溶性固体，溶于水的物质除不掉，过滤后的水仍是混合物。B 夸大了吸附的作用：活性炭吸附的是色素和异味，对可溶性钙镁化合物没有去除作用，不能软化硬水。C 错在分类：自来水仍含有可溶性杂质，属于混合物。","options":["过滤可以除去水中的所有杂质，得到纯净的水","活性炭能吸附水中的钙、镁化合物，使硬水变成软水","经过沉淀、过滤、吸附、消毒处理后的自来水是纯净物","蒸馏可以得到几乎纯净的水，是净化程度最高的方法"],"difficulty":2,"tags":["水的净化","过滤与蒸馏"]},{"id":"chem-substance-4-q4","type":"choice","stem":"区分硬水和软水，最简便可行的方法是（　）","answer":"A","explain":"A 正确：肥皂水遇硬水中的钙、镁化合物会生成浮渣，所以泡沫少、浮渣多的是硬水，泡沫多的是软水。B 不可行：硬水和软水都是无色透明的，看颜色区分不出来。C 不可行：食盐水与钙、镁化合物不反应，没有任何现象。D 不可行：通入二氧化碳后，硬水中只是可能产生少量沉淀，现象不明显且不可靠，不能作为鉴别方法。","options":["分别加入等量的肥皂水，搅拌后比较泡沫与浮渣的多少","观察两种水样的颜色是否不同","分别向两种水样中加入食盐水","分别向两种水样中通入二氧化碳"],"difficulty":1,"tags":["水的净化","硬水与软水"]},{"id":"chem-substance-4-q5","type":"choice","stem":"进行过滤操作时，下列做法正确的是（　）","answer":"A","explain":"A 正确，这正是「一贴、二低」中的要点：滤纸紧贴内壁（中间无气泡）、液面低于滤纸边缘。B 与规范相反：漏斗下端管口必须紧靠烧杯内壁，使滤液沿壁流下，防止液体飞溅，紧靠不会污染滤液。C 危险且错误：用玻璃棒搅拌会戳破滤纸，滤液反而变浑浊，过滤速度也不能靠搅拌加快。D 错：滤纸边缘必须低于漏斗边缘，高出漏斗边缘液体就会从缝隙流走，起不到过滤作用。","options":["滤纸要紧贴漏斗内壁，液面要低于滤纸的边缘","漏斗下端管口不要紧靠烧杯内壁，以免污染滤液","用玻璃棒在漏斗内不断搅拌，以加快过滤的速度","把滤纸剪得比漏斗高一些，以便装更多的液体"],"difficulty":2,"tags":["水的净化","过滤操作"]},{"id":"chem-substance-4-q6","type":"fill","stem":"电解水时，与电源负极相连的电极上产生的气体是 ______（填物质名称）。","answer":"氢气","explain":"记住口诀「正氧负氢，氢二氧一」：正极产生氧气、负极产生氢气，氢气的体积约为氧气的 2 倍。填「氧气」是把两极记反了。检验方法也不同：负极的氢气能燃烧并产生淡蓝色火焰，正极的氧气能使带火星的木条复燃。","difficulty":1,"tags":["水的组成","电解水"]},{"id":"chem-substance-4-q7","type":"fill","stem":"电解 36 g 水，理论上可以得到氢气 ______ g。（相对原子质量：H 1、O 16）","answer":"4","explain":"由 2H₂O —通电→ 2H₂↑ + O₂↑ 可知，水与氢气的质量比为 (2×18)∶(2×2) = 36∶4，所以 36 g 水完全分解可得到氢气 4 g（同时得到氧气 32 g，符合质量守恒：4 + 32 = 36）。也可以用水里氢元素的质量分数来算：36 g × 2/18 = 4 g，两种算法结果一致。","difficulty":2,"tags":["水的组成","化学方程式计算","元素质量分数"]},{"id":"chem-substance-4-q8","type":"short","stem":"某同学电解了 90 g 水，水全部分解。求生成氢气和氧气的质量各是多少克？（相对原子质量：H 1、O 16）","answer":"设生成氢气的质量为 x，氧气的质量为 y。由 2H₂O —通电→ 2H₂↑ + O₂↑ 可知 m(H₂O)∶m(H₂)∶m(O₂) = 36∶4∶32 = 9∶1∶8。由 36∶4 = 90 g∶x 得 x = 10 g；由 36∶32 = 90 g∶y 得 y = 80 g。验算：10 g + 80 g = 90 g，符合质量守恒定律。答：生成氢气 10 g，生成氧气 80 g。","explain":"这道题的两个常见错误：一是把氢气的相对分子质量当成 2（忘记系数 2），得到氢气 5 g；二是把体积比 2∶1 当成质量比来用。检查的方法就是用质量守恒定律验算：反应物 90 g，生成物 10 g + 80 g = 90 g，对上了才说明算对了。","difficulty":2,"tags":["水的组成","化学方程式计算","质量守恒"],"rubric":["化学方程式书写正确并配平，条件写「通电」，气体符号不遗漏","相对质量 36、4、32 算对（H₂ 要按 2×2 = 4 算，不能按 2 算）","两个比例式分别列对，求出氢气 10 g、氧气 80 g","结果带单位、有答句，并用质量守恒定律验算或说明依据"],"steps":["设未知量：设生成氢气的质量为 x，生成氧气的质量为 y。","写出并配平化学方程式：2H₂O —通电→ 2H₂↑ + O₂↑。","算出相对质量总和：2×18 = 36，2×2 = 4，16×2 = 32。","列比例式：36∶4 = 90 g∶x 得 x = 10 g；36∶32 = 90 g∶y 得 y = 80 g。","用质量守恒定律验算并写出带单位的答句。"]},{"id":"chem-substance-4-q9","type":"short","stem":"某同学把浑浊的河水过滤后，发现滤液仍然浑浊。请写出两种可能的原因，并说明正确的过滤操作应该注意哪些要点。","answer":"可能原因：① 滤纸破损（或滤纸与漏斗内壁之间有气泡、滤纸没有紧贴内壁），液体从缝隙流下；② 过滤时液面高于滤纸边缘，液体从滤纸与漏斗之间流下；③ 承接滤液的烧杯不干净。正确的操作要点是「一贴、二低、三靠」：一贴——滤纸紧贴漏斗内壁，中间不留气泡；二低——滤纸边缘低于漏斗边缘、液面低于滤纸边缘；三靠——玻璃棒下端斜靠三层滤纸处、倾倒液体的烧杯口紧靠玻璃棒、漏斗下端管口紧靠烧杯内壁。","explain":"滤液浑浊的本质只有一句话：液体没有经过滤纸就直接流进了烧杯。因此凡是「让液体绕过滤纸」的操作都会导致浑浊——滤纸破了、液面高于滤纸边缘、滤纸与漏斗间有气泡。答题时把「一贴二低三靠」写全，再补一句「过滤不能除去可溶性杂质」就更完整。","difficulty":2,"tags":["水的净化","实验探究","过滤操作"],"rubric":["写出两条合理原因（滤纸破损、液面高于滤纸边缘、烧杯不干净等）","每条原因说明为什么会使滤液浑浊（液体未经滤纸直接流下）","答出「一贴、二低、三靠」的具体内容","指出过滤只能除去不溶性杂质，过滤后的水仍是混合物（加分点）"]},{"id":"chem-substance-4-q10","type":"short","stem":"请用粒子模型（画圆圈并标出元素符号）画出电解水的微观过程：两个水分子在通电条件下分解，原子重新组合成两个氢分子和一个氧分子。画完以后，用一句话说明这个模型说明了什么。","answer":"画法：左边画 2 个水分子（每个水分子由 1 个氧原子和 2 个氢原子构成，氢原子连在氧原子上）；中间用箭头标出「通电」，并画出分解得到的 4 个氢原子和 2 个氧原子；右边画出重新组合后的 2 个氢分子（每个由 2 个氢原子构成）和 1 个氧分子（由 2 个氧原子构成）。说明：化学变化中分子可以再分、原子不能再分，反应前后原子的种类和个数都不变，所以水由氢、氧两种元素组成。","explain":"粒子模型的判分点全在「个数」和「结构」上：2 个水分子一共含 4 个氢原子、2 个氧原子，所以分解后必须画出 4 个氢原子、2 个氧原子，重新组合后是 2 个氢分子（用掉 4 个氢原子）和 1 个氧分子（用掉 2 个氧原子），一个都不能多也不能少。氢分子由 2 个氢原子构成、氧分子由 2 个氧原子构成，画成单个原子就错了。文字说明要落在「原子种类和个数不变」上。","difficulty":3,"tags":["水的组成","作图题","粒子模型"],"rubric":["左边画出 2 个水分子，每个水分子由 1 个氧原子与 2 个氢原子构成，并标注化学式 H₂O","中间画出分解得到的 4 个氢原子与 2 个氧原子（个数必须与方程式 2H₂O —通电→ 2H₂↑ + O₂↑ 一致）","右边画出 2 个氢分子与 1 个氧分子，并标注 H₂ 与 O₂","用箭头标出「通电」与「重新组合」两个过程，文字说明「分子可分、原子不可分」"],"figure":{"id":"fig-chem-substance-4-q10","title":"待画的电解水微观过程","caption":"左边是 2 个水分子，请补全中间的原子和右边的分子","view":"tall","alt":"左侧画有两个水分子，中间有通电的箭头，右侧与中部留空，等待画出分解得到的氢原子、氧原子以及重新组合成的氢分子和氧分子","prims":[{"t":"molecule","x":16,"y":30,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-5,"dy":-4,"r":2.6,"symbol":"H"},{"dx":5,"dy":-4,"r":2.6,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":16,"y":66,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-5,"dy":-4,"r":2.6,"symbol":"H"},{"dx":5,"dy":-4,"r":2.6,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"arrow","x1":30,"y1":48,"x2":44,"y2":48,"label":"通电","labelDy":-4},{"t":"text","x":56,"y":48,"text":"（画出分解得到的原子）","size":3.4,"tone":"muted"},{"t":"text","x":56,"y":58,"text":"（再画出重新组合后的分子）","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":108,"text":"提示：原子的个数要与化学方程式一致","size":3.6,"tone":"accent"}]},"answerFigure":{"id":"fig-chem-substance-4-q10-a","title":"参考答案：电解水的微观过程","caption":"2 个水分子 → 4 个氢原子 + 2 个氧原子 → 2 个氢分子 + 1 个氧分子","view":"tall","alt":"两个水分子分成四个氢原子和两个氧原子，再重新组合成两个氢分子和一个氧分子，原子的种类与个数在反应前后不变","prims":[{"t":"molecule","x":14,"y":24,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-5,"dy":-4,"r":2.6,"symbol":"H"},{"dx":5,"dy":-4,"r":2.6,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":14,"y":58,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-5,"dy":-4,"r":2.6,"symbol":"H"},{"dx":5,"dy":-4,"r":2.6,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"arrow","x1":26,"y1":42,"x2":40,"y2":42,"label":"通电","labelDy":-4},{"t":"atom","x":50,"y":12,"r":4,"symbol":"O","color":"red"},{"t":"atom","x":50,"y":26,"r":4,"symbol":"O","color":"red"},{"t":"atom","x":50,"y":44,"r":4,"symbol":"H"},{"t":"atom","x":50,"y":58,"r":4,"symbol":"H"},{"t":"atom","x":50,"y":74,"r":4,"symbol":"H"},{"t":"atom","x":50,"y":88,"r":4,"symbol":"H"},{"t":"text","x":50,"y":104,"text":"4 个 H + 2 个 O","size":3.4,"tone":"muted"},{"t":"arrow","x1":62,"y1":50,"x2":74,"y2":50,"label":"重新组合","labelDy":-4},{"t":"molecule","x":84,"y":20,"atoms":[{"dx":-3,"dy":0,"symbol":"H"},{"dx":3,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":84,"y":52,"atoms":[{"dx":-3,"dy":0,"symbol":"H"},{"dx":3,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":84,"y":88,"atoms":[{"dx":-3.4,"dy":0,"symbol":"O","color":"red"},{"dx":3.4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"text","x":50,"y":122,"text":"分子可分、原子不可分；原子种类与个数不变","size":3.6,"tone":"accent"}]}},{"id":"chem-substance-4-m1-q1","type":"short","stem":"（3 分）根据材料一，写出负极和正极上分别得到什么气体，并写出电解水的化学方程式。由此可以得出关于水的组成的什么结论？","answer":"负极得到氢气（20 mL），正极得到氧气（10 mL），体积比约为 2∶1。化学方程式：2H₂O —通电→ 2H₂↑ + O₂↑。结论：水在通电条件下分解生成氢气和氧气，根据反应前后元素种类不变，说明水是由氢元素和氧元素组成的。","explain":"","rubric":["答出负极是氢气、正极是氧气，并指出体积比约为 2∶1","化学方程式书写正确，条件写「通电」，气体符号不遗漏","结论写成「水是由氢元素和氧元素组成的」（写成「由氢气和氧气组成」不得分）"]},{"id":"chem-substance-4-m1-q2","type":"short","stem":"（4 分）在电解水实验中，若有 18 g 水完全分解，计算生成氢气和氧气的质量各是多少克？生成氢气和氧气的质量比与体积比是否相同？（相对原子质量：H 1、O 16）","answer":"由 2H₂O —通电→ 2H₂↑ + O₂↑ 可知，水、氢气、氧气的质量比为 36∶4∶32 = 9∶1∶8。18 g 水中含氢、氧元素的质量分别为 18 g × 1/9 = 2 g 和 18 g × 8/9 = 16 g，即生成氢气 2 g、氧气 16 g。质量比是 2∶16 = 1∶8，而体积比约为 2∶1，两者不相同。","explain":"","rubric":["写出化学方程式并算出相对质量 36、4、32（或质量比 9∶1∶8）","求出氢气质量为 2 g","求出氧气质量为 16 g，并带单位写出答句","明确指出质量比 1∶8 与体积比 2∶1 不相同（能说明原因更好）"]},{"id":"chem-substance-4-m1-q3","type":"short","stem":"（3 分）根据材料二与材料三，说明自来水厂的哪些净水步骤属于物理变化？怎样用简单的方法证明该地区的自来水是硬水？生活中可以怎样把它软化？","answer":"沉降（沉淀）、过滤、活性炭吸附属于物理变化（没有生成新物质）；投药消毒属于化学变化。证明是硬水的方法：取等量的自来水与等量的软水（或蒸馏水），分别滴加等量的肥皂水并振荡，泡沫少、浮渣多的是硬水。生活中软化硬水的方法：煮沸（可溶性钙镁化合物受热分解生成水垢沉淀下来）。","explain":"","rubric":["答出沉降、过滤、吸附属于物理变化并说明理由（没有新物质生成）","写清鉴别方法：等量水样加等量肥皂水，比较泡沫与浮渣的多少","答出生活中用煮沸的方法软化硬水"]}]},{"id":"chem-substance-5","title":"碳单质与碳的氧化物：金刚石石墨C60·碳的化学性质·一氧化碳与二氧化碳","subtitle":"人教版九年级 · 第六单元 碳和碳的氧化物 · 9a","grade":"9a","tags":["人教版九年级 · 第六单元 碳和碳的氧化物"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第六单元 碳和碳的氧化物 · 9a"},{"type":"note","title":"问题切入","text":"金刚石和石墨都由碳元素组成，为什么一个硬得能划开玻璃、一个软得能做铅笔芯？木炭、活性炭为什么能吸附颜色和异味？一氧化碳和二氧化碳都由碳、氧两种元素组成，为什么一个有毒、一个却能灭火？"},{"type":"note","title":"一句话抓住关键","text":"组成元素相同、碳原子的排列方式不同，物理性质就差别极大——金刚石、石墨、C60 都是碳元素组成的不同单质。木炭和活性炭结构疏松多孔，具有吸附性，属于物理变化。碳在常温下化学性质稳定，高温下能燃烧、能夺取金属氧化物中的氧（还原性）。CO 与 CO₂ 的组成元素相同，但分子构成不同（1 个 CO₂ 分子比 1 个 CO 分子多 1 个氧原子），所以 CO 有毒、能燃烧、有还原性，而 CO₂ 不能燃烧也不支持燃烧、能溶于水并与水反应。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"金刚石和石墨都是碳元素组成的，可一个硬得能划开玻璃，一个软得能做铅笔芯。就像同一个人穿运动服和穿西装，外表差别巨大，本质却是同一个「人」——决定性质的是碳原子的排列方式。","walk":["碳单质有金刚石、石墨、C₆₀ 等。金刚石是空间网状结构，很硬；石墨是层状结构，层间容易滑动，所以软、能导电；活性炭疏松多孔，有吸附性。","碳的化学性质：常温下稳定，高温下能燃烧，也能夺取某些氧化物中的氧（还原性）。木炭还原氧化铜会生成铜和二氧化碳。","一氧化碳和二氧化碳都由碳、氧元素组成，但分子构成不同：CO 有毒、能燃烧、有还原性；CO₂ 不燃烧也不支持燃烧、能与水反应、能使澄清石灰水变浑浊。"],"try":"用铅笔芯在纸上画线，感受石墨的软和滑；把铅笔芯接入简单电路（电池、小灯泡），观察灯泡是否发光，验证石墨导电。","use":["鉴别 CO 和 CO₂：通入澄清石灰水，变浑浊的是 CO₂；点燃，能燃烧的是 CO。","除 CO₂ 中混有的 CO，用灼热氧化铜；除 CO 中混有的 CO₂，用氢氧化钠溶液。"]},{"type":"h","text":"【宏观】宏观：都是碳，样子与本事却完全不同"},{"type":"p","text":"金刚石是无色透明、正八面体形状的固体，天然存在的最硬的物质，可以划开玻璃、做钻石和切割刀具；石墨是深灰色、有金属光泽的细鳞片状固体，质软、有滑腻感、能导电，用来做铅笔芯、电极和润滑剂；C60 由 60 个碳原子构成一个像足球一样的分子，是近年研究的新材料。木炭、活性炭、焦炭、炭黑也主要由碳元素组成，其中木炭与活性炭结构疏松多孔，表面积很大，能吸附色素和异味——防毒面具的滤毒罐、冰箱除味剂都用它。"},{"type":"figure","figure":{"id":"fig-chem-substance-5-1","title":"三种碳单质的结构示意","caption":"碳原子的排列方式不同：网状、层状、足球状","view":"wide","alt":"左边是金刚石的空间网状结构示意，中间是石墨的层状结构示意，右边是 C60 的球形分子示意，三者都由碳原子构成但排列方式不同","prims":[{"t":"atom","x":14,"y":20,"r":3,"symbol":"C"},{"t":"atom","x":22,"y":14,"r":3,"symbol":"C"},{"t":"atom","x":22,"y":28,"r":3,"symbol":"C"},{"t":"atom","x":30,"y":21,"r":3,"symbol":"C"},{"t":"line","x1":14,"y1":20,"x2":22,"y2":14,"width":0.5,"tone":"muted"},{"t":"line","x1":14,"y1":20,"x2":22,"y2":28,"width":0.5,"tone":"muted"},{"t":"line","x1":22,"y1":14,"x2":30,"y2":21,"width":0.5,"tone":"muted"},{"t":"line","x1":22,"y1":28,"x2":30,"y2":21,"width":0.5,"tone":"muted"},{"t":"text","x":22,"y":40,"text":"金刚石","size":3.6,"tone":"accent"},{"t":"text","x":22,"y":47,"text":"空间网状 → 很硬","size":3,"tone":"muted"},{"t":"atom","x":46,"y":15,"r":2.6,"symbol":"C"},{"t":"atom","x":52,"y":15,"r":2.6,"symbol":"C"},{"t":"atom","x":58,"y":15,"r":2.6,"symbol":"C"},{"t":"atom","x":46,"y":21,"r":2.6,"symbol":"C"},{"t":"atom","x":52,"y":21,"r":2.6,"symbol":"C"},{"t":"atom","x":58,"y":21,"r":2.6,"symbol":"C"},{"t":"line","x1":46,"y1":15,"x2":58,"y2":15,"width":0.5,"tone":"muted"},{"t":"line","x1":46,"y1":21,"x2":58,"y2":21,"width":0.5,"tone":"muted"},{"t":"text","x":52,"y":40,"text":"石墨","size":3.6,"tone":"accent"},{"t":"text","x":52,"y":47,"text":"层状 → 层间易滑动、质软","size":3,"tone":"muted"},{"t":"circle","cx":82,"cy":20,"r":8,"tone":"muted"},{"t":"atom","x":82,"y":12,"r":2.2,"symbol":"C"},{"t":"atom","x":82,"y":28,"r":2.2,"symbol":"C"},{"t":"atom","x":74,"y":20,"r":2.2,"symbol":"C"},{"t":"atom","x":90,"y":20,"r":2.2,"symbol":"C"},{"t":"text","x":82,"y":40,"text":"C60","size":3.6,"tone":"accent"},{"t":"text","x":82,"y":47,"text":"足球状分子","size":3,"tone":"muted"},{"t":"text","x":50,"y":58,"text":"三者都由碳原子构成，只是碳原子的排列方式不同","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"答题时的固定句式：「金刚石与石墨都由碳元素组成，但碳原子的排列方式不同，所以物理性质差异很大」。只写「结构不同」不够完整，要说清「碳原子的排列方式不同」。"},{"type":"h","text":"【宏观】宏观：碳的化学性质——常温稳定，高温活泼"},{"type":"p","text":"古代的字画能保存上千年不变色，说明常温下碳的化学性质很不活泼。但条件一变，碳就活跃起来：氧气充足时碳充分燃烧生成二氧化碳，发出白光、放出大量热；氧气不足时碳不完全燃烧生成一氧化碳，这也是煤炉、汽车尾气中一氧化碳的来源。碳还有还原性：高温下碳能夺取氧化铜中的氧，把黑色的氧化铜还原成红色的铜，同时自己变成二氧化碳——这类「一种物质夺取另一种物质中的氧」的反应叫还原反应，夺氧的物质（碳）叫还原剂。"},{"type":"note","title":"","text":"碳与氧化铜反应的条件是「高温」，不能写「加热」；这与一氧化碳还原氧化铜只需「加热」不同，是中考最容易写错的条件之一。写现象时注意两个变化：黑色粉末逐渐变成红色（生成铜），澄清石灰水变浑浊（生成二氧化碳）。"},{"type":"h","text":"【微观】微观：CO 与 CO₂ 为什么脾气完全不同"},{"type":"p","text":"比较两种分子的构成：1 个一氧化碳分子由 1 个碳原子和 1 个氧原子构成，1 个二氧化碳分子由 1 个碳原子和 2 个氧原子构成，两者只差 1 个氧原子。就是这 1 个氧原子的差别，让它们的性质几乎处处相反：CO 难溶于水、能燃烧、有还原性、有剧毒（与血液中的血红蛋白结合，使血液失去输氧能力）；CO₂ 能溶于水、不能燃烧也不支持燃烧、无毒（但含量过高会使人窒息）。这正说明「结构决定性质」——物质的分子构成不同，性质就不同。"},{"type":"figure","figure":{"id":"fig-chem-substance-5-2","title":"一氧化碳与二氧化碳的分子构成","caption":"两种分子只差一个氧原子，性质却几乎处处相反","view":"wide","alt":"一氧化碳分子由一个碳原子和一个氧原子构成，二氧化碳分子由一个碳原子和两个氧原子构成，下方分别列出它们的性质差异","prims":[{"t":"molecule","x":24,"y":20,"atoms":[{"dx":-4.4,"dy":0,"r":3.8,"symbol":"C","color":"black"},{"dx":4.4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"CO"},{"t":"molecule","x":74,"y":20,"atoms":[{"dx":-4.4,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":0,"r":3.8,"symbol":"C","color":"black"},{"dx":4.4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"text","x":24,"y":40,"text":"难溶于水","size":3.4,"tone":"muted"},{"t":"text","x":24,"y":47,"text":"能燃烧、有还原性","size":3.4,"tone":"muted"},{"t":"text","x":24,"y":54,"text":"有剧毒","size":3.4,"tone":"danger"},{"t":"text","x":74,"y":40,"text":"能溶于水","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":47,"text":"不能燃烧、不支持燃烧","size":3.4,"tone":"muted"},{"t":"text","x":74,"y":54,"text":"无毒，可灭火、可作气体肥料","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":10,"text":"组成元素相同，分子构成不同","size":3.6,"tone":"accent"}]}},{"type":"note","title":"","text":"「组成元素相同 → 性质相同」是错的；「分子构成不同 → 性质不同」才是对的。CO₂ 比 CO 多一个氧原子，正是它不能燃烧的原因（碳已经「烧完」了，处于最高价态）；而 CO 中碳的化合价为 +2，还能继续被氧化成 +4。"},{"type":"h","text":"【符号】符号：碳及其氧化物之间的转化关系"},{"type":"p","text":"把这些反应按「转化」串起来看：碳充分燃烧生成 CO₂，氧气不足生成 CO；CO 燃烧又生成 CO₂；CO₂ 与灼热的碳反应又能生成 CO；CO 能还原氧化铜、氧化铁等金属氧化物，生成 CO₂。写方程式时三处条件必须分清：碳燃烧是「点燃」，CO₂ 与碳反应、碳还原氧化铜都是「高温」，CO 还原氧化铜只需「加热」。配平检验仍是数原子：C + 2CuO —高温→ 2Cu + CO₂↑ 的左边有 1 个碳、2 个铜、2 个氧，右边恰好也是。"},{"type":"figure","figure":{"id":"fig-chem-substance-5-3","title":"碳、一氧化碳、二氧化碳的转化关系","caption":"碳充分燃烧生成 CO₂，氧气不足生成 CO；CO 燃烧又变回 CO₂","view":"square","alt":"图中表示碳、一氧化碳、二氧化碳三者的转化关系：碳与氧气反应生成二氧化碳或一氧化碳，一氧化碳燃烧生成二氧化碳，二氧化碳与碳在高温下反应生成一氧化碳","prims":[{"t":"rect","x":8,"y":34,"w":24,"h":12,"label":"C","tone":"main"},{"t":"rect","x":38,"y":8,"w":26,"h":12,"label":"CO","tone":"accent"},{"t":"rect","x":38,"y":62,"w":26,"h":12,"label":"CO₂","tone":"ok"},{"t":"arrow","x1":32,"y1":34,"x2":38,"y2":18,"tone":"accent","label":"氧气不足","labelDy":-8},{"t":"arrow","x1":32,"y1":44,"x2":38,"y2":64,"tone":"ok","label":"氧气充足","labelDy":12},{"t":"arrow","x1":51,"y1":20,"x2":51,"y2":62,"tone":"danger","label":"点燃","labelDy":0,"labelDx":12},{"t":"arrow","x1":38,"y1":68,"x2":32,"y2":46,"tone":"muted","label":"高温","labelDy":12},{"t":"text","x":74,"y":24,"text":"2CO + O₂ —点燃→ 2CO₂","size":3.2,"anchor":"start"},{"t":"text","x":74,"y":32,"text":"CO₂ + C —高温→ 2CO","size":3.2,"anchor":"start"},{"t":"text","x":74,"y":44,"text":"CO 有剧毒，不能直接排放","size":3.2,"anchor":"start","tone":"danger"},{"t":"text","x":74,"y":52,"text":"尾气可用点燃法处理","size":3.2,"anchor":"start","tone":"muted"},{"t":"text","x":50,"y":92,"text":"碳充分燃烧生成 CO₂，氧气不足生成 CO","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"写「CO₂ + C —高温→ 2CO」时条件写「高温」而不是「点燃」；写「CO + CuO」时条件写「加热」而不是「高温」。这两处条件在中考里都是直接扣分点。"},{"type":"h","text":"【应用】应用：一氧化碳中毒的预防与二氧化碳的用途"},{"type":"p","text":"冬天用煤炉取暖，如果室内通风不良，煤不完全燃烧产生的一氧化碳就会使人中毒：CO 与血红蛋白结合的能力比氧气强得多，使血液失去输氧能力，人就会出现头痛、乏力甚至死亡。预防的办法是保持通风、安装烟囱并把废气排到室外、不在密闭房间内使用炭火。一氧化碳本身也是重要的资源：它是水煤气、煤气的主要成分之一，可作燃料，也可用于冶炼金属。二氧化碳的用途则来自它的性质：不能燃烧也不支持燃烧、密度比空气大，所以用来灭火；能溶于水并与水反应，所以用来制碳酸饮料；固体二氧化碳（干冰）升华吸热，用于人工降雨、食品冷藏和舞台造雾；它还是植物光合作用的原料，可作气体肥料。"},{"type":"note","title":"","text":"一氧化碳中毒的急救要点：立即开窗通风、把人移到通风处、必要时送医院，不能打开明火或电器开关（防止引起爆炸）。答题时「开窗通风」必须写出来。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["相对分子质量（CO 与 CO₂）","CO 的相对分子质量 = 12 + 16 = 28；CO₂ 的相对分子质量 = 12 + 16×2 = 44","用于化学方程式计算和比较气体密度。CO₂ 的相对分子质量 44 大于空气的平均相对分子质量 29，所以 CO₂ 的密度比空气大（可用于灭火、可用向上排空气法收集）；CO 的相对分子质量 28 略小于 29，密度与空气接近，不能用排空气法收集，一般用排水法。"],["元素的质量分数（以 CO₂ 为例）","CO₂ 中碳元素的质量分数 = 12 ÷ 44 × 100% ≈ 27.3%","用于计算纯净物中各元素的质量比例。CO 中碳元素的质量分数 = 12 ÷ 28 × 100% ≈ 42.9%，比 CO₂ 高——所以同样质量的碳不完全燃烧时，碳元素「跑」进 CO 里的比例更大。计算时相对原子质量取整数：C 12、O 16、Cu 64。"],["化学方程式计算中的质量比","C + 2CuO —高温→ 2Cu + CO₂↑，m(C)∶m(CuO)∶m(Cu)∶m(CO₂) = 12∶160∶128∶44","化学方程式计算的依据。只有参加反应的纯物质质量才能代入：题目若给的是含杂质的氧化铜，要先按纯度算出纯 CuO 的质量，再代入比例式计算。条件「高温」不能漏写。"]]},{"type":"h","text":"应用 · 煤炉中的化学与一氧化碳中毒"},{"type":"note","title":"情境","text":"冬天，有人在密闭的房间里用煤炉取暖，结果发生了一氧化碳中毒。煤炉里的煤在燃烧，为什么会产生一氧化碳？怎样预防？"},{"type":"list","title":"解答步骤","items":["写出煤炉中可能发生的三个反应，并指出哪两个会生成一氧化碳。","说明一氧化碳中毒的原理：CO 与血红蛋白结合，使血液无法运输氧气。","给出预防措施：保持室内通风、安装烟囱把废气排到室外、不在密闭房间使用炭火、安装一氧化碳报警器。","补充急救做法：立即开窗通风、把中毒者移到通风处，必要时送医院；不能使用明火或电器开关。"]},{"type":"note","title":"结论","text":"煤不完全燃烧以及 CO₂ 与灼热的碳反应都会生成一氧化碳。答题时「保持通风」和「CO 与血红蛋白结合」是两个必写的得分点。"},{"type":"h","text":"应用 · 用木炭还原氧化铜制铜"},{"type":"note","title":"情境","text":"要把 8 g 氧化铜完全还原成铜，至少需要木炭粉多少克？能得到铜多少克？（相对原子质量：C 12、O 16、Cu 64）"},{"type":"list","title":"解答步骤","items":["写出并配平化学方程式：C + 2CuO —高温→ 2Cu + CO₂↑。","算出相对质量：C = 12，2CuO = 2×(64 + 16) = 160，2Cu = 2×64 = 128。","设需要碳的质量为 x：12∶160 = x∶8 g，解得 x = 0.6 g。","设生成铜的质量为 y：160∶128 = 8 g∶y，解得 y = 6.4 g。","验算：还可以算出生成的二氧化碳为 44/160 × 8 g = 2.2 g，0.6 g + 8 g = 6.4 g + 2.2 g，符合质量守恒定律。"]},{"type":"note","title":"结论","text":"至少需要木炭粉 0.6 g，能得到铜 6.4 g。注意条件写「高温」；若把 CuO 的相对分子质量算成 64 + 32 = 96（把氧当成 32），结果就全错了。"},{"type":"h","text":"实验 1 · 木炭还原氧化铜"},{"type":"note","title":"实验目的","text":"验证碳在高温下具有还原性，能把氧化铜还原成铜，并检验生成的二氧化碳。"},{"type":"list","title":"实验器材","items":["大试管、单孔橡皮塞、导管","木炭粉、氧化铜粉末（充分混合并烘干）","酒精灯（加网罩）、铁架台","试管（盛澄清石灰水）"]},{"type":"figure","figure":{"id":"fig-chem-substance-5-exp1","title":"木炭还原氧化铜","caption":"试管口略向下倾斜，酒精灯加网罩集中火焰提高温度，导管伸入澄清石灰水中","view":"wide","alt":"铁架台夹住试管，试管口略向下倾斜，管内装有木炭粉与氧化铜的混合物，酒精灯加网罩加热，导管把生成的气体通入澄清石灰水中","prims":[{"t":"stand","x":16,"y":48,"h":38,"w":20,"clamps":[0.72]},{"t":"testTube","x":34,"y":22,"h":30,"w":10,"tilt":100},{"t":"hatch","x":22,"y":17,"w":10,"h":8,"gap":1.8},{"t":"text","x":26,"y":10,"text":"木炭粉 + 氧化铜（混合均匀）","size":3},{"t":"alcoholLamp","x":26,"y":40,"lit":true},{"t":"poly","points":[[20,24],[22,20],[30,20],[32,24]],"closed":false,"tone":"muted"},{"t":"text","x":26,"y":58,"text":"酒精灯加网罩：集中火焰、提高温度","size":3,"tone":"accent"},{"t":"line","x1":48,"y1":29,"x2":49.6,"y2":20.2,"width":1.2},{"t":"curve","points":[[50,25],[58,21],[66,22],[68,30],[68,38]]},{"t":"testTube","x":68,"y":46,"h":26,"w":12,"liquid":0.45,"color":"colorless"},{"t":"text","x":88,"y":40,"text":"澄清石灰水","anchor":"end","size":3.2},{"t":"text","x":68,"y":62,"text":"变浑浊 → 生成 CO₂","size":3.2,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["把木炭粉与氧化铜粉末按适当比例混合均匀并烘干，装入试管底部，塞紧带导管的单孔橡皮塞。","把试管固定在铁架台上，使试管口略向下倾斜，导管另一端伸入盛有澄清石灰水的试管中。","在酒精灯上套一个网罩（或用酒精喷灯），先给试管预热，再对准药品部位用外焰加热。","观察试管内固体的颜色变化和澄清石灰水的变化，待反应结束后先把导管从石灰水中取出，再熄灭酒精灯。","等试管冷却后把固体倒在纸上，观察它的颜色。"]},{"type":"note","title":"实验现象","text":"加热一段时间后，试管内黑色粉末逐渐变成红色（有铜生成），澄清石灰水变浑浊（有二氧化碳生成）。"},{"type":"note","title":"实验结论","text":"碳在高温下夺取氧化铜中的氧，把氧化铜还原成铜，同时生成二氧化碳，化学方程式为 C + 2CuO —高温→ 2Cu + CO₂↑；澄清石灰水变浑浊可证明生成的气体是二氧化碳（CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O）。"},{"type":"list","title":"注意事项","items":["试管口要略向下倾斜：防止反应中产生的冷凝水倒流到试管底部，使试管炸裂。","木炭粉与氧化铜要混合均匀并烘干：混合均匀接触面积大、反应更充分；不烘干则水分受热蒸发，容易造成试管炸裂。","酒精灯要加网罩（或使用酒精喷灯）：使火焰集中、提高加热温度，因为该反应需要在高温下进行。","实验结束要先撤导管、后熄灭酒精灯：先熄灯会使石灰水倒吸进热的试管，导致试管炸裂。","木炭粉要稍过量：防止生成的二氧化碳与过量的碳继续反应生成一氧化碳，同时保证氧化铜被完全还原。","加热时要先预热再固定加热、用外焰加热；试管冷却后才能倒出固体观察，防止烫伤和铜被重新氧化。"]},{"type":"h","text":"实验 2 · 木炭的吸附性"},{"type":"note","title":"实验目的","text":"认识木炭（活性炭）的吸附性，理解吸附作用属于物理变化。"},{"type":"list","title":"实验器材","items":["锥形瓶（内盛半瓶水）","红墨水（或品红溶液）","木炭（研碎）、滤纸、漏斗"]},{"type":"figure","figure":{"id":"fig-chem-substance-5-exp2","title":"木炭吸附红墨水","caption":"振荡后红墨水的颜色明显变浅，说明木炭有吸附性","view":"wide","alt":"锥形瓶中盛有红色的水并加入研碎的木炭，振荡后溶液颜色明显变浅，说明木炭能吸附色素","prims":[{"t":"flask","x":32,"y":34,"kind":"conical","h":26,"w":26,"liquid":0.65,"color":"red"},{"t":"text","x":32,"y":56,"text":"加入木炭前：红色","size":3.2,"tone":"danger"},{"t":"arrow","x1":48,"y1":32,"x2":60,"y2":32,"label":"振荡","labelDy":-4},{"t":"flask","x":76,"y":34,"kind":"conical","h":26,"w":26,"liquid":0.65,"color":"colorless"},{"t":"text","x":76,"y":56,"text":"加入木炭振荡后：颜色变浅","size":3.2,"tone":"accent"},{"t":"text","x":54,"y":10,"text":"木炭疏松多孔、表面积大","size":3.4,"tone":"muted"},{"t":"text","x":54,"y":17,"text":"吸附色素与异味（物理变化）","size":3.4,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["在锥形瓶中加入大半瓶水，滴入 1—2 滴红墨水，观察溶液的颜色。","把木炭研碎后加入锥形瓶中，塞紧瓶塞，充分振荡。","静置后观察溶液颜色的变化，并与加入木炭前比较。","若要看得更清楚，可以用过滤的方法把木炭分离出来，观察滤液的颜色。"]},{"type":"note","title":"实验现象","text":"加入木炭并振荡后，红色明显变浅（若用活性炭效果更明显），静置或过滤后得到的液体接近无色。"},{"type":"note","title":"实验结论","text":"木炭（活性炭）具有吸附性，能吸附水中的色素，使溶液颜色变浅。这个过程中没有生成新物质，属于物理变化。"},{"type":"list","title":"注意事项","items":["木炭要研碎：颗粒越小表面积越大，吸附效果越明显，现象更容易观察。","要充分振荡：让木炭与水中的色素充分接触，否则现象不明显。","振荡时要塞紧瓶塞并用手按住，防止液体溅出；不能把锥形瓶放在桌面上剧烈摩擦。","吸附是物理变化，不能写成「木炭与色素发生了化学反应」；吸附能力有限，用过的木炭不能重复使用。","实验后要用过滤的方法把木炭与液体分开再观察，避免木炭颗粒影响对颜色的判断。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["C + O₂ —点燃→ CO₂","点燃","木炭在氧气中剧烈燃烧，发出白光，放出热量，生成能使澄清石灰水变浑浊的气体","配平：1 个碳原子与 1 个氧分子恰好生成 1 个二氧化碳分子，系数均为 1。这是氧气充足时的完全燃烧；注意「发出白光」是固体灼烧发光，不是火焰。"],["2C + O₂ —点燃→ 2CO","点燃","氧气不足时碳不完全燃烧，生成无色无味但有毒的一氧化碳，放出热量较少","配平：左边 2 个碳原子、2 个氧原子，右边 2CO 也是 2 个碳、2 个氧。这条方程式解释了两件事：煤炉、汽车尾气里的一氧化碳从哪里来；为什么燃料燃烧时要有充足的空气（既为了放热多，也为了防止产生有毒气体）。"],["C + 2CuO —高温→ 2Cu + CO₂↑","高温","黑色粉末逐渐变成红色（有铜生成），生成的气体使澄清石灰水变浑浊","配平：左边 1 个碳、2 个铜、2 个氧原子，右边 2Cu 有 2 个铜、CO₂ 有 1 个碳和 2 个氧，两边相等。条件是「高温」，写成「加热」或「点燃」都错。碳在这里夺取氧化铜中的氧，作还原剂，发生的是还原反应。"],["CO₂ + C —高温→ 2CO","高温","把二氧化碳通过灼热的炭层，二氧化碳被还原成一氧化碳（无明显颜色变化，但气体变成有毒的 CO）","配平：左边 1 个碳（来自 CO₂）+ 1 个碳（单质碳）= 2 个碳、2 个氧，右边 2CO 有 2 个碳、2 个氧。这是吸热反应，也是煤炉里「越烧越有毒」的原因；条件写「高温」，不能写「点燃」。"],["2CO + O₂ —点燃→ 2CO₂","点燃","一氧化碳在空气中燃烧，产生蓝色火焰，放出大量热，生成能使澄清石灰水变浑浊的气体","配平：左边 2 个碳、4 个氧（2 个来自 CO、2 个来自 O₂），右边 2CO₂ 也是 2 个碳、4 个氧。一氧化碳是煤气的主要成分，燃烧时火焰是蓝色；点燃前必须验纯，否则可能爆炸。"],["CO + CuO —加热→ Cu + CO₂","加热","黑色的氧化铜逐渐变成红色的铜，生成的气体使澄清石灰水变浑浊","配平：左边 1 个碳、1 个铜、2 个氧，右边 1 个铜、1 个碳、2 个氧，系数均为 1。条件只需「加热」，与碳还原氧化铜需要「高温」不同；CO 夺取氧化铜中的氧，是还原剂，这也是工业炼铁的原理基础。"],["CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O","常温（不写条件）","澄清石灰水变浑浊","这是检验二氧化碳的常用方法，也是木炭还原氧化铜实验里证明「生成的气体是二氧化碳」的依据。配平：左边 1 个碳、1 个钙、2 个氧（CO₂）+ 2 个氧、2 个氢（Ca(OH)₂），右边 CaCO₃ 有 1 个钙、1 个碳、3 个氧，H₂O 有 2 个氢、1 个氧，氧原子合计 4 个，两边相等。CaCO₃ 是沉淀，必须写 ↓。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["金刚石和石墨的物理性质差别很大，是因为它们由不同的元素组成。","金刚石、石墨、C60 都由碳元素组成，是碳的不同单质；物理性质差异大是因为碳原子的排列方式不同。","把「结构不同」错认成「元素不同」。金刚石是空间网状结构、很硬；石墨是层状结构、层间容易滑动、质软且能导电。同种元素可以形成不同的单质，这是「结构决定性质」的典型例子。"],["一氧化碳和二氧化碳都有毒，都会造成空气污染。","一氧化碳有剧毒，是空气污染物之一；二氧化碳无毒，但含量过高会使人窒息，它不属于空气污染物。","两种气体的毒性完全不同：CO 与血红蛋白结合使人缺氧中毒；CO₂ 本身无毒，只是浓度过高时使氧气比例下降导致窒息，它带来的主要问题是温室效应。"],["干冰是固态的水，可用于人工降雨。","干冰是固态的二氧化碳，升华时吸收大量热，使周围温度降低、水蒸气凝结成小水滴，可用于人工降雨、食品冷藏和舞台造雾。","名称里有「冰」，但成分完全不同。判断这类题只看化学式：干冰是 CO₂ 的固态，冰是 H₂O 的固态；干冰升华时没有液态出现，是物理变化。"],["木炭还原氧化铜的条件是加热。","木炭还原氧化铜的条件是高温（所以要用酒精灯加网罩或酒精喷灯），而一氧化碳还原氧化铜只需加热。","两个反应物不同，反应条件也不同：碳是固体，与氧化铜的反应需要很高的温度；CO 是气体，与氧化铜接触充分，加热即可反应。条件写错在中考里直接不给分。"]]},{"type":"table","title":"一氧化碳与二氧化碳（分子构成、物理性质、化学性质与用途）","head":["比较项","一氧化碳 CO","二氧化碳 CO₂"],"rows":[["分子构成","1 个碳原子 + 1 个氧原子","1 个碳原子 + 2 个氧原子"],["溶解性","难溶于水","能溶于水（并能与水反应生成碳酸）"],["化学性质","能燃烧、有还原性、有剧毒","不能燃烧、不支持燃烧、无毒"],["主要用途","作燃料（煤气的主要成分）、冶炼金属","灭火、制碳酸饮料、干冰用于冷藏与人工降雨、作气体肥料"],["鉴别方法","点燃时能燃烧并产生蓝色火焰","通入澄清石灰水，石灰水变浑浊"]]},{"type":"table","title":"金刚石与石墨（碳原子排列方式与相应的性质、用途）","head":["比较项","金刚石","石墨"],"rows":[["结构","碳原子构成空间网状结构","碳原子构成层状结构，层与层之间容易滑动"],["物理性质","无色透明、正八面体形状、天然存在的最硬的物质","深灰色、有金属光泽的细鳞片状固体，质软、有滑腻感、能导电"],["主要用途","切割玻璃、钻探机的钻头、装饰品（钻石）","铅笔芯、电极、润滑剂、高温坩埚"],["共同点","都由碳元素组成的单质，化学性质相似（都可燃烧生成 CO₂ 等）","都由碳元素组成的单质，化学性质相似（都可燃烧生成 CO₂ 等）"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["碳单质的结构与用途","以金刚石、石墨、C60、活性炭的性质与用途为背景，考「同种元素组成的不同单质」「结构决定性质」「吸附性属于物理变化」，常把用途与相应性质配对判断。"],["一氧化碳与二氧化碳的性质差异、鉴别与转化","高频考点：由分子构成不同解释性质差异、用澄清石灰水或点燃的方法鉴别两种气体、一氧化碳中毒的原理与预防，以及「C → CO → CO₂」之间的转化与相应反应条件。"],["木炭还原氧化铜的实验与方程式书写","以装置图为情境考操作细节（试管口略向下倾斜、加网罩、先撤导管后熄灯、药品混合均匀）、现象描述（黑色变红、石灰水变浑浊）与方程式 C + 2CuO —高温→ 2Cu + CO₂↑ 的书写与配平。"],["碳的还原性的计算","用碳还原氧化铜（或氧化铁）的反应考化学方程式计算，数据常给氧化铜的质量，求所需碳或生成的铜、二氧化碳的质量；含杂质时要用纯度先折算成纯物质的质量。"]]},{"type":"quote","text":"【材料一】碳的单质有多种：金刚石是无色透明、天然存在的最硬的物质，可作切割工具；石墨是深灰色细鳞片状固体、质软且能导电，可作电极和铅笔芯；木炭与活性炭疏松多孔，可用于吸附色素和异味。【材料二】冬季用煤炉取暖时，若室内通风不良，容易发生一氧化碳中毒。煤炉中可能发生：C + O₂ —点燃→ CO₂、2C + O₂ —点燃→ 2CO、CO₂ + C —高温→ 2CO。【材料三】某同学用 8 g 氧化铜与足量木炭粉混合均匀后高温加热，使氧化铜完全反应。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）根据材料一回答：金刚石与石墨都由碳元素组成，为什么它们的物理性质差别很大？木炭与活性炭的吸附性属于物理变化还是化学变化？请说明理由。","【设问】（4 分）根据材料二，煤炉中为什么会有一氧化碳产生（写出两条途径并配上化学方程式）？一氧化碳使人中毒的原因是什么？怎样预防？","【设问】（4 分）根据材料三计算：把 8 g 氧化铜完全还原成铜，至少需要木炭粉多少克？能得到铜多少克？（相对原子质量：C 12、O 16、Cu 64）"]}],"questions":[{"id":"chem-substance-5-q1","type":"choice","stem":"如图是木炭还原氧化铜的实验装置。下列说法正确的是（　）","answer":"A","explain":"A 正确：加热固体时试管口必须略向下倾斜，防止冷凝水倒流到试管底部使试管炸裂。B 与操作要求相反：木炭粉与氧化铜要混合均匀并烘干，这样才能充分接触、反应完全；分开放置反应很难进行。C 把两种现象弄混了：澄清石灰水变浑浊说明生成了二氧化碳，铜的生成要通过试管内「黑色粉末变成红色」来判断。D 把顺序颠倒了：必须先撤导管、后熄灭酒精灯，否则石灰水会倒吸进热的试管，使试管炸裂。","options":["试管口略向下倾斜，是为了防止冷凝水倒流使试管炸裂","木炭粉与氧化铜粉末要分开放置在试管的两端，便于观察现象","澄清石灰水变浑浊，说明有铜生成","实验结束时应先熄灭酒精灯，再把导管从石灰水中取出"],"difficulty":2,"tags":["碳的化学性质","木炭还原氧化铜","实验操作"],"figure":{"id":"fig-chem-substance-5-q1","title":"木炭还原氧化铜的装置","caption":"判断哪一个说法正确","view":"wide","alt":"铁架台夹住试管、试管口略向下倾斜，管内是木炭粉与氧化铜的混合物，酒精灯加网罩加热，导管把气体通入澄清石灰水","prims":[{"t":"stand","x":16,"y":48,"h":38,"w":20,"clamps":[0.72]},{"t":"testTube","x":34,"y":22,"h":30,"w":10,"tilt":100},{"t":"hatch","x":22,"y":17,"w":10,"h":8,"gap":1.8},{"t":"text","x":24,"y":10,"text":"C 与 CuO 的混合物","size":3},{"t":"alcoholLamp","x":26,"y":40,"lit":true},{"t":"curve","points":[[50,25],[58,21],[66,22],[68,30],[68,38]]},{"t":"testTube","x":68,"y":46,"h":26,"w":12,"liquid":0.45,"color":"colorless"},{"t":"text","x":88,"y":38,"text":"澄清石灰水","anchor":"end","size":3.2},{"t":"text","x":68,"y":62,"text":"石灰水变浑浊","size":3.2,"tone":"accent"}]}},{"id":"chem-substance-5-q2","type":"choice","stem":"下列关于一氧化碳和二氧化碳的说法正确的是（　）","answer":"C","explain":"C 正确：CO 的还原性正是工业炼铁中还原氧化铁的化学依据；CO₂ 不能燃烧也不支持燃烧，所以能用来灭火。A 有两处错：CO₂ 无毒，也不属于空气污染物。B 把溶解性混为一谈：CO 难溶于水，CO₂ 能溶于水并与水反应生成碳酸。D 把原因说反了：两种气体都由碳、氧两种元素组成，组成元素相同，性质差别大是因为分子构成不同（CO₂ 比 CO 多一个氧原子）。","options":["一氧化碳和二氧化碳都有毒，都属于空气污染物","一氧化碳和二氧化碳都能溶于水","一氧化碳有还原性，可用于冶炼金属；二氧化碳不能燃烧也不支持燃烧","一氧化碳和二氧化碳的组成元素不同，所以性质差别很大"],"difficulty":2,"tags":["碳的氧化物","CO 与 CO₂ 的性质"]},{"id":"chem-substance-5-q3","type":"choice","stem":"下列有关碳单质的说法正确的是（　）","answer":"B","explain":"B 正确：活性炭疏松多孔、表面积很大，能吸附异味和色素，冰箱除味剂、防毒面具的滤毒罐都用它。A 错在「完全相同」：金刚石是空间网状结构、很硬，石墨是层状结构、质软，物理性质差别很大。C 有两处错：C60 只由碳元素组成，属于单质而不是化合物；它与氧元素无关。D 把两个性质混在一起：石墨质软与导电性无关，石墨能导电，正是常用的电极材料。","options":["金刚石和石墨都由碳元素组成，所以物理性质完全相同","活性炭结构疏松多孔、具有吸附性，可用于除去冰箱中的异味","C60 是一种由碳元素和氧元素组成的新型化合物","石墨很软，所以不能导电，不能用作电极"],"difficulty":1,"tags":["碳单质","金刚石与石墨","活性炭"]},{"id":"chem-substance-5-q4","type":"choice","stem":"下列关于二氧化碳用途的说法正确的是（　）","answer":"D","explain":"D 正确：能灭火的两个条件都在这里——密度比空气大（能覆盖在燃烧物表面）、不能燃烧也不支持燃烧。A 把成分弄错了：干冰是固态的二氧化碳，不是固态的水。B 错：CO₂ 不是空气污染物，形成酸雨的主要气体是二氧化硫和二氧化氮。C 绝对化：CO₂ 是植物光合作用的原料，可作气体肥料，还能用于制碳酸饮料、灭火，只有浓度过高时才会使人窒息。","options":["干冰是固态的水，升华时吸热，可用于人工降雨","二氧化碳是空气污染物，也是形成酸雨的主要气体","二氧化碳不能供给呼吸，所以它对人体只有害处","二氧化碳可用于灭火，因为它的密度比空气大，且不能燃烧也不支持燃烧"],"difficulty":1,"tags":["碳的氧化物","二氧化碳的用途"]},{"id":"chem-substance-5-q5","type":"choice","stem":"下列关于碳及其氧化物之间转化的说法正确的是（　）","answer":"C","explain":"C 正确：碳夺取氧化铜中的氧，把氧化铜还原成铜，自身被氧化成二氧化碳，所以碳是还原剂。A 错：常温下碳的化学性质很不活泼（古代字画能长期保存就是这个道理），碳与氧气反应需要点燃。B 的条件写错了：CO₂ 与碳反应的条件是「高温」，写成「点燃」是常见错误。D 的条件也写错：CO 还原氧化铜只需「加热」，需要高温的是碳还原氧化铜。","options":["碳在常温下就能与氧气反应生成二氧化碳","CO₂ + C —点燃→ 2CO","C + 2CuO —高温→ 2Cu + CO₂↑，反应中碳作还原剂","一氧化碳还原氧化铜的条件是高温，生成铜和二氧化碳"],"difficulty":2,"tags":["碳的化学性质","反应条件","还原反应"]},{"id":"chem-substance-5-q6","type":"fill","stem":"金刚石、石墨、C60 都是由 ______ 元素组成的单质（填元素名称或元素符号）。","answer":"碳|C","explain":"三种物质都由碳元素组成，是碳元素形成的不同单质，物理性质差异大是因为碳原子的排列方式不同。填「碳」或「C」都可以，但要注意「碳」是元素名称、「C」是元素符号，两者都不能写成表示物质的「炭」（木炭、活性炭表示含碳的混合物或具体物质）。","difficulty":1,"tags":["碳单质","元素与物质"]},{"id":"chem-substance-5-q7","type":"fill","stem":"把 8 g 氧化铜与足量木炭粉混合后高温加热，氧化铜完全反应，可得到铜 ______ g。（相对原子质量：Cu 64、O 16）","answer":"6.4","explain":"由 C + 2CuO —高温→ 2Cu + CO₂↑ 可知，氧化铜与铜的质量比为 (2×80)∶(2×64) = 160∶128 = 5∶4，所以 8 g 氧化铜可得到铜 8 g × 4/5 = 6.4 g。若把 CuO 的相对分子质量算成 64 + 32 = 96（误把氧的相对原子质量当成 32），结果就会算错。","difficulty":2,"tags":["碳的化学性质","化学方程式计算"]},{"id":"chem-substance-5-q8","type":"short","stem":"把 16 g 氧化铜与足量木炭粉混合均匀后高温加热，氧化铜完全反应。求生成铜的质量和生成二氧化碳的质量。（相对原子质量：C 12、O 16、Cu 64）","answer":"设生成铜的质量为 x，生成二氧化碳的质量为 y。由 C + 2CuO —高温→ 2Cu + CO₂↑ 可知 m(CuO)∶m(Cu)∶m(CO₂) = 160∶128∶44。由 160∶128 = 16 g∶x 得 x = 12.8 g；由 160∶44 = 16 g∶y 得 y = 4.4 g。验算：参加反应的碳为 12/160 × 16 g = 1.2 g，1.2 g + 16 g = 12.8 g + 4.4 g，符合质量守恒定律。答：生成铜 12.8 g，生成二氧化碳 4.4 g。","explain":"这道题最容易错的地方有两处：一是方程式没配平（写成 C + CuO → Cu + CO₂），相对质量比就变成了 80∶64∶44，结果全错；二是 CuO 的相对分子质量算错（把氧的相对原子质量当成 32）。检验方法依旧是质量守恒：算完后再算一下参加反应的碳（1.2 g），看看反应物总质量与生成物总质量是否相等。","difficulty":2,"tags":["碳的化学性质","化学方程式计算","质量守恒"],"rubric":["化学方程式书写正确并配平，条件写「高温」","相对质量 160、128、44 算对（CuO 按 80 算，不能按 96 算）","分别求出铜 12.8 g、二氧化碳 4.4 g","结果带单位、有答句，并用质量守恒定律验算或说明依据"],"steps":["设未知量：设生成铜的质量为 x，生成二氧化碳的质量为 y。","写出并配平化学方程式：C + 2CuO —高温→ 2Cu + CO₂↑。","算出相对质量总和：2×(64 + 16) = 160，2×64 = 128，12 + 16×2 = 44。","列比例式：160∶128 = 16 g∶x 得 x = 12.8 g；160∶44 = 16 g∶y 得 y = 4.4 g。","用质量守恒定律验算（1.2 + 16 = 12.8 + 4.4），写出带单位的答句。"]},{"id":"chem-substance-5-q9","type":"short","stem":"有两瓶无色无味的气体，一瓶是一氧化碳，另一瓶是二氧化碳。请设计实验把它们鉴别开（写出操作步骤、现象和结论，至少写出两种方法）。","answer":"方法一：分别向两个集气瓶中倒入少量澄清石灰水，振荡。石灰水变浑浊的那瓶是二氧化碳（CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O），没有明显变化的那瓶是一氧化碳。方法二：分别用燃着的木条伸入两个集气瓶中。木条熄灭的那瓶是二氧化碳（不燃烧也不支持燃烧）；气体能燃烧并产生蓝色火焰的那瓶是一氧化碳（2CO + O₂ —点燃→ 2CO₂）。方法三：分别通过灼热的氧化铜。能使黑色氧化铜变红、并把生成的气体通入澄清石灰水后变浑浊的是一氧化碳（CO + CuO —加热→ Cu + CO₂）；无明显变化的则是二氧化碳。","explain":"鉴别的答题结构永远是「操作 → 现象 → 结论」三段，缺一段就要扣分。这两种气体最适合用「化学性质差异」来鉴别：CO 能燃烧、有还原性，CO₂ 能与澄清石灰水反应。注意不能只写「用石灰水鉴别」而不写现象；也不要写成「闻气味」，因为两者都是无色无味的气体。","difficulty":2,"tags":["碳的氧化物","实验探究","物质的鉴别"],"rubric":["写出至少两种鉴别方法，操作、现象、结论三者齐全","用澄清石灰水法时写出化学方程式并用「变浑浊」描述现象","用点燃法时指出 CO 能燃烧产生蓝色火焰、CO₂ 使燃着的木条熄灭","结论与现象对应正确，不能只写现象不写结论"]},{"id":"chem-substance-5-q10","type":"short","stem":"请用粒子模型分别画出 1 个一氧化碳分子和 1 个二氧化碳分子的结构（用圆圈表示原子并标出元素符号），再说明这两种气体都由碳、氧两种元素组成，为什么化学性质差别很大。","answer":"画法：一氧化碳分子由 1 个碳原子和 1 个氧原子构成（画成 C—O），二氧化碳分子由 1 个碳原子和 2 个氧原子构成（画成 O—C—O）。说明：两种气体的组成元素虽然相同，但分子构成不同——1 个二氧化碳分子比 1 个一氧化碳分子多 1 个氧原子，分子结构不同，化学性质就不同：CO 能燃烧、有还原性、有剧毒，CO₂ 不能燃烧也不支持燃烧、能溶于水并与水反应。","explain":"这道题的得分点一半在画图、一半在说理。画图时原子的个数不能错：CO 是 1 个碳加 1 个氧，CO₂ 是 1 个碳加 2 个氧，多画或少画一个氧原子就等于把物质写错了。说理时必须落到「分子构成不同 → 性质不同」这条线索上，只说「因为结构不同」太笼统，要说出「相差一个氧原子」。","difficulty":2,"tags":["碳的氧化物","作图题","粒子模型"],"rubric":["一氧化碳分子画出 1 个碳原子与 1 个氧原子，标注化学式 CO","二氧化碳分子画出 1 个碳原子与 2 个氧原子，标注化学式 CO₂","指出两种分子相差 1 个氧原子（分子构成不同）","由「分子构成不同」推出「化学性质不同」，并各举一条性质差异"],"figure":{"id":"fig-chem-substance-5-q10","title":"待画的分子结构","caption":"请分别画出一氧化碳分子和二氧化碳分子的结构","view":"wide","alt":"画布左侧标出一氧化碳、右侧标出二氧化碳，两个位置都留空，等待用圆圈和元素符号画出它们的分子结构","prims":[{"t":"text","x":28,"y":14,"text":"一氧化碳分子 CO","size":4},{"t":"text","x":76,"y":14,"text":"二氧化碳分子 CO₂","size":4},{"t":"rect","x":10,"y":22,"w":36,"h":22,"dashed":true,"tone":"muted"},{"t":"rect","x":58,"y":22,"w":36,"h":22,"dashed":true,"tone":"muted"},{"t":"text","x":28,"y":54,"text":"（在此处画出原子与化学键）","size":3.2,"tone":"muted"},{"t":"text","x":76,"y":54,"text":"（在此处画出原子与化学键）","size":3.2,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-5-q10-a","title":"参考答案：CO 与 CO₂ 的分子结构","caption":"两个分子只差一个氧原子，性质却不同","view":"wide","alt":"左侧画出由 1 个碳原子和 1 个氧原子构成的一氧化碳分子，右侧画出由 1 个碳原子和 2 个氧原子构成的二氧化碳分子","prims":[{"t":"molecule","x":28,"y":24,"atoms":[{"dx":-5,"dy":0,"r":4.4,"symbol":"C","color":"black"},{"dx":5,"dy":0,"r":4.4,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"CO"},{"t":"molecule","x":76,"y":24,"atoms":[{"dx":-6,"dy":0,"r":4.4,"symbol":"O","color":"red"},{"dx":0,"dy":0,"r":4.4,"symbol":"C","color":"black"},{"dx":6,"dy":0,"r":4.4,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"text","x":28,"y":48,"text":"能燃烧、有还原性、有剧毒","size":3.2,"tone":"muted"},{"t":"text","x":76,"y":48,"text":"不能燃烧、不支持燃烧、无毒","size":3.2,"tone":"muted"},{"t":"text","x":52,"y":58,"text":"分子构成不同（相差 1 个氧原子）→ 化学性质不同","size":3.4,"tone":"accent"}]}},{"id":"chem-substance-5-m1-q1","type":"short","stem":"（3 分）根据材料一回答：金刚石与石墨都由碳元素组成，为什么它们的物理性质差别很大？木炭与活性炭的吸附性属于物理变化还是化学变化？请说明理由。","answer":"金刚石与石墨虽然都由碳元素组成，但碳原子的排列方式不同（金刚石是空间网状结构、石墨是层状结构），所以物理性质差别很大。木炭与活性炭的吸附性属于物理变化，因为吸附过程中没有生成新物质，只是把色素、异味等吸附在疏松多孔的表面。","explain":"","rubric":["答出「都由碳元素组成、是碳的不同单质」","答出「碳原子的排列方式不同」并简要说明两种结构（网状、层状）","判断吸附属于物理变化，理由是没有生成新物质"]},{"id":"chem-substance-5-m1-q2","type":"short","stem":"（4 分）根据材料二，煤炉中为什么会有一氧化碳产生（写出两条途径并配上化学方程式）？一氧化碳使人中毒的原因是什么？怎样预防？","answer":"两条途径：① 室内氧气不足时碳不完全燃烧：2C + O₂ —点燃→ 2CO；② 生成的二氧化碳通过灼热的煤层被还原：CO₂ + C —高温→ 2CO。中毒原因：一氧化碳与血液中的血红蛋白结合，结合能力比氧气强得多，使血液失去输氧能力，人因缺氧而中毒。预防措施：保持室内通风；安装烟囱把废气排到室外；不在密闭的房间内用炭火取暖；安装一氧化碳报警器。","explain":"","rubric":["写出两条产生 CO 的途径，化学方程式书写正确、条件写对（点燃／高温）","答出「CO 与血红蛋白结合，使血液失去输氧能力」","给出一条具体的预防措施（通风、烟囱、不用密闭炭火等）","能补充急救做法：开窗通风、把人移到通风处、不使用明火与电器开关（加分点）"]},{"id":"chem-substance-5-m1-q3","type":"short","stem":"（4 分）根据材料三计算：把 8 g 氧化铜完全还原成铜，至少需要木炭粉多少克？能得到铜多少克？（相对原子质量：C 12、O 16、Cu 64）","answer":"设需要木炭粉的质量为 x，得到铜的质量为 y。由 C + 2CuO —高温→ 2Cu + CO₂↑ 可知 m(C)∶m(CuO)∶m(Cu) = 12∶160∶128。由 12∶160 = x∶8 g 得 x = 0.6 g；由 160∶128 = 8 g∶y 得 y = 6.4 g。答：至少需要木炭粉 0.6 g，能得到铜 6.4 g。","explain":"","rubric":["写出并配平化学方程式 C + 2CuO —高温→ 2Cu + CO₂↑（条件写高温）","算出相对质量 12、160、128（CuO 按 64 + 16 = 80 计算）","求出木炭粉 0.6 g、铜 6.4 g","结果带单位并写出答句"]}]},{"id":"chem-substance-6","title":"二氧化碳的制取与性质：实验室制法·装置与检验验满·性质实验与温室效应","subtitle":"人教版九年级 · 第六单元 碳和碳的氧化物 · 9a","grade":"9a","tags":["人教版九年级 · 第六单元 碳和碳的氧化物"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第六单元 碳和碳的氧化物 · 9a"},{"type":"note","title":"问题切入","text":"实验室制取二氧化碳，为什么用大理石和稀盐酸，而不能用稀硫酸或浓盐酸？为什么只能用向上排空气法收集？怎样检验一瓶气体是不是二氧化碳，又怎样判断这瓶气体已经收集满了？"},{"type":"note","title":"一句话抓住关键","text":"实验室用大理石（石灰石）与稀盐酸反应制取二氧化碳：CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑。发生装置用固液常温型（长颈漏斗下端必须伸入液面以下），收集只能用向上排空气法（密度比空气大、能溶于水且与水反应）。检验用澄清石灰水（变浑浊），验满用燃着的木条放在集气瓶口（木条熄灭）——检验看「是不是」，验满看「满没满」，两者不能混。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"打开一瓶汽水，气泡咕嘟咕嘟往上冒；把汽水倒进澄清石灰水，石灰水立刻变浑浊。这些现象背后都是二氧化碳，而实验室里制它，靠的是大理石和稀盐酸。","walk":["实验室用大理石（或石灰石）与稀盐酸反应：碳酸钙加盐酸生成氯化钙、水和二氧化碳。不用稀硫酸，因为生成的硫酸钙微溶，会包在石灰石表面阻止反应；不用浓盐酸，因为会挥发出氯化氢气体；不用碳酸钠粉末，因为反应太快不便收集。","二氧化碳密度比空气大、能溶于水，所以用向上排空气法收集。检验用澄清石灰水，验满把燃着的木条放在瓶口。","二氧化碳不燃烧也不支持燃烧，能和水反应生成碳酸，能使澄清石灰水变浑浊，参与光合作用，也是主要温室气体之一。"],"try":"在成人陪同下，把小苏打放进杯中，倒入白醋，观察大量气泡产生；把气泡「倒」到燃着的蜡烛上方，看蜡烛是否熄灭。","use":["制取气体选药品要同时考虑「能反应、速率合适、产物易分离」。","检验和验满是两件事：检验看「是不是」，验满看「满没满」。"]},{"type":"h","text":"【宏观】宏观：药品的选择与发生装置"},{"type":"p","text":"先选药品：大理石（或石灰石，主要成分是碳酸钙）与稀盐酸反应，生成氯化钙、水和二氧化碳，反应在常温下就能平稳进行。三种药品不能用：不能用稀硫酸（生成的硫酸钙微溶于水，会覆盖在大理石表面阻止反应继续）、不能用浓盐酸（易挥发出氯化氢气体，使收集到的二氧化碳不纯）、不能用碳酸钠粉末（反应太快，气体来不及收集）。再选装置：反应物是固体与液体、常温进行，所以用固液常温型——锥形瓶、双孔橡皮塞、长颈漏斗加导管。"},{"type":"figure","figure":{"id":"fig-chem-substance-6-1","title":"实验室制取二氧化碳的装置","caption":"长颈漏斗下端伸入液面以下形成液封，集气瓶正放、导管伸到接近瓶底","view":"wide","alt":"锥形瓶中放有大理石和稀盐酸，长颈漏斗下端伸入液面以下，双孔橡皮塞上的导管弯向右侧，伸到正放的集气瓶中接近瓶底的位置","prims":[{"t":"flask","x":30,"y":40,"kind":"conical","h":24,"w":26,"liquid":0.6,"color":"colorless"},{"t":"funnel","x":30,"y":28,"kind":"long","h":18,"label":"长颈漏斗"},{"t":"rect","x":20,"y":26,"w":20,"h":2.5,"fill":true},{"t":"curve","points":[[36,28],[52,24],[62,25],[68,30],[68,46]]},{"t":"text","x":46,"y":20,"text":"大理石 + 稀盐酸","size":3.2,"tone":"muted"},{"t":"gasJar","x":78,"y":34,"w":22,"h":28,"color":"colorless","cover":true},{"t":"text","x":78,"y":60,"text":"向上排空气法收集","size":3.2,"tone":"accent"},{"t":"text","x":12,"y":58,"text":"长颈漏斗下端","size":3,"tone":"accent"},{"t":"text","x":12,"y":63,"text":"必须在液面以下","size":3,"tone":"accent"}]}},{"type":"note","title":"","text":"长颈漏斗下端管口伸入液面以下是装置的「命门」：不伸入液面以下，生成的二氧化碳就会从长颈漏斗口逸出，集气瓶里根本收不到气体。橡皮塞上的导管在瓶内只略伸出一点，伸得太长会阻碍气体排出。"},{"type":"h","text":"【宏观】宏观：收集、检验与验满"},{"type":"p","text":"二氧化碳能溶于水并与水反应，所以不能用排水法收集；它的密度比空气大，所以用向上排空气法，集气瓶正放，导管伸到接近瓶底，并用玻璃片盖住瓶口。收集好以后要做两件事，先分清目的：检验是判断「这瓶气体是不是二氧化碳」，方法是把气体通入（或倒入少量）澄清石灰水，石灰水变浑浊就是二氧化碳；验满是判断「瓶里的二氧化碳满了没有」，方法是用燃着的木条放在集气瓶口，木条熄灭说明已收集满——注意木条只能放在瓶口，不能伸进瓶内。"},{"type":"figure","figure":{"id":"fig-chem-substance-6-2","title":"检验与验满的区别","caption":"检验用澄清石灰水（看是不是），验满用燃着的木条放瓶口（看满没满）","view":"wide","alt":"左侧集气瓶内倒入澄清石灰水并振荡，说明检验二氧化碳的方法；右侧集气瓶口放着一根燃着的木条，木条熄灭说明二氧化碳已收集满","prims":[{"t":"gasJar","x":26,"y":34,"w":24,"h":28,"liquid":0.25,"color":"colorless","label":"检验"},{"t":"text","x":26,"y":20,"text":"倒入澄清石灰水","size":3.2,"tone":"muted"},{"t":"text","x":26,"y":56,"text":"石灰水变浑浊 → 是 CO₂","size":3.2,"tone":"accent"},{"t":"gasJar","x":74,"y":34,"w":24,"h":28,"color":"colorless","label":"验满"},{"t":"line","x1":74,"y1":20,"x2":82,"y2":7,"width":0.9},{"t":"poly","points":[[74,21],[72.4,17],[74,13.5],[75.6,17]],"fill":true,"tone":"danger"},{"t":"text","x":74,"y":56,"text":"木条熄灭 → 已收集满","size":3.2,"tone":"accent"},{"t":"text","x":50,"y":8,"text":"木条只能放在瓶口，不能伸入瓶内","size":3.4,"tone":"danger"}]}},{"type":"note","title":"","text":"两处最容易被扣分：一是验满时把燃着的木条伸进瓶内（这样只能说明瓶内有 CO₂，不能说明是否收集满）；二是用燃着的木条去「检验」二氧化碳（木条熄灭的气体很多，氮气也会让木条熄灭，必须用澄清石灰水才能确证）。"},{"type":"h","text":"【微观】微观：二氧化碳与水怎样生成碳酸"},{"type":"p","text":"二氧化碳通入水中时，一部分二氧化碳分子与水分子结合，生成碳酸分子 H₂CO₃；碳酸能使紫色石蕊溶液变红。所以使石蕊变红的是碳酸而不是二氧化碳本身——把二氧化碳通入干燥的紫色石蕊纸花上，纸花不会变红，就是这个道理。碳酸很不稳定，常温下就会缓慢分解，受热时分解得更快：加热变红的溶液，红色又变回紫色，说明碳酸分解放出了二氧化碳和水。"},{"type":"figure","figure":{"id":"fig-chem-substance-6-3","title":"二氧化碳与水反应生成碳酸","caption":"使石蕊变红的是碳酸，碳酸受热又分解成水和二氧化碳","view":"wide","alt":"一个二氧化碳分子和一个水分子结合生成一个碳酸分子，下方说明碳酸不稳定、受热分解生成水和二氧化碳","prims":[{"t":"molecule","x":16,"y":20,"atoms":[{"dx":-4.4,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":0,"r":3.8,"symbol":"C","color":"black"},{"dx":4.4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"molecule","x":16,"y":46,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red"},{"dx":-4,"dy":-3,"symbol":"H"},{"dx":4,"dy":-3,"symbol":"H"}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"arrow","x1":30,"y1":33,"x2":44,"y2":33,"label":"溶解并反应","labelDy":-4},{"t":"molecule","x":68,"y":30,"atoms":[{"dx":0,"dy":0,"r":3.6,"symbol":"C","color":"black"},{"dx":6,"dy":-4,"symbol":"O","color":"red"},{"dx":-6,"dy":-4,"symbol":"O","color":"red"},{"dx":0,"dy":6.5,"symbol":"O","color":"red"},{"dx":-8.5,"dy":3,"r":2.8,"symbol":"H"},{"dx":8.5,"dy":3,"r":2.8,"symbol":"H"}],"bonds":[[0,1],[0,2],[0,3],[2,4],[1,5]],"label":"H₂CO₃"},{"t":"text","x":68,"y":52,"text":"碳酸使紫色石蕊变红","size":3.2,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"碳酸不稳定：H₂CO₃ = H₂O + CO₂↑（受热分解更快）","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"答题要写「二氧化碳与水反应生成了碳酸，碳酸使紫色石蕊溶液变红」，不能写「二氧化碳使石蕊变红」。反过来，加热变红的溶液后红色变回紫色，说明碳酸分解，现象要写成「红色逐渐变回紫色」。"},{"type":"h","text":"【符号】符号：五个方程式，把制取与性质串起来"},{"type":"p","text":"制取：CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑，这类在溶液中常温进行的反应用等号，不写条件，生成的气体标 ↑。与水反应：CO₂ + H₂O = H₂CO₃；碳酸分解：H₂CO₃ = H₂O + CO₂↑（加热时更快）。检验：CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O，CaCO₃ 是沉淀，必须标 ↓。工业上制生石灰与二氧化碳：CaCO₃ —高温→ CaO + CO₂↑，条件是「高温」而不是「加热」。配平仍靠数原子：以第一个方程式为例，左边 1 个钙、1 个碳、3 个氧、2 个氢、2 个氯，右边 CaCl₂ 有 1 个钙与 2 个氯，H₂O 有 2 个氢与 1 个氧，CO₂ 有 1 个碳与 2 个氧，氧原子合计 3 个，两边相等。"},{"type":"note","title":"","text":"「=」与「—条件→」的用法要分清：溶液中常温进行的反应用等号（CaCO₃ + 2HCl、CO₂ + Ca(OH)₂、CO₂ + H₂O），需要加热或高温的用箭头并在箭头上写条件（H₂CO₃ 受热分解、CaCO₃ 高温分解）。气体符号与沉淀符号只在溶液中生成时标注。"},{"type":"h","text":"【应用】应用：灭火、温室效应与低碳生活"},{"type":"p","text":"二氧化碳的用途都来自它的性质：不能燃烧也不支持燃烧、密度比空气大，所以用来灭火（把燃着的蜡烛放在烧杯中，沿杯壁慢慢倒入二氧化碳，下面的蜡烛先熄灭、上面的后熄灭，说明它先在底部聚集）；能溶于水，所以制碳酸饮料；干冰升华吸热，用于人工降雨、食品冷藏、舞台造雾；还是光合作用的原料，可作气体肥料。空气中的二氧化碳含量升高会加剧温室效应，导致全球变暖、海平面上升。减缓的措施有：减少煤、石油等化石燃料的燃烧，开发太阳能、风能等新能源，大力植树造林。"},{"type":"figure","figure":{"id":"fig-chem-substance-6-4","title":"倾倒二氧化碳：阶梯上的蜡烛","caption":"二氧化碳先在底部聚集，下面的蜡烛先熄灭","view":"wide","alt":"烧杯中的二氧化碳沿杯壁慢慢倒入放有阶梯蜡烛的烧杯中，二氧化碳在底部聚集，下面位置较低的蜡烛先熄灭，上面的蜡烛后熄灭","prims":[{"t":"poly","points":[[14,40],[34,40],[34,46],[54,46],[54,52],[74,52]],"closed":false},{"t":"rect","x":23,"y":32,"w":3,"h":8,"fill":true},{"t":"poly","points":[[24.5,32],[23,28],[24.5,25],[26,28]],"fill":true,"tone":"danger"},{"t":"rect","x":43,"y":38,"w":3,"h":8,"fill":true},{"t":"poly","points":[[44.5,38],[43,34],[44.5,31],[46,34]],"fill":true,"tone":"danger"},{"t":"poly","points":[[80,10],[96,10],[92,22],[84,22]],"closed":true},{"t":"arrow","x1":84,"y1":24,"x2":62,"y2":42,"tone":"muted","label":"倾倒 CO₂","labelDy":-6},{"t":"hatch","x":14,"y":52,"w":60,"h":6,"gap":2},{"t":"text","x":44,"y":61,"text":"CO₂ 密度比空气大，先在底部聚集 → 下面的蜡烛先熄灭","size":3.2,"tone":"accent"},{"t":"text","x":26,"y":8,"text":"阶梯上的蜡烛","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"解释现象时两句话都要说：蜡烛熄灭说明 CO₂ 不能燃烧也不支持燃烧；下面的蜡烛先熄灭说明 CO₂ 的密度比空气大、先沉在底部。只说一句拿不到满分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["相对分子质量（CaCO₃ 与 CO₂）","CaCO₃ 的相对分子质量 = 40 + 12 + 16×3 = 100；CO₂ 的相对分子质量 = 12 + 16×2 = 44","用于制取二氧化碳的计算。CO₂ 的相对分子质量 44 大于空气的平均相对分子质量 29，所以它的密度比空气大，可以用向上排空气法收集、可以用来灭火。计算时相对原子质量取整数：Ca 40、C 12、O 16。"],["元素的质量分数（以 CaCO₃ 为例）","CaCO₃ 中钙元素的质量分数 = 40 ÷ 100 × 100% = 40%","用于计算纯净物中某元素的质量分数，也可由元素质量反推物质质量。注意只能用于纯净物：石灰石是混合物（主要成分是 CaCO₃），要先知道其中 CaCO₃ 的质量分数，才能算钙元素的质量分数。"],["含杂质物质的化学方程式计算","纯物质的质量 = 混合物的质量 × 纯度（质量分数）；混合物的质量 = 纯物质的质量 ÷ 纯度","适用于所有含杂质的原料计算。化学方程式中的质量比只适用于参加反应的纯物质，所以必须先换算成纯物质的质量再代入；杂质不参加反应，也不能把混合物的质量直接代入比例式。"]]},{"type":"h","text":"应用 · 二氧化碳灭火器与温室效应"},{"type":"note","title":"情境","text":"图书馆的档案室着火时，常用二氧化碳灭火器灭火；与此同时，空气中的二氧化碳含量逐年升高，人们越来越担心温室效应。二氧化碳为什么能灭火？又为什么会导致温室效应？"},{"type":"list","title":"解答步骤","items":["先写灭火的两条依据：不能燃烧也不支持燃烧；密度比空气大、能覆盖在燃烧物表面。","补充在图书档案场所使用的优点：灭火后不留痕迹、不损坏物品。","说明温室效应的成因：二氧化碳含量升高，吸收地面辐射的热量，使全球气候变暖。","写出减缓措施：减少化石燃料的燃烧、开发使用太阳能与风能等新能源、大力植树造林。"]},{"type":"note","title":"结论","text":"灭火的依据是「不燃烧、不支持燃烧、密度比空气大」；减缓温室效应要从「减少排放」和「增加吸收」两方面答，只写「保护环境」不得分。"},{"type":"h","text":"应用 · 用碳酸钙制取二氧化碳的计算"},{"type":"note","title":"情境","text":"实验室要用碳酸钙与足量稀盐酸反应制取 4.4 g 二氧化碳，至少需要碳酸钙多少克？（相对原子质量：C 12、O 16、Ca 40）"},{"type":"list","title":"解答步骤","items":["写出化学方程式：CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑。","算出相对质量：CaCO₃ = 40 + 12 + 48 = 100，CO₂ = 12 + 32 = 44。","设需要碳酸钙的质量为 x：100∶44 = x∶4.4 g，解得 x = 10 g。","答：至少需要碳酸钙 10 g。"]},{"type":"note","title":"结论","text":"至少需要碳酸钙 10 g。若题目给的是含杂质的石灰石（如含碳酸钙 80% 的石灰石），还要用「纯物质质量 ÷ 纯度」换算成石灰石的质量：10 g ÷ 80% = 12.5 g。"},{"type":"h","text":"实验 1 · 实验室制取二氧化碳"},{"type":"note","title":"实验目的","text":"学会用固液常温型装置制取二氧化碳，掌握装置的连接、收集方法以及检验与验满的区别。"},{"type":"list","title":"实验器材","items":["锥形瓶、双孔橡皮塞、长颈漏斗、导管","大理石（或石灰石）、稀盐酸","集气瓶、玻璃片","燃着的木条、澄清石灰水"]},{"type":"figure","figure":{"id":"fig-chem-substance-6-exp1","title":"实验室制取二氧化碳的装置","caption":"长颈漏斗下端伸入液面以下，导管伸到集气瓶底部，瓶口盖玻璃片","view":"wide","alt":"锥形瓶内放有大理石和稀盐酸，长颈漏斗下端伸入液面以下，橡皮塞上的导管通向正放的集气瓶并伸到接近瓶底，瓶口盖着玻璃片","prims":[{"t":"flask","x":30,"y":40,"kind":"conical","h":24,"w":26,"liquid":0.6,"color":"colorless"},{"t":"funnel","x":30,"y":28,"kind":"long","h":18,"label":"长颈漏斗"},{"t":"rect","x":20,"y":26,"w":20,"h":2.5,"fill":true},{"t":"curve","points":[[36,28],[52,24],[62,25],[68,30],[68,46]]},{"t":"gasJar","x":78,"y":34,"w":22,"h":28,"color":"colorless","cover":true},{"t":"text","x":30,"y":60,"text":"大理石（石灰石）+ 稀盐酸","size":3.2,"tone":"muted"},{"t":"text","x":78,"y":60,"text":"导管伸到接近瓶底","size":3.2,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["按要求组装装置，检查装置的气密性（把导管口浸入水中，用手握住锥形瓶外壁，导管口有气泡冒出说明不漏气）。","把大理石（石灰石）放入锥形瓶中，塞紧带长颈漏斗和导管的双孔橡皮塞，长颈漏斗下端要伸入液面以下。","通过长颈漏斗加入适量稀盐酸，观察锥形瓶内的现象。","用向上排空气法收集二氧化碳：集气瓶正放，导管伸到接近瓶底，瓶口用玻璃片盖住。","把燃着的木条放在集气瓶口，木条熄灭说明已收集满；把气体通入澄清石灰水，石灰水变浑浊说明是二氧化碳。"]},{"type":"note","title":"实验现象","text":"大理石表面产生大量气泡，固体逐渐溶解变小；收集一段时间后，把燃着的木条放在集气瓶口，木条熄灭；把气体通入澄清石灰水，石灰水变浑浊。"},{"type":"note","title":"实验结论","text":"大理石（碳酸钙）与稀盐酸反应生成氯化钙、水和二氧化碳，化学方程式为 CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑；收集到的气体是二氧化碳，可用澄清石灰水检验。"},{"type":"list","title":"注意事项","items":["长颈漏斗的下端管口必须伸入液面以下，形成液封，否则生成的二氧化碳会从长颈漏斗口逸出，收集不到气体。","导管在橡皮塞内只略伸出一点，伸入锥形瓶内太长会阻碍气体排出；伸入集气瓶的一端要接近瓶底，才能把瓶内空气排尽。","不能用稀硫酸代替稀盐酸：生成的硫酸钙微溶于水，会覆盖在大理石表面，阻止反应继续进行。","不能用浓盐酸：浓盐酸易挥发出氯化氢气体，使收集到的二氧化碳不纯；也不能用碳酸钠粉末，它反应太快，气体来不及收集。","验满时燃着的木条只能放在集气瓶口，不能伸入瓶内；检验二氧化碳要用澄清石灰水，不能用燃着的木条。","加入的稀盐酸要适量，浸没长颈漏斗下端即可；实验结束把剩余药品按要求处理，不能随意倒入下水道。"]},{"type":"h","text":"实验 2 · 二氧化碳与水的反应（紫色石蕊溶液的变化）"},{"type":"note","title":"实验目的","text":"证明二氧化碳能与水反应生成碳酸，并认识碳酸的不稳定性。"},{"type":"list","title":"实验器材","items":["集气瓶（充满二氧化碳）、导管","试管、紫色石蕊溶液","酒精灯、试管夹"]},{"type":"figure","figure":{"id":"fig-chem-substance-6-exp2","title":"二氧化碳使紫色石蕊溶液变红","caption":"通入二氧化碳后溶液变红，加热后红色又变回紫色","view":"wide","alt":"一支试管中盛有紫色的石蕊溶液，导管把二氧化碳通入其中，溶液变红；把变红的溶液加热后，红色又变回紫色","prims":[{"t":"testTube","x":26,"y":28,"h":32,"w":13,"liquid":0.5,"color":"red"},{"t":"curve","points":[[12,14],[22,12],[26,16],[26,22]]},{"t":"text","x":26,"y":8,"text":"通入 CO₂","size":3.4,"tone":"accent"},{"t":"text","x":26,"y":50,"text":"紫色石蕊溶液变红","size":3.2,"tone":"danger"},{"t":"arrow","x1":40,"y1":28,"x2":54,"y2":28,"label":"加热","labelDy":-4},{"t":"testTube","x":70,"y":28,"h":32,"w":13,"liquid":0.5,"color":"purple"},{"t":"alcoholLamp","x":70,"y":44,"lit":true},{"t":"text","x":70,"y":50,"text":"红色变回紫色","size":3.2,"tone":"accent"},{"t":"text","x":50,"y":61,"text":"碳酸不稳定：H₂CO₃ = H₂O + CO₂↑","size":3.2,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["取一支试管，加入约三分之一体积的紫色石蕊溶液，观察它的颜色。","把二氧化碳气体通入紫色石蕊溶液中，观察溶液颜色的变化。","用试管夹夹住试管，在酒精灯上加热变红的溶液，观察颜色又发生了什么变化。","记录两次颜色变化，写出对应的化学方程式。"]},{"type":"note","title":"实验现象","text":"通入二氧化碳后，紫色石蕊溶液逐渐变成红色；加热后，红色又逐渐变回紫色，同时有气泡冒出。"},{"type":"note","title":"实验结论","text":"二氧化碳与水反应生成碳酸，碳酸使紫色石蕊溶液变红（CO₂ + H₂O = H₂CO₃）；碳酸不稳定，受热分解生成水和二氧化碳（H₂CO₃ = H₂O + CO₂↑），所以红色又变回紫色。"},{"type":"list","title":"注意事项","items":["使石蕊变红的是碳酸而不是二氧化碳：可以用干燥的紫色石蕊纸花做对照，把二氧化碳直接通到干燥纸花上，纸花不变红。","加热试管时要先预热、再用外焰加热，试管口不要对着人；液体体积不要超过试管容积的三分之一。","不能用嘴吹灭酒精灯，要用灯帽盖灭；实验结束后等试管冷却再洗涤，防止骤冷炸裂。","通入二氧化碳的时间不要太长，观察到颜色变化即可，避免碳酸分解与生成反复进行、现象不清楚。","这个实验只能说明二氧化碳与水反应生成了酸性物质，不能说明二氧化碳本身显酸性。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑","常温（在溶液中反应，不写条件）","大理石的表面产生大量气泡，固体逐渐溶解变小，把燃着的木条放在集气瓶口时木条熄灭","配平：左边 1 个钙、1 个碳、3 个氧、2 个氢、2 个氯，右边 CaCl₂ 提供 1 个钙与 2 个氯、H₂O 提供 2 个氢与 1 个氧、CO₂ 提供 1 个碳与 2 个氧，两边原子个数相等。不能用稀硫酸代替稀盐酸（生成微溶的 CaSO₄ 覆盖在大理石表面，阻止反应继续），不能用浓盐酸（挥发出 HCl 使气体不纯），不能用碳酸钠粉末（反应太快不便收集）。"],["CO₂ + H₂O = H₂CO₃","常温（不写条件）","二氧化碳通入紫色石蕊溶液中，溶液由紫色变成红色","使石蕊变红的是碳酸，不是二氧化碳本身：把二氧化碳通到干燥的紫色石蕊纸花上，纸花不会变红。这条方程式用等号，因为反应在常温的水溶液中进行，不需要写条件。"],["H₂CO₃ = H₂O + CO₂↑","加热（常温下也会缓慢分解）","把变红的石蕊溶液加热，红色逐渐变回紫色，同时有气泡冒出","碳酸很不稳定，容易分解。配平：左边 2 个氢、1 个碳、3 个氧，右边 H₂O 有 2 个氢、1 个氧，CO₂ 有 1 个碳、2 个氧，两边相等。生成的气体从溶液中放出，要标 ↑。"],["CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O","常温（不写条件）","把二氧化碳通入澄清石灰水中，石灰水变浑浊","这是检验二氧化碳的方法。配平：左边 1 个碳、1 个钙、4 个氧、2 个氢，右边 CaCO₃ 有 1 个钙、1 个碳、3 个氧，H₂O 有 2 个氢、1 个氧，氧原子合计 4 个，两边相等。CaCO₃ 不溶于水，是沉淀，必须标 ↓。"],["CaCO₃ —高温→ CaO + CO₂↑","高温","石灰石在高温下分解，生成白色的生石灰（氧化钙）和二氧化碳气体","配平：左边 1 个钙、1 个碳、3 个氧，右边 CaO 有 1 个钙、1 个氧，CO₂ 有 1 个碳、2 个氧，两边相等。条件是「高温」，不能写成「加热」；这是工业上制取生石灰和二氧化碳的方法，与实验室制法（常温、盐酸）要区分开。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["实验室制取二氧化碳可以用稀硫酸代替稀盐酸。","不能用稀硫酸：硫酸与碳酸钙反应生成的硫酸钙微溶于水，会覆盖在大理石表面，阻止反应继续进行，气体很快就不再产生。","把「能发生反应」当成了「适合制取气体」。实验室制气体还要考虑反应速率是否平稳、能否持续进行、气体是否纯净，稀硫酸在这三点上都不合适。"],["把燃着的木条伸入集气瓶中，木条熄灭，说明二氧化碳已经收集满了。","验满要把燃着的木条放在集气瓶口（不能伸入瓶内），木条熄灭才说明已收集满；把木条伸入瓶内只能说明瓶内有二氧化碳，不能说明满没满。","「检验」与「验满」的目的不同：检验是判断气体的种类，验满是判断收集的程度。操作位置也就不同——检验用澄清石灰水，验满用燃着的木条放在瓶口。"],["二氧化碳通入紫色石蕊溶液后变红，说明二氧化碳显酸性。","是二氧化碳与水反应生成的碳酸使石蕊变红；把二氧化碳通到干燥的紫色石蕊纸花上，纸花不会变红，说明二氧化碳本身不能使石蕊变色。","把「生成物的性质」当成了「二氧化碳本身的性质」。这也是鉴别题常设的陷阱：只有「二氧化碳 + 水」才会显酸性。"],["实验室用加热碳酸钙的方法制取二氧化碳。","实验室用大理石（碳酸钙）与稀盐酸在常温下反应制取二氧化碳；碳酸钙高温分解是工业上制生石灰与二氧化碳的方法。","实验室制法要常温、平稳、便于控制；高温分解需要的温度高、装置复杂，不适合实验室使用。这也提醒答题时要分清「实验室制法」与「工业制法」。"]]},{"type":"table","title":"检验二氧化碳与验满二氧化碳（目的、操作、现象与结论）","head":["比较项","检验（是不是二氧化碳）","验满（收集满了没有）"],"rows":[["目的","判断瓶内（或气体中）是否含有二氧化碳","判断集气瓶中的二氧化碳是否已经收集满"],["操作方法","把气体通入（或倒入少量）澄清石灰水，振荡","把燃着的木条放在集气瓶口"],["现象","澄清石灰水变浑浊","木条熄灭"],["结论","该气体是（含有）二氧化碳","二氧化碳已收集满"],["易错点","不能用燃着的木条检验（氮气也会使木条熄灭）","木条只能放在瓶口，不能伸入瓶内"]]},{"type":"table","title":"实验室制氧气与制二氧化碳的装置比较（药品状态、反应条件、发生装置、收集装置）","head":["比较项","制取氧气（以过氧化氢为例）","制取二氧化碳"],"rows":[["药品状态","过氧化氢溶液（液体）+ 二氧化锰（固体）","大理石（固体）+ 稀盐酸（液体）"],["反应条件","常温，二氧化锰作催化剂","常温，不需要催化剂"],["发生装置","固液常温型","固液常温型"],["收集装置","可用排水法或向上排空气法","只能用向上排空气法"],["原因","氧气不易溶于水、密度比空气略大","二氧化碳能溶于水且与水反应、密度比空气大"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["实验室制取二氧化碳的药品与装置选择","常考「为什么用大理石和稀盐酸」「为什么不能用稀硫酸、浓盐酸、碳酸钠粉末」，以及装置图判读：长颈漏斗下端是否伸入液面以下、导管是否伸到接近瓶底、集气瓶是否正放。这些细节反过来就是最常见的错误选项。"],["检验与验满的区别","非选择题高频：给出操作让学生判断是检验还是验满，或让学生写出验满的操作与现象。答题必须写清「放瓶口」与「用澄清石灰水」这两个位置和试剂上的差别。"],["二氧化碳性质的实验探究","以石蕊溶液变红、澄清石灰水变浑浊、阶梯蜡烛实验为情境，考现象描述、结论推断与对照实验设计（干燥纸花与湿润纸花的对比），常要求写出相应的化学方程式并配平。"],["二氧化碳的用途与温室效应","以灭火、干冰、碳酸饮料、低碳生活为情境，考「性质决定用途」的对应关系，以及温室效应的成因与减缓措施；判断 CO₂ 是否属于空气污染物是常见设问。"]]},{"type":"quote","text":"【材料一】实验室制取二氧化碳：在锥形瓶中加入大理石，通过长颈漏斗加入稀盐酸，用向上排空气法收集。【材料二】某同学把二氧化碳通入紫色石蕊溶液中，溶液变红；把变红的溶液加热，红色又变回紫色。另把二氧化碳通入澄清石灰水中，石灰水变浑浊。【材料三】实验室需要用碳酸钙与足量稀盐酸反应制取 4.4 g 二氧化碳。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）根据材料一回答：制取二氧化碳时为什么不能用稀硫酸代替稀盐酸？为什么只能用向上排空气法收集？","【设问】（4 分）根据材料三计算：制取 4.4 g 二氧化碳至少需要碳酸钙多少克？同时生成氯化钙多少克？（相对原子质量：C 12、O 16、Ca 40、Cl 35.5）","【设问】（3 分）根据材料二解释：紫色石蕊溶液为什么会变红？加热后红色为什么又变回紫色？分别写出对应的化学方程式。"]}],"questions":[{"id":"chem-substance-6-q1","type":"choice","stem":"如图是实验室制取二氧化碳的装置。下列说法正确的是（　）","answer":"D","explain":"D 正确：稀硫酸与碳酸钙反应生成的硫酸钙微溶于水，会覆盖在大理石表面，阻止反应继续进行。A 错：普通漏斗的管太短、无法伸到液面以下，气体就会从漏斗口逸出，收不到气体。B 与要求不符：长颈漏斗的下端管口必须伸入液面以下形成液封，只伸到橡皮塞以下是常见错误画法。C 把两种收集方法的导管位置弄混了：向上排空气法要把导管伸到接近集气瓶底部，才能把瓶内空气排尽；导管只伸到瓶口是排水法的要求。","options":["长颈漏斗可以用普通漏斗代替，效果相同","长颈漏斗的下端管口只要伸到橡皮塞以下就可以了","集气瓶中的导管只需伸到瓶口，便于气体进入","反应物用大理石和稀盐酸，不能用稀硫酸代替稀盐酸"],"difficulty":2,"tags":["二氧化碳的制取","装置图判读"],"figure":{"id":"fig-chem-substance-6-q1","title":"实验室制取二氧化碳的装置","caption":"判断哪一个说法正确","view":"wide","alt":"锥形瓶内放有大理石和稀盐酸，长颈漏斗插入瓶中，橡皮塞上的导管通向正放的集气瓶并伸到接近瓶底","prims":[{"t":"flask","x":30,"y":40,"kind":"conical","h":24,"w":26,"liquid":0.6,"color":"colorless"},{"t":"funnel","x":30,"y":28,"kind":"long","h":18,"label":"长颈漏斗"},{"t":"rect","x":20,"y":26,"w":20,"h":2.5,"fill":true},{"t":"curve","points":[[36,28],[52,24],[62,25],[68,30],[68,46]]},{"t":"gasJar","x":78,"y":34,"w":22,"h":28,"color":"colorless"},{"t":"text","x":30,"y":60,"text":"大理石 + 稀盐酸","size":3.2,"tone":"muted"},{"t":"text","x":78,"y":60,"text":"集气瓶正放","size":3.2,"tone":"muted"}]}},{"id":"chem-substance-6-q2","type":"choice","stem":"下列关于检验和验满二氧化碳的说法正确的是（　）","answer":"B","explain":"B 正确，把「检验看是不是、验满看满没满」这两件事的操作与现象都对上了。A 错在位置：验满时木条只能放在瓶口，伸入瓶内只能说明瓶内有二氧化碳，不能说明是否收集满。C 把检验的方法当成了验满的方法：石灰水变浑浊只能说明气体是二氧化碳，与「满没满」无关。D 错：带火星的木条用于检验氧气（复燃），二氧化碳不支持燃烧，木条只会熄灭，不能用来确证是二氧化碳。","options":["把燃着的木条伸入集气瓶中，木条熄灭，说明二氧化碳已收集满","检验二氧化碳的方法是通入澄清石灰水，石灰水变浑浊；验满的方法是把燃着的木条放在集气瓶口，木条熄灭","把澄清石灰水倒入集气瓶中，石灰水变浑浊，说明二氧化碳已收集满","用带火星的木条可以检验二氧化碳"],"difficulty":2,"tags":["二氧化碳的制取","检验与验满"]},{"id":"chem-substance-6-q3","type":"choice","stem":"把二氧化碳通入紫色石蕊溶液中，溶液变红。下列说法正确的是（　）","answer":"A","explain":"A 正确：CO₂ 与 H₂O 反应生成碳酸（CO₂ + H₂O = H₂CO₃），碳酸显酸性使石蕊变红。B 与实验事实不符：把二氧化碳通到干燥的紫色石蕊纸花上，纸花不变红，说明二氧化碳本身不能使石蕊变色。C 把变化的方向说反了：碳酸不稳定，加热时分解，红色会逐渐变回紫色。D 判断错误：有新物质碳酸生成，属于化学变化。","options":["使石蕊变红的是二氧化碳与水反应生成的碳酸","二氧化碳本身显酸性，所以能使紫色石蕊变红","把变红的溶液加热，红色会变得更深","这个变化属于物理变化"],"difficulty":1,"tags":["二氧化碳的性质","石蕊溶液"]},{"id":"chem-substance-6-q4","type":"choice","stem":"实验室收集二氧化碳时，下列做法正确的是（　）","answer":"C","explain":"C 正确：CO₂ 密度比空气大，可以用向上排空气法（集气瓶正放）；同时它还能溶于水并与水反应，所以不能用排水法，这正反两方面都说明了只能用向上排空气法。A 有两处错：二氧化碳能溶于水，不是「不易溶于水」；而且若真能排水法收集，它的溶解性也不能成为理由。B 把密度关系说反了：CO₂ 的密度比空气大，用向上排空气法，向下排空气法用于氢气这类密度比空气小的气体。D 与事实不符：二氧化碳能溶于水并与水反应，排水法会把气体消耗掉，根本收集不到。","options":["用排水法收集，因为二氧化碳不易溶于水","用向下排空气法收集，因为二氧化碳的密度比空气小","用向上排空气法收集，因为二氧化碳的密度比空气大且能溶于水","先用排水法收集，再把气体干燥，因为排水法收集的气体更纯"],"difficulty":2,"tags":["二氧化碳的制取","收集方法"]},{"id":"chem-substance-6-q5","type":"choice","stem":"下列关于二氧化碳与温室效应的说法正确的是（　）","answer":"B","explain":"B 正确：化石燃料燃烧产生大量二氧化碳，减少燃烧就能减少排放，从而减缓温室效应。A 有两处错：CO₂ 不是空气污染物；空气质量指数统计的是二氧化硫、二氧化氮、一氧化碳、可吸入颗粒物等，不反映 CO₂ 含量。C 绝对化：适度的温室效应使地球表面的平均温度保持在适宜生命生存的范围，问题在于「增强」带来的全球变暖。D 把成分弄错了：干冰是固态的二氧化碳，它本身就是温室气体，说它与温室效应无关是错的。","options":["二氧化碳是空气污染物，空气质量指数越高说明二氧化碳越多","二氧化碳含量升高会加剧温室效应，减少化石燃料的燃烧有助于减缓温室效应","温室效应只会带来危害，对地球没有任何好处","干冰是固态的水，它用于人工降雨与温室效应没有关系"],"difficulty":2,"tags":["二氧化碳","温室效应"]},{"id":"chem-substance-6-q6","type":"fill","stem":"实验室制取二氧化碳的化学方程式为 CaCO₃ + 2HCl = CaCl₂ + H₂O + ______↑（填化学式）。","answer":"CO₂|CO2","explain":"大理石（碳酸钙）与稀盐酸反应生成氯化钙、水和二氧化碳，所以填 CO₂。检查配平：左边 1 个钙、1 个碳、3 个氧、2 个氢、2 个氯，右边 CaCl₂（1 个钙、2 个氯）+ H₂O（2 个氢、1 个氧）+ CO₂（1 个碳、2 个氧），氧原子合计 3 个，两边相等。填「CO2」也算对，但书写化学式时下标要写在右下角。","difficulty":1,"tags":["二氧化碳的制取","化学方程式"]},{"id":"chem-substance-6-q7","type":"fill","stem":"实验室用 10 g 碳酸钙与足量稀盐酸完全反应，可制得二氧化碳 ______ g。（相对原子质量：C 12、O 16、Ca 40）","answer":"4.4","explain":"由 CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑ 可知，碳酸钙与二氧化碳的质量比为 100∶44，所以 10 g 碳酸钙可制得二氧化碳 10 g × 44/100 = 4.4 g。若把碳酸钙的相对分子质量算成 40 + 12 + 16 = 68（漏乘氧原子的个数 3），结果就会算错。","difficulty":2,"tags":["二氧化碳的制取","化学方程式计算"]},{"id":"chem-substance-6-q8","type":"short","stem":"实验室要制取 11 g 二氧化碳，用大理石（主要成分是碳酸钙）与足量稀盐酸反应，至少需要碳酸钙多少克？若使用的是含碳酸钙 80% 的石灰石，需要石灰石多少克？（相对原子质量：C 12、O 16、Ca 40）","answer":"设需要碳酸钙的质量为 x。由 CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑ 可知 m(CaCO₃)∶m(CO₂) = 100∶44。由 100∶44 = x∶11 g 得 x = 25 g。若用含碳酸钙 80% 的石灰石，需要石灰石的质量 = 25 g ÷ 80% = 31.25 g。答：至少需要碳酸钙 25 g；用含碳酸钙 80% 的石灰石则需要 31.25 g。","explain":"这道题的关键是「纯量才可以代入」：化学方程式里的质量比只适用于参加反应的碳酸钙，所以先用方程式算出纯碳酸钙 25 g，再用纯度换算成石灰石。常见的错误有两种：一是直接把 11 g CO₂ 与石灰石的质量列比例；二是把 25 g 当成石灰石的质量（把纯物质质量与混合物质量混为一谈）。","difficulty":3,"tags":["二氧化碳的制取","化学方程式计算","含杂质计算"],"rubric":["化学方程式书写正确（等号、化学式、气体符号都对）","相对质量 100、44 算对，比例式列对，求出碳酸钙 25 g","用「纯物质质量 ÷ 纯度」换算出石灰石 31.25 g","明确区分「碳酸钙的质量」与「石灰石的质量」两个概念"],"steps":["设未知量：设需要碳酸钙的质量为 x。","写出化学方程式：CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑。","算出相对质量：CaCO₃ = 100，CO₂ = 44，质量比为 100∶44。","列比例式：100∶44 = x∶11 g，解得 x = 25 g。","换算成石灰石：25 g ÷ 80% = 31.25 g，写出带单位的答句。"]},{"id":"chem-substance-6-q9","type":"short","stem":"某同学用大理石和稀硫酸制取二氧化碳，发现刚开始时有气泡产生，但很快就几乎不再产生气体了。请分析可能的原因，并设计实验证明你的解释。","answer":"原因：稀硫酸与大理石反应生成硫酸钙，硫酸钙微溶于水，覆盖在大理石的表面，把大理石与稀硫酸隔开，反应就无法继续进行。验证方法：取反应后的大理石，用水冲洗干净后放入试管中，再加入稀盐酸（或稀硫酸之外的酸），观察到又有大量气泡产生，说明大理石本身并没有被消耗完，只是表面被生成的硫酸钙覆盖了；也可以把表面覆盖的固体刮下少量，检验它的成分（能溶于水很少、与盐酸反应又有气体）。","explain":"这类「反应为什么停下来」的题目，思路是从「反应物有没有用完」和「反应物有没有被隔开」两条去分析。这里大理石并没有用完，问题出在表面覆盖了一层微溶的硫酸钙。验证实验的设计要点是「换一种酸再试」或「检验表面的物质」——换用稀盐酸后气泡又大量产生，就证明大理石还有剩余、反应是被隔开的。","difficulty":3,"tags":["二氧化碳的制取","实验探究","药品选择"],"rubric":["指出原因是「生成微溶的硫酸钙覆盖在大理石表面」","说明后果：大理石与稀硫酸被隔开，反应不能继续","设计验证实验：把反应后的大理石洗净后加入稀盐酸，观察到又有气泡产生","结论与现象对应，并能由此得出「实验室制二氧化碳应该用稀盐酸」"]},{"id":"chem-substance-6-q10","type":"short","stem":"请画出实验室制取并收集二氧化碳的装置图（发生装置与收集装置都要画出），并标注：长颈漏斗下端管口的位置、导管伸入集气瓶的深度、集气瓶的放置方式。","answer":"发生装置：锥形瓶（内放大理石）加双孔橡皮塞，橡皮塞上插一根长颈漏斗和一根导管，长颈漏斗下端管口要伸入液面以下（形成液封）。收集装置：集气瓶正放，导管从橡皮塞伸出后弯向右侧，伸到接近集气瓶底部，瓶口用玻璃片盖住。标注：长颈漏斗下端在液面以下；导管伸到接近瓶底；集气瓶正放（因为二氧化碳的密度比空气大）。","explain":"这道作图题的三个得分点就是装置图判读的三个考点：长颈漏斗下端必须伸入液面以下、导管必须伸到接近瓶底、集气瓶必须正放。另外两个容易画错的地方是导管在橡皮塞内伸得太长（只应略伸出）和忘记画玻璃片。作图时仪器比例要合理，长颈漏斗的末端一定要画到液面以下，不能只画到橡皮塞以下。","difficulty":2,"tags":["二氧化碳的制取","作图题","装置连接"],"rubric":["画出固液常温型发生装置：锥形瓶 + 双孔橡皮塞 + 长颈漏斗 + 导管","长颈漏斗下端明显伸入液面以下，并标注「形成液封，防止气体逸出」","集气瓶正放，导管伸到接近瓶底，并标注「把瓶内空气排尽」","瓶口画出玻璃片，标注「防止空气进入、气体逸出」"],"figure":{"id":"fig-chem-substance-6-q10","title":"待补画的装置图","caption":"请画出发生装置与收集装置，并标注三处关键位置","view":"wide","alt":"画布上只有一组虚线框和文字提示，等待画出锥形瓶、长颈漏斗、橡皮塞、导管以及正放的集气瓶","prims":[{"t":"rect","x":8,"y":18,"w":36,"h":30,"dashed":true,"tone":"muted"},{"t":"rect","x":56,"y":18,"w":36,"h":30,"dashed":true,"tone":"muted"},{"t":"text","x":26,"y":10,"text":"发生装置（固液常温型）","size":3.4,"tone":"accent"},{"t":"text","x":74,"y":10,"text":"收集装置（向上排空气法）","size":3.4,"tone":"accent"},{"t":"text","x":26,"y":56,"text":"（在此处画出锥形瓶、长颈漏斗、导管）","size":3,"tone":"muted"},{"t":"text","x":74,"y":56,"text":"（在此处画出正放的集气瓶与玻璃片）","size":3,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-6-q10-a","title":"参考答案：完整的制取与收集装置","caption":"长颈漏斗下端伸入液面以下，导管伸到接近瓶底，集气瓶正放并盖玻璃片","view":"wide","alt":"锥形瓶内放有大理石和稀盐酸，长颈漏斗下端伸入液面以下，橡皮塞上的导管伸到正放集气瓶的接近瓶底处，瓶口盖着玻璃片","prims":[{"t":"flask","x":30,"y":40,"kind":"conical","h":24,"w":26,"liquid":0.6,"color":"colorless"},{"t":"funnel","x":30,"y":28,"kind":"long","h":18,"label":"长颈漏斗"},{"t":"text","x":12,"y":52,"text":"下端在液面以下","size":3,"tone":"accent"},{"t":"rect","x":20,"y":26,"w":20,"h":2.5,"fill":true},{"t":"curve","points":[[36,28],[52,24],[62,25],[68,30],[68,46]]},{"t":"gasJar","x":78,"y":34,"w":22,"h":28,"color":"colorless","cover":true},{"t":"text","x":78,"y":60,"text":"集气瓶正放、导管接近瓶底、盖玻璃片","size":3,"tone":"accent"},{"t":"text","x":20,"y":61,"text":"大理石 + 稀盐酸","size":3,"tone":"muted"}]}},{"id":"chem-substance-6-m1-q1","type":"short","stem":"（3 分）根据材料一回答：制取二氧化碳时为什么不能用稀硫酸代替稀盐酸？为什么只能用向上排空气法收集？","answer":"不能用稀硫酸：稀硫酸与碳酸钙反应生成的硫酸钙微溶于水，会覆盖在大理石表面，阻止反应继续进行，气体很快就不再产生。只能用向上排空气法：二氧化碳能溶于水并与水反应，所以不能用排水法；它的密度比空气大，所以用向上排空气法，集气瓶正放。","explain":"","rubric":["答出硫酸钙微溶、覆盖在大理石表面、阻止反应继续","答出「二氧化碳能溶于水并与水反应，不能用排水法」","答出「密度比空气大，用向上排空气法收集，集气瓶正放」"]},{"id":"chem-substance-6-m1-q2","type":"short","stem":"（4 分）根据材料三计算：制取 4.4 g 二氧化碳至少需要碳酸钙多少克？同时生成氯化钙多少克？（相对原子质量：C 12、O 16、Ca 40、Cl 35.5）","answer":"设需要碳酸钙的质量为 x，生成氯化钙的质量为 y。由 CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑ 可知 m(CaCO₃)∶m(CaCl₂)∶m(CO₂) = 100∶111∶44。由 100∶44 = x∶4.4 g 得 x = 10 g；由 44∶111 = 4.4 g∶y 得 y = 11.1 g。答：至少需要碳酸钙 10 g，同时生成氯化钙 11.1 g。","explain":"","rubric":["写出正确的化学方程式 CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑","算出相对质量 100、111、44（CaCl₂ = 40 + 35.5×2 = 111）","求出碳酸钙的质量为 10 g","求出氯化钙的质量为 11.1 g，并写出带单位的答句"]},{"id":"chem-substance-6-m1-q3","type":"short","stem":"（3 分）根据材料二解释：紫色石蕊溶液为什么会变红？加热后红色为什么又变回紫色？分别写出对应的化学方程式。","answer":"二氧化碳通入水中后与水反应生成碳酸，碳酸显酸性，使紫色石蕊溶液变红，化学方程式为 CO₂ + H₂O = H₂CO₃。加热时碳酸不稳定、发生分解，生成水和二氧化碳，溶液中不再有碳酸，所以红色又变回紫色，化学方程式为 H₂CO₃ = H₂O + CO₂↑。","explain":"","rubric":["答出「二氧化碳与水反应生成碳酸，碳酸使石蕊变红」","写出 CO₂ + H₂O = H₂CO₃ 并正确书写化学式","答出「碳酸不稳定，受热分解」并写出 H₂CO₃ = H₂O + CO₂↑（条件写「加热」，标 ↑）"]}]},{"id":"chem-substance-7","title":"金属与金属材料：物理性质与用途·金属与氧气酸盐溶液的反应·金属活动性顺序与置换反应","subtitle":"人教版九年级 · 第八单元 金属和金属材料 · 9b","grade":"9b","tags":["人教版九年级 · 第八单元 金属和金属材料"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第八单元 金属和金属材料 · 9b"},{"type":"note","title":"问题切入","text":"为什么用铜做导线、用铁做锅、把铝压成薄薄的铝箔？为什么铁钉放进硫酸铜溶液里能「长出」红色的铜，而铜丝放进硫酸亚铁溶液里却毫无变化？金属活动性顺序表到底该怎么用？"},{"type":"note","title":"一句话抓住关键","text":"金属有共同的物理性质——有金属光泽、能导电导热、有延展性，所以能做导线、炊具和箔材；但不同金属的活泼程度差别很大，这就是金属活动性顺序：K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au。排在氢前面的金属能与稀盐酸、稀硫酸反应放出氢气；排在前面的金属能把排在后面的金属从它们的盐溶液中置换出来。由一种单质与一种化合物反应生成另一种单质和另一种化合物的反应叫置换反应。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"铜能做导线，铁能做锅，铝能压成薄薄的铝箔。金属的用途不是随便定的，而是由它的性质决定的：导电、导热、延展性、硬度，各取所长。","walk":["金属的共性：有光泽、能导电导热、有延展性，常温下多为固体（汞除外）。","金属的化学性质：能与非金属（如氧气）反应，能与酸反应放出氢气，能与盐溶液反应（前换后）。","金属活动性顺序由强到弱：钾、钙、钠、镁、铝、锌、铁、锡、铅、（氢）、铜、汞、银、铂、金。排在氢前的金属能与稀酸反应；排在前面的金属能把后面的金属从它的盐溶液中置换出来（钾钙钠除外）。"],"try":"用砂纸打磨一段铝箔或一枚铁钉，露出银白色的金属光泽；放几天后再看，表面又会变暗，说明金属与空气中的氧气反应。","use":["判断金属能否与盐溶液反应，只记一句话「前换后」；看到钾、钙、钠要立刻排除，它们太活泼，会先与水反应。","置换反应的特征是「单质 + 化合物 → 单质 + 化合物」，一定有一种单质做反应物。"]},{"type":"h","text":"【宏观】宏观：金属的共性与个性"},{"type":"p","text":"先看共性：金属都有金属光泽，都能导电、导热，都有延展性（能拉成丝、压成片），所以铜、铝用来做导线，铁、铝用来做炊具，铝能压成铝箔包食品。再看个性：大多数金属常温下是固体，但汞（水银）是液体；大多数金属是银白色的，但铜是紫红色、金是黄色；不同的金属密度、硬度、熔点差别也很大——钨的熔点最高，可做灯丝；金、银的延展性最好。使用金属时就是「按性能选用途」：导电性最好的是银，但银太贵，所以导线用铜和铝。"},{"type":"figure","figure":{"id":"fig-chem-substance-7-1","title":"几种金属的颜色与状态","caption":"金属的共性：有金属光泽、能导电导热、有延展性","view":"wide","alt":"四个圆形分别表示铜、铁、金、汞四种金属，标注它们各自的颜色与状态，下方说明金属的共性","prims":[{"t":"circle","cx":14,"cy":22,"r":6,"fill":true,"tone":"danger"},{"t":"circle","cx":38,"cy":22,"r":6,"fill":true,"tone":"main"},{"t":"circle","cx":62,"cy":22,"r":6,"fill":true,"tone":"accent"},{"t":"circle","cx":86,"cy":22,"r":6,"fill":true,"tone":"muted"},{"t":"text","x":14,"y":36,"text":"铜：紫红色","size":3.2},{"t":"text","x":38,"y":36,"text":"铁：银白色","size":3.2},{"t":"text","x":62,"y":36,"text":"金：黄色","size":3.2},{"t":"text","x":86,"y":36,"text":"汞：常温液态","size":3.2},{"t":"text","x":50,"y":50,"text":"金属的共性：有金属光泽、能导电导热、有延展性","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"用途由性能决定：导线用铜铝、灯丝用钨、铝箔包装食品","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"答题时要把「性质」和「用途」配成对：铜、铝导电性好 → 做导线；铝的延展性好 → 压成铝箔；钨的熔点高 → 做灯丝；银的导电性最好却不用来做导线，是因为价格昂贵。"},{"type":"h","text":"【宏观】宏观实验：金属与氧气、稀盐酸、盐溶液的反应"},{"type":"p","text":"把镁、锌、铁、铜分别放入等质量、等浓度的稀盐酸中，现象差别很明显：镁剧烈反应、气泡冒得最快；锌反应较快、气泡较多；铁反应较慢、气泡较少，溶液逐渐变成浅绿色；铜表面没有任何变化。这说明四种金属的活泼程度是镁 > 锌 > 铁 > 铜，而铜排在氢的后面，不能置换出酸中的氢。金属与氧气的反应也不一样：镁、铝在常温下就能与氧气反应（铝表面生成致密的氧化铝薄膜，反而保护了内部的铝），铁只能在点燃时在氧气中燃烧，铜要加热才生成黑色的氧化铜，金则「真金不怕火炼」。"},{"type":"figure","figure":{"id":"fig-chem-substance-7-2","title":"四种金属分别与稀盐酸反应","caption":"气泡越快说明金属越活泼：镁 > 锌 > 铁 > 铜（铜不与稀盐酸反应）","view":"wide","alt":"四支试管中分别盛有等量的稀盐酸并放入镁、锌、铁、铜，镁与锌中气泡最多、铁中气泡较少且溶液呈浅绿色，铜表面没有明显变化","prims":[{"t":"testTube","x":16,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":36,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":56,"y":28,"h":30,"w":12,"liquid":0.5,"color":"green"},{"t":"testTube","x":76,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"text","x":16,"y":10,"text":"镁","size":3.6},{"t":"text","x":36,"y":10,"text":"锌","size":3.6},{"t":"text","x":56,"y":10,"text":"铁","size":3.6},{"t":"text","x":76,"y":10,"text":"铜","size":3.6},{"t":"text","x":16,"y":50,"text":"剧烈","size":3.2,"tone":"accent"},{"t":"text","x":36,"y":50,"text":"较快","size":3.2,"tone":"accent"},{"t":"text","x":56,"y":50,"text":"较慢，溶液变浅绿","size":3.2,"tone":"accent"},{"t":"text","x":76,"y":50,"text":"无明显变化","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"相同条件下产生气泡越快，金属越活泼","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"现象描述要抓住「快慢 + 颜色」：铁与稀盐酸反应时溶液由无色变成浅绿色，这个浅绿色来自亚铁离子 Fe²⁺，不是铁离子。铜与稀盐酸不反应，所以没有气泡，这也是判断「铜排在氢后」的实验依据。"},{"type":"h","text":"【微观】微观：置换反应中谁失电子、谁得电子"},{"type":"p","text":"把铁钉放进硫酸铜溶液，从粒子角度看发生了两件事：铁原子失去 2 个电子变成亚铁离子 Fe²⁺ 进入溶液，溶液中的铜离子 Cu²⁺ 得到 2 个电子变成铜原子，附着在铁钉表面。所以铁钉表面覆盖一层红色的铜，溶液由蓝色（来自 Cu²⁺）逐渐变成浅绿色（来自 Fe²⁺）。这个反应的实质是「活泼金属把较不活泼金属的离子还原成原子」，也就是电子从活泼金属转移给了不活泼金属的离子。"},{"type":"figure","figure":{"id":"fig-chem-substance-7-3","title":"铁与硫酸铜溶液反应的微观实质","caption":"铁原子失去电子变成 Fe²⁺ 进入溶液，Cu²⁺ 得到电子变成铜原子析出","view":"wide","alt":"铁原子与溶液中的铜离子反应，铁原子失去电子变成亚铁离子进入溶液，铜离子得到电子变成铜原子附着在铁钉表面，溶液由蓝色变成浅绿色","prims":[{"t":"atom","x":14,"y":16,"r":4.6,"symbol":"Fe","color":"white","label":"铁原子"},{"t":"atom","x":12,"y":40,"r":4.2,"symbol":"Cu","charge":"2+","color":"blue"},{"t":"atom","x":24,"y":40,"r":4.2,"symbol":"Cu","charge":"2+","color":"blue"},{"t":"text","x":18,"y":52,"text":"溶液中的 Cu²⁺（蓝色）","size":3.2,"tone":"muted"},{"t":"arrow","x1":36,"y1":28,"x2":48,"y2":28,"label":"放入铁钉","labelDy":-4},{"t":"atom","x":62,"y":16,"r":4.6,"symbol":"Fe","charge":"2+","color":"green","label":"Fe²⁺ 进入溶液（浅绿色）"},{"t":"atom","x":62,"y":42,"r":4.2,"symbol":"Cu","color":"red"},{"t":"atom","x":74,"y":42,"r":4.2,"symbol":"Cu","color":"red"},{"t":"text","x":68,"y":54,"text":"铜原子析出（红色）","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":61,"text":"电子从铁原子转移给铜离子：Fe + Cu²⁺ → Fe²⁺ + Cu","size":3.2,"tone":"accent"}]}},{"type":"note","title":"","text":"初中不要求写离子方程式，但说理题里用「铁原子失去电子、铜离子得到电子」来解释「为什么铁能置换铜、铜不能置换铁」很有说服力：活泼的金属原子更容易失去电子。"},{"type":"h","text":"【符号】符号：方程式与金属活动性顺序表"},{"type":"p","text":"这一单元要写的方程式分三类：与氧气反应——3Fe + 2O₂ —点燃→ Fe₃O₄、4Al + 3O₂ = 2Al₂O₃（常温）、2Cu + O₂ —加热→ 2CuO；与稀盐酸（或稀硫酸）反应——Zn + H₂SO₄ = ZnSO₄ + H₂↑、Fe + 2HCl = FeCl₂ + H₂↑、2Al + 6HCl = 2AlCl₃ + 3H₂↑；与盐溶液反应——Fe + CuSO₄ = FeSO₄ + Cu、Cu + 2AgNO₃ = Cu(NO₃)₂ + 2Ag。把这些反应和金属活动性顺序表对照就一目了然：只有排在氢前面的金属才能与稀盐酸、稀硫酸反应，只有排在前面的金属才能把后面的金属从它的盐溶液中置换出来。"},{"type":"figure","figure":{"id":"fig-chem-substance-7-4","title":"金属活动性顺序表","caption":"从左到右金属活动性逐渐减弱，氢前面的金属能与稀盐酸、稀硫酸反应","view":"wide","alt":"金属活动性顺序表按 K Ca Na Mg Al Zn Fe Sn Pb 氢 Cu Hg Ag Pt Au 排列，并标注氢前金属能与稀盐酸反应、前面的金属能把后面的金属从盐溶液中置换出来","prims":[{"t":"text","x":40,"y":14,"text":"K  Ca  Na  Mg  Al  Zn","size":4},{"t":"text","x":40,"y":23,"text":"Fe  Sn  Pb  (H)  Cu  Hg","size":4},{"t":"text","x":40,"y":32,"text":"Ag  Pt  Au","size":4},{"t":"arrow","x1":8,"y1":41,"x2":88,"y2":41,"tone":"accent","label":"金属活动性逐渐减弱"},{"t":"text","x":50,"y":50,"text":"氢前的金属能与稀盐酸、稀硫酸反应放出氢气","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":57,"text":"前面的金属能把后面的金属从它们的盐溶液中置换出来","size":3.4,"tone":"muted"}]}},{"type":"note","title":"","text":"三处易错：① 氢不是金属，但它在顺序表中有位置，用来分界「能与酸反应」和「不能与酸反应」；② 钾、钙、钠太活泼，投入盐溶液中会先与水反应，不能置换出盐中的金属；③ 铁与酸、与盐溶液反应生成的都是亚铁（FeCl₂、FeSO₄），化学式不能写成 FeCl₃、Fe₂(SO₄)₃。"},{"type":"h","text":"【应用】应用：从纯金属到合金"},{"type":"p","text":"生产上很少使用纯金属，大量使用的是合金。合金是在金属中加入其他金属或非金属熔合而成的、具有金属特性的材料。与组成它的纯金属相比，合金的硬度一般更大、熔点一般更低、抗腐蚀性能更好，所以用途更广：生铁和钢都是铁碳合金，生铁的含碳量为 2%—4.3%，钢为 0.03%—2%，所以生铁硬而脆、钢的韧性和可塑性更好，钢的用途比生铁广泛；铝合金质轻而坚硬，用于飞机、门窗；钛合金耐腐蚀、与人体相容性好，用于人造骨和航空航天。"},{"type":"note","title":"","text":"常见的判断：合金一定是混合物（至少含两种物质）；「合金的熔点比成分金属低、硬度比成分金属大」这两句话要背准，中考常把两者反过来设成错误选项。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["相对分子质量（金属化合物）","ZnSO₄ 的相对分子质量 = 65 + 32 + 16×4 = 161；FeSO₄ 的相对分子质量 = 56 + 32 + 16×4 = 152","用于金属与酸、金属与盐溶液反应的计算。注意 FeSO₄ 与 Fe₂(SO₄)₃ 的区别：铁与稀硫酸、硫酸铜溶液反应生成的都是 FeSO₄（相对分子质量 152），不是 Fe₂(SO₄)₃。相对原子质量取整数：Fe 56、Zn 65、Cu 64、Ag 108。"],["化学方程式计算中的质量比（以锌与稀硫酸为例）","Zn + H₂SO₄ = ZnSO₄ + H₂↑，m(Zn)∶m(ZnSO₄)∶m(H₂) = 65∶161∶2","化学方程式计算的依据。只有参加反应的纯金属质量才能代入比例式；若金属样品含杂质（如含杂质的锌粒），要先按纯度算出纯金属的质量。计算时还要注意题目给的是「足量酸」还是「一定量酸」——酸不足时要用酸的质量来计算。"],["金属活动性顺序的用法","K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au（活动性由强逐渐减弱）","三条用法：① 排在氢前面的金属能与稀盐酸、稀硫酸反应放出氢气，氢后面的不能；② 排在前面的金属能把排在后面的金属从它们的盐溶液中置换出来；③ 钾、钙、钠太活泼，投入盐溶液中会先与水反应生成碱和氢气，不能置换出盐溶液中的金属。铁与酸、盐溶液反应都生成亚铁化合物。"]]},{"type":"h","text":"应用 · 金属活动性顺序的应用"},{"type":"note","title":"情境","text":"在硫酸铜溶液中加入一定量的铁粉，充分反应后过滤，得到滤渣和滤液。怎样判断铁粉是否过量？如果向滤渣中加入稀盐酸有气泡产生，说明什么？"},{"type":"list","title":"解答步骤","items":["写出反应的化学方程式 Fe + CuSO₄ = FeSO₄ + Cu，明确「铁能把铜置换出来」。","分析滤渣的成分：铜一定有（置换出来的），铁可能有（铁粉过量时剩余）。","向滤渣中加稀盐酸：有气泡 → 滤渣中有铁 → 铁粉过量；无气泡 → 滤渣中只有铜 → 铁粉不足或恰好反应。","同样可以分析滤液：铁粉过量时滤液中只有 FeSO₄（浅绿色）；铁粉不足时滤液中还有剩余的 CuSO₄（蓝色）。"]},{"type":"note","title":"结论","text":"判断「谁过量」的两条线索：滤渣中加稀盐酸有无气泡；滤液的颜色是浅绿色（只有 FeSO₄）还是蓝色（还有 CuSO₄）。答题时必须把现象与结论一一对应地写出来。"},{"type":"h","text":"应用 · 锌与稀硫酸反应的计算"},{"type":"note","title":"情境","text":"实验室用 13 g 锌粒与足量稀硫酸完全反应制取氢气。求可制得氢气的质量和硫酸锌的质量。（相对原子质量：Zn 65、S 32、O 16、H 1）"},{"type":"list","title":"解答步骤","items":["写出化学方程式：Zn + H₂SO₄ = ZnSO₄ + H₂↑。","算出相对质量：Zn = 65，ZnSO₄ = 65 + 32 + 16×4 = 161，H₂ = 1×2 = 2。","设生成氢气的质量为 x：65∶2 = 13 g∶x，解得 x = 0.4 g。","设生成硫酸锌的质量为 y：65∶161 = 13 g∶y，解得 y = 32.2 g。","答：可制得氢气 0.4 g，硫酸锌 32.2 g。"]},{"type":"note","title":"结论","text":"可制得氢气 0.4 g、硫酸锌 32.2 g。注意 H₂ 的相对分子质量按 2 算（不能按 1），并且只有参加反应的纯锌质量才能代入比例式。"},{"type":"h","text":"实验 1 · 探究金属的活动性顺序"},{"type":"note","title":"实验目的","text":"通过比较几种金属与稀盐酸反应的剧烈程度，排出它们的活动性顺序。"},{"type":"list","title":"实验器材","items":["试管（四支）、试管架","镁条、锌粒、铁钉、铜片","稀盐酸（等质量、等浓度）","砂纸、镊子"]},{"type":"figure","figure":{"id":"fig-chem-substance-7-exp1","title":"金属与稀盐酸反应的对比实验","caption":"条件相同（酸的量与浓度相同、金属形状相近），只改变金属的种类","view":"wide","alt":"四支试管中盛有等量的稀盐酸，分别放入镁、锌、铁、铜，镁与锌中产生大量气泡、铁中气泡较少且溶液呈浅绿色、铜表面无变化","prims":[{"t":"testTube","x":16,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":36,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":56,"y":28,"h":30,"w":12,"liquid":0.5,"color":"green"},{"t":"testTube","x":76,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"text","x":16,"y":10,"text":"镁条","size":3.6},{"t":"text","x":36,"y":10,"text":"锌粒","size":3.6},{"t":"text","x":56,"y":10,"text":"铁钉","size":3.6},{"t":"text","x":76,"y":10,"text":"铜片","size":3.6},{"t":"text","x":16,"y":50,"text":"剧烈反应","size":3.2,"tone":"accent"},{"t":"text","x":36,"y":50,"text":"反应较快","size":3.2,"tone":"accent"},{"t":"text","x":56,"y":50,"text":"反应较慢","size":3.2,"tone":"accent"},{"t":"text","x":76,"y":50,"text":"不反应","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"活动性顺序：Mg > Zn > Fe > (H) > Cu","size":3.4,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["用砂纸打磨镁条、锌粒、铁钉、铜片的表面，除去表面的氧化膜（尤其是铝、镁表面的氧化膜和铁锈）。","取四支试管，分别加入等质量、等浓度的稀盐酸。","把四种金属分别放入四支试管中，观察并比较产生气泡的快慢、溶液颜色的变化。","记录现象，按反应由剧烈到不反应排出四种金属的活动性顺序。"]},{"type":"note","title":"实验现象","text":"镁与稀盐酸反应最剧烈、气泡最多，镁条很快溶解；锌反应较快、气泡较多；铁反应较慢、气泡较少，溶液逐渐变成浅绿色；铜表面没有明显变化，没有气泡产生。"},{"type":"note","title":"实验结论","text":"四种金属的活动性顺序为 Mg > Zn > Fe > Cu；其中镁、锌、铁排在氢的前面，能与稀盐酸反应放出氢气，铜排在氢的后面，不能与稀盐酸反应。反应的化学方程式如 Mg + 2HCl = MgCl₂ + H₂↑、Zn + 2HCl = ZnCl₂ + H₂↑、Fe + 2HCl = FeCl₂ + H₂↑。"},{"type":"list","title":"注意事项","items":["金属表面必须用砂纸打磨：除去氧化膜（铝、镁）和铁锈，否则反应会因为表面覆盖物而变慢，现象不可靠。","必须控制变量：四支试管中稀盐酸的浓度和体积要相同，金属的形状与大小要相近，只有金属的种类不同。","取用金属要用镊子，不能用手直接拿；稀盐酸有腐蚀性，量取时不要溅到皮肤和衣服上。","观察气泡快慢时不要凑近试管口，更不能把鼻孔对着试管口闻气味；反应放热，不要用手紧握试管。","实验结束后把废液倒入指定容器，不能直接倒入下水道；金属固体要回收，不能随意丢弃。"]},{"type":"h","text":"实验 2 · 铁钉与硫酸铜溶液的反应"},{"type":"note","title":"实验目的","text":"通过铁置换出硫酸铜溶液中的铜，认识金属活动性顺序和置换反应。"},{"type":"list","title":"实验器材","items":["试管（或烧杯）","铁钉（用砂纸打磨过）","硫酸铜溶液","镊子、砂纸"]},{"type":"figure","figure":{"id":"fig-chem-substance-7-exp2","title":"铁钉与硫酸铜溶液的反应","caption":"铁钉表面覆盖一层红色的铜，溶液由蓝色变成浅绿色","view":"wide","alt":"两支试管对比：反应前蓝色硫酸铜溶液中插着银白色的铁钉，反应后铁钉表面覆盖红色的铜、溶液变成浅绿色","prims":[{"t":"testTube","x":28,"y":28,"h":32,"w":14,"liquid":0.55,"color":"blue"},{"t":"line","x1":28,"y1":20,"x2":28,"y2":40,"width":1.6},{"t":"text","x":28,"y":12,"text":"反应前：铁钉银白色","size":3.2},{"t":"text","x":28,"y":52,"text":"溶液蓝色","size":3.2,"tone":"muted"},{"t":"arrow","x1":42,"y1":28,"x2":56,"y2":28,"label":"放置一段时间","labelDy":-4},{"t":"testTube","x":76,"y":28,"h":32,"w":14,"liquid":0.55,"color":"green"},{"t":"line","x1":76,"y1":20,"x2":76,"y2":40,"width":1.6,"tone":"danger"},{"t":"text","x":76,"y":12,"text":"反应后：铁钉表面覆盖红色的铜","size":3.2},{"t":"text","x":76,"y":52,"text":"溶液浅绿色","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":61,"text":"Fe + CuSO₄ = FeSO₄ + Cu（湿法炼铜的原理）","size":3.2,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["用砂纸把铁钉表面打磨光亮，除去铁锈和油污。","在试管中加入约三分之一体积的硫酸铜溶液，观察它的颜色。","把铁钉浸入硫酸铜溶液中，静置观察一段时间。","观察铁钉表面和溶液颜色的变化，取出铁钉，写出反应的化学方程式。"]},{"type":"note","title":"实验现象","text":"铁钉表面逐渐覆盖一层红色的物质（铜），溶液由蓝色逐渐变成浅绿色。"},{"type":"note","title":"实验结论","text":"铁的活动性比铜强，能把铜从硫酸铜溶液中置换出来，化学方程式为 Fe + CuSO₄ = FeSO₄ + Cu。溶液由蓝色变浅绿色是因为 Cu²⁺ 减少、Fe²⁺ 增多。"},{"type":"list","title":"注意事项","items":["铁钉必须先用砂纸打磨：铁锈会阻碍铁与硫酸铜溶液接触，导致现象不明显甚至观察不到。","硫酸铜溶液不宜太浓、铁钉不宜太细：溶液太浓会使置换出的铜呈粉末状、不易观察；铁钉太细反应后不易取出。","实验要在通风处进行，取用硫酸铜溶液时避免溅到皮肤和衣物上，实验后要洗手。","观察现象要耐心：颜色变化需要一段时间，不能刚放入就下结论；取出铁钉后要用水洗净再观察，防止残留溶液影响判断。","反应后的溶液含有铜离子等，要倒入指定容器回收处理，不能直接倒入下水道。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["3Fe + 2O₂ —点燃→ Fe₃O₄","点燃","铁丝在氧气中剧烈燃烧，火星四射，放出大量热，生成黑色固体","配平：左边 3 个铁、4 个氧，与 Fe₃O₄ 中的 3 个铁、4 个氧相等。铁在氧气中点燃才生成 Fe₃O₄；铁在潮湿空气中生锈是缓慢氧化，产物主要是 Fe₂O₃ 的水合物（铁锈），两者不是一回事。"],["4Al + 3O₂ = 2Al₂O₃","常温（铝在空气中自然氧化）","铝的表面逐渐形成一层致密的氧化铝薄膜，看不到明显的剧烈反应","配平：左边 4 个铝、6 个氧，右边 2Al₂O₃ 也是 4 个铝、6 个氧。这层致密的氧化铝薄膜能阻止内部的铝继续被氧化，所以铝制品比较耐腐蚀；但铝的活泼性其实比铁强，不能用「铝不容易被氧化」来解释。"],["2Cu + O₂ —加热→ 2CuO","加热","红色的铜表面逐渐变成黑色","配平：左边 2 个铜、2 个氧，右边 2CuO 也是 2 个铜、2 个氧。条件写「加热」，不能写「点燃」（铜不能在空气中点燃）。CuO 中的铜为 +2 价，化学式不能写成 Cu₂O 或 CuO₂。"],["Zn + H₂SO₄ = ZnSO₄ + H₂↑","常温（在溶液中反应，不写条件）","锌粒表面产生大量气泡，锌粒逐渐溶解变小，试管外壁微微发热","配平：左边 1 个锌、1 个硫、4 个氧、2 个氢，右边 ZnSO₄ 有 1 个锌、1 个硫、4 个氧，H₂ 有 2 个氢，两边相等。这是置换反应，也是实验室制取氢气的常用反应（常用锌粒与稀硫酸）。"],["Fe + 2HCl = FeCl₂ + H₂↑","常温（在溶液中反应，不写条件）","铁的表面产生气泡，铁逐渐溶解，溶液由无色变成浅绿色","配平：左边 1 个铁、2 个氢、2 个氯，右边 FeCl₂ 有 1 个铁、2 个氯，H₂ 有 2 个氢。最易错的是产物写成 FeCl₃：铁与稀盐酸、稀硫酸反应生成的都是亚铁化合物（FeCl₂、FeSO₄），溶液呈浅绿色而不是黄色。"],["2Al + 6HCl = 2AlCl₃ + 3H₂↑","常温（在溶液中反应，不写条件）","铝表面产生大量气泡（去掉氧化膜后反应很剧烈），铝逐渐溶解","配平：左边 2 个铝、6 个氢、6 个氯，右边 2AlCl₃ 有 2 个铝、6 个氯，3H₂ 有 6 个氢。铝在空气中表面有氧化铝薄膜，实验前要用砂纸打磨或用稀盐酸浸泡除去，否则反应会明显变慢。"],["Fe + CuSO₄ = FeSO₄ + Cu","常温（在溶液中反应，不写条件）","铁钉表面覆盖一层红色的物质，溶液由蓝色逐渐变成浅绿色","配平：左边 1 个铁、1 个铜、1 个硫、4 个氧，右边 1 个铁、1 个硫、4 个氧、1 个铜，系数均为 1。这就是古代的「湿法炼铜」，说明铁的活动性比铜强；产物是 FeSO₄（浅绿色）而不是 Fe₂(SO₄)₃。"],["Cu + 2AgNO₃ = Cu(NO₃)₂ + 2Ag","常温（在溶液中反应，不写条件）","铜丝表面覆盖一层银白色的物质，溶液由无色逐渐变成蓝色","配平：左边 1 个铜、2 个银、2 个氮、6 个氧，右边 Cu(NO₃)₂ 有 1 个铜、2 个氮、6 个氧，2Ag 有 2 个银。硝酸银溶液中的银离子被置换出来，说明铜的活动性比银强；溶液变蓝是因为生成了蓝色的 Cu²⁺。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["铁与稀盐酸反应生成氯化铁 FeCl₃，溶液呈黄色。","铁与稀盐酸反应生成氯化亚铁 FeCl₂，溶液呈浅绿色（Fe + 2HCl = FeCl₂ + H₂↑）。","铁有两种化合价：与酸、与盐溶液发生置换反应时生成 +2 价的亚铁化合物，溶液是浅绿色；+3 价的铁离子溶液才是黄色。化学式写错，方程式与计算就全错了。"],["铜也能与稀盐酸反应放出氢气，只是反应比较慢。","铜排在氢的后面，不能与稀盐酸、稀硫酸反应，无论放多久都不会有气泡产生。","把「活动性较弱」当成了「反应较慢」。金属活动性顺序表里氢的位置就是分界线：氢前面的金属能与稀酸反应，氢后面的（Cu、Hg、Ag、Pt、Au）都不能，它们也不与稀硫酸反应。"],["合金的熔点比组成它的纯金属高、硬度比组成它的纯金属小。","合金的硬度一般比组成它的纯金属大，熔点一般比组成它的纯金属低，抗腐蚀性能也更好。","这两句话最容易记反。可以这样记：合金「更硬、更耐腐蚀、更容易熔化（熔点低）」，所以焊锡（锡铅合金）熔点低可用于焊接，生铁比纯铁硬可用于制造机械。"],["钠比铜活泼，所以把钠放入硫酸铜溶液中能把铜置换出来。","钠太活泼，放入硫酸铜溶液中会先与水反应生成氢氧化钠和氢气，不能把铜置换出来。","金属活动性顺序中钾、钙、钠过于活泼，在盐溶液中会先与水反应，所以它们不用于置换盐溶液中的金属。置换盐溶液中的金属，通常用锌、铁、铜这类金属。"]]},{"type":"table","title":"生铁与钢（含碳量与性能、用途）","head":["比较项","生铁","钢"],"rows":[["含碳量","2%—4.3%","0.03%—2%"],["性能","硬而脆，可铸不可锻","有良好的韧性和可塑性，可锻可压延"],["主要用途","制造机床的底座、铁锅、暖气片等","制造机械、建筑钢筋、刀具、钢轨等"],["共同点","都是铁碳合金，属于混合物","都是铁碳合金，属于混合物"]]},{"type":"table","title":"氢前金属与氢后金属（在金属活动性顺序表中的位置与相应的化学性质）","head":["比较项","氢前金属（K…Pb）","氢后金属（Cu、Hg、Ag、Pt、Au）"],"rows":[["与稀盐酸、稀硫酸","能反应放出氢气（如 Zn + H₂SO₄ = ZnSO₄ + H₂↑）","不能反应，没有气泡产生"],["与氧气的反应","常温或点燃、加热时能与氧气反应，铝表面形成氧化膜","很不活泼，「真金不怕火炼」，铜需加热才生成 CuO"],["与盐溶液","能把排在它后面的金属从其盐溶液中置换出来","只能被比它活泼的金属置换出来，不能置换更不活泼的金属"],["典型例子","铁钉放入硫酸铜溶液：Fe + CuSO₄ = FeSO₄ + Cu","铜丝放入硝酸银溶液：Cu + 2AgNO₃ = Cu(NO₃)₂ + 2Ag"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["金属活动性顺序的应用","中考必考：判断某反应能否发生、由实验现象排出活动性顺序、分析「把金属加入混合盐溶液中」的滤渣与滤液成分。答题要抓住「谁在前面谁能置换」和「谁过量谁剩余」两条线索。"],["金属的物理性质与用途、合金","考「性质决定用途」的配对（导线、炊具、灯丝、铝箔），以及合金的性质（硬度大、熔点低、抗腐蚀）与生铁、钢的含碳量比较；常把「合金熔点高、硬度小」设成错误选项。"],["化学方程式书写与计算","要求书写金属与氧气、酸、盐溶液反应的方程式并配平，注意铁生成亚铁（FeCl₂、FeSO₄）；计算题常以金属与酸反应制氢气为情境，数据要按纯净物质量代入。"],["置换反应的判断","给出若干反应让学生判断是否属于置换反应（一种单质 + 一种化合物 → 另一种单质 + 另一种化合物），常与化合、分解反应混在一起考查，判断依据只看反应物与生成物的种类。"]]},{"type":"quote","text":"【材料一】金属活动性顺序：K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au。【材料二】某小组的探究记录：取四支试管，各加入等质量、等浓度的稀盐酸，分别放入用砂纸打磨过的镁条、锌粒、铁钉、铜片。镁反应最剧烈、锌较快、铁较慢且溶液逐渐变成浅绿色、铜表面无明显变化。【材料三】实验室用 13 g 锌粒与足量稀硫酸反应制取氢气。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）根据材料二排出镁、锌、铁、铜四种金属的活动性顺序，并说明铜不能与稀盐酸反应的原因。","【设问】（4 分）根据材料一判断下列反应能否发生：① 把铁钉放入硫酸铜溶液中；② 把铜丝放入硫酸亚铁溶液中；③ 把银丝放入稀盐酸中。能发生的写出化学方程式，不能发生的说明理由。","【设问】（4 分）根据材料三计算：13 g 锌与足量稀硫酸完全反应，可制得氢气多少克？同时生成硫酸锌多少克？（相对原子质量：Zn 65、S 32、O 16、H 1）"]}],"questions":[{"id":"chem-substance-7-q1","type":"choice","stem":"如图是四种金属分别与等质量、等浓度的稀盐酸反应的实验。下列说法正确的是（　）","answer":"C","explain":"C 正确：气泡越快说明反应越剧烈、金属越活泼；铜不与稀盐酸反应，正说明它排在氢的后面。A 与实验事实不符：铜表面没有气泡，铜的活动性比铁弱。B 错：四种金属与稀盐酸反应的剧烈程度差别很大，这正说明它们的活动性不同。D 有两处错：铁与稀盐酸反应生成的是氯化亚铁 FeCl₂，溶液呈浅绿色，而不是黄色的 FeCl₃。","options":["铜片表面产生大量气泡，说明铜比铁活泼","四种金属产生气泡的快慢相同，说明它们的活动性相同","产生气泡最快的是镁，说明镁的活动性比锌、铁强；铜片表面无气泡，说明铜排在氢的后面","铁钉与稀盐酸反应生成氯化铁，溶液变成黄色"],"difficulty":2,"tags":["金属活动性顺序","金属与酸反应"],"figure":{"id":"fig-chem-substance-7-q1","title":"四种金属与稀盐酸反应","caption":"判断哪一个说法正确","view":"wide","alt":"四支试管中分别盛有稀盐酸并放入镁、锌、铁、铜，镁与锌中气泡最多，铁中气泡较少且溶液呈浅绿色，铜表面没有变化","prims":[{"t":"testTube","x":16,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":36,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"testTube","x":56,"y":28,"h":30,"w":12,"liquid":0.5,"color":"green"},{"t":"testTube","x":76,"y":28,"h":30,"w":12,"liquid":0.5,"color":"colorless"},{"t":"text","x":16,"y":10,"text":"镁","size":3.6},{"t":"text","x":36,"y":10,"text":"锌","size":3.6},{"t":"text","x":56,"y":10,"text":"铁","size":3.6},{"t":"text","x":76,"y":10,"text":"铜","size":3.6},{"t":"text","x":50,"y":52,"text":"稀盐酸的量与浓度都相同","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"气泡越快，金属越活泼","size":3.4,"tone":"accent"}]}},{"id":"chem-substance-7-q2","type":"choice","stem":"下列反应能发生的是（　）","answer":"A","explain":"A 正确：铁排在铜的前面，能把铜从硫酸铜溶液中置换出来（湿法炼铜的原理）。B 不能发生：铜排在铁的后面，不能把铁从它的盐溶液中置换出来，这条方程式的方向反了。C 不能发生：铜排在氢的后面，不能与稀盐酸反应，不会有氢气放出。D 不能发生：银排在氢的后面，同样不能与稀盐酸反应。判断这类题只需看金属在活动性顺序表中的位置关系。","options":["Fe + CuSO₄ = FeSO₄ + Cu","Cu + FeSO₄ = CuSO₄ + Fe","Cu + 2HCl = CuCl₂ + H₂↑","2Ag + 2HCl = 2AgCl + H₂↑"],"difficulty":2,"tags":["金属活动性顺序","置换反应"]},{"id":"chem-substance-7-q3","type":"choice","stem":"下列关于金属和合金的说法正确的是（　）","answer":"D","explain":"D 正确，这是金属的共性以及「性质决定用途」的典型对应。A 错：汞（水银）在常温下是液体，是唯一的液态金属。B 把两条性质都说反了：合金的硬度一般比组成它的纯金属大，熔点一般比组成它的纯金属低。C 与事实相反：铝的表面会生成一层致密的氧化铝薄膜，阻止内部的铝继续被氧化，所以铝制品比较耐腐蚀，可以做炊具。","options":["所有金属在常温下都是固体","合金的熔点一般比组成它的纯金属高，硬度比组成它的纯金属小","铝制品在空气中很容易被腐蚀，所以不适合做炊具","金属具有良好的导电性、导热性和延展性，所以可以做导线、炊具和箔材"],"difficulty":1,"tags":["金属的性质与用途","合金"]},{"id":"chem-substance-7-q4","type":"choice","stem":"下列反应属于置换反应的是（　）","answer":"B","explain":"B 正确：铁（单质）与盐酸（化合物）反应生成氯化亚铁（化合物）和氢气（单质），符合「一种单质与一种化合物反应生成另一种单质和另一种化合物」，属于置换反应。A 是两种物质生成一种物质，属于化合反应。C 是一种物质生成两种物质，属于分解反应。D 是两种化合物互相交换成分生成另外两种化合物，不属于置换反应——判断的关键是反应物与生成物中都要有单质。","options":["3Fe + 2O₂ —点燃→ Fe₃O₄","Fe + 2HCl = FeCl₂ + H₂↑","CaCO₃ —高温→ CaO + CO₂↑","CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O"],"difficulty":2,"tags":["置换反应","反应类型"]},{"id":"chem-substance-7-q5","type":"choice","stem":"把铁钉放入硫酸铜溶液中，铁钉表面覆盖一层红色的物质，溶液由蓝色逐渐变成浅绿色。下列对该变化的解释正确的是（　）","answer":"A","explain":"A 正确：活泼的铁原子失去电子变成 Fe²⁺ 进入溶液，溶液中较不活泼的 Cu²⁺ 得到电子变成铜原子析出，所以铁钉表面出现红色的铜、溶液由蓝色变浅绿色。B 把得失电子的方向弄反了：活泼金属失电子，较不活泼金属的离子得电子。C 判断错误：有新物质铜和硫酸亚铁生成，属于化学变化（置换反应）。D 把产物写错了：生成的是硫酸亚铁 FeSO₄（浅绿色），硫酸铁是黄色的。","options":["铁原子失去电子变成亚铁离子进入溶液，铜离子得到电子变成铜原子附着在铁钉表面","铜离子失去电子变成铜原子，铁原子得到电子变成铁离子","该变化属于物理变化，因为只是颜色发生了改变","溶液变成浅绿色说明生成了硫酸铁 Fe₂(SO₄)₃"],"difficulty":2,"tags":["金属与盐溶液反应","置换反应的实质"]},{"id":"chem-substance-7-q6","type":"fill","stem":"金属活动性顺序中排在最前面、活动性最强的金属是 ______（填元素符号）。","answer":"K","explain":"金属活动性顺序为 K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au，排在最前面的是钾 K，活动性最强，常温下就能与水剧烈反应。注意钾、钙、钠因为太活泼，不能用于把其他金属从盐溶液中置换出来，因为它们会先与水反应。","difficulty":1,"tags":["金属活动性顺序"]},{"id":"chem-substance-7-q7","type":"fill","stem":"把 5.6 g 铁粉放入足量稀盐酸中完全反应，可生成氢气 ______ g。（相对原子质量：Fe 56、H 1）","answer":"0.2","explain":"由 Fe + 2HCl = FeCl₂ + H₂↑ 可知，铁与氢气的质量比为 56∶2 = 28∶1，所以 5.6 g 铁完全反应可生成氢气 5.6 g ÷ 28 = 0.2 g。若把产物写成 FeCl₃（2Fe + 6HCl = 2FeCl₃ + 3H₂↑），氢气的比例就会算错；也要注意 H₂ 的相对分子质量是 2，不是 1。","difficulty":2,"tags":["金属与酸反应","化学方程式计算"]},{"id":"chem-substance-7-q8","type":"short","stem":"把 6.5 g 锌粒放入足量稀盐酸中完全反应。求生成氢气的质量和生成氯化锌的质量。（相对原子质量：Zn 65、Cl 35.5、H 1）","answer":"设生成氢气的质量为 x，生成氯化锌的质量为 y。由 Zn + 2HCl = ZnCl₂ + H₂↑ 可知 m(Zn)∶m(ZnCl₂)∶m(H₂) = 65∶136∶2。由 65∶2 = 6.5 g∶x 得 x = 0.2 g；由 65∶136 = 6.5 g∶y 得 y = 13.6 g。答：生成氢气 0.2 g，生成氯化锌 13.6 g。","explain":"这类计算的关键是「化学式写对、比例列对」。常见错误有三个：把 ZnCl₂ 写成 ZnCl（那就漏掉一个氯原子，相对质量变成 100.5）；把 H₂ 的相对分子质量按 1 算；忘记配平。检验的办法还是质量守恒：反应物总质量应等于生成物总质量。","difficulty":2,"tags":["金属与酸反应","化学方程式计算"],"rubric":["化学方程式书写正确并配平，注意生成 ZnCl₂ 而不是 ZnCl","相对质量 65、136、2 算对（ZnCl₂ 中 Cl 按 35.5 算）","求出氢气质量为 0.2 g","求出氯化锌质量为 13.6 g，并写出带单位的答句"],"steps":["设未知量：设生成氢气的质量为 x，生成氯化锌的质量为 y。","写出并配平化学方程式：Zn + 2HCl = ZnCl₂ + H₂↑。","算出相对质量：Zn = 65，ZnCl₂ = 65 + 35.5×2 = 136，H₂ = 2。","列比例式：65∶2 = 6.5 g∶x 得 x = 0.2 g；65∶136 = 6.5 g∶y 得 y = 13.6 g。","写出带单位的答句，并可用质量守恒验算（6.5 g + 盐酸中参加反应的 HCl 质量 = 0.2 g + 13.6 g）。"]},{"id":"chem-substance-7-q9","type":"short","stem":"现只有铁、铜、银三种金属的单质和稀盐酸、硫酸铜溶液、硝酸银溶液等试剂，请设计实验比较铁、铜、银三种金属的活动性顺序。写出实验步骤、现象和结论。","answer":"方案一（用金属与盐溶液反应）：① 把铁丝放入硫酸铜溶液中，铁丝表面覆盖一层红色的铜，说明铁比铜活泼（Fe + CuSO₄ = FeSO₄ + Cu）；② 把铜丝放入硝酸银溶液中，铜丝表面覆盖一层银白色的银，说明铜比银活泼（Cu + 2AgNO₃ = Cu(NO₃)₂ + 2Ag）。由此得出活动性顺序：Fe > Cu > Ag。方案二（用金属与稀盐酸反应结合盐溶液反应）：把铁、铜分别放入稀盐酸中，铁表面有气泡、铜没有，说明铁在氢前、铜在氢后；再把铜丝放入硝酸银溶液中，铜能置换出银，说明铜比银活泼，同样得到 Fe > Cu > Ag。","explain":"比较三种金属活动性的通用思路有两条：一是「两金夹一盐」或「两盐夹一金」（用中间的金属与两边金属的盐溶液反应，或用中间的盐溶液与两边金属反应）；二是先与稀盐酸比较出谁在氢前，再用盐溶液比较。答题时必须把「现象」和「由现象得出的结论」分开写清楚，只说「铁比铜活泼」而没有实验现象，拿不到分。另外，铁的化合物要写成 FeSO₄，不能写成 Fe₂(SO₄)₃。","difficulty":3,"tags":["金属活动性顺序","实验探究","实验设计"],"rubric":["设计至少两个实验，每个实验都能比较出两种金属的活动性","用「铁丝放入硫酸铜溶液」证明铁比铜活泼，现象写成「铁丝表面覆盖红色的铜」","用「铜丝放入硝酸银溶液」证明铜比银活泼，现象写成「铜丝表面覆盖银白色的银」","写出相应的化学方程式（Fe + CuSO₄ = FeSO₄ + Cu、Cu + 2AgNO₃ = Cu(NO₃)₂ + 2Ag）","结论明确写出活动性顺序 Fe > Cu > Ag"]},{"id":"chem-substance-7-q10","type":"short","stem":"请画出铁钉与硫酸铜溶液反应的实验装置（用两支试管做对比），并在图上标出反应前后铁钉表面和溶液颜色的变化。","answer":"画法：两支试管中各加入约三分之一体积的硫酸铜溶液；左边试管插入一根银白色（打磨过）的铁钉，标注「反应前：溶液蓝色、铁钉银白色」；右边试管插入反应后的铁钉，铁钉表面画成红色（覆盖一层铜），溶液画成浅绿色，标注「反应后：铁钉表面覆盖红色的铜、溶液变浅绿色」，并写出化学方程式 Fe + CuSO₄ = FeSO₄ + Cu。","explain":"这道作图题的核心是「颜色变化要画对」：硫酸铜溶液是蓝色的，反应后生成的硫酸亚铁溶液是浅绿色的；铁钉是银白色的，置换出的铜是红色的。这两组颜色是中考判断「是否真的发生了反应」的依据，画错颜色就等于把结论画错了。另外，铁钉要画成浸在溶液中（不能只画在液面上），试管中的液体不要画满。","difficulty":2,"tags":["金属与盐溶液反应","作图题","实验现象"],"rubric":["画出两支试管并都加入硫酸铜溶液，体现对比实验","反应前标注溶液为蓝色、铁钉为银白色（用砂纸打磨过）","反应后铁钉表面画成红色（覆盖铜），溶液画成浅绿色","写出化学方程式 Fe + CuSO₄ = FeSO₄ + Cu，产物写 FeSO₄ 而不是 Fe₂(SO₄)₃"],"figure":{"id":"fig-chem-substance-7-q10","title":"待画的实验装置与现象","caption":"请画出两支试管与铁钉，并标出反应前后的颜色变化","view":"wide","alt":"画布上有两个虚线框，左边标注反应前、右边标注反应后，等待画出盛硫酸铜溶液的试管与插入溶液中的铁钉以及颜色变化","prims":[{"t":"rect","x":8,"y":16,"w":36,"h":32,"dashed":true,"tone":"muted"},{"t":"rect","x":56,"y":16,"w":36,"h":32,"dashed":true,"tone":"muted"},{"t":"text","x":26,"y":10,"text":"反应前","size":4,"tone":"accent"},{"t":"text","x":74,"y":10,"text":"反应后","size":4,"tone":"accent"},{"t":"text","x":26,"y":56,"text":"（画出试管、硫酸铜溶液与铁钉）","size":3,"tone":"muted"},{"t":"text","x":74,"y":56,"text":"（画出铁钉表面与溶液颜色的变化）","size":3,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-7-q10-a","title":"参考答案：铁钉与硫酸铜溶液反应的前后对比","caption":"溶液由蓝色变浅绿色，铁钉表面由银白色变成覆盖一层红色的铜","view":"wide","alt":"左边试管中是蓝色的硫酸铜溶液和银白色的铁钉，右边试管中铁钉表面覆盖红色的铜、溶液变成浅绿色","prims":[{"t":"testTube","x":28,"y":28,"h":32,"w":14,"liquid":0.55,"color":"blue"},{"t":"line","x1":28,"y1":20,"x2":28,"y2":40,"width":1.6},{"t":"text","x":28,"y":11,"text":"反应前","size":3.4,"tone":"accent"},{"t":"text","x":28,"y":54,"text":"溶液蓝色、铁钉银白色","size":3.2,"tone":"muted"},{"t":"testTube","x":74,"y":28,"h":32,"w":14,"liquid":0.55,"color":"green"},{"t":"line","x1":74,"y1":20,"x2":74,"y2":40,"width":1.6,"tone":"danger"},{"t":"text","x":74,"y":11,"text":"反应后","size":3.4,"tone":"accent"},{"t":"text","x":74,"y":54,"text":"铁钉表面覆盖红色的铜、溶液浅绿色","size":3.2,"tone":"muted"},{"t":"text","x":50,"y":62,"text":"Fe + CuSO₄ = FeSO₄ + Cu","size":3.4,"tone":"accent"}]}},{"id":"chem-substance-7-m1-q1","type":"short","stem":"（3 分）根据材料二排出镁、锌、铁、铜四种金属的活动性顺序，并说明铜不能与稀盐酸反应的原因。","answer":"四种金属的活动性顺序为 Mg > Zn > Fe > Cu（依据是相同条件下与稀盐酸反应的剧烈程度：越剧烈越活泼）。铜不能与稀盐酸反应，是因为铜在金属活动性顺序中排在氢的后面，只有排在氢前面的金属才能与稀盐酸、稀硫酸反应放出氢气。","explain":"","rubric":["排出正确顺序 Mg > Zn > Fe > Cu","说明判断依据是「与稀盐酸反应的剧烈程度（产生气泡的快慢）」","答出「铜排在氢的后面，所以不能与稀盐酸反应」"]},{"id":"chem-substance-7-m1-q2","type":"short","stem":"（4 分）根据材料一判断下列反应能否发生：① 把铁钉放入硫酸铜溶液中；② 把铜丝放入硫酸亚铁溶液中；③ 把银丝放入稀盐酸中。能发生的写出化学方程式，不能发生的说明理由。","answer":"① 能发生，因为铁排在铜的前面：Fe + CuSO₄ = FeSO₄ + Cu，现象是铁钉表面覆盖一层红色的铜、溶液由蓝色变成浅绿色。② 不能发生，因为铜排在铁的后面，不能把铁从硫酸亚铁溶液中置换出来。③ 不能发生，因为银排在氢的后面，不能与稀盐酸反应。","explain":"","rubric":["① 判断正确并写出 Fe + CuSO₄ = FeSO₄ + Cu，产物写 FeSO₄ 而不是 Fe₂(SO₄)₃","② 判断正确，理由为「铜排在铁的后面，不能置换出铁」","③ 判断正确，理由为「银排在氢的后面，不能与稀盐酸反应」","判断与理由一一对应，现象描述准确（红色物质、溶液由蓝色变浅绿色）"]},{"id":"chem-substance-7-m1-q3","type":"short","stem":"（4 分）根据材料三计算：13 g 锌与足量稀硫酸完全反应，可制得氢气多少克？同时生成硫酸锌多少克？（相对原子质量：Zn 65、S 32、O 16、H 1）","answer":"设生成氢气的质量为 x，生成硫酸锌的质量为 y。由 Zn + H₂SO₄ = ZnSO₄ + H₂↑ 可知 m(Zn)∶m(ZnSO₄)∶m(H₂) = 65∶161∶2。由 65∶2 = 13 g∶x 得 x = 0.4 g；由 65∶161 = 13 g∶y 得 y = 32.2 g。答：可制得氢气 0.4 g，同时生成硫酸锌 32.2 g。","explain":"","rubric":["写出并配平化学方程式 Zn + H₂SO₄ = ZnSO₄ + H₂↑","算出相对质量 65、161、2（H₂ 按 2 算，ZnSO₄ 按 161 算）","求出氢气质量为 0.4 g","求出硫酸锌质量为 32.2 g，并写出带单位的答句"]}]},{"id":"chem-substance-8","title":"金属资源的利用和保护：铁的冶炼·铁生锈的条件与防锈·金属资源保护与含杂质计算","subtitle":"人教版九年级 · 第八单元 金属和金属材料 · 9b","grade":"9b","tags":["人教版九年级 · 第八单元 金属和金属材料"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第八单元 金属和金属材料 · 9b"},{"type":"note","title":"问题切入","text":"铁矿石是怎样变成铁的？高炉里到底发生了什么反应？为什么铁在潮湿的空气中很快就锈迹斑斑，放在干燥的空气里却能放很久？怎样防止铁生锈，又该怎样保护有限的金属资源？"},{"type":"note","title":"一句话抓住关键","text":"工业炼铁的原理是用一氧化碳在高温下把铁从铁矿石里还原出来：3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂。铁生锈是铁与氧气和水同时接触发生缓慢氧化的结果，两个条件缺一不可，所以防锈的思路就是隔绝氧气或隔绝水——刷漆、涂油、镀锌、制成不锈钢。含杂质的计算要先按纯度把混合物质量换算成纯物质的质量，再代入化学方程式。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"铁钉放在潮湿的空气中，几天就锈迹斑斑；放在干燥的盒子里，却能放很久。铁生锈就像人生病，需要同时满足两个条件才会「发作」：与氧气接触，与水接触。","walk":["工业炼铁的原理是用一氧化碳把铁从铁矿石中还原出来，高炉里主要反应是氧化铁与一氧化碳生成铁和二氧化碳。","铁生锈的两个条件：与氧气接触、与水接触，缺一不可。所以防锈的思路就是「隔绝其中一个」：刷漆、涂油、镀层、保持干燥。","含杂质计算要先换算成纯净物质量：纯净物质量 = 样品质量 × 纯度。代入化学方程式的一定是纯净物质量，不能直接拿样品质量去算。"],"try":"取两枚铁钉，一枚放在干燥的塑料袋里，一枚沾湿后放在敞口杯中，过几天对比，看哪一枚先生锈。","use":["防锈题答「隔绝氧气或水」，并给出具体做法，不要只写「保护起来」。","含杂质计算先算纯度，再按方程式算，最后别忘了换算回样品质量。"]},{"type":"h","text":"【宏观】宏观：工业炼铁——从铁矿石到铁"},{"type":"p","text":"工业炼铁的主要设备是高炉，原料是铁矿石（如赤铁矿，主要成分 Fe₂O₃）、焦炭和石灰石。高炉里的反应分三步看：焦炭燃烧放热并提供还原剂——C + O₂ —点燃→ CO₂（提供热量）、CO₂ + C —高温→ 2CO（生成还原剂一氧化碳）；一氧化碳在高温下把铁从铁矿石中还原出来——3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂；石灰石在高温下分解生成生石灰——CaCO₃ —高温→ CaO + CO₂↑，生石灰再把矿石中的杂质（二氧化硅）变成炉渣除去。所以高炉的出铁口流出铁水、出渣口排出炉渣。"},{"type":"figure","figure":{"id":"fig-chem-substance-8-1","title":"高炉炼铁示意","caption":"铁矿石、焦炭、石灰石从炉顶加入，热空气从下部鼓入，出铁口流出铁水","view":"wide","alt":"高炉的炉身剖面示意，炉顶加入铁矿石、焦炭和石灰石，下部鼓入热空气，出铁口流出铁水、出渣口排出炉渣，炉内发生一氧化碳还原氧化铁的反应","prims":[{"t":"poly","points":[[42,18],[58,18],[64,30],[64,50],[36,50],[36,30]],"closed":true},{"t":"arrow","x1":50,"y1":4,"x2":50,"y2":17,"label":"铁矿石、焦炭、石灰石"},{"t":"arrow","x1":24,"y1":44,"x2":35,"y2":44,"label":"热空气","labelDy":-4},{"t":"arrow","x1":64,"y1":47,"x2":80,"y2":47,"tone":"danger","label":"铁水（出铁口）","labelDy":6},{"t":"arrow","x1":64,"y1":34,"x2":80,"y2":32,"tone":"muted","label":"炉渣（出渣口）","labelDy":-5},{"t":"text","x":50,"y":26,"text":"高温","size":3.4},{"t":"text","x":50,"y":40,"text":"3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂","size":3},{"t":"text","x":50,"y":58,"text":"焦炭：① 燃烧放热 ② 生成还原剂 CO；石灰石：造渣除杂","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"三个反应要分清：焦炭燃烧（点燃）提供热量，二氧化碳与碳反应（高温）生成还原剂 CO，CO 还原氧化铁（高温）得到铁。答题时别说「焦炭直接还原氧化铁」——真正起还原作用的是它生成的一氧化碳。"},{"type":"h","text":"【宏观】微观：一氧化碳怎样把氧从铁矿石里夺走"},{"type":"p","text":"从粒子角度看，一氧化碳分子中的碳原子「抢氧」的能力很强：在高温下，3 个一氧化碳分子各夺取氧化铁中的 1 个氧原子，变成 3 个二氧化碳分子；氧化铁失去氧以后，铁原子被「解放」出来，成为单质铁。这个过程中，碳元素的化合价从 +2 升高到 +4（被氧化），铁元素的化合价从 +3 降到 0（被还原）。凡是能夺取含氧化合物中氧的物质叫还原剂，CO 就是这里最常见的还原剂；氧化铁失去了氧，发生的是还原反应。"},{"type":"figure","figure":{"id":"fig-chem-substance-8-2","title":"一氧化碳还原氧化铁的微观过程","caption":"CO 夺取 Fe₂O₃ 中的氧变成 CO₂，铁被还原出来","view":"wide","alt":"三个一氧化碳分子与一个氧化铁粒子在高温下反应，生成两个铁原子和三个二氧化碳分子，说明一氧化碳夺取了氧化铁中的氧","prims":[{"t":"molecule","x":12,"y":12,"atoms":[{"dx":-3.6,"dy":0,"r":3,"symbol":"C","color":"black"},{"dx":3.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"CO"},{"t":"molecule","x":12,"y":26,"atoms":[{"dx":-3.6,"dy":0,"r":3,"symbol":"C","color":"black"},{"dx":3.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]]},{"t":"molecule","x":12,"y":40,"atoms":[{"dx":-3.6,"dy":0,"r":3,"symbol":"C","color":"black"},{"dx":3.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]]},{"t":"text","x":12,"y":52,"text":"3 CO","size":3.4},{"t":"molecule","x":40,"y":26,"atoms":[{"dx":0,"dy":-7,"r":4,"symbol":"Fe","color":"brown"},{"dx":0,"dy":6,"r":4,"symbol":"Fe","color":"brown"},{"dx":-7,"dy":0,"symbol":"O","color":"red"},{"dx":7,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":-14,"symbol":"O","color":"red"}],"bonds":[[0,2],[1,3],[0,4]],"label":"Fe₂O₃"},{"t":"arrow","x1":54,"y1":30,"x2":66,"y2":30,"label":"高温","labelDy":-4},{"t":"atom","x":78,"y":12,"r":4.4,"symbol":"Fe","color":"brown"},{"t":"atom","x":88,"y":12,"r":4.4,"symbol":"Fe","color":"brown"},{"t":"text","x":83,"y":24,"text":"2 Fe","size":3.4},{"t":"molecule","x":78,"y":42,"atoms":[{"dx":-4,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":0,"r":3.2,"symbol":"C","color":"black"},{"dx":4,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"text","x":50,"y":58,"text":"CO 夺氧被氧化成 CO₂，Fe₂O₃ 失氧被还原成 Fe","size":3.2,"tone":"accent"}]}},{"type":"note","title":"","text":"「还原剂」与「被还原的物质」要分清：CO 是还原剂（它夺氧，自己被氧化），Fe₂O₃ 是被还原的物质（它失氧，发生还原反应）。同一条方程式里，碳元素化合价升高、铁元素化合价降低，这就是氧化还原的微观本质。"},{"type":"h","text":"【微观】宏观实验：铁生锈的条件与防锈办法"},{"type":"p","text":"用三支试管做对比实验：第一支试管里放一根铁钉、加少量水使铁钉一半浸在水中（铁钉同时接触水和空气）；第二支试管里放干燥的铁钉并放入干燥剂（只有氧气，没有水）；第三支试管里放入用煮沸并迅速冷却的蒸馏水浸没的铁钉，再在水面上加一层植物油（只有水，没有氧气）。几天后只有第一支试管里的铁钉生锈，说明铁生锈是铁与氧气、水同时接触的结果，两个条件缺一不可。防锈的思路也就清楚了：隔绝氧气或隔绝水——刷漆、涂油、镀锌、镀铬、制成不锈钢，还可以保持铁制品表面干燥洁净。"},{"type":"figure","figure":{"id":"fig-chem-substance-8-3","title":"铁生锈条件的探究","caption":"①同时接触水和氧气才生锈；②只有氧气 ③只有水，都不生锈","view":"wide","alt":"三支试管的对比实验：第一支铁钉一半浸在水中、几天后生锈；第二支铁钉放在有干燥剂的干燥空气中、不生锈；第三支铁钉浸在煮沸的蒸馏水中并用植物油隔绝空气、不生锈","prims":[{"t":"text","x":50,"y":5,"text":"铁生锈条件的探究（对比实验）","size":3.6,"tone":"accent"},{"t":"testTube","x":20,"y":26,"h":30,"w":13,"liquid":0.5,"color":"colorless"},{"t":"line","x1":20,"y1":18,"x2":20,"y2":36,"width":1.5},{"t":"text","x":20,"y":48,"text":"①铁钉一半浸在水中","size":3},{"t":"text","x":20,"y":54,"text":"（同时接触水和氧气）","size":3},{"t":"text","x":20,"y":60,"text":"→ 铁钉生锈","size":3,"tone":"danger"},{"t":"testTube","x":50,"y":26,"h":30,"w":13,"color":"colorless"},{"t":"line","x1":50,"y1":18,"x2":50,"y2":36,"width":1.5},{"t":"hatch","x":45,"y":40,"w":10,"h":4,"gap":1.4},{"t":"text","x":50,"y":48,"text":"②干燥空气中","size":3},{"t":"text","x":50,"y":54,"text":"（放干燥剂，只有氧气）","size":3},{"t":"text","x":50,"y":60,"text":"→ 不生锈","size":3,"tone":"muted"},{"t":"testTube","x":80,"y":26,"h":30,"w":13,"liquid":0.6,"color":"colorless"},{"t":"line","x1":80,"y1":18,"x2":80,"y2":36,"width":1.5},{"t":"rect","x":74.2,"y":27.5,"w":11.6,"h":2.6,"fill":true,"tone":"accent"},{"t":"text","x":80,"y":48,"text":"③煮沸蒸馏水 + 植物油","size":3},{"t":"text","x":80,"y":54,"text":"（只有水，没有氧气）","size":3},{"t":"text","x":80,"y":60,"text":"→ 不生锈","size":3,"tone":"muted"}]}},{"type":"note","title":"","text":"三个细节要能说清：水要煮沸并迅速冷却，是为了赶走水中溶解的氧气；加植物油是为了隔绝空气（防止氧气重新溶入）；放干燥剂是为了保证试管内没有水。只有这样才能做到「只让铁接触其中一个条件」。"},{"type":"h","text":"【符号】符号：方程式与含杂质的计算"},{"type":"p","text":"这一节的方程式要写全：炼铁原理 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂；检验生成的二氧化碳 CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O；尾气处理 2CO + O₂ —点燃→ 2CO₂；焦炭的作用 C + O₂ —点燃→ CO₂、CO₂ + C —高温→ 2CO；石灰石分解 CaCO₃ —高温→ CaO + CO₂↑。做计算时记住一句话：化学方程式里的质量比只对纯物质成立。题目给的往往是矿石或生铁的质量，要先按纯度换成纯 Fe₂O₃（或纯铁）的质量，再把纯量代入方程式。"},{"type":"figure","figure":{"id":"fig-chem-substance-8-4","title":"含杂质计算的换算关系","caption":"先把矿石的质量换算成纯 Fe₂O₃ 的质量，再代入化学方程式","view":"wide","alt":"示意图表示赤铁矿石的质量乘以氧化铁的质量分数得到纯氧化铁的质量，再由化学方程式算出铁的质量，最后除以生铁中铁的质量分数得到生铁的质量","prims":[{"t":"rect","x":10,"y":22,"w":22,"h":14,"fill":true,"label":"赤铁矿石"},{"t":"text","x":21,"y":44,"text":"×80%（纯度）","size":3},{"t":"arrow","x1":33,"y1":29,"x2":45,"y2":29,"tone":"accent"},{"t":"rect","x":46,"y":22,"w":20,"h":14,"fill":true,"tone":"accent","label":"Fe₂O₃"},{"t":"text","x":56,"y":44,"text":"×112/160","size":3},{"t":"arrow","x1":67,"y1":29,"x2":79,"y2":29,"tone":"ok"},{"t":"rect","x":80,"y":22,"w":16,"h":14,"fill":true,"tone":"ok","label":"Fe"},{"t":"text","x":88,"y":44,"text":"÷96%","size":3},{"t":"text","x":50,"y":56,"text":"纯物质质量 = 混合物质量 × 纯度；生铁质量 = 纯铁质量 ÷ 生铁中铁的质量分数","size":3.2,"tone":"muted"}]}},{"type":"note","title":"","text":"常见错误是把矿石的质量直接当成 Fe₂O₃ 的质量代入方程式，或者算出的纯铁质量忘了再除以生铁中铁的质量分数。写完答案可以反过来验算：矿石中 Fe₂O₃ 的质量 × 70% 应等于纯铁的质量。"},{"type":"h","text":"【应用】应用：保护金属资源"},{"type":"p","text":"金属资源是有限的、不可再生的，保护金属资源主要有四条途径：一是防止金属腐蚀（刷漆、涂油、镀金属、制成不锈钢），这也是最直接、最经济的办法；二是回收利用废旧金属（回收一个铝制易拉罐比用铝土矿炼铝节省约 95% 的能源）；三是有计划、合理地开采矿物，严禁乱采滥挖；四是寻找金属的代用品（用塑料代替金属做管道、用铝合金代替部分钢材）。其中防止腐蚀之所以重要，是因为全世界每年因腐蚀而损失的金属约占年产量的很大一部分，而铁生锈是最主要的腐蚀形式。"},{"type":"note","title":"","text":"答「保护金属资源的措施」时最好分类写：防腐蚀、回收利用、合理开采、寻找替代品。只写「节约用金属」太笼统，拿不到完整的分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["元素的质量分数（以 Fe₂O₃ 为例）","Fe₂O₃ 中铁元素的质量分数 = (56×2) ÷ (56×2 + 16×3) × 100% = 112 ÷ 160 × 100% = 70%","用于由铁矿石的质量直接估算铁的质量：纯铁质量 = 纯 Fe₂O₃ 质量 × 70%。反过来，若已知需要得到的铁的质量，也可以先换算成 Fe₂O₃ 的质量再算矿石的质量。注意只能用于纯物质，矿石要先乘纯度。"],["含杂质物质的换算","纯物质的质量 = 混合物的质量 × 纯度；混合物的质量 = 纯物质的质量 ÷ 纯度","适用于所有含杂质原料的计算（铁矿石、生铁、石灰石、含杂质的锌粒等）。化学方程式中的质量比只对参加反应的纯物质成立，所以必须先把混合物质量换算成纯物质质量再代入；算出的纯铁质量若要折算成生铁，还要除以生铁中铁的质量分数。"],["炼铁方程式中的质量比","3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂，m(Fe₂O₃)∶m(Fe)∶m(CO)∶m(CO₂) = 160∶112∶84∶132","炼铁计算的核心比例，其中 Fe₂O₃ 与 Fe 的比可以化简为 10∶7。计算 CO 的用量时用 160∶84（即 40∶21）；实际生产中通入的 CO 要过量，题目若给的是「实际消耗」与「理论需要」的对比，可以据此求一氧化碳的利用率。"]]},{"type":"h","text":"应用 · 用赤铁矿石炼铁的计算"},{"type":"note","title":"情境","text":"某炼铁厂用 1000 t 含氧化铁 80% 的赤铁矿石炼铁（假设氧化铁全部被还原，其他成分不含铁）。理论上可炼出多少吨纯铁？如果炼出的是含铁 96% 的生铁，可得生铁多少吨？（相对原子质量：Fe 56、O 16）"},{"type":"list","title":"解答步骤","items":["算出矿石中纯氧化铁的质量：1000 t × 80% = 800 t。","算出 Fe₂O₃ 与 Fe 的质量比：(56×2 + 16×3)∶(56×2) = 160∶112 = 10∶7。","求纯铁：800 t × 112/160 = 560 t（也可以直接算 Fe₂O₃ 中铁元素的质量分数 70%，800 t × 70% = 560 t）。","求生铁：560 t ÷ 96% ≈ 583.3 t。","答：理论上可炼出纯铁 560 t，可得含铁 96% 的生铁约 583.3 t。"]},{"type":"note","title":"结论","text":"纯铁 560 t，生铁约 583.3 t。两个易错点：把 1000 t 直接代入方程式（忘了先乘 80%）；算出 560 t 后就当作生铁的质量（忘了除以 96%）。"},{"type":"h","text":"应用 · 自行车上的防锈措施"},{"type":"note","title":"情境","text":"自行车的链条经常涂油、车圈表面镀铬、车架表面喷漆、车把套用塑料制成。这些做法分别用了什么防锈原理？"},{"type":"list","title":"解答步骤","items":["先明确铁生锈的条件：铁与氧气和水同时接触。","逐个分析做法的原理：涂油、镀铬、喷漆都是隔绝氧气和水；塑料代替金属是寻找代用品。","补充其他常见措施：保持铁制品表面干燥洁净；制成不锈钢（改变金属的内部结构，提高抗腐蚀能力）。","归纳答题模板：防止铁生锈的方法是「隔绝氧气或水」，具体做法有刷漆、涂油、镀金属、制成合金等。"]},{"type":"note","title":"结论","text":"答题时要「措施 + 原理」成对写出：涂油、镀铬、喷漆 → 隔绝氧气和水；用塑料代替金属 → 寻找金属代用品。只写措施不写原理会被扣分。"},{"type":"h","text":"实验 1 · 一氧化碳还原氧化铁"},{"type":"note","title":"实验目的","text":"验证一氧化碳的还原性，观察氧化铁被还原成铁的现象，并学会处理有毒尾气。"},{"type":"list","title":"实验器材","items":["硬质玻璃管、橡皮塞、导管","氧化铁粉末、一氧化碳","酒精灯（或酒精喷灯）、铁架台","试管（盛澄清石灰水）、酒精灯（处理尾气）"]},{"type":"figure","figure":{"id":"fig-chem-substance-8-exp1","title":"一氧化碳还原氧化铁","caption":"先通 CO 排尽空气再加热，尾气用酒精灯点燃处理","view":"wide","alt":"硬质玻璃管中装有红棕色的氧化铁粉末，左侧通入一氧化碳，下方用酒精灯加热，右侧导管把生成的气体通入澄清石灰水，末端用另一盏酒精灯点燃处理尾气","prims":[{"t":"stand","x":14,"y":46,"h":34,"w":18,"clamps":[0.6]},{"t":"rect","x":22,"y":22,"w":34,"h":10},{"t":"hatch","x":32,"y":23,"w":14,"h":8,"gap":1.6},{"t":"text","x":39,"y":16,"text":"Fe₂O₃（红棕色）","size":3.2,"tone":"muted"},{"t":"alcoholLamp","x":39,"y":40,"lit":true},{"t":"arrow","x1":6,"y1":27,"x2":21,"y2":27,"tone":"accent","label":"CO","labelDy":-4},{"t":"curve","points":[[56,27],[64,25],[70,28],[72,38]]},{"t":"testTube","x":72,"y":48,"h":26,"w":13,"liquid":0.45,"color":"colorless"},{"t":"text","x":88,"y":40,"text":"澄清石灰水","anchor":"end","size":3.2},{"t":"text","x":92,"y":56,"text":"尾气点燃","anchor":"end","size":3.2,"tone":"danger"},{"t":"poly","points":[[92,52],[90.5,48],[92,45],[93.5,48]],"fill":true,"tone":"danger"},{"t":"text","x":50,"y":61,"text":"先通 CO 排尽空气，再加热；结束时先停止加热，继续通 CO 至冷却","size":3,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["按图组装装置，检查装置的气密性，在硬质玻璃管中装入少量氧化铁粉末。","先通入一氧化碳一段时间，把玻璃管内的空气排尽（防止加热时发生爆炸）。","点燃酒精灯（或酒精喷灯）加热氧化铁，观察玻璃管内固体颜色的变化和澄清石灰水的变化。","反应结束后先停止加热，继续通一氧化碳直到玻璃管冷却，再停止通气。","用点燃的方法处理尾气（或用气球收集），防止一氧化碳污染空气。"]},{"type":"note","title":"实验现象","text":"红棕色的氧化铁粉末逐渐变成黑色（生成铁），澄清石灰水变浑浊（生成二氧化碳），尾气点燃时产生蓝色火焰。"},{"type":"note","title":"实验结论","text":"一氧化碳在高温下把氧化铁还原成铁，同时生成二氧化碳，化学方程式为 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂；澄清石灰水变浑浊证明生成的气体是二氧化碳（CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O）。"},{"type":"list","title":"注意事项","items":["实验开始必须先通一氧化碳、后加热：先把玻璃管内的空气排尽，否则一氧化碳与空气的混合气体受热可能发生爆炸。","实验结束必须先停止加热、继续通一氧化碳直到玻璃管冷却：防止刚生成的铁在高温下被空气重新氧化，也防止石灰水倒吸。","尾气必须处理：一氧化碳有毒，要用酒精灯点燃（2CO + O₂ —点燃→ 2CO₂）或收集起来，不能直接排放到空气中。","实验要在通风处进行，装置的气密性要好；一氧化碳有毒，实验时不要长时间靠近装置。","氧化铁粉末要平铺在玻璃管中，便于气体充分接触；加热要用外焰，先预热再固定加热。","澄清石灰水中的导管只伸到液面以下少许即可，不能插入太深，以免倒吸。"]},{"type":"h","text":"实验 2 · 探究铁生锈的条件"},{"type":"note","title":"实验目的","text":"用对比实验研究铁生锈需要哪些条件，并由此推出防锈的方法。"},{"type":"list","title":"实验器材","items":["试管（三支）、橡皮塞","铁钉（洁净、无锈）","蒸馏水、植物油、干燥剂（如氯化钙）","砂纸"]},{"type":"figure","figure":{"id":"fig-chem-substance-8-exp2","title":"铁生锈条件的对比实验","caption":"只有同时接触水和氧气的那支试管里的铁钉才生锈","view":"wide","alt":"三支试管中：第一支铁钉一半浸在水中并接触空气、铁钉生锈；第二支铁钉在加有干燥剂的干燥空气中、不生锈；第三支铁钉浸在煮沸的蒸馏水中并用植物油隔绝空气、不生锈","prims":[{"t":"testTube","x":20,"y":24,"h":30,"w":13,"liquid":0.5,"color":"colorless"},{"t":"line","x1":20,"y1":16,"x2":20,"y2":34,"width":1.5,"tone":"danger"},{"t":"text","x":20,"y":10,"text":"一半浸在水中","size":3},{"t":"text","x":20,"y":46,"text":"同时接触水和氧气","size":3,"tone":"danger"},{"t":"text","x":20,"y":52,"text":"→ 生锈","size":3,"tone":"danger"},{"t":"testTube","x":50,"y":24,"h":30,"w":13,"color":"colorless"},{"t":"line","x1":50,"y1":16,"x2":50,"y2":34,"width":1.5},{"t":"hatch","x":45,"y":38,"w":10,"h":4,"gap":1.4},{"t":"text","x":50,"y":10,"text":"干燥空气中","size":3},{"t":"text","x":50,"y":46,"text":"只有氧气（放干燥剂）","size":3,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"→ 不生锈","size":3,"tone":"muted"},{"t":"testTube","x":80,"y":24,"h":30,"w":13,"liquid":0.6,"color":"colorless"},{"t":"line","x1":80,"y1":16,"x2":80,"y2":34,"width":1.5},{"t":"rect","x":74.2,"y":25.5,"w":11.6,"h":2.6,"fill":true,"tone":"accent"},{"t":"text","x":80,"y":10,"text":"煮沸蒸馏水 + 植物油","size":3},{"t":"text","x":80,"y":46,"text":"只有水（没有氧气）","size":3,"tone":"muted"},{"t":"text","x":80,"y":52,"text":"→ 不生锈","size":3,"tone":"muted"},{"t":"text","x":50,"y":60,"text":"结论：铁生锈是铁与氧气和水同时接触的结果","size":3.2,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["取三支洁净的试管并编号，用砂纸把三根铁钉打磨光亮（除去表面的铁锈和油污）。","试管①中加入少量水，使铁钉一半浸在水中、一半露在空气中。","试管②中放入铁钉和适量干燥剂，塞紧橡皮塞，使铁钉处在干燥的空气中。","试管③中加入煮沸后迅速冷却的蒸馏水，使铁钉完全浸没，再在水面上加一层植物油，塞紧橡皮塞。","把三支试管放在同一处静置观察几天，比较三根铁钉的变化。"]},{"type":"note","title":"实验现象","text":"几天后，试管①中的铁钉表面出现红棕色的铁锈；试管②与试管③中的铁钉都没有生锈。"},{"type":"note","title":"实验结论","text":"铁生锈是铁与氧气、水同时接触发生缓慢氧化的结果，两个条件缺一不可。因此防锈的方法就是隔绝氧气或隔绝水：刷漆、涂油、镀锌、镀铬、制成不锈钢，并保持铁制品表面干燥洁净。"},{"type":"list","title":"注意事项","items":["水必须煮沸并迅速冷却：赶走水中溶解的氧气，否则试管③中仍有氧气，实验结论就不可靠。","试管③水面上要加一层植物油：隔绝空气，防止空气中的氧气重新溶入水中。","试管②必须塞紧并放干燥剂：保证试管内没有水蒸气，才能说明「只有氧气时铁不生锈」。","三支试管要放在相同环境、观察同样长的时间：控制变量，否则现象差异不能归因到水或氧气上。","铁钉要先用砂纸打磨：除去已有的铁锈和油污，否则铁钉表面已有锈，无法判断是否新生成铁锈。","实验需要几天时间，期间不要频繁打开试管塞，也不要把试管放在潮湿处。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂","高温","红棕色的氧化铁粉末逐渐变成黑色（生成铁），生成的气体使澄清石灰水变浑浊","配平：左边 3 个碳、3 个铁、6 个氧（3CO 有 3 个氧 + Fe₂O₃ 有 3 个氧），右边 2Fe 有 2 个铁、3CO₂ 有 3 个碳和 6 个氧，两边相等。条件必须写「高温」，写成「加热」或「点燃」都错。CO 是还原剂，Fe₂O₃ 被还原。"],["CO₂ + Ca(OH)₂ = CaCO₃↓ + H₂O","常温（不写条件）","澄清石灰水变浑浊","用来检验炼铁（或一氧化碳还原氧化铁）实验中生成的二氧化碳。配平：左边 1 个碳、1 个钙、4 个氧、2 个氢，右边 CaCO₃ 有 1 个钙、1 个碳、3 个氧，H₂O 有 2 个氢、1 个氧，氧原子合计 4 个。CaCO₃ 是沉淀，必须标 ↓。"],["2CO + O₂ —点燃→ 2CO₂","点燃","一氧化碳燃烧产生蓝色火焰，放出大量热","这是尾气处理的方法之一：把未反应完的有毒一氧化碳点燃，变成无毒的二氧化碳再排放。配平：左边 2 个碳、4 个氧，右边 2CO₂ 也是 2 个碳、4 个氧。CO 有毒，不能直接排入空气。"],["C + O₂ —点燃→ CO₂","点燃","焦炭在炉内燃烧，放出大量的热，为炼铁提供热量","焦炭的第一个作用：燃烧放热、维持高炉内的高温。配平：系数均为 1。注意高炉内还有 CO₂ + C —高温→ 2CO 的反应，那两个反应的条件不同，不能混写。"],["CO₂ + C —高温→ 2CO","高温","二氧化碳通过灼热的焦炭层被还原成一氧化碳","焦炭的第二个作用：生成还原剂一氧化碳。配平：左边 1 个碳（来自 CO₂）+ 1 个碳（焦炭）= 2 个碳、2 个氧，右边 2CO 有 2 个碳、2 个氧。条件写「高温」，不能写「点燃」。"],["CaCO₃ —高温→ CaO + CO₂↑","高温","石灰石在高温下分解，生成的生石灰与矿石中的杂质反应形成炉渣","石灰石的作用是造渣除杂。配平：左边 1 个钙、1 个碳、3 个氧，右边 CaO 有 1 个钙、1 个氧，CO₂ 有 1 个碳、2 个氧。条件是「高温」，不能写「加热」；实验室制二氧化碳用的是大理石与稀盐酸，两者不要混淆。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["铁只与水接触就会生锈，所以雨天铁制品都会被锈坏。","铁生锈是铁与氧气和水同时接触发生缓慢氧化的结果，两个条件缺一不可。","对照实验可以说明这一点：干燥的空气中（只有氧气）铁不生锈；煮沸后隔绝氧气的蒸馏水中（只有水）铁也不生锈；只有同时接触水和氧气时才生锈。所以保持干燥是防锈的好办法。"],["铁在氧气中燃烧和铁生锈都是铁与氧气反应，产物都是四氧化三铁。","铁在氧气中燃烧生成黑色的 Fe₃O₄；铁生锈生成的是主要成分为 Fe₂O₃·xH₂O 的铁锈，呈红棕色、疏松多孔。","反应条件不同、产物不同：燃烧是剧烈的氧化，需要点燃；生锈是缓慢氧化，常温下就发生。而且铁锈疏松多孔，不能保护内部的铁，所以铁会一直锈下去；铝表面的氧化铝薄膜却是致密的，能保护内部金属。"],["计算炼铁的产量时，可以直接把铁矿石的质量代入化学方程式。","铁矿石是混合物，必须先按纯度换算出纯 Fe₂O₃ 的质量，再代入化学方程式计算；算出的纯铁质量还要按生铁中铁的质量分数折算成生铁的质量。","化学方程式里的质量比只适用于参加反应的纯物质。忽略纯度或忽略生铁中的含铁量，是含杂质计算题最常见的两处失分点。"],["不锈钢在任何条件下都不会生锈，所以可以长时间用它盛放酸性或过咸的食物。","不锈钢只是在一般条件下比普通钢耐腐蚀；在酸性、高盐等条件下仍会被腐蚀，不宜长时间盛放酸性、过咸的食物。","把「抗腐蚀性能更好」说成了「绝对不会腐蚀」。合金的作用是提高抗腐蚀能力，不是让它变成「永不生锈」的材料。"]]},{"type":"table","title":"铁生锈与铁燃烧（反应条件、现象与产物）","head":["比较项","铁生锈（缓慢氧化）","铁在氧气中燃烧（剧烈氧化）"],"rows":[["条件","常温下，铁同时接触氧气和水","点燃，铁丝在纯氧中燃烧"],["现象","铁表面逐渐出现红棕色的锈，缓慢、无明显发光发热","剧烈燃烧，火星四射，放出大量热"],["产物","铁锈，主要成分 Fe₂O₃·xH₂O（疏松多孔）","四氧化三铁 Fe₃O₄（黑色固体）"],["影响","疏松多孔不能保护内部的铁，会持续腐蚀，每年损失大量金属","生成致密固体落于瓶底，实验室中要防止熔化物炸裂瓶底"]]},{"type":"table","title":"常见的防锈方法（做法与对应原理、适用场合）","head":["比较项","做法","原理与适用场合"],"rows":[["刷漆、喷漆","铁栏杆、车架、船体表面刷防锈漆","隔绝氧气和水；适合大面积、不宜经常摩擦的表面"],["涂油","自行车链条、刀具、机器零件涂油","隔绝氧气和水，同时起润滑作用；适合经常活动的部件"],["镀金属","车圈镀铬、铁皮镀锌（白铁皮）","镀层隔绝氧气和水，镀层破损后锌还能先被腐蚀，保护铁"],["制成合金","制成不锈钢（加入铬、镍等）","改变金属的内部结构，提高抗腐蚀能力；适合餐具、医疗器械"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["铁的冶炼原理与方程式书写","考高炉炼铁的原料（铁矿石、焦炭、石灰石）与各自的作用、炼铁原理方程式的书写与配平（3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂），以及一氧化碳还原氧化铁实验的现象、先通气后加热的操作顺序和尾气处理。"],["铁生锈条件的探究与防锈措施","以对比实验为情境，考「水要煮沸冷却」「加植物油」「放干燥剂」这些操作的目的，得出结论「铁生锈是铁与氧气、水同时作用的结果」，并结合生活情境（自行车、铁锅、铁栏杆）考防锈措施与原理的对应。"],["含杂质物质的化学方程式计算","中考计算题的常客：由铁矿石（含 Fe₂O₃ 的质量分数）求纯铁或生铁的产量，或反过来由铁产量求所需矿石的质量。得分点在「先按纯度换算成纯物质、再代入方程式、最后折算成生铁」这三步。"],["金属资源的保护","以资源短缺、废金属回收、防止腐蚀为情境，考保护金属资源的四条途径（防腐蚀、回收利用、合理开采、寻找代用品），常与铁生锈的条件结合起来设问。"]]},{"type":"quote","text":"【材料一】工业炼铁的主要设备是高炉，原料有铁矿石、焦炭和石灰石。炉内发生的主要反应有：C + O₂ —点燃→ CO₂、CO₂ + C —高温→ 2CO、3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂。【材料二】某同学探究铁生锈的条件，记录如下：试管①铁钉一半浸在水中，几天后铁钉生锈；试管②把铁钉放在加有干燥剂的干燥空气中，铁钉不生锈；试管③把铁钉浸没在煮沸后迅速冷却的蒸馏水中，并在水面上加一层植物油，铁钉不生锈。【材料三】某炼铁厂用 2000 t 含氧化铁 70% 的赤铁矿石炼铁，假设氧化铁全部被还原，其他成分不含铁，炼出的生铁中含铁 98%。（本材料为原创仿真情境）","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】（3 分）根据材料一，写出工业炼铁的原理（用化学方程式表示），并说明焦炭在高炉中的两个作用。","【设问】（4 分）根据材料二的实验记录，说明铁生锈需要什么条件？试管③中的水为什么要先煮沸、还要在水面上加一层植物油？","【设问】（5 分）根据材料三计算：2000 t 含氧化铁 70% 的赤铁矿石理论上可炼出纯铁多少吨？可炼出含铁 98% 的生铁多少吨？（相对原子质量：Fe 56、O 16）"]}],"questions":[{"id":"chem-substance-8-q1","type":"choice","stem":"如图是一氧化碳还原氧化铁的实验装置。下列说法正确的是（　）","answer":"B","explain":"B 正确：先停止加热、继续通入一氧化碳直到玻璃管冷却，一方面防止刚生成的铁在高温下被空气重新氧化，另一方面防止石灰水倒吸。A 把顺序说反了：必须先通一氧化碳排尽玻璃管内的空气再加热，否则一氧化碳与空气的混合气体受热可能爆炸。C 错：一氧化碳有毒，尾气必须点燃或收集处理。D 把两个现象弄混了：红棕色粉末变黑说明氧化铁被还原成了铁；说明生成二氧化碳的依据是澄清石灰水变浑浊。","options":["实验开始时应该先点燃加热玻璃管的酒精灯，再通入一氧化碳","实验结束时先停止加热，继续通入一氧化碳直到玻璃管冷却","反应产生的尾气可以直接排放到空气中","玻璃管中红棕色粉末逐渐变成黑色，说明生成了二氧化碳"],"difficulty":2,"tags":["铁的冶炼","一氧化碳还原氧化铁","实验操作"],"figure":{"id":"fig-chem-substance-8-q1","title":"一氧化碳还原氧化铁的装置","caption":"判断哪一个说法正确","view":"wide","alt":"硬质玻璃管中装有红棕色氧化铁粉末，左侧通入一氧化碳、下方酒精灯加热，右侧导管通向澄清石灰水，末端有一盏酒精灯处理尾气","prims":[{"t":"rect","x":22,"y":22,"w":34,"h":10},{"t":"hatch","x":32,"y":23,"w":14,"h":8,"gap":1.6},{"t":"text","x":39,"y":16,"text":"Fe₂O₃","size":3.2,"tone":"muted"},{"t":"alcoholLamp","x":39,"y":40,"lit":true},{"t":"arrow","x1":6,"y1":27,"x2":21,"y2":27,"tone":"accent","label":"CO","labelDy":-4},{"t":"curve","points":[[56,27],[64,25],[70,28],[72,38]]},{"t":"testTube","x":72,"y":48,"h":26,"w":13,"liquid":0.45,"color":"colorless"},{"t":"text","x":88,"y":40,"text":"澄清石灰水","anchor":"end","size":3.2},{"t":"poly","points":[[92,52],[90.5,48],[92,45],[93.5,48]],"fill":true,"tone":"danger"},{"t":"text","x":50,"y":61,"text":"尾气用酒精灯点燃处理","size":3.2,"tone":"danger"}]}},{"id":"chem-substance-8-q2","type":"choice","stem":"下列关于铁生锈的说法正确的是（　）","answer":"D","explain":"D 正确：铁生锈的两个条件缺一不可，这也是「保持干燥」「刷漆」「涂油」等防锈措施的原理。A 与 B 都只说了其中一个条件：干燥空气中的铁（只有氧气）不生锈，煮沸后隔绝氧气的蒸馏水中的铁（只有水）也不生锈。C 判断错误：铁生锈生成了新物质铁锈（主要成分 Fe₂O₃·xH₂O），属于化学变化，而且是缓慢氧化。","options":["铁只要与氧气接触就会生锈","铁只要与水接触就会生锈","铁生锈属于物理变化，只是铁的表面变色了","铁生锈是铁与氧气和水同时接触发生缓慢氧化的结果，所以保持铁制品干燥可以防锈"],"difficulty":1,"tags":["铁生锈的条件","防锈"]},{"id":"chem-substance-8-q3","type":"choice","stem":"下列做法中，不能防止铁制品生锈的是（　）","answer":"C","explain":"C 不能防锈：用钢丝球擦去油膜使铁直接暴露在空气和水分中，又放在潮湿处，正好满足了铁生锈的两个条件，反而更容易生锈。A 涂油能隔绝氧气和水，同时起润滑作用，是链条这类活动部件的常用做法。B 镀铬在铁表面覆盖一层耐腐蚀的金属，隔绝氧气和水。D 刷防锈漆是最常见、最经济的防锈方法，适合大面积表面。判断这类题只需看「有没有隔绝氧气或水」。","options":["自行车链条经常涂油","车圈表面镀铬","用钢丝球擦去铁锅表面的油膜后放在潮湿处","铁栏杆表面刷防锈漆"],"difficulty":1,"tags":["防锈措施","金属资源的保护"]},{"id":"chem-substance-8-q4","type":"choice","stem":"工业炼铁的主要原料是（　）","answer":"A","explain":"A 正确：高炉炼铁的原料是铁矿石（提供铁元素）、焦炭（燃烧供热并生成还原剂一氧化碳）、石灰石（高温分解生成生石灰，造渣除去矿石中的杂质）。B 错：一氧化碳是在炉内由焦炭与二氧化碳反应生成的，不是从炉外加入的原料。C 错：鼓入的是热空气而不是纯氧气，焦炭与空气中的氧气反应提供热量。D 错：加入的是石灰石而不是生石灰，生石灰是石灰石在炉内分解后生成的。","options":["铁矿石、焦炭、石灰石","铁矿石、一氧化碳、石灰石","铁矿石、焦炭、氧气","铁矿石、焦炭、生石灰"],"difficulty":1,"tags":["铁的冶炼","高炉炼铁"]},{"id":"chem-substance-8-q5","type":"choice","stem":"用 1000 t 含氧化铁 80% 的赤铁矿石炼铁（假设氧化铁全部被还原，其他成分不含铁），理论上可炼出纯铁的质量为（相对原子质量：Fe 56、O 16）（　）","answer":"D","explain":"D 正确：矿石中纯氧化铁的质量为 1000 t × 80% = 800 t；Fe₂O₃ 中铁元素的质量分数为 112/160 × 100% = 70%，所以纯铁的质量为 800 t × 70% = 560 t。A 项 800 t 是把纯氧化铁的质量当成了纯铁的质量，忘了乘铁元素的质量分数。B 项 640 t 是用 800 t × 80% 再乘一次纯度，属于重复计算纯度。C 项 1000 t 是直接把矿石的总质量当成了纯铁的质量，完全没有考虑纯度。","options":["800 t","640 t","1000 t","560 t"],"difficulty":2,"tags":["含杂质计算","铁的冶炼"]},{"id":"chem-substance-8-q6","type":"fill","stem":"一氧化碳还原氧化铁的化学方程式为 3CO + Fe₂O₃ —高温→ 2Fe + ______（填化学式与化学计量数）。","answer":"3CO₂|3CO2","explain":"一氧化碳夺取氧化铁中的氧，自己被氧化成二氧化碳，化学方程式为 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂，所以填 3CO₂。配平依据：左边 3 个碳、6 个氧（3CO 提供 3 个氧、Fe₂O₃ 提供 3 个氧），右边 3CO₂ 也正好有 3 个碳、6 个氧。系数 3 不能漏写。","difficulty":2,"tags":["铁的冶炼","化学方程式"]},{"id":"chem-substance-8-q7","type":"fill","stem":"把 100 g 含氧化铁 80% 的赤铁矿石完全还原，理论上可得到铁 ______ g（假设其他成分不含铁，相对原子质量 Fe 56、O 16）。","answer":"56","explain":"矿石中纯氧化铁的质量为 100 g × 80% = 80 g；Fe₂O₃ 中铁元素的质量分数为 (56×2)÷(56×2 + 16×3) = 112/160 = 70%，所以可得到铁 80 g × 70% = 56 g。若直接把 100 g 当成氧化铁的质量，就会算成 70 g，这是含杂质计算最常见的错误。","difficulty":2,"tags":["含杂质计算","元素质量分数"]},{"id":"chem-substance-8-q8","type":"short","stem":"某炼铁厂用 2000 t 含氧化铁 70% 的赤铁矿石炼铁，假设氧化铁全部被还原，其他成分不含铁。求理论上可炼出纯铁多少吨？如果炼出的生铁中含铁 98%，可得生铁多少吨？（相对原子质量：Fe 56、O 16）","answer":"矿石中纯氧化铁的质量 = 2000 t × 70% = 1400 t。由 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂ 可知 m(Fe₂O₃)∶m(Fe) = 160∶112 = 10∶7，所以纯铁的质量 = 1400 t × 112/160 = 980 t。生铁的质量 = 980 t ÷ 98% = 1000 t。答：理论上可炼出纯铁 980 t，可得含铁 98% 的生铁 1000 t。","explain":"这道题是含杂质计算的「标准三步」：先按纯度把混合物质量换成纯物质质量，再用化学方程式（或元素质量分数）算出纯铁，最后按生铁的含铁量折算成生铁。三处常见错误：直接用 2000 t 列比例；算出 980 t 后当作生铁的质量；把「生铁质量 × 98%」与「纯铁质量 ÷ 98%」弄反。用反算验算一下（1000 t × 98% = 980 t）就能避免最后这个错误。","difficulty":3,"tags":["含杂质计算","铁的冶炼","化学方程式计算"],"rubric":["第一步按纯度换算出纯氧化铁 1400 t（不能直接用 2000 t）","Fe₂O₃ 与 Fe 的质量比 160∶112（或铁元素质量分数 70%）使用正确","求出纯铁质量 980 t","用「纯铁质量 ÷ 98%」求出所得生铁 1000 t，并写出带单位的答句"],"steps":["先把矿石换算成纯氧化铁：2000 t × 70% = 1400 t。","写出化学方程式：3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂（也可用 Fe₂O₃ 中铁元素的质量分数 70% 计算）。","由质量比 160∶112 求出纯铁：1400 t × 112/160 = 980 t。","求生铁质量：980 t ÷ 98% = 1000 t。","作答：纯铁 980 t，生铁 1000 t（并可用「生铁质量 × 98% = 980 t」反向验算）。"]},{"id":"chem-substance-8-q9","type":"short","stem":"请设计实验探究铁生锈的条件。写出你需要的器材、三组实验的条件设置、预期的现象和由此得出的结论。","answer":"器材：三支洁净的试管、三根用砂纸打磨光亮的铁钉、蒸馏水、植物油、干燥剂（如氯化钙）、橡皮塞。实验设置：试管①加少量水，使铁钉一半浸在水中、一半露在空气中（同时接触水和氧气）；试管②放入铁钉和干燥剂并塞紧，使铁钉处于干燥的空气中（只有氧气）；试管③加入煮沸后迅速冷却的蒸馏水浸没铁钉，水面上加一层植物油并塞紧（只有水，没有氧气）。现象：几天后只有试管①中的铁钉生锈，②③中的铁钉都不生锈。结论：铁生锈是铁与氧气和水同时接触发生缓慢氧化的结果，两个条件缺一不可；所以防锈的办法就是隔绝氧气或隔绝水（刷漆、涂油、镀金属、制成不锈钢等）。","explain":"设计对比实验的关键是「每一次只改变一个条件」：试管①是「水和氧气都有」，试管②是「只有氧气」，试管③是「只有水」。因此试管②必须放干燥剂并塞紧（除去水），试管③必须用煮沸的蒸馏水（除去溶解的氧气）并加植物油（隔绝空气）。实验需要放置几天，现象要写成「铁钉表面出现红棕色的铁锈」。由现象到结论再到防锈措施，是一条完整的答题链，缺一环就要扣分。","difficulty":3,"tags":["铁生锈的条件","实验探究","对比实验"],"rubric":["器材中体现「控制变量」的关键材料：蒸馏水（煮沸除氧）、植物油、干燥剂","三组条件设置写全：同时接触水和氧气、只有氧气、只有水","写出「水要煮沸并迅速冷却」与「加植物油隔绝空气」的目的","由现象（只有①生锈）得出结论「铁生锈是铁与氧气和水共同作用的结果」","由结论推出防锈措施：隔绝氧气或水，并举例（刷漆、涂油、镀金属、制成合金）"]},{"id":"chem-substance-8-q10","type":"short","stem":"请画出探究铁生锈条件的三支试管的对比实验装置图，并在每支试管旁用文字标注它所控制的条件（接触到的物质）。","answer":"画法：画出三支试管。试管①中画少量水，铁钉一半浸在水中、一半露在空气中，标注「同时接触水和氧气」；试管②中画一根铁钉并在管底画斜线阴影表示干燥剂，用橡皮塞塞紧，标注「只有氧气（放干燥剂）」；试管③中画浸没铁钉的蒸馏水，并在水面上画一层植物油，用橡皮塞塞紧，标注「只有水（煮沸除氧，植物油隔绝空气）」。在三支试管下方写出结论：只有①中的铁钉生锈，说明铁生锈需要同时接触氧气和水。","explain":"这道作图题考的是「把控制变量的思想画出来」：三支试管的差别必须一眼可见——①有水和空气、②只有空气（干燥剂）、③只有水（煮沸除氧 + 植物油）。常画错的地方有三处：试管②忘了画干燥剂或橡皮塞、试管③忘了画植物油层、以及把「煮沸」这个关键操作漏掉（不煮沸水中仍有溶解的氧气，实验就不成立）。标注文字要写在对应试管的旁边，与图形一一对应。","difficulty":2,"tags":["铁生锈的条件","作图题","对比实验"],"rubric":["画出三支试管并都放入洁净的铁钉","试管①：铁钉一半浸在水中，标注「同时接触水和氧气」","试管②：画出干燥剂（斜线阴影）与橡皮塞，标注「只有氧气」","试管③：画出植物油层与橡皮塞，标注「只有水」","在图上或图下写出结论：铁生锈是铁与氧气和水同时接触的结果"],"figure":{"id":"fig-chem-substance-8-q10","title":"待画的对比实验装置","caption":"请画出三支试管与铁钉，并标注每支试管控制的条件","view":"wide","alt":"画布上有三个虚线框，分别标注试管①②③，等待画出盛水或干燥剂的试管、铁钉以及对应的条件标注","prims":[{"t":"rect","x":6,"y":14,"w":28,"h":30,"dashed":true,"tone":"muted"},{"t":"rect","x":36,"y":14,"w":28,"h":30,"dashed":true,"tone":"muted"},{"t":"rect","x":66,"y":14,"w":28,"h":30,"dashed":true,"tone":"muted"},{"t":"text","x":20,"y":8,"text":"试管①","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":8,"text":"试管②","size":3.6,"tone":"accent"},{"t":"text","x":80,"y":8,"text":"试管③","size":3.6,"tone":"accent"},{"t":"text","x":20,"y":52,"text":"（画出铁钉与水）","size":3,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"（画出铁钉与干燥剂）","size":3,"tone":"muted"},{"t":"text","x":80,"y":52,"text":"（画出铁钉、蒸馏水与植物油）","size":3,"tone":"muted"}]},"answerFigure":{"id":"fig-chem-substance-8-q10-a","title":"参考答案：铁生锈条件的对比实验","caption":"只有同时接触水和氧气的试管①中铁钉生锈","view":"wide","alt":"三支试管：试管①铁钉一半浸在水中并接触空气、标注同时接触水和氧气；试管②铁钉放在有干燥剂的干燥空气中、标注只有氧气；试管③铁钉浸在煮沸的蒸馏水中并用植物油隔绝空气、标注只有水；下方写出结论","prims":[{"t":"testTube","x":18,"y":26,"h":28,"w":13,"liquid":0.5,"color":"colorless"},{"t":"line","x1":18,"y1":18,"x2":18,"y2":36,"width":1.5,"tone":"danger"},{"t":"text","x":18,"y":9,"text":"试管①","size":3.4,"tone":"accent"},{"t":"text","x":18,"y":46,"text":"水和氧气都有","size":3,"tone":"danger"},{"t":"text","x":18,"y":52,"text":"→ 铁钉生锈","size":3,"tone":"danger"},{"t":"testTube","x":50,"y":26,"h":28,"w":13,"color":"colorless"},{"t":"line","x1":50,"y1":18,"x2":50,"y2":36,"width":1.5},{"t":"hatch","x":45,"y":40,"w":10,"h":4,"gap":1.4},{"t":"text","x":50,"y":9,"text":"试管②","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":46,"text":"只有氧气（干燥剂）","size":3,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"→ 不生锈","size":3,"tone":"muted"},{"t":"testTube","x":82,"y":26,"h":28,"w":13,"liquid":0.6,"color":"colorless"},{"t":"line","x1":82,"y1":18,"x2":82,"y2":36,"width":1.5},{"t":"rect","x":76.2,"y":27.5,"w":11.6,"h":2.6,"fill":true,"tone":"accent"},{"t":"text","x":82,"y":9,"text":"试管③","size":3.4,"tone":"accent"},{"t":"text","x":82,"y":46,"text":"只有水（煮沸除氧","size":3,"tone":"muted"},{"t":"text","x":82,"y":52,"text":"+ 植物油隔绝空气）","size":3,"tone":"muted"},{"t":"text","x":50,"y":61,"text":"结论：铁生锈是铁与氧气和水同时接触的结果","size":3.2,"tone":"accent"}]}},{"id":"chem-substance-8-m1-q1","type":"short","stem":"（3 分）根据材料一，写出工业炼铁的原理（用化学方程式表示），并说明焦炭在高炉中的两个作用。","answer":"工业炼铁的原理：3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂。焦炭的两个作用：① 燃烧放出大量的热，为炼铁提供热量（C + O₂ —点燃→ CO₂）；② 与二氧化碳反应生成还原剂一氧化碳（CO₂ + C —高温→ 2CO）。","explain":"","rubric":["写出 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂，条件写「高温」并配平","答出焦炭燃烧放热、提供热量，最好配上方程式","答出焦炭与二氧化碳反应生成还原剂 CO，并写出 CO₂ + C —高温→ 2CO"]},{"id":"chem-substance-8-m1-q2","type":"short","stem":"（4 分）根据材料二的实验记录，说明铁生锈需要什么条件？试管③中的水为什么要先煮沸、还要在水面上加一层植物油？","answer":"由试管①生锈、试管②和③都不生锈，可以得出结论：铁生锈是铁与氧气和水同时接触发生缓慢氧化的结果，两个条件缺一不可。试管③中的水先煮沸是为了赶走水中溶解的氧气；在水面上加一层植物油是为了隔绝空气，防止空气中的氧气重新溶入水中。这样试管③中就只有水、没有氧气，才能说明「只有水时铁不生锈」。","explain":"","rubric":["由三支试管的对比得出「铁生锈需要同时接触氧气和水」","说明水煮沸的目的是除去水中溶解的氧气","说明加植物油的目的是隔绝空气（防止氧气溶入）","指出试管③是「只有水、没有氧气」的对照条件"]},{"id":"chem-substance-8-m1-q3","type":"short","stem":"（5 分）根据材料三计算：2000 t 含氧化铁 70% 的赤铁矿石理论上可炼出纯铁多少吨？可炼出含铁 98% 的生铁多少吨？（相对原子质量：Fe 56、O 16）","answer":"矿石中纯氧化铁的质量 = 2000 t × 70% = 1400 t。由 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂ 可知 m(Fe₂O₃)∶m(Fe) = 160∶112 = 10∶7。纯铁的质量 = 1400 t × 112/160 = 980 t（也可按 Fe₂O₃ 中铁元素的质量分数 70% 计算：1400 t × 70% = 980 t）。生铁的质量 = 980 t ÷ 98% = 1000 t。答：可炼出纯铁 980 t，可炼出含铁 98% 的生铁 1000 t。","explain":"","rubric":["先算出纯氧化铁的质量 1400 t（不能把 2000 t 直接代入）","写出炼铁方程式或算出 Fe₂O₃ 中铁元素的质量分数 70%","求出纯铁的质量 980 t","用「纯铁质量 ÷ 生铁中铁的质量分数」求生铁 1000 t","结果带单位并写出完整答句"]}]},{"id":"chem-substance-9","title":"物质的变化和性质：物理变化与化学变化·性质决定用途","subtitle":"人教版九年级 · 第一单元 走进化学世界 · 9a","grade":"9a","tags":["人教版九年级 · 第一单元 走进化学世界"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第一单元 走进化学世界 · 9a"},{"type":"note","title":"问题切入","text":"水结成冰、石蜡熔化、玻璃破碎，蜡烛燃烧、铁锅生锈、食物腐败——同样是「变」，为什么化学把它们分成两类？判断的依据到底是什么？为什么说「可燃性」是性质，而「正在燃烧」是变化？"},{"type":"note","title":"一句话抓住关键","text":"分类的依据只有一条：有没有新物质生成。没有新物质生成的是物理变化（只是形状、状态、位置变了），有新物质生成的是化学变化。化学变化常伴随发光、放热、变色、放出气体、生成沉淀，但这些现象都只是「伴随」，不能反过来当判据——灯泡发光、电炉丝发热都没有新物质生成。性质是物质固有的属性（句子里常有「能、会、易、可以」），变化是性质的具体表现（句子里常有「已经、正在、了」）。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"水结成冰、蜡熔化成液体、玻璃摔碎，这些「变」过后还是原来的物质；而蜡烛燃烧、铁锅生锈、食物腐败，变完之后就再也回不去了。化学要做的第一件事，就是分清这两种「变」。","walk":["物理变化没有新物质生成，只是形状、状态、位置改变；化学变化有新物质生成。判断的唯一标准就是「有没有新物质生成」。","性质是物质本身固有的属性，如可燃性、稳定性、酸碱性；变化是一个过程，如正在燃烧、正在生锈。描述性质常用「能、可以、易、会」。","性质决定用途，用途反映性质。铜导电所以做导线，氮气稳定所以可作保护气，这是化学最常见的思维方式。"],"try":"观察一支蜡烛燃烧：蜡烛受热熔化是物理变化，烛芯燃烧生成二氧化碳和水是化学变化，同一过程可以同时包含两种变化。","use":["判断题先问「有没有新物质生成」，再看颜色、发光、放热这些现象只是辅助。","答「性质决定用途」类题，按「因为具有某性质，所以可用于某用途」的句式写。"]},{"type":"h","text":"【宏观】宏观：给变化分类，只看有没有新物质生成"},{"type":"p","text":"把课本上的例子摆在一起看：水结冰、石蜡熔化、玻璃破碎、汽油挥发、铁水铸成锅，这些变化里物质还是原来的物质，只是形状、状态或位置变了，属于物理变化；蜡烛燃烧、铁锅生锈、食物腐败、镁条燃烧，这些变化里都生成了与原来不同的物质，属于化学变化。判断时只问一句话：有没有新物质生成？有就是化学变化，没有就是物理变化。发光、放热、变色、放出气体、生成沉淀是化学变化常常伴随的现象，不能拿它当判据。"},{"type":"figure","figure":{"id":"fig-chem-substance-9-1","title":"两类变化的判据：有没有新物质生成","caption":"左边的例子物质没变，右边的例子都生成了新物质","view":"wide","alt":"左右两个方框对比：左边写「物理变化：没有新物质生成」，例举水结冰、石蜡熔化、玻璃破碎、汽油挥发；右边写「化学变化：有新物质生成」，例举蜡烛燃烧、铁锅生锈、食物腐败、镁条燃烧","prims":[{"t":"rect","x":5,"y":8,"w":42,"h":40,"tone":"ok"},{"t":"text","x":26,"y":14,"text":"物理变化：没有新物质生成","size":3.8,"tone":"ok"},{"t":"text","x":10,"y":22,"text":"水结成冰、石蜡熔化","size":3.6},{"t":"text","x":10,"y":29,"text":"玻璃破碎、汽油挥发","size":3.6},{"t":"text","x":10,"y":36,"text":"铁水铸成锅、木材做成桌椅","size":3.6},{"t":"text","x":10,"y":43,"text":"形状、状态、位置变了，物质没变","size":3.4,"tone":"muted"},{"t":"rect","x":53,"y":8,"w":42,"h":40,"tone":"danger"},{"t":"text","x":74,"y":14,"text":"化学变化：有新物质生成","size":3.8,"tone":"danger"},{"t":"text","x":58,"y":22,"text":"蜡烛燃烧、镁条燃烧","size":3.6},{"t":"text","x":58,"y":29,"text":"铁锅生锈、食物腐败","size":3.6},{"t":"text","x":58,"y":36,"text":"石灰石与稀盐酸反应","size":3.6},{"t":"text","x":58,"y":43,"text":"常伴随发光、放热、变色、放出气体","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":55,"text":"判据只有一条：有没有新物质生成","size":4,"tone":"main"}]}},{"type":"note","title":"","text":"最容易错的是拿现象当判据：「有发光放热就是化学变化」——灯泡通电发光、电炉丝发热都是物理变化；「有气泡冒出就是化学变化」——水沸腾时冒的气泡只是水蒸气。反过来，化学变化也不一定有明显现象（铁生锈要几天才看得出来），所以最终还是要问「有没有新物质」。"},{"type":"h","text":"【宏观】宏观实验：点燃一支蜡烛，把两类变化一起看全"},{"type":"p","text":"点燃前先观察：蜡烛是白色（或红色）固体，质软、有气味、不溶于水、密度比水小（放入水中会浮起来）——这些都是物理性质。点燃后：火焰分三层，外焰温度最高，所以加热要用外焰；火焰周围的石蜡先熔化、再汽化，这是物理变化。把一只干冷的烧杯罩在火焰上方，烧杯内壁出现水雾，说明生成了水；把烧杯立即倒转过来，向其中注入少量澄清石灰水并振荡，石灰水变浑浊，说明生成了二氧化碳——这两条现象说明蜡烛燃烧是化学变化。熄灭蜡烛的一瞬间，烛芯上方冒出白烟，用点燃的火柴去点这股白烟，白烟竟然也能烧起来：因为它是石蜡蒸气冷凝成的石蜡固体小颗粒，不是水蒸气，也不是二氧化碳。"},{"type":"figure","figure":{"id":"fig-chem-substance-9-2","title":"对蜡烛及其燃烧的探究","caption":"干冷烧杯内壁出现水雾 → 有水生成；澄清石灰水变浑浊 → 有二氧化碳生成","view":"wide","alt":"一支点燃的蜡烛，火焰上方罩着一只干冷烧杯，烧杯内壁标出水雾；旁边一只试管里盛着澄清石灰水，箭头指向烧杯表示把石灰水倒入检验气体","prims":[{"t":"rect","x":30,"y":42,"w":12,"h":14,"fill":true,"tone":"muted"},{"t":"line","x1":36,"y1":42,"x2":36,"y2":38,"width":1},{"t":"poly","points":[[36,38],[33,32],[36,22],[39,32]],"closed":true,"tone":"accent"},{"t":"beaker","x":24,"y":10,"w":24,"h":20,"label":""},{"t":"text","x":36,"y":6,"text":"干冷烧杯（内壁有水雾）","size":3.4,"tone":"main","anchor":"middle"},{"t":"text","x":12,"y":12,"text":"水雾","size":3.4,"tone":"accent"},{"t":"text","x":36,"y":62,"text":"蜡烛（白色固体，密度比水小）","size":3.4,"tone":"muted","anchor":"middle"},{"t":"testTube","x":66,"y":24,"h":22,"liquid":0.6,"color":"colorless","tilt":0,"label":"澄清石灰水"},{"t":"arrow","x1":62,"y1":34,"x2":50,"y2":26,"tone":"danger"},{"t":"text","x":66,"y":56,"text":"变浑浊 → 有 CO₂ 生成","size":3.4,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":34,"text":"熄灭后的白烟可被点燃","size":3.4,"tone":"muted","anchor":"start"}]}},{"type":"note","title":"","text":"现象描述要按「变…了」的句式写：水雾是「烧杯内壁出现水雾」，二氧化碳是「澄清石灰水变浑浊」，不能写成「烧杯里有水」「石灰水是浑浊的」。另外「白烟」不能写成「白雾」：烟是固体小颗粒，雾是小液滴，白烟能被点燃正说明它是石蜡固体而不是水。"},{"type":"h","text":"【微观】微观：分子有没有被拆开，是两类变化的分水岭"},{"type":"p","text":"从粒子角度看，两类变化的区别一目了然。水结成冰只是水分子之间的间隔变小、排列变整齐了，水分子本身还是那个水分子，所以是物理变化；石蜡熔化、汽化同理，只是分子间隔和运动快慢变了。而蜡烛燃烧时，石蜡分子和氧分子一起被拆开成碳原子、氢原子和氧原子，这些原子重新组合成两种新的分子——二氧化碳分子和水分子，原来的石蜡分子、氧分子都不存在了，所以是化学变化。由此还能得到一条重要结论：在化学变化中，分子可以被拆开，原子却不能再分，反应前后原子的种类和个数都没有改变，这就是质量守恒的微观原因。"},{"type":"figure","figure":{"id":"fig-chem-substance-9-3","title":"水结冰与蜡烛燃烧在粒子层面的区别","caption":"左边分子本身没变（物理变化），右边分子被拆开重组（化学变化）","view":"wide","alt":"左框里水分子排列由疏到密、分子本身不变；右框里石蜡分子与氧分子被拆成原子，重新组合成二氧化碳分子和水分子","prims":[{"t":"rect","x":5,"y":8,"w":40,"h":34,"tone":"ok"},{"t":"molecule","x":14,"y":20,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":""},{"t":"molecule","x":26,"y":18,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":""},{"t":"molecule","x":34,"y":26,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red"},{"dx":2.6,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":""},{"t":"text","x":25,"y":13,"text":"水结成冰：分子间隔变小","size":3.4,"tone":"ok","anchor":"middle"},{"t":"text","x":25,"y":38,"text":"分子本身没变 → 物理变化","size":3.6,"tone":"ok","anchor":"middle"},{"t":"rect","x":53,"y":8,"w":42,"h":34,"tone":"danger"},{"t":"molecule","x":62,"y":18,"atoms":[{"dx":-2.6,"dy":0,"symbol":"C"},{"dx":2.6,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"石蜡分子"},{"t":"text","x":74,"y":18,"text":"＋ O₂","size":3.4,"anchor":"start"},{"t":"arrow","x1":66,"y1":26,"x2":74,"y2":26,"tone":"danger"},{"t":"molecule","x":66,"y":34,"atoms":[{"dx":-2.6,"dy":0,"symbol":"C"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":-2.6,"symbol":"O","color":"red"}],"bonds":[[0,1],[0,2]],"label":""},{"t":"text","x":74,"y":34,"text":"＋ H₂O","size":3.4,"anchor":"start"},{"t":"text","x":74,"y":12,"text":"燃烧：分子被拆开、原子重新组合","size":3.4,"tone":"danger","anchor":"middle"},{"t":"text","x":74,"y":38,"text":"生成新分子 → 化学变化","size":3.6,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":51,"text":"化学变化中分子可分、原子不可分：反应前后原子的种类和个数都不变","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"「分子是保持物质化学性质的最小粒子」这句话是有前提的：只对由分子构成的物质成立。铁、铜、氯化钠这些由原子或离子构成的物质，保持其化学性质的最小粒子分别是原子、离子，答题时不要一概而论。"},{"type":"h","text":"【符号】符号：变化写成式子，性质说成「能、会、易」"},{"type":"p","text":"变化用式子记录：镁条燃烧写成「2Mg + O₂ —点燃→ 2MgO」，蜡烛燃烧写成「石蜡 + O₂ —点燃→ CO₂ + H₂O」（石蜡是混合物，没有固定的化学式，初中阶段直接用「石蜡」写，不要求配平）。性质与变化的语言必须分开：说「蜡烛能燃烧」「铁在潮湿空气中易生锈」是在描述性质，说「蜡烛正在燃烧」「铁钉已经生锈了」是在描述变化；性质决定用途，用途反过来反映性质——铜有良好的导电性所以做导线，金刚石硬度大所以做钻头，石墨有导电性所以做电极。"},{"type":"figure","figure":{"id":"fig-chem-substance-9-4","title":"性质与变化的语言区别","caption":"同一个词，加上「能、会、易」是性质，加上「正在、已经」是变化","view":"wide","alt":"上下两行对照：第一行「性质」列出可燃性、稳定性、氧化性、导电性并注明句子里常有「能、会、易」；第二行「变化」列出燃烧、生锈、变质、熔化并注明句子里常有「正在、已经、了」","prims":[{"t":"rect","x":6,"y":10,"w":88,"h":16,"tone":"main"},{"t":"text","x":10,"y":16,"text":"性质（物质固有的属性）","size":3.8,"tone":"main"},{"t":"text","x":10,"y":23,"text":"可燃性、稳定性、氧化性、酸性、碱性、导电性、挥发性","size":3.6},{"t":"text","x":62,"y":16,"text":"句子里常有","size":3.4,"tone":"muted"},{"t":"text","x":62,"y":23,"text":"「能、会、易、可以」","size":3.6,"tone":"accent"},{"t":"rect","x":6,"y":32,"w":88,"h":16,"tone":"accent"},{"t":"text","x":10,"y":38,"text":"变化（正在发生的事）","size":3.8,"tone":"accent"},{"t":"text","x":10,"y":45,"text":"燃烧、生锈、腐败、熔化、汽化、破碎","size":3.6},{"t":"text","x":62,"y":38,"text":"句子里常有","size":3.4,"tone":"muted"},{"t":"text","x":62,"y":45,"text":"「正在、已经、了」","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"性质决定用途，用途反映性质：导电性 → 做导线；硬度大 → 做钻头","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"答题时的固定写法：由用途说性质要写出「物质—性质—用途」三件套，例如「铜有良好的导电性，所以用来做导线」，只写「铜能做导线」得不到完整的分。"},{"type":"h","text":"应用 · 给一列变化分类：物理变化还是化学变化"},{"type":"note","title":"情境","text":"把下列变化分成两类：①铁水铸成锅 ②铁锅生锈 ③石蜡熔化 ④蜡烛燃烧 ⑤玻璃破碎 ⑥食物腐败 ⑦汽油挥发 ⑧镁条在空气中燃烧。"},{"type":"list","title":"解答步骤","items":["逐条写出「变化后还是不是原来的物质」：①铁还是铁 ③石蜡还是石蜡 ⑤玻璃还是玻璃 ⑦汽油还是汽油。","找有新物质生成的：②铁 → 铁锈 ④石蜡 → 水 + 二氧化碳 ⑥食物 → 腐败产物 ⑧镁 → 氧化镁。","按有无新物质分成两组，并检查有没有把「伴随现象」当判据。"]},{"type":"note","title":"结论","text":"物理变化：①③⑤⑦；化学变化：②④⑥⑧。判断依据统一写成「有没有新物质生成」。"},{"type":"h","text":"应用 · 由用途推性质：性质决定用途"},{"type":"note","title":"情境","text":"为什么用铜做导线、用金刚石做钻头、用石墨做电极、用氦气填充探空气球？请分别说出用到的性质，并指出它属于物理性质还是化学性质。"},{"type":"list","title":"解答步骤","items":["铜做导线 → 用到的性质是良好的导电性（物理性质）。","金刚石做钻头 → 硬度很大（物理性质）。","石墨做电极 → 有良好的导电性、化学性质稳定（前者是物理性质，后者是化学性质）。","氦气填充气球 → 密度比空气小且化学性质很不活泼（不燃、不助燃，比氢气安全）。"]},{"type":"note","title":"结论","text":"回答模板：某物质具有某性质（物理／化学性质），所以可以用于某用途。只写用途不写性质不给分。"},{"type":"h","text":"实验 1 · 对蜡烛及其燃烧的探究"},{"type":"note","title":"实验目的","text":"用观察与实验区分蜡烛的物理性质、物理变化与化学变化，并检验燃烧产物"},{"type":"list","title":"实验器材","items":["蜡烛","火柴","干冷烧杯","澄清石灰水","小刀","水槽"]},{"type":"figure","figure":{"id":"fig-chem-substance-9-exp1","title":"检验蜡烛燃烧的产物","caption":"干冷烧杯检验水，澄清石灰水检验二氧化碳","view":"wide","alt":"一支点燃的蜡烛上方罩着干冷烧杯，烧杯内壁出现水雾；旁边一只试管盛澄清石灰水，用于检验生成的二氧化碳","prims":[{"t":"rect","x":26,"y":46,"w":10,"h":12,"fill":true,"tone":"muted"},{"t":"line","x1":31,"y1":46,"x2":31,"y2":42,"width":1},{"t":"poly","points":[[31,42],[28,36],[31,26],[34,36]],"closed":true,"tone":"accent"},{"t":"beaker","x":20,"y":12,"w":22,"h":20},{"t":"text","x":31,"y":8,"text":"干冷烧杯","size":3.4,"anchor":"middle"},{"t":"text","x":8,"y":66,"text":"内壁水雾 → 有水生成","size":3.6,"tone":"accent"},{"t":"testTube","x":62,"y":26,"h":24,"liquid":0.6,"color":"colorless","tilt":0,"label":"澄清石灰水"},{"t":"text","x":62,"y":62,"text":"变浑浊 → 有 CO₂ 生成","size":3.6,"tone":"danger","anchor":"middle"},{"t":"arrow","x1":46,"y1":34,"x2":56,"y2":34,"tone":"main"},{"t":"text","x":31,"y":62,"text":"外焰温度最高","size":3.4,"tone":"muted","anchor":"middle"}]}},{"type":"list","title":"实验步骤","items":["点燃前观察蜡烛的颜色、状态、气味，用小刀切下一小块放入水中，观察它是沉还是浮。","点燃蜡烛，观察火焰的层次与颜色，用一根火柴梗平放在火焰中约 1 秒后取出，比较各层的炭化程度。","把一只干冷的烧杯罩在火焰上方，观察烧杯内壁的变化。","把烧杯迅速倒转过来，注入少量澄清石灰水并振荡，观察石灰水的变化。","熄灭蜡烛，立即用点燃的火柴去点烛芯上方的白烟，观察现象。"]},{"type":"note","title":"实验现象","text":"点燃前：白色固体、质软、有气味、浮在水面上（密度比水小）、不溶于水。燃烧时：发出黄白色火焰，放出热量，火柴梗在外焰处最先变黑（外焰温度最高）。干冷烧杯内壁出现水雾；澄清石灰水变浑浊。熄灭后的白烟能被点燃，火焰顺着白烟又回到烛芯。"},{"type":"note","title":"实验结论","text":"石蜡熔化、汽化是物理变化；石蜡燃烧生成水和二氧化碳，是化学变化。蜡烛的燃烧产物是水和二氧化碳，可用干冷烧杯与澄清石灰水分别检验。"},{"type":"list","title":"注意事项","items":["罩在火焰上方的烧杯必须是干冷的，否则内壁原有的水珠会干扰「有水生成」的判断。","检验二氧化碳要在火焰熄灭后立即进行，倒转烧杯时动作要快，避免气体逸散。","「白烟」是石蜡蒸气冷凝成的固体小颗粒，不是水蒸气也不是二氧化碳；写成「白雾」是概念性错误。","实验在通风处进行，熄灭蜡烛用灯帽或吹灭后不要用手直接触摸熔化的石蜡，避免烫伤。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2Mg + O₂ —点燃→ 2MgO","点燃","镁条剧烈燃烧，发出耀眼的白光，放出大量的热，生成白色固体","配平核对：左边 2 个镁原子、2 个氧原子，右边 2MgO 里同样是 2 个镁原子、2 个氧原子。生成白色固体氧化镁是「有新物质生成」的直接证据——变化前后物质不同，所以镁条燃烧是化学变化。"],["石蜡 + O₂ —点燃→ CO₂ + H₂O","点燃","发出黄白色火焰，放出热量；干冷烧杯内壁出现水雾，澄清石灰水变浑浊","石蜡是混合物、没有固定化学式，初中阶段直接用「石蜡」写在式子里，不需要配平。判断产物的依据全在现象上：水雾说明生成水，石灰水变浑浊说明生成二氧化碳——这也是「产物检验」这类实验题的固定套路。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["有发光、放热现象的变化一定是化学变化","判断依据只有「有没有新物质生成」，发光放热只是伴随现象","灯泡通电发光、电炉丝发热、白炽灯丝变亮都没有新物质生成，是物理变化；而铁生锈这样的化学变化反而不发光、不放热（放热很缓慢，察觉不到）。拿伴随现象当判据，两头都会判错。"],["熄灭蜡烛后冒出的白烟是水蒸气","白烟是石蜡蒸气冷凝成的石蜡固体小颗粒，能被点燃","蜡烛熄灭的瞬间温度下降，烛芯附近汽化的石蜡蒸气冷凝成极细的固体小颗粒，就形成「白烟」。它由石蜡组成，所以能被点燃并顺着白烟把火焰引回烛芯。水蒸气是无色透明的，看不见，也不会燃烧；写成「白雾」则把它误当成了小液滴。"],["物理性质就是不发生化学变化时表现出来的性质，所以「不溶于水」不是物理性质","溶解性属于物理性质，性质与「是否发生化学变化」无关","物质的性质分两类：不需要发生化学变化就能表现出来的（颜色、状态、气味、熔点、沸点、硬度、密度、溶解性、挥发性、导电性、导热性）叫物理性质；只有在化学变化中才能表现出来的（可燃性、氧化性、还原性、稳定性、酸性、碱性、毒性）叫化学性质。判断标准是「要不要发生化学变化才能体现」，不是「变化本身属哪一类」。"]]},{"type":"table","title":"物理变化与化学变化（两类变化的本质区别与判断要点）","head":["比较项","物理变化","化学变化"],"rows":[["本质区别","没有新物质生成","有新物质生成"],["常见实例","水结冰、石蜡熔化、玻璃破碎、汽油挥发、铁水铸锅","蜡烛燃烧、铁锅生锈、食物腐败、镁条燃烧"],["伴随现象","形状、状态、位置改变，一般无明显其他现象","常伴随发光、放热、变色、放出气体、生成沉淀"],["微观解释","分子本身不变，只是间隔和运动快慢改变","分子被拆成原子，原子重新组合成新分子"],["联系的例子","石蜡先受热熔化（物理变化）","汽化的石蜡蒸气再燃烧（化学变化）"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["变化类型的判断","给出一组生活或实验中的变化，要求分类并说明依据。评分点落在「有／没有新物质生成」这句话上；只写「因为它是物理变化」属于循环论证，不给分。常见陷阱：把灯泡发光、水沸腾冒气泡、汽油挥发误判为化学变化。"],["性质与变化的语言辨析","给出一句话判断它描述的是性质还是变化，或是把用途与性质对应起来。判分关键是句中的标志词：「能、会、易、可以」是性质，「正在、已经、了」是变化；由用途说性质要写出「物质—性质—用途」三件套。"],["对蜡烛及其燃烧的探究","实验探究题的高频起点：考查点燃前的物理性质、火焰分层与温度、燃烧产物的检验方法（干冷烧杯验水、澄清石灰水验二氧化碳）、白烟的本质。常与「现象描述规范」一起考，写成「烧杯里有水」「石灰水是浑浊的」都要扣分。"]]},{"type":"quote","text":"【材料一】化学变化常伴随能量变化。镁条燃烧时发出耀眼的白光并放出大量的热，这些能量来自物质内部储存的化学能；反过来，给水通电，电能又可以让水分解成氢气和氧气。\n【材料二】小华做了三组实验：①把一段铁丝放入盛有干燥空气的试管中密封放置一周，铁丝表面没有明显变化；②把同样的铁丝放入盛有少量水的试管中（铁部分浸在水中），一周后铁丝表面出现红棕色锈迹；③把铁丝完全浸没在煮沸后迅速冷却的蒸馏水中并滴一层植物油密封，一周后铁丝依然光亮。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】结合材料一说明：物理变化与化学变化在能量上有什么共同点？为什么不能说「有能量变化的变化就是化学变化」？（3 分）","【设问】材料二中三组实验的变量是什么？由①②③得出的结论是什么？铁丝生锈属于哪一类变化？（3 分）"]}],"questions":[{"id":"chem-substance-9-q1","type":"choice","stem":"下列变化中，属于化学变化的是","answer":"C","explain":"化学变化的判据是有没有新物质生成。铁锅生锈生成了铁锈这一新物质，属于化学变化；冰雪融化（水→水）、汽油挥发（液态→气态）、玻璃破碎（形状改变）都只是状态或形状变化，物质本身没变，属于物理变化。","options":["冰雪融化","汽油挥发","铁锅生锈","玻璃破碎"],"difficulty":1,"tags":["物理变化与化学变化"]},{"id":"chem-substance-9-q2","type":"choice","stem":"下列现象中，一定发生了化学变化的是","answer":"D","explain":"灯泡发光、电炉丝发热只是电能转化为光能和热能，没有新物质生成；木材制成桌椅只改变了形状。石灰石与稀盐酸反应生成了二氧化碳等新物质，产生气泡正是新物质生成的表现，属于化学变化。A、B 两项专门用来考查「发光放热不等于化学变化」。","options":["灯泡通电发光","电炉丝发热变红","木材制成桌椅","石灰石与稀盐酸接触后产生气泡"],"difficulty":2,"tags":["物理变化与化学变化","现象与本质"]},{"id":"chem-substance-9-q3","type":"choice","stem":"下列关于物质性质的说法中，描述的是化学性质的是","answer":"C","explain":"化学性质只有在化学变化中才能表现出来。镁能在空气中燃烧（可燃性）需要发生化学变化才能体现，属于化学性质；紫红色固体（颜色、状态）、不易溶于水（溶解性）、能导电（导电性）都不需要发生化学变化就能表现，属于物理性质。「能」只是性质句式的标志，不能据此判成化学性质。","options":["铜是紫红色固体","氧气不易溶于水","镁能在空气中燃烧","石墨能导电"],"difficulty":2,"tags":["物理性质与化学性质","性质与变化"]},{"id":"chem-substance-9-q4","type":"choice","stem":"用小刀切下一小块石蜡放入水中，石蜡浮在水面上。这一操作能得出的结论是","answer":"A","explain":"浮在水面上说明石蜡的密度比水小，这是不需要发生化学变化就能表现出的性质，属于物理性质，A 正确。石蜡不溶于水同样是物理性质，B 错；本操作中石蜡只是形状和位置变化，没有新物质生成，C 错；能浮起来与硬度无关，D 错。","options":["石蜡的密度比水小，属于物理性质","石蜡不溶于水，属于化学性质","石蜡发生了化学变化","石蜡的硬度比水大"],"difficulty":2,"tags":["物理性质与化学性质","蜡烛探究"]},{"id":"chem-substance-9-q5","type":"choice","stem":"熄灭蜡烛时，烛芯上方会冒出一股白烟。关于这股白烟，下列说法正确的是","answer":"B","explain":"白烟能被点燃、火焰顺着它回到烛芯，说明它的成分仍是石蜡，只是石蜡蒸气冷凝成了极细的固体小颗粒。水蒸气无色透明看不见、不能燃烧；二氧化碳也不能燃烧；石蜡是完全燃烧的，不留下灰烬。判断依据就落在「白烟能点燃」这条现象上。","options":["是水蒸气，遇冷凝结成的小水滴","是石蜡蒸气冷凝成的石蜡固体小颗粒，可以被点燃","是石蜡燃烧生成的二氧化碳","是石蜡完全燃烧后留下的灰烬"],"difficulty":3,"tags":["蜡烛探究","白烟"]},{"id":"chem-substance-9-q6","type":"fill","stem":"把下列描述按「性质」或「变化」归类，填在横线上：①酒精能燃烧 ②水结成冰 ③铁在潮湿空气中易生锈 ④蜡烛正在燃烧。属于性质的是________，属于变化的是________。","answer":"①③；②④","explain":"「能、易」是性质的标志词：「酒精能燃烧」（可燃性）、「铁在潮湿空气中易生锈」都是在描述物质固有的属性；「结成了冰」「正在燃烧」描述的是正在发生的过程，属于变化。这两句话里的动词形式就是判断依据。","difficulty":2,"tags":["性质与变化"]},{"id":"chem-substance-9-q7","type":"fill","stem":"判断一个变化是物理变化还是化学变化，依据是________；在化学变化中，________可以被拆开，________不能再分，因此反应前后原子的种类和个数都不变。","answer":"有没有新物质生成；分子；原子","explain":"分类判据只有一条，就是有没有新物质生成，不能拿发光、放热、变色等现象当依据。微观上化学变化中分子被拆成原子，原子重新组合成新分子，原子本身不再分，这正是质量守恒的微观原因。","difficulty":2,"tags":["物理变化与化学变化","分子与原子"]},{"id":"chem-substance-9-q8","type":"short","stem":"小明用一只干冷的烧杯罩在蜡烛火焰上方，发现烧杯内壁出现水雾；接着他立即把烧杯倒转过来，注入少量澄清石灰水并振荡，石灰水变浑浊。请回答：(1) 这两个现象分别说明蜡烛燃烧生成了什么物质？(2) 由此能说明蜡烛燃烧属于哪一类变化？为什么？(3) 实验中对烧杯有什么要求？为什么？","answer":"(1) 内壁出现水雾说明生成了水，澄清石灰水变浑浊说明生成了二氧化碳。(2) 蜡烛燃烧生成了水与二氧化碳两种新物质，所以属于化学变化。(3) 烧杯必须是干冷的，否则烧杯内壁原有的水珠会与生成的水混在一起，无法判断水雾是不是燃烧产生的。","explain":"产物检验的固定套路：水用干冷烧杯（看到水雾），二氧化碳用澄清石灰水（变浑浊）。判断变化类型仍然回到「有没有新物质生成」这一条。控制变量思想体现在「干冷」二字上：必须排除烧杯自带水珠的干扰，否则结论不成立。","difficulty":3,"tags":["蜡烛探究","产物检验","物理变化与化学变化"],"rubric":["答出「水雾说明有水生成」","答出「石灰水变浑浊说明有二氧化碳生成」","由新物质生成判断为化学变化","答出干冷烧杯是为了排除原有水珠的干扰"],"figure":{"id":"fig-chem-substance-9-q8","title":"检验蜡烛燃烧产物的实验","caption":"干冷烧杯内壁出现水雾；澄清石灰水变浑浊","view":"wide","alt":"点燃的蜡烛上方罩着一只干冷烧杯，内壁出现水雾；旁边的烧杯里盛着澄清石灰水，用来检验二氧化碳","prims":[{"t":"rect","x":24,"y":44,"w":10,"h":12,"fill":true,"tone":"muted"},{"t":"line","x1":29,"y1":44,"x2":29,"y2":40,"width":1},{"t":"poly","points":[[29,40],[26,34],[29,24],[32,34]],"closed":true,"tone":"accent"},{"t":"beaker","x":18,"y":10,"w":22,"h":20},{"t":"text","x":29,"y":6,"text":"干冷烧杯","size":3.4,"anchor":"middle"},{"t":"text","x":6,"y":62,"text":"水雾 → 有水生成","size":3.6,"tone":"accent"},{"t":"beaker","x":62,"y":26,"w":22,"h":20,"fill":0.5},{"t":"text","x":73,"y":22,"text":"澄清石灰水","size":3.4,"anchor":"middle"},{"t":"text","x":62,"y":62,"text":"变浑浊 → 有 CO₂ 生成","size":3.6,"tone":"danger","anchor":"middle"}]}},{"id":"chem-substance-9-q9","type":"short","stem":"请设计实验证明蜡烛燃烧生成水和二氧化碳，并画出实验装置示意图。写出实验步骤、观察到的现象与结论。","answer":"见参考答案图：把一只干冷的小烧杯罩在蜡烛火焰上方（或将玻璃片放在火焰上方），观察内壁是否出现水雾；随后立即把烧杯倒转，注入少量澄清石灰水并振荡，观察是否变浑浊。现象：烧杯内壁出现水雾，澄清石灰水变浑浊。结论：蜡烛燃烧生成了水和二氧化碳，属于化学变化。","explain":"设计实验要交代三件事：用什么装置、怎么操作、看什么现象。水用干冷烧杯（不能用湿烧杯，否则无法区分），二氧化碳用澄清石灰水；两步要在火焰熄灭后立即进行，防止气体逸散。装置示意要画清火焰、烧杯与石灰水三者的位置关系，并注明「干冷」。","difficulty":3,"tags":["实验设计","蜡烛探究","作图"],"rubric":["装置：干冷烧杯罩在火焰上方，并注明「干冷」（1 分）","操作与现象：内壁出现水雾说明有水生成（1 分）","操作与现象：澄清石灰水变浑浊说明有二氧化碳生成（1 分）","结论：生成水和二氧化碳，属于化学变化（1 分）"],"answerFigure":{"id":"fig-chem-substance-9-q9-ans","title":"参考答案：检验蜡烛燃烧产物的装置","caption":"干冷烧杯验水，澄清石灰水验二氧化碳","view":"wide","alt":"点燃的蜡烛上方罩着干冷烧杯，烧杯内壁有水雾；另一只烧杯中盛澄清石灰水，箭头表示把石灰水倒入检验","prims":[{"t":"rect","x":22,"y":46,"w":10,"h":12,"fill":true,"tone":"muted"},{"t":"line","x1":27,"y1":46,"x2":27,"y2":42,"width":1},{"t":"poly","points":[[27,42],[24,36],[27,26],[30,36]],"closed":true,"tone":"accent"},{"t":"beaker","x":16,"y":12,"w":22,"h":20},{"t":"text","x":27,"y":8,"text":"干冷烧杯","size":3.4,"anchor":"middle"},{"t":"text","x":6,"y":64,"text":"内壁水雾","size":3.4,"tone":"accent"},{"t":"arrow","x1":44,"y1":34,"x2":58,"y2":34,"tone":"main"},{"t":"testTube","x":64,"y":24,"h":24,"liquid":0.55,"color":"colorless","tilt":0,"label":"澄清石灰水"},{"t":"text","x":64,"y":64,"text":"变浑浊 → CO₂","size":3.6,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":14,"text":"火焰熄灭后立即检验","size":3.4,"tone":"muted","anchor":"middle"}]}},{"id":"chem-substance-9-q10","type":"short","stem":"实验课上，老师把一小块石灰石放进盛有稀盐酸的试管中，看到石灰石表面产生大量气泡。小明说：「有气泡冒出，所以这是化学变化。」小华说：「冒气泡只能说明有气体产生，还不足以判断变化类型。」请判断谁的说法更严密，并说明理由；再写出这一步操作中能证明化学变化的证据。","answer":"小华的说法更严密。冒出气泡只能说明有气体产生，水受热沸腾时同样会冒气泡，但那只是水由液态变成气态，属于物理变化。要判断化学变化，必须确认生成了新物质：石灰石与稀盐酸反应生成了二氧化碳等新物质（把产生的气体通入澄清石灰水，石灰水变浑浊），这才是化学变化的证据。","explain":"这是一道关于「判据」的说理题，考的是不把伴随现象当依据。答题分三步：先亮明谁更严密，再指出气泡为什么不能当判据（举出水沸腾的例子），最后给出真正能证明化学变化的证据（产物是新物质，可用澄清石灰水检验）。","difficulty":3,"tags":["物理变化与化学变化","实验现象与结论"],"rubric":["指出小华的说法更严密（1 分）","说明气泡只是现象、水沸腾也能冒气泡（1 分）","给出新物质证据：气体使澄清石灰水变浑浊（1 分）"],"steps":["第一步：亮明观点——小华的说法更严密。","第二步：说明理由——气泡只是伴随现象，水沸腾时也冒气泡，且没有新物质生成。","第三步：给出证据——把气体通入澄清石灰水，石灰水变浑浊，说明生成了二氧化碳这一新物质。","第四步：下结论——有新物质生成，故属于化学变化。"]},{"id":"chem-substance-9-m1-q1","type":"short","stem":"结合材料一说明：物理变化与化学变化在能量上有什么共同点？为什么不能说「有能量变化的变化就是化学变化」？（3 分）","answer":"两类变化都常常伴随能量变化：化学变化中化学能可以转化为光能、热能（镁条燃烧），也可以由电能转化为化学能（电解水）；物理变化同样可以有能量变化，例如水沸腾要吸热、灯泡通电把电能转化为光能和热能。因此能量变化不是化学变化的判据，判断依据仍然是有没有新物质生成。","explain":"","tags":["物理变化与化学变化","能量变化"],"rubric":["指出两类变化都可能伴随能量变化（1 分）","举出一个物理变化伴随能量变化的实例（1 分）","明确判据是有没有新物质生成（1 分）"]},{"id":"chem-substance-9-m1-q2","type":"short","stem":"材料二中三组实验的变量是什么？由①②③得出的结论是什么？铁丝生锈属于哪一类变化？（3 分）","answer":"变量是水（潮湿程度）：①干燥空气、②有水、③隔绝氧气与水。①②对比说明铁丝生锈需要水，②③对比说明生锈还需要氧气；结论是铁在与水和氧气同时接触时容易生锈。铁锈是新物质（主要成分是氧化铁），所以铁丝生锈属于化学变化，只是进行得很缓慢。","explain":"","tags":["铁生锈","对比实验","物理变化与化学变化"],"rubric":["说出变量是水（潮湿程度）或同时有氧气与水（1 分）","由对比得出结论：铁生锈需要与氧气和水同时接触（1 分）","判断为化学变化并说明有新物质生成（1 分）"]}]},{"id":"chem-substance-10","title":"燃烧与灭火·化石燃料：条件、原理与能源","subtitle":"人教版九年级 · 第七单元 燃料及其利用 · 9a","grade":"9a","tags":["人教版九年级 · 第七单元 燃料及其利用"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第七单元 燃料及其利用 · 9a"},{"type":"note","title":"问题切入","text":"为什么有的物质一点就着，有的却怎么也点不着？灭火时为什么可以「盖、喷、移」三招齐用？煤、石油、天然气为什么叫化石燃料，它们烧完以后又给空气留下了什么？"},{"type":"note","title":"一句话抓住关键","text":"燃烧需要三个条件同时满足：有可燃物、有氧气（或空气）、温度达到可燃物的着火点。灭火只要破坏其中任意一个条件：清除或隔离可燃物、隔绝氧气、把温度降到着火点以下。化石燃料是煤、石油、天然气，属于不可再生能源，燃烧会带来二氧化碳（温室效应）、二氧化硫与氮的氧化物（酸雨）和烟尘等环境问题。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"点篝火要三样东西：能烧的木头、足够的空气、把温度升到着火点。灭火也一样，只要破坏其中任何一个条件，火就烧不起来。","walk":["燃烧的三个条件缺一不可：可燃物、与氧气（或空气）接触、温度达到着火点。","灭火三招对应三个条件：清除可燃物、隔绝氧气、降低温度到着火点以下。用水浇是降温，用锅盖盖是隔绝氧气，砍隔离带是清除可燃物。","化石燃料包括煤、石油、天然气，属于不可再生能源，燃烧会产生二氧化碳、二氧化硫、氮氧化物和烟尘，带来温室效应和酸雨。"],"try":"点燃一支蜡烛，用玻璃杯罩住，观察火焰逐渐变小直到熄灭，体会「隔绝氧气」这一招。","use":["灭火题必须写「破坏了哪个燃烧条件」，只写「灭火了」不得分。","燃料题从「热值高、污染小、可再生」三个角度比较，答新能源优点时别只写「环保」。"]},{"type":"h","text":"【宏观】宏观：三个条件缺一不可，灭火就是破坏其中一个"},{"type":"p","text":"把一张纸、一根木条和一块煤分别放在空气中点燃：纸最容易着，煤最难着——它们的着火点不同。再给燃烧的三个条件做「减法」：抽走可燃物（森林火灾打出隔离带）、隔绝氧气（用锅盖盖灭油锅、用湿抹布扑盖）、把温度降到着火点以下（用水浇、用干粉灭火器）——任何一个条件被破坏，燃烧就无法继续。要特别注意：着火点是物质本身的属性，灭火时降低的是温度，不是着火点，「降低着火点」是错误说法。"},{"type":"figure","figure":{"id":"fig-chem-substance-10-1","title":"燃烧的三个条件与对应的灭火方法","caption":"三个条件同时满足才能燃烧；灭火只需破坏其中任意一个","view":"wide","alt":"上方三个方框分别写出燃烧的三个条件：可燃物、氧气或空气、温度达到着火点；下方三个方框写出对应的灭火做法：清除或隔离可燃物、隔绝氧气、降温到着火点以下","prims":[{"t":"text","x":50,"y":8,"text":"燃烧的三个条件（必须同时满足）","size":3.8,"tone":"main","anchor":"middle"},{"t":"rect","x":6,"y":12,"w":27,"h":12,"tone":"main"},{"t":"text","x":19,"y":19,"text":"可燃物","size":3.6},{"t":"rect","x":37,"y":12,"w":27,"h":12,"tone":"main"},{"t":"text","x":50,"y":19,"text":"氧气（或空气）","size":3.6},{"t":"rect","x":68,"y":12,"w":27,"h":12,"tone":"main"},{"t":"text","x":81,"y":19,"text":"温度达到着火点","size":3.6},{"t":"arrow","x1":19,"y1":25,"x2":19,"y2":32,"tone":"danger"},{"t":"arrow","x1":50,"y1":25,"x2":50,"y2":32,"tone":"danger"},{"t":"arrow","x1":81,"y1":25,"x2":81,"y2":32,"tone":"danger"},{"t":"rect","x":6,"y":32,"w":27,"h":12,"tone":"danger"},{"t":"text","x":19,"y":39,"text":"清除或隔离可燃物","size":3.4},{"t":"rect","x":37,"y":32,"w":27,"h":12,"tone":"danger"},{"t":"text","x":50,"y":39,"text":"隔绝氧气","size":3.4},{"t":"rect","x":68,"y":32,"w":27,"h":12,"tone":"danger"},{"t":"text","x":81,"y":39,"text":"降温到着火点以下","size":3.4},{"t":"text","x":50,"y":52,"text":"着火点是物质本身的属性，灭火降低的是温度，不是着火点","size":3.8,"tone":"accent","anchor":"middle"}]}},{"type":"note","title":"","text":"举例答题时要「做法 + 原理」一起写：用锅盖盖灭油锅，是因为隔绝了氧气（同时盖上后热量不易散失，但主要原理是隔绝氧气）；用水浇灭木柴，是因为水吸热使温度降到木柴的着火点以下。只写做法不写原理，通常只得一半分。"},{"type":"h","text":"【宏观】宏观实验：用白磷与红磷做对照，把条件一个个试出来"},{"type":"p","text":"在盛有热水的烧杯上放一片薄铜片，铜片的一侧放一小块白磷、另一侧放一小块红磷。现象是：铜片上的白磷燃烧起来，铜片上的红磷不燃烧，水中的白磷也不燃烧。再把氧气通到水中的白磷附近，水中的白磷立刻燃烧。三次对照把条件试得很清楚：白磷与红磷的差别在于着火点不同（白磷约 40 ℃、红磷约 240 ℃），说明「温度达到着火点」是必要条件；水中白磷缺氧气不燃、通氧气后燃烧，说明「氧气」是必要条件。"},{"type":"figure","figure":{"id":"fig-chem-substance-10-2","title":"探究燃烧条件的实验","caption":"白磷与红磷的对照说明「着火点」，水中白磷通氧气前后对照说明「需要氧气」","view":"wide","alt":"盛有热水的烧杯上放着一片铜片，铜片左端放白磷、右端放红磷；水底另有一块白磷，导管通入氧气后水中的白磷燃烧","prims":[{"t":"beaker","x":14,"y":30,"w":40,"h":26,"fill":0.7,"label":"热水"},{"t":"rect","x":12,"y":26,"w":44,"h":3,"fill":true,"tone":"muted"},{"t":"circle","cx":20,"cy":23,"r":3.4,"fill":true,"tone":"accent"},{"t":"text","x":20,"y":16,"text":"白磷（燃烧）","size":3.4,"tone":"accent","anchor":"middle"},{"t":"circle","cx":48,"cy":23,"r":3.4,"fill":true,"tone":"muted"},{"t":"text","x":48,"y":16,"text":"红磷（不燃烧）","size":3.4,"tone":"muted","anchor":"middle"},{"t":"circle","cx":24,"cy":50,"r":3,"fill":true,"tone":"main"},{"t":"text","x":24,"y":58,"text":"水中的白磷（通氧气前不燃烧）","size":3.4,"tone":"main","anchor":"middle"},{"t":"curve","points":[[70,10],[60,34],[30,50]]},{"t":"text","x":72,"y":8,"text":"通入氧气","size":3.4,"tone":"danger"},{"t":"text","x":72,"y":26,"text":"白磷着火点约 40 ℃","size":3.4,"tone":"muted","anchor":"middle"},{"t":"text","x":72,"y":34,"text":"红磷着火点约 240 ℃","size":3.4,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"对照实验要看清「谁和谁比」：铜片上的白磷与红磷相比，变量是着火点；铜片上的白磷与水中的白磷相比，变量是有没有氧气；水中的白磷通氧气前后相比，变量仍然是氧气。写结论时必须说清是哪一个变量导致的差别。"},{"type":"h","text":"【微观】微观：燃烧是急剧的氧化，缓慢氧化与爆炸只是快慢不同"},{"type":"p","text":"从粒子角度看，燃烧是可燃物的分子在点燃后与氧分子剧烈作用，分子被拆成原子、与氧原子重新组合成新的分子（二氧化碳、水等），同时把储存在分子里的化学能释放出来，变成热和光。同一类氧化反应，快慢不同，名称就不同：铁生锈、食物腐败、动植物呼吸都是缓慢氧化，放热很慢、察觉不到，也没有火焰；而面粉粉尘、煤气与空气混合后遇到明火，会在极短时间内放出大量热，气体体积急剧膨胀，就形成爆炸。可见爆炸并不都是化学变化：气球爆裂、轮胎爆胎只是气体膨大，没有新物质生成，属于物理变化。"},{"type":"figure","figure":{"id":"fig-chem-substance-10-3","title":"燃烧、缓慢氧化与爆炸的对比","caption":"三者都是氧化反应，区别在于快慢与是否在有限空间内急剧放热","view":"wide","alt":"三个并列的场景：燃烧（发光放热的剧烈氧化）、缓慢氧化（铁生锈与呼吸，放热缓慢）、爆炸（面粉粉尘在有限空间内急速燃烧体积急剧膨胀）","prims":[{"t":"rect","x":5,"y":10,"w":28,"h":32,"tone":"accent"},{"t":"text","x":19,"y":16,"text":"燃烧","size":3.8,"tone":"accent","anchor":"middle"},{"t":"text","x":19,"y":24,"text":"剧烈氧化","size":3.4,"anchor":"middle"},{"t":"text","x":19,"y":31,"text":"发光、放热、有火焰","size":3.2,"anchor":"middle"},{"t":"text","x":19,"y":38,"text":"例：木炭燃烧","size":3.2,"tone":"muted","anchor":"middle"},{"t":"rect","x":36,"y":10,"w":28,"h":32,"tone":"ok"},{"t":"text","x":50,"y":16,"text":"缓慢氧化","size":3.8,"tone":"ok","anchor":"middle"},{"t":"text","x":50,"y":24,"text":"放热很慢","size":3.4,"anchor":"middle"},{"t":"text","x":50,"y":31,"text":"不发光、无明显现象","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":38,"text":"例：铁生锈、呼吸","size":3.2,"tone":"muted","anchor":"middle"},{"t":"rect","x":67,"y":10,"w":28,"h":32,"tone":"danger"},{"t":"text","x":81,"y":16,"text":"爆炸","size":3.8,"tone":"danger","anchor":"middle"},{"t":"text","x":81,"y":24,"text":"有限空间内急速燃烧","size":3.2,"anchor":"middle"},{"t":"text","x":81,"y":31,"text":"气体体积急剧膨胀","size":3.2,"anchor":"middle"},{"t":"text","x":81,"y":38,"text":"例：面粉粉尘爆炸","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":52,"text":"爆炸不都是化学变化：气球爆裂、轮胎爆胎属于物理变化","size":3.8,"tone":"main","anchor":"middle"}]}},{"type":"note","title":"","text":"答「爆炸原因」这类题要写出三个要点：可燃物与空气（或氧气）充分混合、遇到明火（或达到着火点）、在有限空间内急速燃烧使气体体积急剧膨胀。缺少「有限空间」这一条，答案是不完整的。"},{"type":"h","text":"【符号】符号：化石燃料的组成与燃烧的方程式"},{"type":"p","text":"化石燃料是煤、石油、天然气，它们都是古代生物的遗骸经过漫长年代形成的，属于不可再生能源。煤是复杂的混合物，主要含碳元素；石油是混合物，主要含碳、氢元素；天然气的主要成分是甲烷 CH₄。燃烧的方程式要写全条件与配平：甲烷完全燃烧生成二氧化碳和水，碳完全燃烧生成二氧化碳；若氧气不足，碳会生成有毒的一氧化碳，甲烷也会因不完全燃烧产生炭黑（黑烟）。此外，燃料中还含有硫、氮等元素，燃烧后会生成二氧化硫、二氧化氮，它们溶于雨水就形成酸雨，所以使用脱硫煤、推广天然气与乙醇汽油、发展氢能都是为了减少污染。"},{"type":"figure","figure":{"id":"fig-chem-substance-10-4","title":"三种化石燃料与它们带来的环境问题","caption":"组成元素决定了燃烧产物，硫、氮元素是酸雨的来源","view":"wide","alt":"上方列出煤、石油、天然气三种化石燃料及主要成分；下方列出它们的燃烧产物与带来的环境问题：二氧化碳引起温室效应，二氧化硫和二氧化氮形成酸雨，不完全燃烧产生一氧化碳与炭黑","prims":[{"t":"rect","x":5,"y":8,"w":28,"h":22,"tone":"muted"},{"t":"text","x":19,"y":14,"text":"煤（混合物）","size":3.6,"anchor":"middle"},{"t":"text","x":19,"y":22,"text":"主要含碳，含少量硫","size":3.2,"anchor":"middle"},{"t":"rect","x":36,"y":8,"w":28,"h":22,"tone":"muted"},{"t":"text","x":50,"y":14,"text":"石油（混合物）","size":3.6,"anchor":"middle"},{"t":"text","x":50,"y":22,"text":"主要含碳、氢","size":3.2,"anchor":"middle"},{"t":"rect","x":67,"y":8,"w":28,"h":22,"tone":"accent"},{"t":"text","x":81,"y":14,"text":"天然气","size":3.6,"anchor":"middle"},{"t":"text","x":81,"y":22,"text":"主要成分 CH₄","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":36,"text":"燃烧产物 → 环境问题","size":3.8,"tone":"main","anchor":"middle"},{"t":"text","x":8,"y":44,"text":"CO₂ → 温室效应","size":3.4},{"t":"text","x":38,"y":44,"text":"SO₂、NO₂ → 酸雨","size":3.4,"tone":"danger"},{"t":"text","x":68,"y":44,"text":"CO、炭黑 → 污染与中毒","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":54,"text":"对策：脱硫煤、天然气替代煤、乙醇汽油、氢能、太阳能","size":3.6,"tone":"accent","anchor":"middle"}]}},{"type":"note","title":"","text":"方程式题的两个常见失分点：一是漏写「点燃」条件；二是甲烷燃烧配平时氧原子个数算错——CH₄ 需要 2 个 O₂，可以记作「1 个碳配 1 个 CO₂、4 个氢配 2 个 H₂O」。"},{"type":"h","text":"应用 · 火灾现场怎么灭：做法与原理一一对应"},{"type":"note","title":"情境","text":"①炒菜时油锅着火 ②图书档案着火 ③森林火灾中开辟隔离带 ④实验时少量酒精洒在桌面上燃烧。请分别说明采用的灭火方法和原理。"},{"type":"list","title":"解答步骤","items":["①油锅着火：立即用锅盖盖灭，原理是隔绝氧气（同时避免用水的错误做法）。","②图书档案着火：用二氧化碳灭火器，原理是隔绝氧气且不损坏物品。","③森林火灾：砍出隔离带，原理是清除（隔离）可燃物。","④酒精洒出燃烧：用湿抹布扑盖，原理是隔绝氧气并使温度降到着火点以下。"]},{"type":"note","title":"结论","text":"灭火答题模板：采取某做法，破坏了「可燃物／氧气／温度达到着火点」中的某一个条件。"},{"type":"h","text":"应用 · 燃料选择与环境保护"},{"type":"note","title":"情境","text":"某家庭原来用煤取暖，后来改用天然气；某城市推广乙醇汽油并发展氢能公交。请从燃烧产物、能源利用与环境保护三个方面说明这样做的理由。"},{"type":"list","title":"解答步骤","items":["比较燃烧产物：煤 → CO₂、SO₂、NO₂、CO、烟尘；天然气 → CO₂、H₂O。","比较能源属性：化石燃料不可再生；乙醇属于可再生能源。","给结论：减少 SO₂、NO₂ 与烟尘排放 → 减轻酸雨与雾霾；但 CO₂ 排放仍会增加，所以还要发展太阳能、风能。"]},{"type":"note","title":"结论","text":"结论要写成「因为……所以……」的两段：清洁燃料的燃烧产物更简单，能减少酸雨与烟尘；同时要指出它仍会排放二氧化碳，能源结构需要多元化。"},{"type":"h","text":"实验 1 · 探究燃烧的条件"},{"type":"note","title":"实验目的","text":"通过白磷与红磷、水中白磷的对照，得出燃烧的三个条件"},{"type":"list","title":"实验器材","items":["烧杯","薄铜片","白磷","红磷","热水","导管","氧气"]},{"type":"figure","figure":{"id":"fig-chem-substance-10-exp1","title":"探究燃烧条件的装置","caption":"铜片上的白磷燃烧、红磷不燃烧；水中白磷通氧气后燃烧","view":"wide","alt":"盛热水的烧杯口架着薄铜片，铜片左端放白磷、右端放红磷，水底还有一块白磷，一根导管伸向水中的白磷","prims":[{"t":"beaker","x":16,"y":32,"w":38,"h":26,"fill":0.72,"label":"60 ℃ 热水"},{"t":"rect","x":14,"y":28,"w":42,"h":3,"fill":true,"tone":"muted"},{"t":"circle","cx":22,"cy":25,"r":3.4,"fill":true,"tone":"accent"},{"t":"text","x":22,"y":18,"text":"白磷（燃烧）","size":3.4,"tone":"accent","anchor":"middle"},{"t":"circle","cx":48,"cy":25,"r":3.4,"fill":true,"tone":"muted"},{"t":"text","x":48,"y":18,"text":"红磷（不燃烧）","size":3.4,"tone":"muted","anchor":"middle"},{"t":"circle","cx":26,"cy":52,"r":3,"fill":true,"tone":"main"},{"t":"text","x":26,"y":60,"text":"水中的白磷","size":3.4,"tone":"main","anchor":"middle"},{"t":"curve","points":[[74,12],[64,36],[32,52]]},{"t":"text","x":76,"y":10,"text":"通氧气","size":3.4,"tone":"danger"}]}},{"type":"list","title":"实验步骤","items":["向烧杯中倒入约 60 ℃ 的热水，把薄铜片架在烧杯口上。","在铜片的一端放一小块白磷，另一端放一小块红磷，观察现象。","在烧杯水底放一小块白磷，观察它是否燃烧。","用导管向水中的白磷附近缓缓通入氧气，观察现象。","对比三处现象，归纳燃烧所需要的条件。"]},{"type":"note","title":"实验现象","text":"铜片上的白磷燃烧、产生大量白烟；铜片上的红磷不燃烧；水中的白磷通氧气之前不燃烧，通入氧气后立即燃烧。"},{"type":"note","title":"实验结论","text":"铜片上的白磷与红磷对比，说明温度必须达到可燃物的着火点；水中的白磷通氧气前后对比，说明燃烧需要氧气。三处现象合起来得到：燃烧需要可燃物、氧气（或空气）、温度达到着火点三个条件同时满足。"},{"type":"list","title":"注意事项","items":["白磷有剧毒且着火点只有约 40 ℃，取用必须在水中进行，切不可用手直接接触。","实验要在通风处（或密闭装置中）进行，白磷燃烧产生的白烟（五氧化二磷）有刺激性。","热水的温度要控制在白磷着火点以上、红磷着火点以下，否则对照实验不成立。","通入氧气时气流要缓慢，防止热水溅出烫伤；实验结束后用湿抹布覆盖残余白磷。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O","点燃","甲烷安静地燃烧，发出明亮的淡蓝色火焰，放出大量的热，烧杯内壁出现水雾，澄清石灰水变浑浊","配平核对：左边 1 个碳、4 个氢、4 个氧；右边 CO₂ 里有 1 个碳、2 个氧，2H₂O 里有 4 个氢、2 个氧，合计 1 个碳、4 个氢、4 个氧。天然气的主要成分就是甲烷，它是三种化石燃料中相对清洁的一种。"],["C + O₂ —点燃→ CO₂","点燃","木炭在氧气中剧烈燃烧，发出白光，放出热量，生成能使澄清石灰水变浑浊的气体","氧气充足时碳生成 CO₂；氧气不足时会生成有毒的一氧化碳：2C + O₂ —点燃→ 2CO。同一种可燃物燃烧产物可能不同，取决于氧气的量，「燃料燃烧不充分」既浪费能源又污染空气。"],["2CO + O₂ —点燃→ 2CO₂","点燃","一氧化碳燃烧时发出蓝色的火焰，放出热量","煤气的主要成分之一是一氧化碳，它本身可以燃烧；但一氧化碳无色无味、有剧毒，泄漏后会造成中毒，所以煤炉取暖必须保持通风。配平核对：左边 2 个碳、4 个氧，右边 2 个 CO₂ 里同样是 2 个碳、4 个氧。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["燃烧一定要有氧气参与","通常的燃烧需要氧气，但镁可以在二氧化碳中燃烧、氢气可以在氯气中燃烧","初中讨论的燃烧大多以氧气为助燃物，但「燃烧需要氧气」是有前提的。把燃着的镁条伸入盛二氧化碳的集气瓶中，镁会继续剧烈燃烧并生成氧化镁和碳（2Mg + CO₂ —点燃→ 2MgO + C），说明二氧化碳在这种情况下不但不灭火，反而支持燃烧。因此不能把「氧气」写成燃烧的绝对条件；规范表述是「需要助燃物（通常是氧气）」。"],["灭火就是降低可燃物的着火点","着火点是物质本身的属性，灭火降低的是温度","着火点只与物质本身有关，不能通过浇水、吹气等方式改变。用水灭火之所以有效，是因为水汽化时吸收热量，使可燃物的温度降到着火点以下，燃烧就无法继续。写「降低着火点」是中考高频错答。"],["所有爆炸都是化学变化","气球爆裂、轮胎爆胎只是气体膨大，属于物理变化","爆炸分两种：由化学变化引起的（可燃物在有限空间内急速燃烧、气体体积急剧膨胀，如粉尘爆炸、煤气爆炸），也有由物理变化引起的（气球、轮胎、锅炉因压力过大而爆裂）。判断依据仍然是老规矩——有没有新物质生成。"]]},{"type":"table","title":"三种化石燃料（主要成分、燃烧特点与环境保护）","head":["比较项","煤","石油 / 天然气"],"rows":[["类别","混合物，主要含碳元素，还含少量硫、氮","石油是混合物，主要含碳、氢；天然气主要成分是 CH₄"],["燃烧特点","火焰发黄、有烟，易产生 SO₂、NO₂、烟尘","天然气火焰呈淡蓝色、几乎无烟，燃烧更充分"],["主要污染","酸雨（SO₂、NO₂）、烟尘、CO（燃烧不充分时）","主要是 CO₂（温室效应）；通风不良时天然气也会产生 CO"],["能源属性","不可再生，储量有限","同为不可再生；乙醇、氢气属于可再生或清洁替代能源"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["燃烧条件的探究","以白磷、红磷的对照实验为载体的实验探究题：要求指出变量、描述现象、写出结论，并解释「水中的白磷为什么要通氧气才燃烧」。评分点落在「变量说清、结论与现象对应」上，只写结论不写现象不给分。"],["灭火原理的应用","给出生活情境（油锅着火、电器着火、森林火灾、酒精灯不慎打翻），要求写出灭火方法及其原理。判分看是否把做法落到「清除可燃物／隔绝氧气／降温到着火点以下」这三条上；「降低着火点」直接判错。"],["燃料、能源与环境保护","结合酸雨、温室效应、PM2.5、乙醇汽油、氢能等素材，要求比较燃料的优劣或提出减排措施。答题要有「燃烧产物 → 环境问题 → 对策」这条链，只写「保护环境」这类空话不得分。"]]},{"type":"quote","text":"【材料一】某市近三年的空气质量监测显示：冬季 PM2.5 与 SO₂ 浓度明显高于夏季，城区浓度高于郊区。监测站分析认为，冬季取暖燃煤量增加是重要原因。\n【材料二】某中学开展「燃料与能源」调查，得到三条信息：①本地公交车已全部更换为天然气或纯电动；②家用燃气热水器使用天然气，说明书上特别提示「使用时必须开窗通风」；③农村仍有部分家庭用煤炉取暖，冬季曾发生一氧化碳中毒事件。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】结合材料一说明：为什么冬季的 PM2.5 与 SO₂ 浓度会明显升高？从燃烧的角度提出两条可行的减排措施。（3 分）","【设问】材料二中提到燃气热水器「使用时必须开窗通风」，请用化学方程式说明原因；用煤炉取暖为什么会发生一氧化碳中毒？（4 分）"]}],"questions":[{"id":"chem-substance-10-q1","type":"choice","stem":"下列关于燃烧与灭火的说法中，正确的是","answer":"C","explain":"燃烧需要三个条件同时满足，只达到着火点但缺少氧气也不能燃烧，A 错；着火点是物质本身的属性，用水灭火是把温度降到着火点以下，B 错；锅盖把油与空气隔开，隔绝了氧气，C 正确；镁能在二氧化碳中燃烧，D 错。","options":["只要温度达到着火点，可燃物就一定能燃烧","用水灭火的原理是降低可燃物的着火点","用锅盖盖灭油锅火焰的原理是隔绝氧气","燃烧一定要有氧气参加"],"difficulty":2,"tags":["燃烧条件","灭火原理"]},{"id":"chem-substance-10-q2","type":"choice","stem":"图书档案、精密仪器着火时，最适宜使用的灭火方法是","answer":"B","explain":"图书档案与精密仪器怕水、怕残留物。二氧化碳灭火器喷出的二氧化碳既不燃烧也不支持燃烧，能隔绝氧气灭火，且喷出后不留痕迹、不损坏物品；水会浸坏纸张和仪器，湿抹布适用于桌面小火，干粉会留下粉末污染。","options":["用水浇灭","用二氧化碳灭火器","用湿抹布扑盖","用干粉灭火器大量喷洒"],"difficulty":2,"tags":["灭火原理","二氧化碳灭火器"]},{"id":"chem-substance-10-q3","type":"choice","stem":"煤、石油、天然气是三种重要的化石燃料。下列说法中不正确的是","answer":"D","explain":"煤是复杂混合物，除碳以外还含硫、氮等元素，燃烧后会生成二氧化硫、二氧化氮（形成酸雨）与烟尘，若氧气不足还会生成一氧化碳，因此「只生成二氧化碳、不污染空气」是错误的。A、B、C 三项都是正确表述。","options":["它们都是古代生物的遗骸经过漫长年代形成的","它们都属于不可再生能源","天然气的主要成分是甲烷","煤燃烧的产物只有二氧化碳，不会污染空气"],"difficulty":2,"tags":["化石燃料","燃料与环境"]},{"id":"chem-substance-10-q4","type":"choice","stem":"面粉加工厂、煤矿的车间里都严禁烟火，其主要原因是","answer":"B","explain":"面粉粉尘、煤粉尘都是可燃物，悬浮在空气中时会与氧气充分接触，一旦遇到明火，会在有限空间内急速燃烧、气体体积急剧膨胀而发生爆炸。这正是「严禁烟火」的原因，也是爆炸三要素（可燃物、与空气充分混合、有限空间内急速燃烧）的典型应用。","options":["面粉和煤粉尘都有毒","可燃性粉尘与空气混合后遇明火可能发生爆炸","明火会使粉尘变潮湿","粉尘会吸收空气中的氧气"],"difficulty":2,"tags":["爆炸","粉尘爆炸"]},{"id":"chem-substance-10-q5","type":"choice","stem":"下列关于燃烧现象的判断中，属于物理变化的是","answer":"C","explain":"玻璃棒受热变软只是状态变化，没有新物质生成，属于物理变化；木炭、镁条、天然气燃烧都生成了新物质（CO₂、MgO、CO₂ 和 H₂O），属于化学变化。这道题把「物理变化与化学变化」和「燃烧」两个知识点串在一起。","options":["木炭在氧气中燃烧","镁条在空气中燃烧","点燃的酒精灯火焰使玻璃棒受热变软","天然气燃烧"],"difficulty":2,"tags":["燃烧","物理变化与化学变化"]},{"id":"chem-substance-10-q6","type":"fill","stem":"燃烧需要同时满足三个条件：________、________、________；灭火时只要破坏其中________个条件即可。","answer":"有可燃物；有氧气（或空气）；温度达到可燃物的着火点；一","explain":"三个条件必须同时满足才能燃烧，这是「缺一不可」；而灭火只需要破坏任意一个条件就够了，这是「破坏其一」。这两句常常被写成颠倒，记忆时可以想「点燃很难，灭火很容易」。","difficulty":2,"tags":["燃烧条件","灭火原理"]},{"id":"chem-substance-10-q7","type":"fill","stem":"天然气的主要成分是________（写化学式），它完全燃烧的化学方程式为________；若通风不良、氧气不足，会产生有毒的________气体。","answer":"CH₄；CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O；一氧化碳（CO）","explain":"甲烷的化学式是 CH₄，1 个碳配 1 个 CO₂、4 个氢配 2 个 H₂O，所以需要 2 个 O₂，据此就能把方程式配平。氧气不足时甲烷不完全燃烧会生成一氧化碳，这是燃气热水器必须通风的原因。","difficulty":3,"tags":["甲烷","化学方程式","一氧化碳"]},{"id":"chem-substance-10-q8","type":"short","stem":"某同学用如图装置探究燃烧的条件：烧杯中盛有 60 ℃ 的热水，铜片架在烧杯口，铜片左端放一小块白磷、右端放一小块红磷，水底另放一小块白磷。请回答：(1) 铜片上的白磷燃烧而红磷不燃烧，说明什么？(2) 水中的白磷不燃烧，原因是什么？(3) 若向水中的白磷通入氧气，它会燃烧吗？请说明理由。","answer":"(1) 说明燃烧需要温度达到可燃物的着火点：白磷的着火点约为 40 ℃，低于热水温度所以燃烧；红磷的着火点约为 240 ℃，高于热水温度所以不燃烧。(2) 水中的白磷虽然温度达到了着火点，但它被水与空气隔开，缺少氧气，所以不能燃烧。(3) 会燃烧。通入氧气后，水中的白磷同时具备了可燃物、氧气和达到着火点三个条件，因此立即燃烧起来。","explain":"这道题是燃烧条件实验的经典问法，核心是把每个现象对应到「哪个条件满足了、哪个条件没满足」。(1) 的变量是着火点，(2)(3) 的变量是有没有氧气。回答时不能只说「白磷容易燃烧」，要说清着火点的数值差异与氧气是否接触。","difficulty":3,"tags":["燃烧条件","对照实验"],"rubric":["答出白磷着火点低于热水温度（1 分）","答出红磷着火点高于热水温度（1 分）","答出水中白磷缺少氧气（1 分）","答出通氧气后三个条件同时满足故能燃烧（1 分）"],"figure":{"id":"fig-chem-substance-10-q8","title":"探究燃烧条件的实验装置","caption":"铜片上的白磷燃烧、红磷不燃烧；水中白磷通氧气后燃烧","view":"wide","alt":"盛 60 ℃ 热水的烧杯口架着薄铜片，铜片左端是白磷、右端是红磷，水底有一块白磷，一根导管伸入水中","prims":[{"t":"beaker","x":18,"y":32,"w":36,"h":26,"fill":0.72,"label":"60 ℃ 热水"},{"t":"rect","x":16,"y":28,"w":40,"h":3,"fill":true,"tone":"muted"},{"t":"circle","cx":24,"cy":25,"r":3.4,"fill":true,"tone":"accent"},{"t":"text","x":24,"y":18,"text":"白磷","size":3.4,"tone":"accent","anchor":"middle"},{"t":"circle","cx":48,"cy":25,"r":3.4,"fill":true,"tone":"muted"},{"t":"text","x":48,"y":18,"text":"红磷","size":3.4,"tone":"muted","anchor":"middle"},{"t":"circle","cx":28,"cy":52,"r":3,"fill":true,"tone":"main"},{"t":"text","x":70,"y":52,"text":"水中的白磷","size":3.4,"tone":"main","anchor":"middle"},{"t":"text","x":70,"y":26,"text":"铜片","size":3.4,"tone":"muted","anchor":"middle"}]}},{"id":"chem-substance-10-q9","type":"short","stem":"请设计实验证明「燃烧需要氧气」，画出实验装置示意图（可选用蜡烛、烧杯、集气瓶、玻璃片、火柴等），写出操作步骤、现象与结论。","answer":"见参考答案图。方案：把两支同样的蜡烛点燃，分别放在空气中与倒扣的集气瓶中（或用玻璃片盖住），观察现象。现象：敞口放置的蜡烛继续燃烧，倒扣在集气瓶中的蜡烛过一会儿熄灭。结论：密闭后瓶内氧气被消耗完，蜡烛因缺少氧气而熄灭，说明燃烧需要氧气。","explain":"设计实验要保证「只有氧气这一个变量不同」：两支蜡烛要相同、都要先点燃、唯一差别是一支与空气相通、另一支被密闭。装置示意图要把蜡烛、集气瓶（或烧杯）与玻璃片的位置画清楚，并在图上注明「密闭」这一关键条件。","difficulty":3,"tags":["实验设计","燃烧条件","作图"],"rubric":["两支相同的蜡烛都被点燃（控制变量）（1 分）","一支敞口、一支密闭，装置示意图画清（1 分）","描述现象：密闭的蜡烛熄灭（1 分）","得出结论：燃烧需要氧气（1 分）"],"answerFigure":{"id":"fig-chem-substance-10-q9-ans","title":"参考答案：两支蜡烛的对照实验","caption":"左支敞口继续燃烧，右支被集气瓶倒扣后熄灭","view":"wide","alt":"两支点燃的蜡烛：左边一支暴露在空气中继续燃烧，右边一支被倒扣的集气瓶罩住，火焰逐渐熄灭","prims":[{"t":"rect","x":20,"y":46,"w":8,"h":12,"fill":true,"tone":"muted"},{"t":"poly","points":[[24,44],[21,38],[24,30],[27,38]],"closed":true,"tone":"accent"},{"t":"text","x":24,"y":62,"text":"敞口：继续燃烧","size":3.4,"tone":"accent","anchor":"middle"},{"t":"rect","x":66,"y":46,"w":8,"h":12,"fill":true,"tone":"muted"},{"t":"poly","points":[[70,44],[68,40],[70,36],[72,40]],"closed":true,"tone":"muted"},{"t":"gasJar","x":58,"y":18,"w":24,"h":28,"label":"倒扣的集气瓶"},{"t":"text","x":70,"y":62,"text":"密闭：氧气耗尽后熄灭","size":3.4,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":10,"text":"两支蜡烛相同、都点燃，只有「是否与空气相通」不同","size":3.6,"tone":"main","anchor":"middle"}]}},{"id":"chem-substance-10-q10","type":"short","stem":"某家庭用天然气做饭，某次完全燃烧消耗了 3.2 kg 甲烷。请计算：(1) 需要消耗多少千克氧气？(2) 生成多少千克二氧化碳？（相对原子质量：H 1、C 12、O 16）","answer":"(1) 12.8 kg；(2) 8.8 kg。设消耗氧气质量为 x、生成二氧化碳质量为 y：CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O，相对分子质量依次为 16、64、44。由 16 : 64 = 3.2 kg : x 得 x = 12.8 kg；由 16 : 44 = 3.2 kg : y 得 y = 8.8 kg。","explain":"化学计算的基本流程是「设、写、算、列、答」：先设未知量，再写配平的化学方程式并在相关物质下方标出相对分子质量（要乘系数），然后按「上下同种物质、左右同一单位」列比例式。本题的两个比例式都以甲烷为基准：甲烷的相对分子质量是 16，氧气是 2×32 = 64，二氧化碳是 44（相对分子质量）。","difficulty":3,"tags":["化学计算","甲烷燃烧"],"rubric":["写出配平的化学方程式 CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O（1 分）","在方程式下方正确标出 16、64、44（1 分）","列比例式并求出氧气 12.8 kg（1 分）","列比例式并求出二氧化碳 8.8 kg，带单位作答（1 分）"],"steps":["第一步（设）：设消耗氧气的质量为 x，生成二氧化碳的质量为 y。","第二步（写）：写出方程式 CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O，并标出相对分子质量 16、2×32 = 64、44。","第三步（算）：把已知的甲烷质量统一成 3.2 kg，注意单位一致。","第四步（列）：16 : 64 = 3.2 kg : x，解得 x = 12.8 kg；16 : 44 = 3.2 kg : y，解得 y = 8.8 kg。","第五步（答）：完全燃烧 3.2 kg 甲烷需要 12.8 kg 氧气，同时生成 8.8 kg 二氧化碳。"]},{"id":"chem-substance-10-m1-q1","type":"short","stem":"结合材料一说明：为什么冬季的 PM2.5 与 SO₂ 浓度会明显升高？从燃烧的角度提出两条可行的减排措施。（3 分）","answer":"冬季取暖燃煤量增加，煤中除碳以外还含有少量硫、氮元素，燃烧时会生成二氧化硫、二氧化氮和烟尘，这些污染物正是 PM2.5 与 SO₂ 浓度升高的原因，所以冬季浓度高于夏季；城区取暖与交通更集中，浓度也高于郊区。减排措施：①使用脱硫煤或改用天然气、电取暖（减少 SO₂ 与烟尘）；②改善燃烧条件使燃料充分燃烧（如增大进风口、把煤做成蜂窝煤），减少一氧化碳与炭黑。","explain":"","tags":["燃料与环境","酸雨","空气污染"],"rubric":["指出煤中含硫、氮元素，燃烧生成 SO₂、NO₂ 与烟尘（1 分）","给出一条可行措施（脱硫煤／改用天然气或电／使燃料充分燃烧）（1 分）","措施与原因对应，表述完整（1 分）"]},{"id":"chem-substance-10-m1-q2","type":"short","stem":"材料二中提到燃气热水器「使用时必须开窗通风」，请用化学方程式说明原因；用煤炉取暖为什么会发生一氧化碳中毒？（4 分）","answer":"天然气的主要成分是甲烷，燃烧的方程式为 CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O。如果通风不良、氧气不足，甲烷会燃烧不充分，生成一氧化碳：2CH₄ + 3O₂ —点燃→ 2CO + 4H₂O，一氧化碳无色无味、有剧毒，会使人中毒。煤炉中碳在氧气不足时也会生成一氧化碳（2C + O₂ —点燃→ 2CO），加上冬季门窗紧闭，所以容易发生中毒事故。开窗通风能保证氧气供应充足并使一氧化碳及时排出，因此说明书上必须提示。","explain":"","tags":["甲烷燃烧","一氧化碳","燃料的合理利用"],"rubric":["写出甲烷完全燃烧的方程式并配平（1 分）","说明通风不良导致燃烧不充分生成 CO（1 分）","写出一氧化碳有剧毒、会使人中毒（1 分）","联系煤炉中碳不完全燃烧同样生成 CO（1 分）"]}]},{"id":"chem-substance-11","title":"化学与生活：营养素·人体元素·有机合成材料","subtitle":"人教版九年级 · 第十二单元 化学与生活 · 9b","grade":"9b","tags":["人教版九年级 · 第十二单元 化学与生活"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第十二单元 化学与生活 · 9b"},{"type":"note","title":"问题切入","text":"一顿饭里的米饭、鸡蛋、青菜、食用油，各自给身体提供什么？为什么缺铁会贫血、缺碘会得「大脖子病」？家里装东西的塑料袋、穿的化纤衣服，又和「白色污染」有什么关系？"},{"type":"note","title":"一句话抓住关键","text":"人体需要的营养素主要是蛋白质、糖类、油脂、维生素、无机盐和水：蛋白质是构成细胞的基础，糖类是主要供能物质，油脂是重要的储能物质，维生素调节新陈代谢。人体中的元素分常量元素（钙、磷、钾等）与微量元素（铁、锌、碘、硒、氟等），缺什么补什么、过量同样有害。有机合成材料指塑料、合成纤维、合成橡胶，它们大多难以降解，因此要回收利用、减少使用、开发可降解材料。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"一顿饭里，米饭给能量，鸡蛋长肌肉，青菜帮消化，食用油储存能量。身体不是「吃饱就行」，而是需要不同营养素各司其职。","walk":["六大营养素：蛋白质、糖类、油脂、维生素、无机盐、水。蛋白质是构成细胞的基础，糖类是主要供能物质，油脂是备用能源，维生素调节代谢。","人体中的元素：含量较多的有氧、碳、氢、氮；缺铁会贫血，缺碘会得甲状腺肿大，缺钙影响骨骼和牙齿。","材料分四类：金属材料、无机非金属材料、有机合成材料、复合材料。塑料、合成纤维、合成橡胶属于有机合成材料，废弃塑料造成的「白色污染」需要回收和降解。"],"try":"拿起一袋饼干或一瓶饮料，看营养成分表：蛋白质、脂肪、碳水化合物、钠各是多少，试着对应到六大营养素。","use":["营养素题按「是什么—有什么用—缺了会怎样—从哪里来」四问作答。","材料分类题先看「是不是人工合成的高分子」，再判断是有机合成还是天然材料。"]},{"type":"h","text":"【宏观】宏观：六大营养素各管什么"},{"type":"p","text":"把一顿日常的饭拆开看：米饭、馒头的主要成分是糖类（淀粉），它在体内最终变成葡萄糖并被氧化，放出能量；鸡蛋、瘦肉、牛奶富含蛋白质，是构成细胞、修补组织的基础，也是青少年长身体最需要的；食用油、肥肉提供油脂，它是人体内储存能量的「仓库」，还能帮助吸收脂溶性维生素；青菜、水果提供维生素与无机盐（矿物质）；水则参与一切生命活动。六类营养素缺一不可，但也不是越多越好——糖类与油脂摄入过多会转化为脂肪储存，导致肥胖。"},{"type":"figure","figure":{"id":"fig-chem-substance-11-1","title":"六大营养素与主要食物来源","caption":"每一类营养素都有对应的功能与来源食物","view":"wide","alt":"表格列出六大营养素及来源：蛋白质来自鸡蛋、瘦肉、牛奶、大豆，糖类来自米饭、馒头、马铃薯，油脂来自食用油、肥肉，维生素来自蔬菜、水果，无机盐来自奶类、海产品，水来自饮用水与食物","prims":[{"t":"rect","x":5,"y":8,"w":44,"h":9,"tone":"accent"},{"t":"text","x":9,"y":14,"text":"蛋白质：鸡蛋、瘦肉、牛奶、大豆","size":3.4},{"t":"rect","x":5,"y":19,"w":44,"h":9,"tone":"main"},{"t":"text","x":9,"y":25,"text":"糖类：米饭、馒头、马铃薯","size":3.4},{"t":"rect","x":5,"y":30,"w":44,"h":9,"tone":"muted"},{"t":"text","x":9,"y":36,"text":"油脂：食用油、肥肉、坚果","size":3.4},{"t":"rect","x":51,"y":8,"w":44,"h":9,"tone":"ok"},{"t":"text","x":55,"y":14,"text":"维生素：蔬菜、水果","size":3.4},{"t":"rect","x":51,"y":19,"w":44,"h":9,"tone":"danger"},{"t":"text","x":55,"y":25,"text":"无机盐：奶类、豆类、海产品","size":3.4},{"t":"rect","x":51,"y":30,"w":44,"h":9,"tone":"main"},{"t":"text","x":55,"y":36,"text":"水：饮用水与各种食物","size":3.4},{"t":"text","x":50,"y":50,"text":"功能：蛋白质构成细胞，糖类主要供能，油脂储存能量，维生素调节代谢","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"答题时不要只写「有营养」：要写清「某营养素 + 它的功能 + 对应的食物来源」。例如「鸡蛋富含蛋白质，蛋白质是构成细胞的基础，青少年生长发育需要它」。"},{"type":"h","text":"【宏观】宏观：缺什么补什么，人体元素的清单"},{"type":"p","text":"人体中的元素按含量分成两类：含量较多的叫常量元素（钙、磷、钾、硫、钠、氯、镁等），含量很少的叫微量元素（铁、锌、碘、硒、氟等）。缺钙会影响骨骼和牙齿的发育，幼儿易得佝偻病、老年人易骨质疏松；缺铁会得缺铁性贫血；缺碘会引起甲状腺肿大（俗称「大脖子病」），所以食盐里要加碘；缺锌会使生长发育迟缓、味觉减退；缺维生素 A 会得夜盲症，缺维生素 C 会得坏血病（牙龈出血、抵抗力下降）。反过来，元素和维生素也不是越多越好：碘过量同样会引起甲状腺疾病，维生素 A 过量会中毒。"},{"type":"figure","figure":{"id":"fig-chem-substance-11-2","title":"缺乏症与对应的元素或维生素","caption":"缺少什么就出现什么症状，注意「缺」与「过」都有害","view":"wide","alt":"左右对照表：左侧列出缺乏的元素或维生素，右侧列出对应的症状——缺钙引起佝偻病或骨质疏松，缺铁引起贫血，缺碘引起甲状腺肿大，缺锌使生长发育迟缓，缺维生素 A 引起夜盲症，缺维生素 C 引起坏血病","prims":[{"t":"rect","x":5,"y":8,"w":42,"h":8,"tone":"main"},{"t":"text","x":9,"y":13,"text":"缺钙","size":3.6},{"t":"text","x":22,"y":13,"text":"佝偻病、骨质疏松","size":3.4,"tone":"muted"},{"t":"rect","x":5,"y":17,"w":42,"h":8,"tone":"main"},{"t":"text","x":9,"y":22,"text":"缺铁","size":3.6},{"t":"text","x":22,"y":22,"text":"缺铁性贫血","size":3.4,"tone":"muted"},{"t":"rect","x":5,"y":26,"w":42,"h":8,"tone":"main"},{"t":"text","x":9,"y":31,"text":"缺碘","size":3.6},{"t":"text","x":22,"y":31,"text":"甲状腺肿大","size":3.4,"tone":"muted"},{"t":"rect","x":5,"y":35,"w":42,"h":8,"tone":"main"},{"t":"text","x":9,"y":40,"text":"缺锌","size":3.6},{"t":"text","x":22,"y":40,"text":"生长发育迟缓、味觉减退","size":3.4,"tone":"muted"},{"t":"rect","x":53,"y":8,"w":42,"h":8,"tone":"accent"},{"t":"text","x":57,"y":13,"text":"缺维生素 A","size":3.6},{"t":"text","x":72,"y":13,"text":"夜盲症","size":3.4,"tone":"muted"},{"t":"rect","x":53,"y":17,"w":42,"h":8,"tone":"accent"},{"t":"text","x":57,"y":22,"text":"缺维生素 C","size":3.6},{"t":"text","x":72,"y":22,"text":"坏血病、牙龈出血","size":3.4,"tone":"muted"},{"t":"text","x":50,"y":52,"text":"常量元素（钙、磷、钾…）含量多，微量元素（铁、锌、碘…）含量少但不可缺","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"「加碘食盐」「铁强化酱油」这类食品添加剂考点的答法是：补充人体所需的微量元素，预防相应的缺乏症。要写清是哪种元素、预防哪种病，不能笼统写「补充营养」。"},{"type":"h","text":"【微观】微观：淀粉与蛋白质——用检验来区分大分子"},{"type":"p","text":"糖类中的淀粉、蛋白质都是分子很大的有机物，它们的分子由许多小单元连接而成，所以性质与小分子不同：淀粉遇碘会变成蓝色，这是检验淀粉（也是检验碘）的常用方法；蛋白质遇到重金属盐（如硫酸铜、醋酸铅）、甲醛、浓酒精或加热时会发生变性，失去原有的生理功能——这就是误服重金属盐后要立即喝牛奶、蛋清的原因，牛奶中的蛋白质先把重金属离子「接住」，减少人体蛋白质被破坏。维生素 C 则具有还原性，能使高锰酸钾溶液褪色，可据此检验。"},{"type":"figure","figure":{"id":"fig-chem-substance-11-3","title":"淀粉遇碘变蓝与蛋白质变性","caption":"左：淀粉溶液滴入碘水变蓝；右：蛋白质溶液加入硫酸铜溶液后出现沉淀（变性）","view":"wide","alt":"两支试管：左边试管里的淀粉溶液滴入碘水后变成蓝色，右边试管里的蛋白质溶液加入硫酸铜溶液后出现白色沉淀","prims":[{"t":"testTube","x":18,"y":14,"h":30,"liquid":0.6,"color":"blue","tilt":0,"label":"淀粉溶液 + 碘水"},{"t":"text","x":18,"y":60,"text":"滴入碘水 → 变蓝（检验淀粉）","size":3.6,"tone":"main","anchor":"middle"},{"t":"testTube","x":62,"y":14,"h":30,"liquid":0.6,"color":"colorless","tilt":0,"label":"蛋白质溶液"},{"t":"text","x":62,"y":60,"text":"加入硫酸铜 → 出现沉淀（变性）","size":3.6,"tone":"danger","anchor":"middle"},{"t":"text","x":50,"y":8,"text":"重金属盐、甲醛、加热都会使蛋白质变性","size":3.8,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"「误服重金属盐后喝牛奶」的理由要写两层：牛奶中的蛋白质与重金属离子结合发生变性，从而保护了人体自身的蛋白质；同时要立刻就医。只写「牛奶有营养」不得分。"},{"type":"h","text":"【符号】符号：有机合成材料与白色污染"},{"type":"p","text":"按来源把材料分三类：天然材料（棉花、羊毛、蚕丝、木材）、有机合成材料（塑料、合成纤维、合成橡胶）、无机材料（金属、玻璃、陶瓷）。有机合成材料的优点是密度小、耐腐蚀、易加工，缺点是大多难以降解，废弃后会造成「白色污染」。鉴别天然纤维与合成纤维最简便的方法是燃烧法：羊毛、蚕丝（蛋白质纤维）燃烧时有烧焦羽毛的气味，灰烬用手指一捏就碎；棉花燃烧时有烧纸的气味，灰烬是灰白色的粉末；合成纤维（涤纶、锦纶）燃烧时先熔化后燃烧、有特殊气味，灰烬是黑色硬块，不易捏碎。防治白色污染的措施是：减少使用不必要的塑料袋、重复使用、分类回收、使用可降解塑料。"},{"type":"figure","figure":{"id":"fig-chem-substance-11-4","title":"燃烧法鉴别三种纤维","caption":"气味与灰烬的性状是鉴别的依据","view":"wide","alt":"三种纤维燃烧现象对照：羊毛燃烧有烧焦羽毛气味、灰烬易碎；棉花燃烧有烧纸气味、灰烬为灰白色粉末；合成纤维熔化后燃烧、有特殊气味、灰烬为黑色硬块","prims":[{"t":"rect","x":5,"y":10,"w":28,"h":30,"tone":"ok"},{"t":"text","x":19,"y":16,"text":"羊毛、蚕丝","size":3.6,"anchor":"middle"},{"t":"text","x":19,"y":24,"text":"烧焦羽毛气味","size":3.2,"anchor":"middle"},{"t":"text","x":19,"y":31,"text":"灰烬一捏就碎","size":3.2,"tone":"muted","anchor":"middle"},{"t":"rect","x":36,"y":10,"w":28,"h":30,"tone":"main"},{"t":"text","x":50,"y":16,"text":"棉花","size":3.6,"anchor":"middle"},{"t":"text","x":50,"y":24,"text":"烧纸的气味","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":31,"text":"灰烬为灰白色粉末","size":3.2,"tone":"muted","anchor":"middle"},{"t":"rect","x":67,"y":10,"w":28,"h":30,"tone":"danger"},{"t":"text","x":81,"y":16,"text":"合成纤维","size":3.6,"anchor":"middle"},{"t":"text","x":81,"y":24,"text":"先熔化后燃烧","size":3.2,"anchor":"middle"},{"t":"text","x":81,"y":31,"text":"黑色硬块，不易捏碎","size":3.2,"tone":"muted","anchor":"middle"},{"t":"text","x":50,"y":50,"text":"共同点：都是有机物，完全燃烧都生成 CO₂ 和 H₂O","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"note","title":"","text":"鉴别题只写「有气味」不够，要写清是哪种气味（烧焦羽毛味 / 烧纸味 / 特殊气味）与灰烬的性状，两者合起来才是完整的实验结论。"},{"type":"h","text":"应用 · 由缺乏症推断缺什么"},{"type":"note","title":"情境","text":"医生发现：甲同学经常牙龈出血、抵抗力差；乙同学视力在暗处明显下降，夜间看不清东西；丙同学被诊断为缺铁性贫血；丁同学身材矮小、生长发育迟缓。请分别推断他们可能缺乏的营养素或元素，并给出饮食建议。"},{"type":"list","title":"解答步骤","items":["甲：维生素 C 缺乏 → 多吃新鲜蔬菜、水果（如青椒、橙子）。","乙：维生素 A 缺乏 → 多吃动物肝脏、胡萝卜（胡萝卜素可转化）。","丙：铁元素缺乏 → 多吃瘦肉、动物肝脏、菠菜。","丁：锌元素缺乏 → 多吃海产品、瘦肉、坚果。"]},{"type":"note","title":"结论","text":"答题模板：根据症状判断缺乏的物质，再给出一条含该物质丰富的食物，并说明它在体内的功能。"},{"type":"h","text":"应用 · 白色污染：从材料性质说到治理措施"},{"type":"note","title":"情境","text":"某校调查发现，校园里每天产生大量塑料袋与饮料瓶。请说明塑料为什么难降解，并提出三条减少白色污染的措施。"},{"type":"list","title":"解答步骤","items":["说明原因：塑料是有机合成高分子化合物，化学性质稳定、不易被微生物降解。","措施一（减少使用）：自带布袋、少用一次性塑料餐具。","措施二（回收利用）：塑料瓶、塑料袋分类回收再加工。","措施三（替代与降解）：推广纸质包装与可降解塑料。"]},{"type":"note","title":"结论","text":"措施要具体可执行，并把「为什么有效」说出来（减少进入环境的塑料量 / 让它能被降解），不能只写「保护环境」。"},{"type":"h","text":"实验 1 · 检验食物中的淀粉，并鉴别羊毛纤维与合成纤维"},{"type":"note","title":"实验目的","text":"学会用碘水检验淀粉，用燃烧法区别天然纤维与合成纤维"},{"type":"list","title":"实验器材","items":["碘水","试管","滴管","马铃薯片（或米饭）","羊毛线","涤纶线","镊子","酒精灯"]},{"type":"figure","figure":{"id":"fig-chem-substance-11-exp1","title":"检验淀粉与鉴别纤维","caption":"左：碘水检验淀粉；右：燃烧法鉴别羊毛与涤纶","view":"wide","alt":"左边试管中马铃薯片滴入碘水后变蓝；右边用镊子夹着一段纤维在酒精灯上燃烧，下方放着两种纤维的样品","prims":[{"t":"testTube","x":16,"y":16,"h":30,"liquid":0.55,"color":"blue","tilt":0,"label":"碘水 + 马铃薯"},{"t":"text","x":16,"y":58,"text":"变蓝 → 含淀粉","size":3.6,"tone":"main","anchor":"middle"},{"t":"alcoholLamp","x":62,"y":42,"lit":true,"label":"酒精灯"},{"t":"line","x1":58,"y1":30,"x2":62,"y2":34,"width":0.9},{"t":"text","x":62,"y":24,"text":"羊毛：烧焦羽毛味","size":3.4,"tone":"ok","anchor":"middle"},{"t":"text","x":84,"y":34,"text":"涤纶：特殊气味、黑色硬块","size":3.4,"tone":"danger","anchor":"end"},{"t":"text","x":62,"y":60,"text":"燃烧法：气味 + 灰烬性状","size":3.6,"tone":"muted","anchor":"middle"}]}},{"type":"list","title":"实验步骤","items":["取一小片马铃薯（或几粒米饭）放入试管，滴入 2～3 滴碘水，观察颜色变化。","用镊子分别夹住一段羊毛线和一段涤纶线，放在酒精灯外焰上点燃。","分别闻燃烧产生的气味，观察燃烧后的灰烬，用手指（冷却后）轻捏灰烬。","记录两种纤维的气味与灰烬性状，得出结论。"]},{"type":"note","title":"实验现象","text":"滴入碘水的马铃薯（米饭）变成蓝色。羊毛线燃烧时产生烧焦羽毛的气味，灰烬呈黑褐色、用手指一捏就碎；涤纶线受热先熔化成小球再燃烧，有特殊气味，灰烬是黑色硬块，不易捏碎。"},{"type":"note","title":"实验结论","text":"淀粉遇碘变蓝，可用碘水检验食物中是否含有淀粉；羊毛（蛋白质纤维）燃烧有烧焦羽毛气味且灰烬易碎，合成纤维燃烧有特殊气味且灰烬为黑色硬块，据此可鉴别两类纤维。"},{"type":"list","title":"注意事项","items":["碘水有腐蚀性，取用时用滴管，不要沾到皮肤和衣服上。","燃烧纤维要在通风处进行，一次只烧一小段，避免熔融物滴落引燃桌面。","刚燃烧完的灰烬温度很高，必须冷却后再用手指轻捏。","明火实验要在成人指导下进行，实验结束后熄灭酒精灯、清理桌面。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["C₆H₁₂O₆ + 6O₂ —酶→ 6CO₂ + 6H₂O","酶（在人体细胞内进行）","葡萄糖在人体内被氧化，放出能量供生命活动使用（不发光，属于缓慢氧化）","配平核对：左边 6 个碳、12 个氢、6 + 12 = 18 个氧；右边 6CO₂ 里有 6 个碳、12 个氧，6H₂O 里有 12 个氢、6 个氧，合计碳 6、氢 12、氧 18。糖类供能的实质就是这条反应，与木炭燃烧属于同一类「氧化放出能量」，只是它缓慢、不发光。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["吃得越多、越饱，营养就越好","营养讲究种类齐全、比例合理，糖类与油脂摄入过多会转化为脂肪","人体需要六类营养素按合理比例供给。长期摄入过多糖类与油脂，多余的能量会转变成脂肪储存在体内，导致肥胖，还会增加代谢负担；反过来，只吃精米白面、不吃蔬菜水果，会缺乏维生素与无机盐。评价膳食要用「种类齐全、比例合理」这两条。"],["人体需要的元素越多越好，所以补钙、补碘越多越好","元素不足会得缺乏症，过量同样有害","钙摄入过量会增加结石与肾脏负担，碘摄入过量同样会引起甲状腺疾病，维生素 A 过量会中毒。所以补充要适量，缺什么补什么；「加碘食盐」「铁强化酱油」是公共卫生层面的适量补充，不是越多越好。"],["有机合成材料都有毒，应该完全禁用","合成材料的耐腐蚀、易加工等优点不可替代，关键在于合理使用与回收","塑料、合成纤维、合成橡胶在医疗、交通、电子等领域不可或缺（如医用输液管、汽车轮胎）。问题不在材料本身，而在于废弃后难以降解：只要减少一次性使用、分类回收、使用可降解材料，就能既用其长又防其害。「完全禁用」既不现实也不科学。"]]},{"type":"table","title":"天然纤维与合成纤维（来源、手感与燃烧现象）","head":["比较项","天然纤维（棉、羊毛、蚕丝）","合成纤维（涤纶、锦纶、腈纶）"],"rows":[["来源","来自植物或动物","由石油、煤等原料经化学方法合成"],["主要成分","棉花主要是纤维素，羊毛、蚕丝是蛋白质","合成高分子化合物"],["燃烧气味","羊毛有烧焦羽毛味，棉花有烧纸味","有特殊气味（区别于前两者）"],["灰烬性状","灰烬易捏碎（羊毛为黑褐色，棉花为灰白色）","先熔化后燃烧，灰烬是黑色硬块，不易捏碎"],["性能特点","透气吸湿，易皱、强度较低","耐磨、挺括、不易皱，但透气吸湿性较差"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["营养素与人体健康","以食谱、食品标签或缺乏症为情境，考查六大营养素的种类、功能与来源。答题要落到「某营养素—功能—食物来源」三段式；只写「有营养」「多吃蔬菜」这类笼统表述不得分。"],["元素与人体健康","考查常量元素与微量元素的区分（钙、铁、锌、碘、硒、氟），以及缺乏症与过量危害。常与「加碘食盐」「铁强化酱油」等生活情境结合，要求说明添加剂的作用原理。"],["有机合成材料与环境保护","考查三类材料的分类、天然纤维与合成纤维的鉴别（燃烧法）、白色污染的成因与治理措施、可降解塑料。鉴别题的评分点落在「气味 + 灰烬性状」两条现象上。"]]},{"type":"quote","text":"【材料一】某食品包装上的配料表写着：小麦粉、白砂糖、植物油、鸡蛋、食用盐、碳酸钙、维生素 D、食用香精。营养成分表显示每 100 g 含蛋白质 8.0 g、脂肪 20.0 g、糖类 58.0 g、钠 320 mg、钙 240 mg。\n【材料二】某地曾发生一起误服硫酸铜溶液的事故：患者被送医前，医生电话指导家属让其立即喝下大量牛奶或生鸡蛋清，随后紧急送医洗胃。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据材料一，说明这种食品主要能提供哪些营养素；配料表中的碳酸钙与维生素 D 起什么作用？（4 分）","【设问】结合材料二，用化学知识解释「误服硫酸铜溶液后先喝牛奶或蛋清」的原因；为什么随后还必须立即送医？（3 分）"]}],"questions":[{"id":"chem-substance-11-q1","type":"choice","stem":"下列食物中，富含蛋白质的是","answer":"B","explain":"米饭主要含糖类（淀粉），鸡蛋富含蛋白质，食用油提供油脂，白菜主要提供维生素与无机盐。判断食物与营养素的对应关系时，记住「主食给糖、蛋奶肉给蛋白、油给油脂、果蔬给维生素」这条线索。","options":["米饭","鸡蛋","食用油","白菜"],"difficulty":1,"tags":["营养素"]},{"id":"chem-substance-11-q2","type":"choice","stem":"人体缺少下列哪种元素会引起贫血","answer":"B","explain":"铁是血红蛋白的组成元素，缺铁会导致缺铁性贫血。缺钙影响骨骼发育（佝偻病、骨质疏松），缺碘引起甲状腺肿大，缺锌使生长发育迟缓、味觉减退，缺维生素 A 引起夜盲症，缺维生素 C 引起坏血病——这一组对应关系必须记牢。","options":["钙","铁","碘","锌"],"difficulty":2,"tags":["元素与人体健康"]},{"id":"chem-substance-11-q3","type":"choice","stem":"要鉴别一件毛衣是羊毛的还是合成纤维的，最简便的方法是","answer":"C","explain":"羊毛是蛋白质纤维，燃烧时有烧焦羽毛的气味、灰烬一捏就碎；合成纤维受热先熔化再燃烧、有特殊气味、灰烬是黑色硬块。用燃烧法既简便又有明确的现象依据。吸水性与手感不够可靠，食醋与两者都不反应。","options":["放入水中看是否吸水","用手摸软硬","抽一根线点燃，闻气味并观察灰烬","放入食醋中观察是否溶解"],"difficulty":2,"tags":["合成材料","纤维鉴别"]},{"id":"chem-substance-11-q4","type":"choice","stem":"下列关于材料与「白色污染」的说法中，正确的是","answer":"B","explain":"塑料是有机合成高分子材料，分子链长、化学性质稳定，自然条件下难以被微生物分解，所以会长期残留在环境中。白色污染指废弃塑料制品造成的污染，深埋并不能让它降解，反而占用土地、影响土壤。正确做法是减少使用、分类回收、使用可降解塑料。","options":["塑料属于天然材料","塑料难降解是因为它的化学性质非常稳定","白色污染是指白色油漆造成的污染","只要把塑料深埋地下，白色污染就彻底解决了"],"difficulty":2,"tags":["有机合成材料","白色污染"]},{"id":"chem-substance-11-q5","type":"choice","stem":"下列说法中，符合科学道理的是","answer":"C","explain":"钙、碘过量都有害；维生素虽然需要量很少，却参与调节新陈代谢，缺了会得相应缺乏症；糖类是主要供能物质、油脂能提供必需脂肪酸并帮助吸收脂溶性维生素，完全不吃会损害健康。误服重金属盐后先喝牛奶或蛋清是公认的应急措施，但必须立即就医，C 正确。","options":["人体所需的元素越多越好，应大量补充钙和碘","维生素在人体中含量很少，所以不起作用","误服重金属盐后可先喝牛奶应急，再立即就医","为了减肥可以完全不吃糖类和油脂"],"difficulty":3,"tags":["营养素","元素与人体健康","化学与健康"]},{"id":"chem-substance-11-q6","type":"fill","stem":"人体需要的六大营养素是蛋白质、糖类、油脂、维生素、________ 和水。其中构成细胞的基础、青少年生长发育最需要的是________；在人体内被氧化放出能量、被称为主要供能物质的是________。","answer":"无机盐；蛋白质；糖类","explain":"六类营养素要按顺序记牢：蛋白质、糖类、油脂、维生素、无机盐、水。功能对应关系是：蛋白质构成细胞与修补组织，糖类是主要供能物质，油脂是重要的储能物质，维生素调节新陈代谢，无机盐维持正常的生理功能，水参与一切生命活动。","difficulty":2,"tags":["营养素"]},{"id":"chem-substance-11-q7","type":"fill","stem":"用碘水可以检验食物中是否含有________，现象是________；误服重金属盐后应立即喝牛奶或蛋清，其原因是牛奶和蛋清中的蛋白质会先与重金属离子结合并发生________，从而保护人体自身的蛋白质。","answer":"淀粉；变蓝；变性","explain":"淀粉遇碘变蓝是经典的颜色检验，既用于检验淀粉，也用于检验碘。重金属盐、甲醛、浓酒精和加热都会使蛋白质变性（失去原有的生理功能），这是「喝牛奶应急」的原理。","difficulty":2,"tags":["淀粉检验","蛋白质变性"]},{"id":"chem-substance-11-q8","type":"short","stem":"某同学从超市买回一袋食品，配料表中含有小麦粉、白砂糖、植物油、鸡蛋、食用盐、碳酸钙、维生素 D。请回答：(1) 该食品能提供哪些营养素？(2) 配料表中的碳酸钙属于哪一类物质？它起什么作用？(3) 为什么钙片中常常同时添加维生素 D？","answer":"(1) 小麦粉与白砂糖提供糖类，植物油提供油脂，鸡蛋提供蛋白质，食用盐提供无机盐，食品中还含有水，因此可提供糖类、油脂、蛋白质、无机盐和水。(2) 碳酸钙属于无机盐（化合物），用于补充人体所需的钙元素，预防儿童佝偻病和老年人骨质疏松。(3) 维生素 D 能促进人体对钙的吸收，只补钙而不补充维生素 D，钙的吸收率低，所以两者常配合使用。","explain":"食品标签题的关键是把配料逐条对应到营养素，再解释添加剂的功能。作答时不要漏掉「水」，它虽然不写在配料里（原料中自带），但属于六大营养素之一；碳酸钙的作用要写成「补充钙元素 + 预防相应缺乏症」。","difficulty":3,"tags":["营养素","食品标签"],"rubric":["答出糖类、油脂、蛋白质、无机盐等并提供对应原料（1 分）","说明碳酸钙补充钙元素（1 分）","说明钙与维生素 D 的关系（1 分）","表述完整、有「预防缺乏症」的结论（1 分）"],"figure":{"id":"fig-chem-substance-11-q8","title":"食品配料与营养素对应","caption":"配料逐条对应六大营养素","view":"wide","alt":"配料表与营养素对应示意：小麦粉、白砂糖对应糖类，植物油对应油脂，鸡蛋对应蛋白质，食用盐对应无机盐，碳酸钙补充钙元素，维生素 D 促进钙吸收","prims":[{"t":"rect","x":5,"y":10,"w":42,"h":34,"tone":"main"},{"t":"text","x":26,"y":16,"text":"配料表","size":3.8,"anchor":"middle"},{"t":"text","x":9,"y":24,"text":"小麦粉、白砂糖","size":3.4},{"t":"text","x":9,"y":31,"text":"植物油、鸡蛋","size":3.4},{"t":"text","x":9,"y":38,"text":"食用盐、碳酸钙、维生素 D","size":3.4},{"t":"arrow","x1":49,"y1":27,"x2":56,"y2":27,"tone":"accent"},{"t":"rect","x":58,"y":10,"w":38,"h":34,"tone":"accent"},{"t":"text","x":77,"y":16,"text":"营养素","size":3.8,"anchor":"middle"},{"t":"text","x":62,"y":24,"text":"糖类、油脂、蛋白质","size":3.4},{"t":"text","x":62,"y":31,"text":"无机盐（钠、钙）","size":3.4},{"t":"text","x":62,"y":38,"text":"维生素 D（促进钙吸收）","size":3.4},{"t":"text","x":50,"y":52,"text":"食品标签题：配料逐条落到营养素，再说明功能","size":3.6,"tone":"muted","anchor":"middle"}]}},{"id":"chem-substance-11-q9","type":"short","stem":"请设计实验鉴别三种纤维：棉线、羊毛线、涤纶线。画出实验示意（可用文字配合简图说明），写出操作步骤、现象与结论。","answer":"见参考答案图。操作：各取一小段纤维，分别用镊子夹住，放在酒精灯外焰上点燃，闻气味并观察灰烬。现象与结论：有烧纸气味、灰烬为灰白色粉末、一捏就碎的是棉线（纤维素）；有烧焦羽毛气味、灰烬为黑褐色且一捏就碎的是羊毛线（蛋白质）；先熔化后燃烧、有特殊气味、灰烬是黑色硬块且不易捏碎的是涤纶线（合成纤维）。","explain":"鉴别实验要交代清楚「怎么操作、看什么现象、得出什么结论」三件事。三种纤维的现象差别集中在气味与灰烬性状上，所以设计里必须写出「闻气味」和「观察灰烬」两个观察点，并用对照的方式呈现。画图时可以用三点法把三种纤维与酒精灯的位置关系画清楚。","difficulty":3,"tags":["实验设计","纤维鉴别","作图"],"rubric":["写出用燃烧法并说明要闻气味、看灰烬（1 分）","正确描述棉线的现象与结论（1 分）","正确描述羊毛线的现象与结论（1 分）","正确描述涤纶线的现象与结论，并画出实验示意（1 分）"],"answerFigure":{"id":"fig-chem-substance-11-q9-ans","title":"参考答案：燃烧法鉴别三种纤维","caption":"三种纤维在酒精灯上燃烧，分别闻气味、看灰烬","view":"wide","alt":"酒精灯上方用镊子夹着纤维燃烧，旁边标出三种纤维的燃烧现象：棉线有烧纸味、羊毛有烧焦羽毛味、涤纶有特殊气味且灰烬为黑色硬块","prims":[{"t":"alcoholLamp","x":24,"y":46,"lit":true,"label":"酒精灯"},{"t":"line","x1":20,"y1":30,"x2":26,"y2":38,"width":0.9},{"t":"text","x":24,"y":24,"text":"分别夹取一小段点燃","size":3.4,"tone":"main","anchor":"middle"},{"t":"rect","x":52,"y":12,"w":44,"h":9,"tone":"main"},{"t":"text","x":56,"y":18,"text":"棉线：烧纸味、灰白色粉末","size":3.4},{"t":"rect","x":52,"y":23,"w":44,"h":9,"tone":"ok"},{"t":"text","x":56,"y":29,"text":"羊毛线：烧焦羽毛味、易碎","size":3.4},{"t":"rect","x":52,"y":34,"w":44,"h":9,"tone":"danger"},{"t":"text","x":56,"y":40,"text":"涤纶线：特殊气味、黑色硬块","size":3.4},{"t":"text","x":50,"y":62,"text":"观察点：气味 + 灰烬性状，两者合起来才是完整结论","size":3.6,"tone":"muted","anchor":"middle"}]}},{"id":"chem-substance-11-q10","type":"short","stem":"某品牌饼干每 100 g 含蛋白质 8.0 g、脂肪 20.0 g、糖类 58.0 g。请回答：(1) 计算这 100 g 饼干中蛋白质、脂肪、糖类三种营养素的总质量。(2) 小明吃了 250 g 这种饼干，按上表比例计算他摄入了多少克糖类？(3) 从营养均衡的角度，指出这种饼干的一个不足。","answer":"(1) 三种营养素的总质量为 8.0 g + 20.0 g + 58.0 g = 86.0 g。(2) 每 100 g 含糖类 58.0 g，250 g 是 100 g 的 2.5 倍，所以摄入糖类 58.0 g × 2.5 = 145.0 g。(3) 这种饼干含糖类与脂肪较高（86% 的营养素中，糖类与脂肪合计 78 g），维生素、无机盐等含量少，长期只吃饼干会造成营养素不均衡（例如缺乏维生素 C 可能引起坏血病）。","explain":"第 (1) 问是简单的加法，注意带上单位；第 (2) 问用比例关系：先把 250 g 与 100 g 的倍数关系求出来，再乘以每 100 g 的含量，避免直接相加。第 (3) 问从「种类齐全、比例合理」两个角度评价：该食品能量密度高、营养素单一。","difficulty":3,"tags":["营养素","化学计算","化学与健康"],"rubric":["(1) 求和正确并带单位（1 分）","(2) 先求倍数再计算，结果 145.0 g（1 分）","(3) 指出糖类与脂肪偏高、维生素与无机盐不足（1 分）"],"steps":["第一步（读表）：明确每 100 g 中各营养素的质量，注意单位是 g。","第二步（求和）：8.0 g + 20.0 g + 58.0 g = 86.0 g。","第三步（比例）：250 g ÷ 100 g = 2.5，糖类 = 58.0 g × 2.5 = 145.0 g。","第四步（评价）：糖类与脂肪合计 78.0 g，占营养素的大多数，维生素与无机盐少，营养不均衡。","第五步（答）：按表格比例，250 g 饼干约提供 145.0 g 糖类；长期以饼干为主食会造成营养不均衡。"]},{"id":"chem-substance-11-m1-q1","type":"short","stem":"根据材料一，说明这种食品主要能提供哪些营养素；配料表中的碳酸钙与维生素 D 起什么作用？（4 分）","answer":"小麦粉与白砂糖提供糖类，植物油提供油脂，鸡蛋提供蛋白质，食用盐提供无机盐（钠），因此这种食品主要提供糖类、油脂、蛋白质和无机盐；配料表中还含有水（来自原料）。碳酸钙用于补充钙元素，预防佝偻病和骨质疏松；维生素 D 能促进钙的吸收，两者配合才能让钙真正被身体利用。","explain":"","tags":["营养素","食品标签","元素与健康"],"rubric":["答出至少三类营养素并对应到原料（2 分）","说明碳酸钙补充钙元素、预防缺钙引起的疾病（1 分）","说明维生素 D 促进钙的吸收（1 分）"]},{"id":"chem-substance-11-m1-q2","type":"short","stem":"结合材料二，用化学知识解释「误服硫酸铜溶液后先喝牛奶或蛋清」的原因；为什么随后还必须立即送医？（3 分）","answer":"硫酸铜属于重金属盐，会使蛋白质变性而失去生理功能。牛奶、生鸡蛋清中含有大量蛋白质，喝下后它们会先与铜离子结合并变性，从而减少了人体自身蛋白质（如胃黏膜、消化酶）被破坏，起到应急保护作用。但牛奶只能结合一部分重金属离子，不能把体内的铜离子完全清除，所以必须立即送医，通过洗胃、用药等方式彻底处理。","explain":"","tags":["蛋白质变性","重金属盐","化学与健康"],"rubric":["指出硫酸铜是重金属盐、会使蛋白质变性（1 分）","说明牛奶、蛋清中的蛋白质先与重金属离子结合从而保护人体蛋白质（1 分）","指出这只是应急措施，必须立即就医（1 分）"]}]}];
